{"title":"NOWY_iou","content":"// ==UserScript==
// @name         Sesame & Yard 360 - Carrier Claim + Coungaurd AutoFill Pro
// @namespace    yard-claim-suite / lycgracj
// @version      9.0
// @description  Automatyzacja roszczeń transportowych Yard 360 oraz auto-uzupełnianie modala New Shipment (Coungaurd) danymi z placu.
// @match        https://trans-logistics-eu.amazon.com/yms/sesameGateConsole*
// @match        https://trans-logistics-eu.amazon.com/yms/relayYardHub/*
// @match        https://trans-logistics-eu.amazon.com/ssp/dock/hrz/ob*
// @match        *://*/*
// @connect      prod-eu.eu-west-1.idx-backend.aft.amazon.dev
// @connect      prod-eu.eu-west-1.idx-website.aft.amazon.dev
// @grant        GM_xmlhttpRequest
// @grant        GM.xmlHttpRequest
// @grant        GM_setValue
// @grant        GM_getValue
// @run-at       document-idle
// ==/UserScript==

(function () {
  'use strict';

  // =========================================================================
  // 1. STYLE TAKTYCZNE FUI
  // =========================================================================
  var CENTRAL_STYLES = [
    ':root {',
    '  --fui-bg: #090d12;',
    '  --fui-panel: #111722;',
    '  --fui-card: #161f2e;',
    '  --fui-border: #233147;',
    '  --fui-orange: #f36c00;',
    '  --fui-claim-red: #ef4444;',
    '  --fui-text: #c5d1de;',
    '  --fui-text-bright: #f0f6fc;',
    '  --fui-text-dim: #64748b;',
    '  --fui-green: #10b981;',
    '  --fui-amber: #f59e0b;',
    '  --fui-ktw3: #00ffcc;',
    '  --fui-font: "JetBrains Mono", "Share Tech Mono", monospace, Consolas;',
    '}',
    '',
    '.fui-root, .fui-root * { box-sizing: border-box; border-radius: 0 !important; font-family: var(--fui-font); }',
    '.fui-btn {',
    '  cursor: pointer; background: #121820; color: var(--fui-orange); border: 1px solid var(--fui-orange);',
    '  font-size: 10px; font-weight: 700; padding: 2px 6px; text-transform: uppercase;',
    '  transition: background 0.15s, color 0.15s; vertical-align: middle;',
    '}',
    '.fui-btn:hover { background: var(--fui-orange); color: #000; }',
    '.fui-btn-claim {',
    '  background: #450a0a; color: #fca5a5; border: 1px solid var(--fui-claim-red);',
    '  font-size: 10px; font-weight: 900; padding: 3px 8px; cursor: pointer; text-transform: uppercase;',
    '  margin-left: 4px; vertical-align: middle; transition: all 0.15s ease;',
    '}',
    '.fui-btn-claim:hover { background: #b91c1c; color: #fff; box-shadow: 0 0 8px rgba(239,68,68,0.7); }',
    '.fui-btn-fill {',
    '  background: #143026; color: #34d399; border: 1px solid #059669;',
    '  font-size: 10px; font-weight: 800; padding: 3px 7px; cursor: pointer; text-transform: uppercase;',
    '  margin-left: 4px; vertical-align: middle; transition: all 0.15s ease;',
    '}',
    '.fui-btn-fill:hover { background: #059669; color: #000; box-shadow: 0 0 8px rgba(16,185,129,0.7); }',
    '.fui-btn-sub { background: #1a2332; color: #8198b5; border: 1px solid var(--fui-border); font-size: 9px; padding: 1px 5px; cursor: pointer; }',
    '.fui-btn-sub:hover { background: #223044; color: #fff; }',
    '.ktw3-tag { display: inline-block; padding: 2px 5px; font-size: 9px; font-weight: 900; background: rgba(0,255,204,0.15); color: var(--fui-ktw3); border: 1px solid var(--fui-ktw3); margin-left: 4px; vertical-align: middle; }',
    '',
    '#claim-tactical-terminal {',
    '  position: fixed; right: 14px; bottom: 14px; z-index: 999990; background: var(--fui-bg);',
    '  color: var(--fui-text); box-shadow: 0 6px 30px rgba(0,0,0,0.95); width: 460px; height: auto;',
    '  min-width: 340px; min-height: 200px; max-width: 94vw; max-height: 90vh; resize: both;',
    '  overflow: hidden; display: flex; flex-direction: column; border: 1px solid var(--fui-border);',
    '  border-top: 3px solid var(--fui-claim-red);',
    '}',
    '.ct-head { cursor: move; user-select: none; display: flex; align-items: center; gap: 8px; padding: 8px 10px; background: var(--fui-panel); border-bottom: 1px solid var(--fui-border); }',
    '.ct-head-title { flex: 1; color: var(--fui-text-bright); font-size: 11px; font-weight: 900; letter-spacing: 0.8px; }',
    '.ct-tabs-bar { display: flex; border-bottom: 1px solid var(--fui-border); background: var(--fui-bg); }',
    '.ct-tab-btn { flex: 1; padding: 6px 2px; border: none; background: var(--fui-bg); color: var(--fui-text-dim); cursor: pointer; font-size: 10px; font-weight: 700; outline: none; }',
    '.ct-tab-btn.active { background: var(--fui-card); color: var(--fui-claim-red); border-bottom: 2px solid var(--fui-claim-red); }',
    '.ct-view { padding: 10px; overflow-y: auto; flex: 1; display: flex; flex-direction: column; gap: 8px; }',
    '.ct-claim-card { border: 1px solid var(--fui-border); background: var(--fui-panel); padding: 8px; display: flex; flex-direction: column; gap: 4px; font-size: 11px; }',
    '.ct-claim-card.critical { border-left: 3px solid var(--fui-claim-red); }',
    '.ct-copy-box { background: #05080c; border: 1px solid var(--fui-border); color: #38bdf8; font-size: 10px; padding: 6px; white-space: pre-wrap; max-height: 140px; overflow-y: auto; }',
    '',
    '.fui-quickbar { position: absolute; top: 10px; right: 50px; z-index: 10000; display: flex; gap: 6px; }'
  ].join('\n');

  var styleEl = document.createElement('style');
  styleEl.textContent = CENTRAL_STYLES;
  document.head.appendChild(styleEl);

  // =========================================================================
  // 2. MODUŁ UZUPEŁNIANIA FORMULARZA (COUNGAURD / ANGULAR ADAPTER)
  // =========================================================================

  function fillAngularField(inputName, value) {
    if (!value) return;
    var input = document.querySelector('input[name="' + inputName + '"]');
    if (!input) return;

    input.value = value;
    input.dispatchEvent(new Event('input', { bubbles: true }));
    input.dispatchEvent(new Event('change', { bubbles: true }));
    input.dispatchEvent(new Event('blur', { bubbles: true }));
  }

  function fillAngularDropdown(selectName, searchPhrase) {
    if (!searchPhrase) return;
    var host = document.querySelector('select-list[name="' + selectName + '"]');
    if (!host) return;

    var trigger = host.querySelector('.form-control') || host;
    trigger.click();

    setTimeout(function () {
      var filterInput = host.querySelector('input[name="inputFilter"]');
      if (filterInput) {
        filterInput.value = searchPhrase;
        filterInput.dispatchEvent(new Event('input', { bubbles: true }));
      }
      setTimeout(function () {
        var opt = document.querySelector('.dropdown-item, .select-item, [role="option"]');
        if (opt) opt.click();
      }, 120);
    }, 120);
  }

  function autofillCoungaurdModal(data) {
    var modal = document.querySelector('.modal-content-container, shipment');
    if (!modal) return false;

    // 1. Alias (login użytkownika z sesji lub domyślny)
    var userAlias = (data && data.alias) || localStorage.getItem('coungaurd_alias') || '';
    if (userAlias) fillAngularField('alias_origin', userAlias);

    // 2. Pola tekstowe z obiektu Yard
    if (data) {
      if (data.vrid) fillAngularField('cargoid', data.vrid);
      if (data.tractor && data.tractor !== '---') fillAngularField('truck_plate1', data.tractor);
      if (data.trailer && data.trailer !== '---') fillAngularField('trailer_plate', data.trailer);
      if (data.carrier && data.carrier !== '---') fillAngularField('truck_carrier', data.carrier);

      // 3. Rozwijane listy (opcjonalne dopasowania)
      if (data.trailerType) fillAngularDropdown('trailer_type', data.trailerType);
      if (data.route) fillAngularDropdown('route', data.route);
      if (data.lockMethod) fillAngularDropdown('lock_method', data.lockMethod);
      if (data.devicelessReason) fillAngularDropdown('deviceless_reason', data.devicelessReason);
    }

    return true;
  }

  // Wstrzyknięcie przycisku "⚡ Wklej dane z Yard" w nagłówku modala
  function attachModalAutofillButton() {
    var header = document.querySelector('.modal-header');
    if (!header || header.querySelector('.btn-coungaurd-autofill')) return;

    var btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'fui-btn-fill btn-coungaurd-autofill';
    btn.textContent = '⚡ WYPEŁNIJ DANYMI Z YARD';
    btn.title = 'Wypełnij danymi ostatnio wybranego lub wykrytego pojazdu';
    btn.style.marginRight = '12px';

    btn.onclick = function (e) {
      e.preventDefault();
      var stored = null;
      try {
        var raw = localStorage.getItem('last_yard_selected_item');
        if (raw) stored = JSON.parse(raw);
      } catch (err) {}

      if (!stored && detectedClaimsList.length > 0) {
        stored = detectedClaimsList[0];
      }

      if (stored) {
        autofillCoungaurdModal(stored);
        btn.textContent = '✔ UZUPEŁNIONO';
        setTimeout(function () { btn.textContent = '⚡ WYPEŁNIJ DANYMI Z YARD'; }, 1500);
      } else {
        alert('Brak danych w buforze Yard! Wybierz ładunek w tabeli lub w terminalu.');
      }
    };

    var controls = header.querySelector('.modal-header-controls');
    if (controls) {
      header.insertBefore(btn, controls);
    } else {
      header.appendChild(btn);
    }
  }

  // =========================================================================
  // 3. OBSŁUGA SCHOWKA I SYGNAŁÓW
  // =========================================================================
  function copyText(text, btnElement, okMsg) {
    var original = btnElement ? btnElement.textContent : '';
    var notify = function () {
      if (btnElement) {
        btnElement.textContent = okMsg || '✔ SKOPIOWANO';
        btnElement.style.background = '#10b981';
        btnElement.style.color = '#000';
        setTimeout(function () {
          btnElement.textContent = original;
          btnElement.style.background = '';
          btnElement.style.color = '';
        }, 1200);
      }
    };
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(text).then(notify).catch(function () {
        fallbackCopy(text);
        notify();
      });
    } else {
      fallbackCopy(text);
      notify();
    }
  }

  function fallbackCopy(text) {
    var ta = document.createElement('textarea');
    ta.value = text;
    ta.style.position = 'fixed';
    ta.style.opacity = '0';
    document.body.appendChild(ta);
    ta.select();
    try { document.execCommand('copy'); } catch (e) {}
    document.body.removeChild(ta);
  }

  function getNode() {
    var m = location.hash.match(/\/(WRO5|WRO6|YWRO|[A-Z0-9]+)\b/i) || location.href.match(/setNodeId=([A-Z0-9]+)/i);
    return m ? m[1].toUpperCase() : 'WRO5';
  }

  function extractMinutes(timeStr) {
    if (!timeStr || timeStr.indexOf(':') === -1) return null;
    var parts = timeStr.split(':').map(Number);
    var target = new Date();
    target.setHours(parts[0], parts[1], 0, 0);
    return Math.round((target.getTime() - new Date().getTime()) / 60000);
  }

  // =========================================================================
  // 4. PARSER YARD 360 / APPOINTMENTS
  // =========================================================================
  var detectedClaimsList = [];

  function scanYard360ForClaims() {
    var table = document.querySelector('table[data-testid="wranglingTable"]');
    if (!table) return;

    var rows = table.querySelectorAll('tbody tr[data-testid]');
    var currentClaims = [];

    rows.forEach(function (row) {
      var rawText = (row.innerText || '').replace(/&gt;/g, '>').toUpperCase();
      var vrid = row.getAttribute('data-testid') || '';

      var timeEl = row.querySelector('[data-testid="departureTimeDisplay"]');
      var timeMatch = timeEl ? timeEl.innerText.match(/\d{2}:\d{2}/) : rawText.match(/\d{2}:\d{2}/);
      var baseTime = timeMatch ? timeMatch[0] : '';
      var diff = extractMinutes(baseTime);

      var statusEl = row.querySelector('[data-testid="loadStatusText"]');
      var status = statusEl ? statusEl.innerText.trim().toUpperCase() : '';

      var driverEl = row.querySelector('[data-testid$="DriverStatus"]');
      var hasDriver = Boolean(driverEl && driverEl.innerText.indexOf('—') === -1 && driverEl.innerText.trim() !== '');

      var locEl = row.querySelector('[data-testid$="Location"]');
      var loc = locEl ? locEl.innerText.replace(/\s+/g, ' ').trim() : '---';

      var eqEl = row.querySelector('[data-testid$="Equipment"]');
      var eqText = eqEl ? eqEl.innerText.replace(/\s+/g, ' ') : '';
      var trailerMatch = eqText.match(/Trailer:[^\w]*ID\s*([A-Z0-9]+)/i) || loc.match(/Trailer:\s*([A-Z0-9-]+)/i);
      var trailer = trailerMatch ? trailerMatch[1] : vrid;
      var tractorMatch = eqText.match(/Tractor:[^\w]*LP\s*([A-Z0-9]+)/i) || loc.match(/Tractor:\s*([A-Z0-9-]+)/i);
      var tractor = tractorMatch ? tractorMatch[1] : '---';

      // Carrier SCAC (szukamy w komórkach 2-4 literowych kodów)
      var carrierMatch = rawText.match(/\b([A-Z]{3,4})\b(?=\s*(?:STD|SCAC|LOADED|EMPTY))/);
      var carrier = carrierMatch ? carrierMatch[1] : '---';

      var hasSeal = /\b(SEAL|PLOMBA|SEALED)\b/i.test(rawText);
      var isTransfers = rawText.indexOf('TRANSFERSINITIAL') !== -1;
      var isFinished = status.indexOf('FINISHED') !== -1;
      var isKtw = rawText.indexOf('KTW3') !== -1;
      var lane = isKtw ? 'WRO5->KTW3' : 'WRO5->LANE';

      var isClaimQualified = (isFinished && !hasDriver) || (diff !== null && diff <= 10 && !hasDriver) || (diff !== null && diff < 0) || (isFinished && !hasSeal && !isTransfers);

      var itemData = {
        vrid: vrid,
        baseTime: baseTime,
        diff: diff,
        status: status,
        hasDriver: hasDriver,
        loc: loc,
        trailer: trailer,
        tractor: tractor,
        carrier: carrier,
        lane: lane,
        seal: hasSeal ? 'OBECNA' : 'BRAK',
        sealDefect: !hasSeal && isFinished && !isTransfers,
        isTransfers: isTransfers,
        isKtw3: isKtw,
        row: row
      };

      if (isClaimQualified) {
        currentClaims.push(itemData);
        injectActionButtons(row, itemData);
      }
    });

    detectedClaimsList = currentClaims;
    renderTerminalClaims(currentClaims);
  }

  function injectActionButtons(row, itemData) {
    var actionCell = row.cells[row.cells.length - 1];
    if (!actionCell || actionCell.querySelector('.fui-btn-claim')) return;

    var container = document.createElement('span');
    container.style.whiteSpace = 'nowrap';

    // Przycisk roszczenia
    var claimBtn = document.createElement('button');
    claimBtn.type = 'button';
    claimBtn.className = 'fui-btn-claim fui-root';
    claimBtn.textContent = '⚖️ CLAIM';
    claimBtn.title = 'Kopiuj protokół roszczenia';
    claimBtn.onclick = function (e) {
      e.stopPropagation();
      copyText(buildClaimReport(itemData), claimBtn, 'SKOPIOWANO');
    };

    // Przycisk wysyłki do Coungaurd
    var fillBtn = document.createElement('button');
    fillBtn.type = 'button';
    fillBtn.className = 'fui-btn-fill fui-root';
    fillBtn.textContent = '⚡ COUNCARD';
    fillBtn.title = 'Zapisz dane ładunku do autouzupełnienia w Coungaurd';
    fillBtn.onclick = function (e) {
      e.stopPropagation();
      localStorage.setItem('last_yard_selected_item', JSON.stringify(itemData));
      copyText(itemData.vrid, fillBtn, 'ZAPISANO!');
      autofillCoungaurdModal(itemData);
    };

    container.appendChild(claimBtn);
    container.appendChild(fillBtn);
    actionCell.appendChild(container);
  }

  function buildClaimReport(item) {
    var now = new Date();
    var dateStr = now.toLocaleDateString('pl-PL') + ' ' + now.toLocaleTimeString('pl-PL', { hour: '2-digit', minute: '2-digit' });

    var reasonBullets = [];
    if (!item.hasDriver) reasonBullets.push('❌ BRAK KIEROWCY NA MIEJSCU (NO DRIVER / MISSED DEPARTURE)');
    if (item.sealDefect) reasonBullets.push('❌ BRAK / USZKODZONA PLOMBA ZABEZPIECZAJĄCA (SEAL DEFECT / NO SEAL)');
    if (item.diff !== null && item.diff < 0) reasonBullets.push('❌ SPÓŹNIENIE ODJAZDU: ' + Math.abs(item.diff) + ' min po planie');
    if (reasonBullets.length === 0) reasonBullets.push('⚠️ ZAGROŻENIE PUNKTUALNOŚCI ODJAZDU');

    return [
      '=================================================================',
      '🚨 PROTOKÓŁ ROSZCZENIA TRANSPORTOWEGO // CARRIER CLAIM',
      '=================================================================',
      '• Data i godzina raportu : ' + dateStr,
      '• Węzeł (Node) / Strefa  : ' + getNode() + ' | Strefa: ' + (item.loc || '---'),
      '• Numer ładunku (VRID)   : ' + (item.vrid || '---'),
      '• Relacja trasy (Lane)   : ' + (item.lane || '---'),
      '• Przewoźnik (Carrier)   : ' + (item.carrier || '---'),
      '• Numer naczepy (Trailer): ' + (item.trailer || '---'),
      '• Ciągnik (Tractor Plate): ' + (item.tractor || '---'),
      '• Status kierowcy        : ' + (item.hasDriver ? 'Obecny na placu' : 'BRAK KIEROWCY'),
      '• SDT / Opóźnienie       : ' + (item.baseTime || '---') + ' (' + (item.diff !== null ? item.diff + ' min' : '-') + ')',
      '-----------------------------------------------------------------',
      'UZASADNIENIE ZGŁOSZENIA:',
      reasonBullets.join('\n'),
      '================================================================='
    ].join('\n');
  }

  // =========================================================================
  // 5. TERMINAL HUD & LISTA ZGŁOSZEŃ
  // =========================================================================
  function injectClaimTerminal() {
    if (document.getElementById('claim-tactical-terminal')) return;

    var terminal = document.createElement('div');
    terminal.id = 'claim-tactical-terminal';
    terminal.className = 'fui-root';
    terminal.innerHTML = [
      '<div class="ct-head" id="ct-drag-head">',
      '  <span style="color:var(--fui-claim-red);font-weight:900;">⚖️</span>',
      '  <span class="ct-head-title">YARD CLAIM & COUNCARD AUTOFILL</span>',
      '  <button id="ct-btn-min" class="fui-btn-sub">_</button>',
      '</div>',
      '<div class="ct-tabs-bar">',
      '  <button id="ct-tab-list" class="ct-tab-btn active">AKTYWNE ROSZCZENIA (<span id="ct-claim-count">0</span>)</button>',
      '  <button id="ct-tab-manual" class="ct-tab-btn">FORMULARZ RĘCZNY</button>',
      '</div>',
      '<div class="ct-view" id="ct-view-list">',
      '  <div id="ct-claims-container" style="display:flex;flex-direction:column;gap:6px;"></div>',
      '</div>',
      '<div class="ct-view" id="ct-view-manual" style="display:none;">',
      '  <input id="ct-in-alias" class="fui-input" placeholder="Twój Alias (login)..." style="width:100%;margin-bottom:4px;">',
      '  <input id="ct-in-vrid" class="fui-input" placeholder="Wpisz VRID..." style="width:100%;text-transform:uppercase;margin-bottom:4px;">',
      '  <button id="ct-btn-autofill-now" class="fui-btn-fill" style="width:100%;padding:6px;">⚡ WYPEŁNIJ OTWARTY MODAL</button>',
      '</div>'
    ].join('\n');

    document.body.appendChild(terminal);

    // Przeciąganie okna
    var head = terminal.querySelector('#ct-drag-head');
    var drag = null;
    head.addEventListener('mousedown', function (e) {
      if (e.target.id === 'ct-btn-min') return;
      var r = terminal.getBoundingClientRect();
      drag = { dx: e.clientX - r.left, dy: e.clientY - r.top };
      terminal.style.left = r.left + 'px'; terminal.style.top = r.top + 'px';
      terminal.style.right = 'auto'; terminal.style.bottom = 'auto';
      e.preventDefault();
    });
    document.addEventListener('mousemove', function (e) {
      if (!drag) return;
      terminal.style.left = Math.max(0, e.clientX - drag.dx) + 'px';
      terminal.style.top = Math.max(0, e.clientY - drag.dy) + 'px';
    });
    document.addEventListener('mouseup', function () { drag = null; });

    // Zwijanie / minimalizacja
    var isMin = false;
    terminal.querySelector('#ct-btn-min').onclick = function () {
      isMin = !isMin;
      terminal.querySelector('#ct-view-list').style.display = isMin ? 'none' : 'flex';
      terminal.querySelector('#ct-view-manual').style.display = 'none';
      terminal.style.height = isMin ? '36px' : 'auto';
      this.textContent = isMin ? '□' : '_';
    };

    // Zakładki
    var tabList = terminal.querySelector('#ct-tab-list');
    var tabManual = terminal.querySelector('#ct-tab-manual');
    var viewList = terminal.querySelector('#ct-view-list');
    var viewManual = terminal.querySelector('#ct-view-manual');

    tabList.onclick = function () {
      tabList.classList.add('active'); tabManual.classList.remove('active');
      viewList.style.display = 'flex'; viewManual.style.display = 'none';
    };
    tabManual.onclick = function () {
      tabManual.classList.add('active'); tabList.classList.remove('active');
      viewManual.style.display = 'flex'; viewList.style.display = 'none';
    };

    // Ręczne uzupełnienie z poziomu wpisanego VRID
    terminal.querySelector('#ct-btn-autofill-now').onclick = function () {
      var vrid = terminal.querySelector('#ct-in-vrid').value.trim();
      var alias = terminal.querySelector('#ct-in-alias').value.trim();
      if (alias) localStorage.setItem('coungaurd_alias', alias);

      var payload = { vrid: vrid, alias: alias };
      var ok = autofillCoungaurdModal(payload);
      if (ok) {
        copyText(vrid, this, '✔ MODAL UZUPEŁNIONY!');
      } else {
        alert('Modal "New Shipment" nie jest aktualnie otwarty!');
      }
    };
  }

  function renderTerminalClaims(claims) {
    var countEl = document.getElementById('ct-claim-count');
    var container = document.getElementById('ct-claims-container');
    if (countEl) countEl.textContent = String(claims.length);
    if (!container) return;

    if (claims.length === 0) {
      container.innerHTML = '<div style="color:var(--fui-text-dim);padding:8px;text-align:center;">[ BRAK KWALIFIKUJĄCYCH SIĘ ROSZCZEŃ ]</div>';
      return;
    }

    container.innerHTML = '';
    claims.forEach(function (c) {
      var card = document.createElement('div');
      card.className = 'ct-claim-card critical fui-root';

      card.innerHTML = [
        '<div style="display:flex;justify-content:space-between;align-items:center;">',
        '  <b>VRID: <span style="color:#38bdf8;">' + c.vrid + '</span></b>',
        '  <div>',
        '    <button class="fui-btn-fill ct-btn-card-fill" style="font-size:9px;">⚡ COUNCARD</button>',
        '    <button class="fui-btn-claim ct-btn-card-claim" style="font-size:9px;">CLAIM</button>',
        '  </div>',
        '</div>',
        '<div>Naczepa: <b>' + c.trailer + '</b> | Ciągnik: <b>' + c.tractor + '</b></div>',
        '<div>Dok: <b style="color:var(--fui-orange);">' + c.loc + '</b> | Carrier: <b>' + c.carrier + '</b></div>'
      ].join('');

      // Akcja wypełnienia Coungaurd
      card.querySelector('.ct-btn-card-fill').onclick = function () {
        localStorage.setItem('last_yard_selected_item', JSON.stringify(c));
        autofillCoungaurdModal(c);
        copyText(c.vrid, this, 'WYSLANO!');
      };

      // Akcja kopiowania roszczenia
      card.querySelector('.ct-btn-card-claim').onclick = function () {
        copyText(buildClaimReport(c), this, 'OK!');
      };

      container.appendChild(card);
    });
  }

  // =========================================================================
  // 6. GŁÓWNA PĘTLA I OBSERWATOR DOM
  // =========================================================================
  function init() {
    injectClaimTerminal();
    scanYard360ForClaims();
    attachModalAutofillButton();
  }

  var debounceTimer = null;
  var observer = new MutationObserver(function () {
    if (debounceTimer) return;
    debounceTimer = setTimeout(function () {
      scanYard360ForClaims();
      attachModalAutofillButton();
      debounceTimer = null;
    }, 400);
  });

  observer.observe(document.body, { childList: true, subtree: true });
  setInterval(init, 7000);

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
"}

{"title":"contguard","content":"// ==UserScript==
//
// @name         ContGuard Side Panel
// @namespace    http://tampermonkey.net/
// @version      1.0.2
// @description  Wygodny panel boczny z podgladem i statystykami dla ContGuard
// @author       Assistant
// @match        https://*.contguard.com/*
// @match        https://app.contguard.com/*
// @grant        GM_setValue
// @grant        GM_getValue
// @grant        GM_addStyle
// ==/UserScript==


(function () {
    'use strict';

    // Stan aplikacji i pamięć podręczna skryptu
    const STATE = {
        isOpen: false,
        containers: [],
        filteredContainers: [],
        pinnedIds: GM_getValue('cg_pinned_containers', []),
        notes: GM_getValue('cg_container_notes', {}),
        searchTerm: '',
        filterStatus: 'ALL', // ALL, ALERT, OK
        autoRefreshInterval: null,
        refreshSeconds: 30,
        debounceTimer: null
    };

    // Iniekcja stylów CSS dopasowanych do oprawy wizualnej ContGuard
    const styles = `
        #cg-sidebar-toggle {
            position: fixed;
            top: 50%;
            right: 0;
            transform: translateY(-50%);
            z-index: 99999;
            background: linear-gradient(135deg, #0b192c 0%, #0f172a 100%);
            color: #00a8e8;
            border: 1px solid #1e3a5f;
            border-right: none;
            padding: 14px 10px;
            cursor: pointer;
            display: flex;
            flex-direction: column;
            align-items: center;
            gap: 8px;
            font-family: "Roboto", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
            font-size: 11px;
            font-weight: 700;
            letter-spacing: 0.8px;
            transition: all 0.25s cubic-bezier(0.4, 0, 0.2, 1);
        }

        #cg-sidebar-toggle:hover {
            background: #1e293b;
            color: #38bdf8;
            padding-left: 14px;
        }

        #cg-sidebar-panel {
            position: fixed;
            top: 0;
            right: -430px;
            width: 410px;
            height: 100vh;
            z-index: 99998;
            background: #090f1d;
            color: #f1f5f9;
            border-left: 1px solid #1e3a5f;
            transition: right 0.3s cubic-bezier(0.16, 1, 0.3, 1);
            font-family: "Roboto", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
            display: flex;
            flex-direction: column;
        }

        #cg-sidebar-panel.open {
            right: 0;
        }

        /* Nagłówek Panelu ContGuard */
        .cg-header {
            padding: 16px 20px;
            background: linear-gradient(90deg, #0b192c 0%, #112240 100%);
            border-bottom: 1px solid #1e3a5f;
            display: flex;
            justify-content: space-between;
            align-items: center;
        }

        .cg-title {
            font-size: 15px;
            font-weight: 700;
            color: #00a8e8;
            display: flex;
            align-items: center;
            gap: 10px;
            letter-spacing: 0.5px;
            text-transform: uppercase;
        }

        .cg-close-btn {
            background: rgba(255, 255, 255, 0.05);
            border: 1px solid #1e3a5f;
            color: #94a3b8;
            font-size: 16px;
            cursor: pointer;
            width: 28px;
            height: 28px;

            display: flex;
            align-items: center;
            justify-content: center;
            transition: all 0.2s ease;
        }

        .cg-close-btn:hover {
            color: #ffffff;
            background: #1e293b;
            border-color: #00a8e8;
        }

        /* Pasek Statystyk */
        .cg-stats-grid {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            gap: 8px;
            padding: 12px 16px;
            background: #060a14;
            border-bottom: 1px solid #162a45;
        }

        .cg-stat-card {
            background: #0d1b2a;
            padding: 10px 12px;

            text-align: center;
            border: 1px solid #1e3a5f;
            transition: transform 0.2s ease;
        }

        .cg-stat-val {
            font-size: 18px;
            font-weight: 800;
            color: #f8fafc;
        }

        .cg-stat-lbl {
            font-size: 10px;
            color: #64748b;
            text-transform: uppercase;
            font-weight: 600;
            letter-spacing: 0.5px;
            margin-top: 2px;
        }

        .cg-stat-card.alert { border-color: rgba(244, 63, 94, 0.4); }
        .cg-stat-card.alert .cg-stat-val { color: #f43f5e; }
        .cg-stat-card.ok { border-color: rgba(16, 185, 129, 0.4); }
        .cg-stat-card.ok .cg-stat-val { color: #10b981; }

        /* Kontrolki i Filtry */
        .cg-controls {
            padding: 12px 16px;
            display: flex;
            flex-direction: column;
            gap: 10px;
            background: #0b1424;
            border-bottom: 1px solid #162a45;
        }

        .cg-search-input {
            width: 100%;
            padding: 9px 14px;
            background: #0d1b2a;
            border: 1px solid #1e3a5f;

            color: #f8fafc;
            font-size: 13px;
            box-sizing: border-box;
            transition: all 0.2s ease;
        }

        .cg-search-input:focus {
            outline: none;
            border-color: #00a8e8;

        }

        .cg-filter-tabs {
            display: flex;
            gap: 6px;
        }

        .cg-tab-btn {
            flex: 1;
            padding: 7px;
            font-size: 11px;
            font-weight: 600;
            background: #0d1b2a;
            border: 1px solid #1e3a5f;
            color: #94a3b8;

            cursor: pointer;
            text-align: center;
            transition: all 0.2s ease;
        }

        .cg-tab-btn:hover {
            color: #e2e8f0;
            background: #112240;
        }

        .cg-tab-btn.active {
            background: linear-gradient(135deg, #0077b6 0%, #00a8e8 100%);
            color: #ffffff;
            border-color: #00a8e8;
        }

        /* Lista Kontenerów */
        .cg-container-list {
            flex: 1;
            overflow-y: auto;
            padding: 14px 16px;
            display: flex;
            flex-direction: column;
            gap: 12px;
            background: #090f1d;
        }

        .cg-card {
            background: #0d1b2a;
            border: 1px solid #1e3a5f;

            padding: 12px 14px;
            display: flex;
            flex-direction: column;
            gap: 8px;
            transition: all 0.2s ease;
        }

        .cg-card:hover {
            border-color: #00a8e8;
            transform: translateY(-1px);
        }

        .cg-card.pinned {
            border-left: 4px solid #f59e0b;
        }

        .cg-card-header {
            display: flex;
            justify-content: space-between;
            align-items: center;
        }

        .cg-card-id {
            font-weight: 800;
            font-size: 14px;
            color: #00a8e8;
            letter-spacing: 0.5px;
        }

        .cg-card-name {
            font-size: 12px;
            font-weight: 600;
            color: #e2e8f0;
            margin-top: -2px;
            word-break: break-word;
            display: flex;
            align-items: center;
            gap: 6px;
        }

        .cg-badge {
            font-size: 10px;
            padding: 3px 8px;
            font-weight: 700;
            text-transform: uppercase;
            letter-spacing: 0.5px;
        }

        .cg-badge.ok { background: rgba(16, 185, 129, 0.15); color: #34d399; border: 1px solid rgba(16, 185, 129, 0.4); }
        .cg-badge.alert { background: rgba(244, 63, 94, 0.15); color: #fb7185; border: 1px solid rgba(244, 63, 94, 0.4); }

        .cg-card-details {
            display: grid;
            grid-template-columns: repeat(2, 1fr);
            gap: 6px;
            font-size: 12px;
            color: #cbd5e1;
            background: rgba(0, 0, 0, 0.2);
            padding: 8px;

        }

        .cg-card-loc {
            font-size: 11px;
            color: #94a3b8;
            grid-column: span 2;
            display: flex;
            align-items: center;
            gap: 4px;
            white-space: nowrap;
            overflow: hidden;
            text-overflow: ellipsis;
        }

        .cg-note-input {
            width: 100%;
            background: #060a14;
            border: 1px solid #162a45;

            color: #cbd5e1;
            font-size: 11px;
            padding: 6px 10px;
            margin-top: 2px;
            box-sizing: border-box;
            transition: border-color 0.2s ease;
        }

        .cg-note-input:focus {
            outline: none;
            border-color: #00a8e8;
        }

        .cg-card-actions {
            display: flex;
            justify-content: flex-end;
            gap: 8px;
        }

        .cg-icon-btn {
            background: transparent;
            border: none;
            color: #64748b;
            cursor: pointer;
            font-size: 11px;
            font-weight: 600;
            padding: 2px 6px;
            transition: all 0.2s ease;
        }

        .cg-icon-btn:hover {
            color: #00a8e8;
            background: rgba(0, 168, 232, 0.1);
        }

        /* Stopka */
        .cg-footer {
            padding: 12px 16px;
            background: #0b1424;
            border-top: 1px solid #162a45;
            display: flex;
            justify-content: space-between;
            align-items: center;
            font-size: 11px;
        }

        .cg-btn {
            background: linear-gradient(135deg, #0077b6 0%, #00a8e8 100%);
            color: #ffffff;
            border: none;
            padding: 7px 14px;

            font-weight: 700;
            cursor: pointer;
            font-size: 11px;
            letter-spacing: 0.3px;
            transition: all 0.2s ease;
        }

        .cg-btn:hover {
            transform: translateY(-1px);
        }
    `;

    function injectStyles() {
        const styleSheet = document.createElement("style");
        styleSheet.innerText = styles;
        document.head.appendChild(styleSheet);
    }

    // Tworzenie elementów interfejsu
    function createUI() {
        // Przycisk otwierania panelu
        const toggleBtn = document.createElement('button');
        toggleBtn.id = 'cg-sidebar-toggle';
        toggleBtn.innerHTML = `
            <span>◀</span>
            <span style="writing-mode: vertical-rl; text-orientation: mixed;">CONTGUARD</span>
        `;
        toggleBtn.onclick = toggleSidebar;
        document.body.appendChild(toggleBtn);

        // Główny kontener panelu
        const panel = document.createElement('div');
        panel.id = 'cg-sidebar-panel';
        panel.innerHTML = `
            <div class="cg-header">
                <div class="cg-title">
                    <span>📦</span> Panel ContGuard
                </div>
                <button class="cg-close-btn" id="cg-close">✕</button>
            </div>

            <div class="cg-stats-grid">
                <div class="cg-stat-card">
                    <div class="cg-stat-val" id="cg-stat-total">0</div>
                    <div class="cg-stat-lbl">Łącznie</div>
                </div>
                <div class="cg-stat-card alert">
                    <div class="cg-stat-val" id="cg-stat-alerts">0</div>
                    <div class="cg-stat-lbl">Alarmy</div>
                </div>
                <div class="cg-stat-card ok">
                    <div class="cg-stat-val" id="cg-stat-ok">0</div>
                    <div class="cg-stat-lbl">W норmie</div>
                </div>
            </div>

            <div class="cg-controls">
                <input type="text" class="cg-search-input" id="cg-search" placeholder="Szukaj kontenera, lokacji...">
                <div class="cg-filter-tabs">
                    <button class="cg-tab-btn active" data-filter="ALL">Wszystkie</button>
                    <button class="cg-tab-btn" data-filter="PINNED">📌 Przypięte</button>
                    <button class="cg-tab-btn" data-filter="ALERT">⚠️ Alarmy</button>
                </div>
            </div>

            <div class="cg-container-list" id="cg-list">
                <div style="text-align: center; color: #94a3b8; margin-top: 20px;">
                    Skanowanie widoku... Kliknij "Odśwież" jeśli dane się nie pojawiły.
                </div>
            </div>

            <div class="cg-footer">
                <span id="cg-auto-timer" style="color: #94a3b8;">Odświeżanie za: 30s</span>
                <div style="display: flex; gap: 8px;">
                    <button class="cg-btn" id="cg-export-btn" title="Eksportuj do CSV">📊 CSV</button>
                    <button class="cg-btn" id="cg-refresh-btn">🔄 Odśwież</button>
                </div>
            </div>
        `;
        document.body.appendChild(panel);

        // Rejestracja zdarzeń
        document.getElementById('cg-close').onclick = toggleSidebar;
        document.getElementById('cg-search').oninput = handleSearch;
        document.getElementById('cg-refresh-btn').onclick = scrapeAndRender;
        document.getElementById('cg-export-btn').onclick = exportToCSV;

        // Tabs
        panel.querySelectorAll('.cg-tab-btn').forEach(tab => {
            tab.onclick = (e) => {
                panel.querySelectorAll('.cg-tab-btn').forEach(b => b.classList.remove('active'));
                e.target.classList.add('active');
                STATE.filterStatus = e.target.dataset.filter;
                renderList();
            };
        });
    }

    // Odczytywanie danych z aktualnego widoku ContGuard
    function scrapePageData() {
        const containers = [];

        // Próba odczytania danych z tabel/kart na stronie ContGuard (z wykluczeniem własnego panelu)
        const rawRows = document.querySelectorAll('table tbody tr, .container-card, [data-container-id], .shipment-row, .card');
        const rows = Array.from(rawRows).filter(row => !row.closest('#cg-sidebar-panel') && !row.closest('#cg-sidebar-toggle'));

        if (rows.length > 0) {
            rows.forEach((row, idx) => {
                const text = row.innerText || '';
                const lines = text.split('\n').map(l => l.trim()).filter(Boolean);

                if (lines.length > 0) {
                    // Ekstrakcja numeru kontenera
                    const containerId = (text.match(/[A-Z]{4}\d{7}/) || [lines[0] || `CONT-${idx + 1}`])[0];

                    // Wyciąganie Nazwy przesyłki / Referencji
                    const nameEl = row.querySelector('.shipment-name, .container-name, .reference, .cargo-title, [data-shipment]');
                    let shipmentName = nameEl ? nameEl.innerText.trim() : '';
                    if (!shipmentName && lines.length > 1 && lines[1] !== containerId) {
                        shipmentName = lines[1];
                    }
                    if (!shipmentName || shipmentName === containerId) {
                        shipmentName = 'Przesyłka bez nazwy';
                    }

                    const hasAlert = text.toLowerCase().includes('alert') || text.toLowerCase().includes('breach') || text.toLowerCase().includes('alarm') || row.querySelector('.alert, .danger, .warning');

                    // Odczyt parametrów
                    const tempMatch = text.match(/(-?\d+(\.\d+)?)\s*°[C|F]/);
                    const temp = tempMatch ? tempMatch[0] : 'N/A';

                    const humMatch = text.match(/(\d+)\s*%/);
                    const humidity = humMatch ? humMatch[0] : null;

                    containers.push({
                        id: containerId,
                        name: shipmentName,
                        status: hasAlert ? 'ALERT' : 'OK',
                        temp: temp,
                        humidity: humidity,
                        location: lines[2] || lines[1] || 'Śledzenie w toku...',
                        rawText: text
                    });
                }
            });
        }

        // Jeśli DOM jest jeszcze pusty (pobieranie SPA), spróbujmy przechwycić elementy listy
        if (containers.length === 0) {
            const allLinks = document.querySelectorAll('a[href*="container"], a[href*="shipment"]');
            allLinks.forEach((link, idx) => {
                const id = link.innerText.trim();
                if (id && id.length >= 4) {
                    containers.push({
                        id: id,
                        name: 'Ładunek ' + (idx + 1),
                        status: 'OK',
                        temp: 'N/A',
                        location: 'Kliknij, aby otworzyć',
                        rawText: id
                    });
                }
            });
        }

        STATE.containers = containers;
        updateStats();
    }

    // Renderowanie statystyk
    function updateStats() {
        const total = STATE.containers.length;
        const alerts = STATE.containers.filter(c => c.status === 'ALERT').length;
        const ok = total - alerts;

        document.getElementById('cg-stat-total').innerText = total;
        document.getElementById('cg-stat-alerts').innerText = alerts;
        document.getElementById('cg-stat-ok').innerText = ok;
    }

    // Renderowanie listy w panelu
    function renderList() {
        const listEl = document.getElementById('cg-list');
        listEl.innerHTML = '';

        let filtered = STATE.containers.filter(item => {
            const matchesSearch = item.id.toLowerCase().includes(STATE.searchTerm.toLowerCase()) ||
                item.name.toLowerCase().includes(STATE.searchTerm.toLowerCase()) ||
                item.location.toLowerCase().includes(STATE.searchTerm.toLowerCase());

            if (!matchesSearch) return false;

            if (STATE.filterStatus === 'PINNED') {
                return STATE.pinnedIds.includes(item.id);
            } else if (STATE.filterStatus === 'ALERT') {
                return item.status === 'ALERT';
            }
            return true;
        });

        if (filtered.length === 0) {
            listEl.innerHTML = `<div style="text-align: center; color: #64748b; margin-top: 30px;">Brak wyników do wyświetlenia</div>`;
            return;
        }

        filtered.forEach(item => {
            const isPinned = STATE.pinnedIds.includes(item.id);
            const note = STATE.notes[item.id] || '';

            const card = document.createElement('div');
            card.className = `cg-card ${isPinned ? 'pinned' : ''}`;
            card.innerHTML = `
                <div class="cg-card-header">
                    <span class="cg-card-id">${item.id}</span>
                    <span class="cg-badge ${item.status === 'ALERT' ? 'alert' : 'ok'}">${item.status}</span>
                </div>
                <div class="cg-card-name" title="${item.name}">🏷️ ${item.name}</div>
                <div class="cg-card-details">
                    <div>Temp: <strong>${item.temp}</strong></div>
                    ${item.humidity ? `<div>Wilg: <strong>${item.humidity}</strong></div>` : ''}
                    <div class="cg-card-loc">📍 ${item.location}</div>
                </div>
                <input type="text" class="cg-note-input" placeholder="Dodaj szybką notatkę..." value="${note}" data-id="${item.id}">
                <div class="cg-card-actions">
                    <button class="cg-icon-btn cg-pin-btn" data-id="${item.id}">${isPinned ? '📌 Odklej' : '📍 Przypnij'}</button>
                </div>
            `;

            // Obsługa wpisywania notatek
            const noteInput = card.querySelector('.cg-note-input');
            noteInput.onchange = (e) => {
                STATE.notes[item.id] = e.target.value;
                GM_setValue('cg_container_notes', STATE.notes);
            };

            // Obsługa przypinania
            const pinBtn = card.querySelector('.cg-pin-btn');
            pinBtn.onclick = () => {
                togglePin(item.id);
            };

            listEl.appendChild(card);
        });
    }

    function togglePin(id) {
        if (STATE.pinnedIds.includes(id)) {
            STATE.pinnedIds = STATE.pinnedIds.filter(pId => pId !== id);
        } else {
            STATE.pinnedIds.push(id);
        }
        GM_setValue('cg_pinned_containers', STATE.pinnedIds);
        renderList();
    }

    function toggleSidebar() {
        const panel = document.getElementById('cg-sidebar-panel');
        const toggleBtn = document.getElementById('cg-sidebar-toggle');
        STATE.isOpen = !STATE.isOpen;

        if (STATE.isOpen) {
            panel.classList.add('open');
            toggleBtn.innerHTML = `<span>▶</span>`;
            scrapeAndRender();
        } else {
            panel.classList.remove('open');
            toggleBtn.innerHTML = `
                <span>◀</span>
                <span style="writing-mode: vertical-rl; text-orientation: mixed;">CONTGUARD</span>
            `;
        }
    }

    function handleSearch(e) {
        STATE.searchTerm = e.target.value;
        renderList();
    }

    function scrapeAndRender() {
        scrapePageData();
        renderList();
    }

    // Funkcja eksportu do CSV
    function exportToCSV() {
        if (STATE.containers.length === 0) {
            alert('Brak danych do wyeksportowania.');
            return;
        }

        let csvContent = "data:text/csv;charset=utf-8,ID Kontenera,Nazwa Przesyłki,Status,Temperatura,Wilgotność,Lokalizacja,Notatka\n";
        STATE.containers.forEach(c => {
            const note = (STATE.notes[c.id] || '').replace(/,/g, ' ');
            const name = (c.name || '').replace(/,/g, ' ');
            csvContent += `${c.id},"${name}",${c.status},${c.temp},${c.humidity || 'N/A'},"${c.location}","${note}"\n`;
        });

        const encodedUri = encodeURI(csvContent);
        const link = document.createElement("a");
        link.setAttribute("href", encodedUri);
        link.setAttribute("download", `contguard_report_${new Date().toISOString().slice(0, 10)}.csv`);
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
    }

    function startAutoRefresh() {
        let counter = STATE.refreshSeconds;
        const timerEl = document.getElementById('cg-auto-timer');

        setInterval(() => {
            counter--;
            if (timerEl) {
                timerEl.innerText = `Odświeżanie za: ${counter}s`;
            }
            if (counter <= 0) {
                counter = STATE.refreshSeconds;
                scrapeAndRender();
            }
        }, 1000);
    }

    // Inicjalizacja skryptu po załadowaniu strony
    window.addEventListener('load', () => {
        setTimeout(() => {
            injectStyles();
            createUI();
            scrapeAndRender();
            startAutoRefresh();

            // Obserwowanie zmian w DOM z zabezpieczeniem przed pętlą (ignore własnych zmian + debounce)
            const observer = new MutationObserver((mutations) => {
                if (!STATE.isOpen) return;

                // Sprawdzamy czy zmiana zaszła POZA naszym panelem
                const hasExternalMutation = mutations.some(m => {
                    const target = m.target;
                    return target && target.nodeType === 1 && !target.closest('#cg-sidebar-panel') && !target.closest('#cg-sidebar-toggle');
                });

                if (hasExternalMutation) {
                    if (STATE.debounceTimer) clearTimeout(STATE.debounceTimer);
                    STATE.debounceTimer = setTimeout(() => {
                        scrapePageData();
                        renderList();
                    }, 600);
                }
            });
            observer.observe(document.body, { childList: true, subtree: true });

        }, 1500); // Małe opóźnienie, aby platforma ContGuard załadowała dane API
    });

})();"}

{"title":"Snippets HUD","content":"// ==UserScript==
// @name         Tactical Snippets HUD
// @namespace    http://tampermonkey.net/
// @version      2.0.0
// @description  Pływający dock z gotowymi określeniami i kodem w stylu Tactical FUI (CSS, INNE, =) z edytorem RAW JSON
// @author       You
// @match        *://*/*
// @grant        GM_setValue
// @grant        GM_getValue
// @grant        GM_setClipboard
// @run-at       document-end
// ==/UserScript==

(function () {
  'use strict';

  // Zapobieganie wielokrotnemu uruchomieniu w ramkach iframe
  if (window.top !== window.self) return;

  const STORAGE_KEY = "tactical_snippets_data_v2";

  // Baza domyślna
  const defaultPhrases = [
    // --- KATEGORIA: CSS ---
    { cat: "CSS", tag: "ZERO_RADIUS", value: "*, *::before, *::after { border-radius: 0 !important; }" },
    { cat: "CSS", tag: "SHADOW_DROP", value: "--shadow-drop: rgba(32, 32, 32, 0.4) 0px 0px 0px 2px, rgba(0, 0, 0, 0.65) 0px 4px 6px -1px, rgba(255, 255, 255, 0.08) 0px 1px 0px inset;" },
    { cat: "CSS", tag: "SHADOW_INSET", value: "--shadow-inset: inset 0px 0px 0px 2px rgba(32, 32, 32, 0.4), inset 0px 4px 6px -1px rgba(0, 0, 0, 0.65), inset 0px 1px 0px rgba(255, 255, 255, 0.08);" },
    { cat: "CSS", tag: "BG_MODE", value: "--bg-mode: repeating-linear-gradient(-45deg, transparent, transparent 10px, rgba(255, 255, 255, 0.03) 10px, rgba(255, 255, 255, 0.03) 11px);" },
    { cat: "CSS", tag: "FONTS_IMPORT", value: '@import url("https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@400;700&family=Share+Tech+Mono&display=swap");' },
    { cat: "CSS", tag: "SCROLLBAR", value: "::-webkit-scrollbar { width: 8px; height: 8px; }\n::-webkit-scrollbar-track { background: var(--bg-color); }\n::-webkit-scrollbar-thumb { background: var(--border-color); border: 1px solid var(--bg-color); }" },
    { cat: "CSS", tag: "HIGHLIGHT", value: "--highlight-color: #f36c00;" },

    // --- KATEGORIA: INNE ---
    { cat: "INNE", tag: "CLIPBOARD", value: "navigator.clipboard.writeText(text).then(() => { /* copied */ });" },
    { cat: "INNE", tag: "ESCAPE_HTML", value: "function escapeHtml(t) { return String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/\"/g, '&quot;'); }" },
    { cat: "INNE", tag: "PREVENT_DEFAULT", value: "e.preventDefault();\ne.stopPropagation();" },
    { cat: "INNE", tag: "LOCAL_STORAGE", value: "localStorage.setItem(KEY, JSON.stringify(data));\nconst data = JSON.parse(localStorage.getItem(KEY) || '[]');" },
    { cat: "INNE", tag: "DEBOUNCE", value: "function debounce(fn, ms = 200) { let t; return (...args) => { clearTimeout(t); t = setTimeout(() => fn(...args), ms); }; }" },

    // --- KATEGORIA: = ---
    { cat: "=", tag: "STRICT_EQ", value: "===" },
    { cat: "=", tag: "STRICT_NEQ", value: "!==" },
    { cat: "=", tag: "ARROW_ASSIGN", value: "const fn = (payload) => {" },
    { cat: "=", tag: "DESTRUCTURE", value: "const { width, height, top, left } =" },
    { cat: "=", tag: "CSS_VAR_SET", value: "document.documentElement.style.setProperty('--highlight-color', value);" },
    { cat: "=", tag: "TERNARY_SET", value: "const result = condition ? valTrue : valFalse;" },
    { cat: "=", tag: "NULLISH_OR", value: "const value = rawInput ?? defaultValue;" },
    { cat: "=", tag: "BOUND_MATH", value: "const clamped = Math.max(minVal, Math.min(maxVal, currentVal));" }
  ];

  // Helpery storage
  function getStorageData() {
    try {
      if (typeof GM_getValue === "function") {
        return GM_getValue(STORAGE_KEY, defaultPhrases);
      }
      const raw = localStorage.getItem(STORAGE_KEY);
      return raw ? JSON.parse(raw) : defaultPhrases;
    } catch (e) {
      return defaultPhrases;
    }
  }

  function setStorageData(val) {
    try {
      if (typeof GM_setValue === "function") {
        GM_setValue(STORAGE_KEY, val);
      }
      localStorage.setItem(STORAGE_KEY, JSON.stringify(val));
    } catch (e) {
      console.error("Storage error:", e);
    }
  }

  // Wstrzyknięcie czcionek i FontAwesome do dokumentu
  const fontLink = document.createElement("link");
  fontLink.rel = "stylesheet";
  fontLink.href = "https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@400;700&family=Share+Tech+Mono&display=swap";
  document.head.appendChild(fontLink);

  const faLink = document.createElement("link");
  faLink.rel = "stylesheet";
  faLink.href = "https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css";
  document.head.appendChild(faLink);

  // Wstrzyknięcie stylów CSS
  const styleEl = document.createElement("style");
  styleEl.textContent = `
    :root {
       --shadow-drop: rgba(32, 32, 32, 0.4) 0px 0px 0px 2px, rgba(0, 0, 0, 0.65) 0px 4px 6px -1px, rgba(255, 255, 255, 0.08) 0px 1px 0px inset;
       --shadow-inset: inset 0px 0px 0px 2px rgba(32, 32, 32, 0.4), inset 0px 4px 6px -1px rgba(0, 0, 0, 0.65), inset 0px 1px 0px rgba(255, 255, 255, 0.08);
       --padding: 0.125rem;
       --gap: 0.125rem;
       --bg-tertiary: #2e2e2e;
       --border-color: #2a2a2a;
       --panel-bg: #2a2a2a;
       --card-bg: #1e1e1e;
       --text-muted: #858585;
       --text-color: #e0e0e0;
       --highlight-color: #f36c00;
       --border-color-hover: #444444;
       --hover-bg: #3c3c3c;
       --bg-color: #121212;
       --danger-color: #dc3545;
       --font-main: "JetBrains Mono", monaco, courier, monospace;
       --transition-speed: 0.2s;
       --transition-ease: ease;
       --transition-ui: background-color var(--transition-speed) var(--transition-ease),
          color var(--transition-speed) var(--transition-ease),
          border-color var(--transition-speed) var(--transition-ease),
          box-shadow var(--transition-speed) var(--transition-ease);
       --bg-mode: repeating-linear-gradient(-45deg, transparent, transparent 10px, rgba(255, 255, 255, 0.03) 10px, rgba(255, 255, 255, 0.03) 11px);
    }

    #tacticalDockRoot *, #tacticalDockRoot *::before, #tacticalDockRoot *::after {
       border-radius: 0 !important;
       box-sizing: border-box;
       user-select: none;
       font-family: var(--font-main);
    }

    #tacticalDockRoot ::-webkit-scrollbar { width: 8px; height: 8px; }
    #tacticalDockRoot ::-webkit-scrollbar-track { background: var(--bg-color); }
    #tacticalDockRoot ::-webkit-scrollbar-thumb { background: var(--border-color); border: 1px solid var(--bg-color); }
    #tacticalDockRoot ::-webkit-scrollbar-thumb:hover { background: var(--highlight-color); }

    .tac-btn-bg {
       display: flex;
       justify-content: center;
       align-items: center;
       box-shadow: var(--shadow-inset);
       padding: var(--padding);
       gap: var(--gap);
       position: relative;
       overflow: hidden;
       width: fit-content;
       border: 1px solid var(--border-color);
       background: var(--card-bg);
       box-sizing: border-box;
       transition: var(--transition-ui);
    }
    .tac-btn-bg:hover { border-color: var(--border-color-hover); }
    .tac-btn-bg.tac-btn-bg-full { width: calc(100% - 0.25rem); margin: 0.125rem; }
    .tac-btn-bg.tac-btn-bg-tab { flex: 1; margin: 0; border: none; border-right: 1px solid var(--border-color); }
    .tac-btn-bg.tac-btn-bg-tab:last-child { border-right: none; }
    .tac-btn-bg:has(.tac-se-select-wrap), .tac-btn-bg.tac-btn-bg-dropdown { overflow: visible !important; }
    .tac-btn-bg:has(.tac-se-select-open) { z-index: 105; }

    .tac-setting-label {
       display: flex; align-items: center; justify-content: space-between;
       cursor: pointer; color: var(--text-color); font-size: 0.75rem;
       text-transform: uppercase; user-select: none; gap: 8px; width: 100%;
       font-weight: 600; letter-spacing: 0.05em; transition: var(--transition-ui);
    }
    .tac-setting-label-text { display: flex; align-items: center; gap: 8px; }
    .tac-setting-label i { color: var(--text-muted); transition: color 0.2s ease; }
    .tac-setting-item:hover .tac-setting-label i { color: var(--highlight-color); }

    .tac-setting-label input[type="checkbox"] {
       width: 18px; height: 18px; min-width: 18px; cursor: pointer; accent-color: var(--highlight-color);
       border: 1px solid var(--border-color); background-color: var(--panel-bg);
       appearance: none; -webkit-appearance: none; position: relative; transition: var(--transition-ui);
       box-shadow: var(--shadow-inset); box-sizing: border-box; margin: 0;
    }
    .tac-setting-label input[type="checkbox"]:checked {
       background-color: var(--highlight-color); outline-offset: -2px; outline: 1px solid var(--bg-color);
    }
    .tac-setting-label input[type="checkbox"]:checked::after {
       content: "✓"; position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%);
       color: #000; font-size: 0.75rem; font-weight: 900; line-height: 1;
    }

    .tac-setting-item.tac-setting-range { display: flex; flex-direction: column; gap: 4px; }
    .tac-setting-control { display: flex; align-items: center; gap: 10px; width: 100%; }
    .tac-setting-control input[type="range"] {
       flex: 1; height: 12px; background: var(--bg-color); outline: none;
       border: 1px solid var(--border-color); cursor: pointer; -webkit-appearance: none !important; margin: 0;
    }
    .tac-setting-control input[type="range"]::-webkit-slider-runnable-track {
       height: 10px; background: var(--border-color-hover); border: 1px solid var(--border-color);
    }
    .tac-setting-control input[type="range"]::-webkit-slider-thumb {
       -webkit-appearance: none !important; width: 14px; height: 14px;
       background: var(--highlight-color) !important; cursor: pointer; border: 2px solid #000 !important; margin-top: -3px;
    }
    .tac-setting-value {
       color: var(--highlight-color); font-weight: bold; min-width: 50px;
       text-align: right; font-size: 0.75rem; font-family: var(--font-main);
    }

    .tac-se-select-wrap { position: relative; width: 100%; z-index: 1; }
    .tac-se-select-wrap.tac-se-select-open { z-index: 110; }
    .tac-se-select-btn {
       background-color: transparent; color: var(--text-color); border: 1px solid var(--border-color);
       padding: 0 0.8rem; cursor: pointer; font-size: 0.8rem; font-weight: 600; font-family: var(--font-main);
       text-transform: uppercase; display: flex; justify-content: space-between; align-items: center;
       transition: var(--transition-ui); height: 32px; box-sizing: border-box; width: 100%; position: relative;
    }
    .tac-se-select-btn:hover { color: var(--highlight-color); background: var(--hover-bg); }
    .tac-se-select-btn .tac-se-select-arrow { font-size: 0.7rem; transition: transform var(--transition-speed); color: var(--text-muted); pointer-events: none; }
    .tac-se-select-btn.tac-se-open { background: var(--bg-tertiary); }
    .tac-se-select-btn.tac-se-open .tac-se-select-arrow { transform: rotate(180deg); color: var(--highlight-color); }

    .tac-se-select-list {
       position: absolute; top: calc(100% + 1px); left: -1px; right: -1px;
       background-color: var(--panel-bg); border: 1px solid var(--border-color); z-index: 9999;
       display: none; box-shadow: var(--shadow-drop); max-height: 200px; overflow-y: auto;
    }
    .tac-se-select-list.tac-se-visible { display: block !important; }
    .tac-se-select-item {
       padding: 0 0.5rem; cursor: pointer; font-size: 0.8rem; font-weight: 600;
       font-family: var(--font-main); color: var(--text-color); border-bottom: 1px solid var(--border-color);
       border-left: 3px solid transparent; display: flex; align-items: center; transition: var(--transition-ui);
       height: 30px; box-sizing: border-box; text-transform: uppercase;
    }
    .tac-se-select-item:last-child { border-bottom: none; }
    .tac-se-select-item .tac-se-select-prefix { margin-right: 0.5rem; opacity: 0; color: var(--highlight-color); transition: opacity var(--transition-speed); font-weight: 700; }
    .tac-se-select-item:hover, .tac-se-select-item.tac-se-selected { background-color: var(--hover-bg); color: var(--highlight-color); border-left: 3px solid var(--highlight-color); }
    .tac-se-select-item:hover .tac-se-select-prefix, .tac-se-select-item.tac-se-selected .tac-se-select-prefix { opacity: 1; }

    .tac-dock {
       position: fixed; top: 40px; right: 40px; width: 380px; background: var(--panel-bg);
       border: 1px solid var(--border-color); box-shadow: var(--shadow-drop); z-index: 999999;
       display: flex; flex-direction: column; font-family: var(--font-main); color: var(--text-color);
    }
    .tac-header {
       background-color: var(--card-bg); border-bottom: 1px solid var(--border-color); color: var(--highlight-color);
       display: flex; justify-content: space-between; align-items: center; flex-shrink: 0; padding: 0.2rem 0.7rem;
       box-shadow: var(--shadow-drop); background-image: var(--bg-mode); height: 40px; box-sizing: border-box; cursor: grab;
    }
    .tac-header:active { cursor: grabbing; }
    .tac-title { font-weight: 700; text-transform: uppercase; letter-spacing: 2px; font-size: 0.82rem; display: flex; align-items: center; gap: 8px; }

    .tac-header-btn {
       background: var(--bg-tertiary); border: 1px solid var(--border-color); color: var(--text-muted);
       transition: var(--transition-ui); width: 30px; height: 26px; display: flex; align-items: center;
       justify-content: center; cursor: pointer; box-shadow: var(--shadow-drop); font-size: 0.75rem;
    }
    .tac-header-btn:hover { color: var(--highlight-color); background: var(--hover-bg); border-color: var(--border-color-hover); }

    .tac-tabs {
       display: flex; flex-wrap: nowrap; gap: 0; background: var(--bg-tertiary);
       border-bottom: 1px solid var(--border-color); box-shadow: var(--shadow-drop);
    }
    .tac-tab {
       width: 100%; display: flex; align-items: center; justify-content: center; gap: 0.4rem; font-size: 0.65rem;
       padding: 6px 4px; background: var(--bg-tertiary); border: 1px solid var(--border-color); color: var(--text-muted);
       transition: var(--transition-ui); font-weight: 600; text-transform: uppercase; cursor: pointer;
       font-family: var(--font-main); box-shadow: var(--shadow-drop);
    }
    .tac-tab i { color: var(--highlight-color); transition: var(--transition-ui); }
    .tac-tab:hover { color: var(--highlight-color); background: var(--hover-bg); }
    .tac-tab:hover i { color: var(--text-color); }
    .tac-tab.active { background: var(--card-bg); color: var(--highlight-color); }
    .tac-tab.active i { color: var(--text-color); }

    .tac-search-wrap { padding: 0.25rem; background: var(--bg-tertiary); border-bottom: 1px solid var(--border-color); }
    .tac-search-input {
       width: 100%; background: var(--card-bg); border: 1px solid var(--border-color); color: var(--text-color);
       padding: 6px 8px; font-family: var(--font-main); font-size: 0.75rem; outline: none; box-shadow: var(--shadow-inset);
    }
    .tac-search-input:focus { border-bottom-color: var(--highlight-color); }

    .tac-body { flex: 1; overflow-y: auto; overflow-x: hidden; padding: 0.125rem; background: var(--bg-tertiary); max-height: 420px; }
    .tac-body.collapsed { display: none; }

    .tac-setting-item {
       border-bottom: 1px solid var(--border-color); background-color: var(--panel-bg); border-left: 1px solid var(--border-color);
       box-shadow: var(--shadow-drop); margin-bottom: 0.125rem; padding: 0.4rem 0.6rem; transition: var(--transition-ui);
       position: relative; z-index: 1;
    }
    .tac-setting-item:last-child { margin-bottom: 0; }
    .tac-setting-item:hover { border-left-color: var(--highlight-color); background: var(--hover-bg); }
    .tac-setting-item:hover .tac-setting-label { color: var(--highlight-color); }
    .tac-setting-item:has(.tac-se-select-open) { z-index: 1000 !important; }

    .tac-snippet-item {
       border-bottom: 1px solid var(--border-color); background-color: var(--panel-bg); border-left: 3px solid var(--border-color);
       box-shadow: var(--shadow-drop); margin-bottom: 0.125rem; padding: 0.45rem 0.65rem; transition: var(--transition-ui);
       position: relative; cursor: pointer; display: flex; flex-direction: column; gap: 4px;
    }
    .tac-snippet-item:last-child { margin-bottom: 0; }
    .tac-snippet-item:hover { border-left-color: var(--highlight-color); background: var(--hover-bg); }
    .tac-snippet-head { display: flex; align-items: center; justify-content: space-between; font-size: 0.68rem; text-transform: uppercase; font-weight: 700; letter-spacing: 0.05em; }
    .tac-snippet-tag { color: var(--highlight-color); display: flex; align-items: center; gap: 6px; }
    .tac-snippet-hint { color: var(--text-muted); font-size: 0.62rem; transition: var(--transition-ui); }
    .tac-snippet-item:hover .tac-snippet-hint { color: var(--text-color); }

    .tac-snippet-code {
       font-size: 0.78rem; color: var(--text-muted); word-break: break-all; line-height: 1.35;
       background: var(--card-bg); padding: 4px 6px; border: 1px solid var(--border-color); box-shadow: var(--shadow-inset);
       transition: var(--transition-ui); white-space: pre-wrap;
    }
    .tac-snippet-code:hover { color: var(--text-color); }
    .tac-snippet-item.copied { border-left-color: #28a745 !important; background: #1c2e1f !important; }
    .tac-snippet-item.copied .tac-snippet-tag, .tac-snippet-item.copied .tac-snippet-hint { color: #28a745; }

    .tac-footer {
       border-top: 1px solid var(--border-color); padding: 0px 11px; flex-shrink: 0; background-image: var(--bg-mode);
       background-color: var(--card-bg); display: flex; flex-direction: column; justify-content: flex-end; height: 15px;
    }
    .tac-footer.collapsed { display: none; }
    .tac-footer-info {
       display: flex; justify-content: space-between; align-items: center; font-size: 0.65rem;
       color: var(--text-muted); font-family: "Share Tech Mono", monospace; text-transform: uppercase; letter-spacing: 0.5px;
    }
    .tac-footer-info i { color: var(--highlight-color); font-size: 0.7rem; }

    .tac-toast {
       position: absolute; bottom: -28px; left: -1px; right: -1px; background: var(--highlight-color); color: #000;
       font-size: 0.7rem; font-family: "Share Tech Mono", monospace; font-weight: 700; letter-spacing: 1px;
       padding: 4px 8px; text-align: center; text-transform: uppercase; box-shadow: var(--shadow-drop);
       opacity: 0; transform: translateY(-4px); transition: var(--transition-ui); pointer-events: none; z-index: 9999999;
    }
    .tac-toast.active { opacity: 1; transform: translateY(0); }

    .tac-overlay {
       position: fixed; top: 0; left: 0; width: 100%; height: 100%; z-index: 999998;
       opacity: 0; pointer-events: none; transition: opacity 0.3s ease; background: rgba(0, 0, 0, 0.65);
    }
    .tac-overlay.active { opacity: 1; pointer-events: auto; }

    .tac-sidebar {
       position: fixed; top: 0; right: 0; width: 620px; max-width: 92%; height: 100vh;
       background: var(--panel-bg); border-left: 2px solid var(--border-color); box-shadow: var(--shadow-drop);
       z-index: 999999; display: flex; flex-direction: column; transform: translateX(100%);
       transition: transform 0.3s cubic-bezier(0.1, 0.9, 0.2, 1); overflow: hidden;
       font-family: var(--font-main); color: var(--text-color);
    }
    .tac-sidebar.active { transform: translateX(0); }

    .tac-drawer-body { flex: 1; overflow-y: auto; padding: 0.25rem; background: var(--bg-tertiary); }
    .tac-config-card {
       background: var(--panel-bg); border: 1px solid var(--border-color); box-shadow: var(--shadow-drop);
       padding: 8px; margin-bottom: 0.25rem; display: flex; flex-direction: column; gap: 6px;
    }
    .tac-config-row { display: flex; gap: 6px; align-items: center; }
    .tac-config-input {
       background: var(--card-bg); border: 1px solid var(--border-color); color: var(--text-muted);
       font-family: var(--font-main); font-size: 0.72rem; padding: 4px 6px; outline: none; box-shadow: var(--shadow-inset);
    }
    .tac-config-input:focus { border-bottom-color: var(--highlight-color); color: var(--text-color); }
    .tac-config-textarea {
       width: 100%; background: var(--card-bg); border: 1px solid var(--border-color); color: var(--text-muted);
       font-family: var(--font-main); font-size: 0.72rem; padding: 6px; min-height: 48px; resize: vertical;
       outline: none; box-shadow: var(--shadow-inset);
    }
    .tac-config-textarea:focus { border-bottom-color: var(--highlight-color); color: var(--text-color); }

    .tac-btn-action {
       background: var(--bg-tertiary); border: 1px solid var(--border-color); color: var(--text-muted);
       cursor: pointer; font-size: 0.72rem; padding: 4px 8px; transition: var(--transition-ui);
       font-weight: 700; text-transform: uppercase; font-family: var(--font-main); box-shadow: var(--shadow-drop);
    }
    .tac-btn-action i { color: var(--text-color); transition: var(--transition-ui); }
    .tac-btn-action:hover i { color: var(--highlight-color); }
    .tac-btn-action:hover { color: var(--text-color); background: var(--hover-bg); border-color: var(--border-color-hover); }
    .tac-btn-action.btn-danger:hover { color: var(--danger-color); border-color: var(--border-color-hover); }
    .tac-btn-action.btn-danger:hover i { color: var(--danger-color); }

    .tac-json-manager-container { display: flex; flex-direction: column; height: 100%; gap: 6px; box-sizing: border-box; }
    .tac-json-editor-area {
       width: 100%; flex: 1; min-height: 380px; background: var(--card-bg); border: 1px solid var(--border-color);
       color: #98c379; font-family: var(--font-main); font-size: 0.75rem; padding: 10px; outline: none;
       resize: none; box-shadow: var(--shadow-inset); line-height: 1.45; white-space: pre; tab-size: 2;
       user-select: text; box-sizing: border-box;
    }
