    dockToast._t = setTimeout(() => dockToast.classList.remove("active"), 1600);
  }

  function copyText(str, cardEl) {
    if (typeof GM_setClipboard === "function") {
      GM_setClipboard(str);
      if (cardEl) {
        cardEl.classList.add("copied");
        setTimeout(() => cardEl.classList.remove("copied"), 600);
      }
      showToast(`SKOPIOWANO: ${str.substring(0, 24)}${str.length > 24 ? '...' : ''}`);
      return;
    }
    navigator.clipboard.writeText(str).then(() => {
      if (cardEl) {
        cardEl.classList.add("copied");
        setTimeout(() => cardEl.classList.remove("copied"), 600);
      }
      showToast(`SKOPIOWANO: ${str.substring(0, 24)}${str.length > 24 ? '...' : ''}`);
    }).catch(() => showToast("BŁĄD SCHOWKA"));
  }

  function renderMainList() {
    const filterText = dockFilter.value.toLowerCase().trim();
    dockItemsList.innerHTML = "";

    const filtered = phrases.filter(item => {
      const matchCat = activeCategory === "ALL" || item.cat === activeCategory;
      const matchQuery = item.tag.toLowerCase().includes(filterText) ||
                         item.value.toLowerCase().includes(filterText) ||
                         item.cat.toLowerCase().includes(filterText);
      return matchCat && matchQuery;
    });

    itemCountLabel.textContent = `${filtered.length} / ${phrases.length} REKORDÓW`;

