      if (!Array.isArray(parsed)) throw new Error("Musi być tablicą []");

      const isValid = parsed.every(item => item && typeof item === 'object' && typeof item.cat === 'string' && typeof item.tag === 'string' && typeof item.value === 'string');
      if (!isValid) throw new Error("Wymagana struktura: { cat, tag, value }");

      phrases = parsed;
      setStorageData(phrases);
      renderMainList();
      renderSettingsEditor();
      showToast("STRUKTURA JSON ZAŁADOWANA");
    } catch (err) {
      showToast("BŁĄD: " + err.message);
