  copyJsonBtn.addEventListener("click", () => {
    if (!rawJsonArea.value.trim()) return;
    copyText(rawJsonArea.value);
  });

  // Drawer
  function openSettings() {
    renderSettingsEditor();
    settingsSidebar.classList.add("active");
    settingsOverlay.classList.add("active");
  }
  function closeSettings() {
    settingsSidebar.classList.remove("active");
    settingsOverlay.classList.remove("active");
  }

  openSettingsBtn.addEventListener("click", openSettings);
  closeSettingsBtn.addEventListener("click", closeSettings);
  settingsOverlay.addEventListener("click", closeSettings);

  // Przeciąganie okna (Drag HUD)
  let isDragging = false, startX, startY, initLeft, initTop;

  dockHeader.addEventListener("mousedown", (e) => {
    if (e.target.closest("button")) return;
    isDragging = true;
    const rect = dock.getBoundingClientRect();
    initLeft = rect.left;
    initTop = rect.top;
    startX = e.clientX;
    startY = e.clientY;

    dock.style.right = "auto";
    dock.style.left = initLeft + "px";
    dock.style.top = initTop + "px";

    document.addEventListener("mousemove", onMouseMove);
    document.addEventListener("mouseup", onMouseUp);
  });

  function onMouseMove(e) {
    if (!isDragging) return;
    let nx = initLeft + (e.clientX - startX);
    let ny = initTop + (e.clientY - startY);

    nx = Math.max(10, Math.min(window.innerWidth - dock.offsetWidth - 10, nx));
    ny = Math.max(10, Math.min(window.innerHeight - dock.offsetHeight - 10, ny));

    dock.style.left = nx + "px";
    dock.style.top = ny + "px";
  }

  function onMouseUp() {
    isDragging = false;
    document.removeEventListener("mousemove", onMouseMove);
    document.removeEventListener("mouseup", onMouseUp);
  }

  // Zakładki HUD
  dockTabs.querySelectorAll(".tac-tab").forEach(tab => {
    tab.addEventListener("click", () => {
      dockTabs.querySelectorAll(".tac-tab").forEach(t => t.classList.remove("active"));
      tab.classList.add("active");
      activeCategory = tab.dataset.category;
      renderMainList();
    });
  });

  dockFilter.addEventListener("input", renderMainList);

  // Zwijanie HUD
  let isCollapsed = false;
  toggleCollapseBtn.addEventListener("click", () => {
    isCollapsed = !isCollapsed;
    dockItemsList.classList.toggle("collapsed", isCollapsed);
    dockSearchWrap.classList.toggle("collapsed", isCollapsed);
    dockTabs.classList.toggle("collapsed", isCollapsed);
    dockFooter.classList.toggle("collapsed", isCollapsed);
    toggleCollapseBtn.innerHTML = isCollapsed ? '<i class="fas fa-plus"></i>' : '<i class="fas fa-minus"></i>';
  });

  resetPosBtn.addEventListener("click", () => {
    dock.style.left = "auto";
    dock.style.top = "40px";
    dock.style.right = "40px";
  });

  // Start
  renderMainList();
})();"}

{"title":"auto","content":"// ==UserScript==
// @name         Universal Web Action Recorder & Generator (Clean & Precision)
// @namespace    https://github.com/universal-action-recorder
// @version      4.0.0
// @description  Rejestrator akcji z wykrywaniem zachowań (Hover) i agresywną aktywacją wygórowanych/zablokowanych przycisków.
// @match        *://*/*
// @run-at       document-end
// @grant        none
// ==/UserScript==

(function () {
  'use strict';

  // Ignoruj osadzone ramki iframe bez dokumentu głównego
  if (window !== window.top) {
    try {
      if (!window.location.href.startsWith('http')) return;
    } catch (e) {
      return;
    }
  }

  const state = {
    isRecording: false,
    recordedActions: [],
    lastActionTime: 0,
    inputDebounceTimer: null,
    hoverTimer: null,
    lastHoveredElement: null,
    pendingInputs: new Map(),
    lastRecordedEvent: { type: '', target: null, time: 0 }
  };

  const hostElement = document.createElement('div');
  hostElement.id = 'universal-rec-host';
  hostElement.style.position = 'fixed';
  hostElement.style.bottom = '16px';
  hostElement.style.right = '16px';
  hostElement.style.zIndex = '2147483647';
  document.documentElement.appendChild(hostElement);

  const shadow = hostElement.attachShadow({ mode: 'open' });

  const styleEl = document.createElement('style');
  styleEl.textContent = `
    * { box-sizing: border-box; margin: 0; padding: 0; font-family: ui-monospace, SFMono-Regular, Consolas, monospace; font-size: 11px; user-select: none; }
    #hud-panel { width: 420px; background: #090d16; border: 1px solid #1e293b; border-left: 3px solid #10b981; color: #f1f5f9; box-shadow: 0 12px 35px rgba(0, 0, 0, 0.75); display: flex; flex-direction: column; gap: 10px; padding: 12px; transition: all 0.2s ease; }
    #hud-panel.recording { border-left-color: #ef4444; }
    .header { display: flex; align-items: center; justify-content: space-between; border-bottom: 1px solid #1e293b; padding-bottom: 8px; }
    .title-group { display: flex; align-items: center; gap: 8px; font-weight: 700; color: #f8fafc; }
    .status-dot { width: 8px; height: 8px; border-radius: 50%; background: #64748b; }
    .status-dot.active { background: #ef4444; box-shadow: 0 0 10px #ef4444; animation: pulse 1.2s infinite; }
    @keyframes pulse { 0%, 100% { opacity: 1; transform: scale(1); } 50% { opacity: 0.4; transform: scale(0.9); } }
    .header-btns { display: flex; gap: 4px; }
    .icon-btn { background: #111827; border: 1px solid #1f2937; color: #94a3b8; width: 22px; height: 22px; display: flex; align-items: center; justify-content: center; cursor: pointer; }
    .icon-btn:hover { background: #1e293b; color: #f8fafc; }
    .badge { background: #111827; border: 1px solid #1f2937; color: #94a3b8; padding: 2px 6px; font-size: 9px; font-weight: 600; }
    .stats { display: flex; justify-content: space-between; color: #94a3b8; font-size: 10px; }
    .stats strong { color: #38bdf8; }
    .controls-grid { display: grid; grid-template-columns: 1fr 1fr 1.2fr 1fr; gap: 6px; }
    .btn { padding: 7px 4px; background: #111827; border: 1px solid #1f2937; color: #cbd5e1; font-weight: 700; cursor: pointer; text-align: center; transition: all 0.15s; }
    .btn:hover:not(:disabled) { background: #1e293b; border-color: #38bdf8; color: #ffffff; }
    .btn:disabled { opacity: 0.35; cursor: not-allowed; }
    .btn-record { border-color: #ef4444; color: #ef4444; }
    .btn-record.is-rec { background: #ef4444; color: #000; }
    .btn-generate { border-color: #10b981; color: #10b981; }
    .btn-generate:hover:not(:disabled) { background: #10b981; color: #022c22; }
    .btn-mini { padding: 4px 8px; font-size: 9px; font-weight: bold; border-width: 1px; border-style: solid; background: #111827; cursor: pointer; transition: all 0.2s;}
    .btn-mini:hover { filter: brightness(1.3); }
    .action-feed { max-height: 130px; overflow-y: auto; background: #05070d; border: 1px solid #1e293b; padding: 5px; display: flex; flex-direction: column; gap: 3px; }
    .feed-item { display: flex; align-items: center; background: #0d131f; padding: 4px 6px; font-size: 9px; color: #94a3b8; border-left: 2px solid #38bdf8; }
    .feed-item.type-hover { border-left-color: #f59e0b; }
    .feed-item.type-force { border-left-color: #d946ef; }
    .feed-item span.action-type { font-weight: 700; color: #38bdf8; min-width: 50px; }
    .feed-item.type-hover span.action-type { color: #f59e0b; }
    .feed-item.type-force span.action-type { color: #d946ef; }
    .feed-item span.action-info { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; flex: 1; margin-left: 6px; }
    .output-section { display: none; flex-direction: column; gap: 6px; border-top: 1px dashed #1e293b; padding-top: 8px; }
    .output-bar { display: flex; justify-content: space-between; align-items: center; color: #94a3b8; font-size: 10px; }
    textarea#output-code { width: 100%; height: 190px; background: #030712; border: 1px solid #1e293b; color: #38bdf8; padding: 8px; font-size: 10px; resize: vertical; white-space: pre; user-select: text; }
    .collapsed-view { display: none; cursor: pointer; align-items: center; gap: 8px; background: #090d16; border: 1px solid #1e293b; border-left: 3px solid #10b981; padding: 8px 12px; box-shadow: 0 6px 20px rgba(0, 0, 0, 0.7); }
    .hint { color: #64748b; font-size: 9px; text-align: center; margin-top: 4px; font-style: italic; }
  `;
  shadow.appendChild(styleEl);

  const hudContainer = document.createElement('div');
  hudContainer.innerHTML = `
    <div id="hud-panel">
      <div class="header">
        <div class="title-group"><div class="status-dot" id="dot"></div><span>RECORDER // BEHAVIOR_CORE</span></div>
        <div class="header-btns">
          <span class="badge" id="rec-status">STANDBY</span>
          <button class="icon-btn" id="btn-collapse" title="Zwiń HUD">_</button>
        </div>
      </div>
      <div class="stats"><span>Zarejestrowane akcje:</span><strong id="counter-display">0</strong></div>
      <div class="action-feed" id="action-feed">
        <div style="color: #475569; font-style: italic; text-align: center; padding: 6px;">Czekam na rozpoczęcie nagrywania...</div>
      </div>
      <div class="hint">Wskazówka: Przytrzymaj klawisz ALT i kliknij, aby wymusić kliknięcie zablokowanego elementu.</div>
      <div class="controls-grid">
        <button id="btn-rec" class="btn btn-record">● REC</button>
        <button id="btn-stop" class="btn" disabled>■ STOP</button>
        <button id="btn-gen" class="btn btn-generate" disabled>⚡ GENERUJ</button>
        <button id="btn-reset" class="btn">RESET</button>
      </div>
      <div class="output-section" id="output-box">
        <div class="output-bar">
          <span>KOD USERSCRIPTU:</span>
          <div style="display:flex; gap: 6px;">
            <button class="btn-mini" id="btn-test" style="border-color: #f59e0b; color: #f59e0b;" title="Uruchom skrypt teraz na stronie">▶ TESTUJ</button>
            <button class="btn-mini" id="btn-download" style="border-color: #3b82f6; color: #3b82f6;" title="Pobierz jako plik .user.js">↓ POBIERZ</button>
            <button class="btn-mini" id="btn-copy" style="border-color: #10b981; color: #10b981;">KOPIUJ</button>
          </div>
        </div>
        <textarea id="output-code" readonly></textarea>
      </div>
    </div>
    <div class="collapsed-view" id="collapsed-panel">
      <div class="status-dot" id="collapsed-dot"></div><span style="font-weight: 700; color: #f8fafc;">REC</span>
      <span style="color: #38bdf8;" id="collapsed-count">[0]</span>
    </div>
  `;
  shadow.appendChild(hudContainer);

  const panel = shadow.getElementById('hud-panel');
  const collapsedPanel = shadow.getElementById('collapsed-panel');
  const dot = shadow.getElementById('dot');
  const collapsedDot = shadow.getElementById('collapsed-dot');
  const statusBadge = shadow.getElementById('rec-status');
  const counterDisplay = shadow.getElementById('counter-display');
  const collapsedCount = shadow.getElementById('collapsed-count');
  const actionFeed = shadow.getElementById('action-feed');
  const outputBox = shadow.getElementById('output-box');
  const outputCode = shadow.getElementById('output-code');

  const btnRec = shadow.getElementById('btn-rec');
  const btnStop = shadow.getElementById('btn-stop');
  const btnGen = shadow.getElementById('btn-gen');
  const btnReset = shadow.getElementById('btn-reset');
  const btnCopy = shadow.getElementById('btn-copy');
  const btnTest = shadow.getElementById('btn-test');
  const btnDownload = shadow.getElementById('btn-download');
  const btnCollapse = shadow.getElementById('btn-collapse');

  function getCleanClasses(el) {
    if (!el) return [];
    const rawClass = typeof el.className === 'string' ? el.className : (el.className?.baseVal || '');
    if (!rawClass) return [];
    return rawClass.split(/\s+/).filter(c => {
      const clean = c.trim();
      return clean.length > 1 && !clean.startsWith('ng-') && !clean.startsWith('cdk-') && !clean.startsWith('mat-') && !clean.includes(':') && !clean.match(/^[a-z]{1,2}[0-9a-z]{6,}$/i);
    });
  }

  function getReadableLabel(el) {
    if (!el) return '';
    const text = el.innerText || el.textContent || '';
    const cleanText = text.replace(/\s+/g, ' ').trim();
    if (cleanText.length > 0 && cleanText.length <= 30) return `"${cleanText}"`;
    const aria = el.getAttribute('aria-label') || el.getAttribute('placeholder') || el.getAttribute('title') || el.getAttribute('name');
    if (aria) return `[${aria.trim()}]`;
    if (el.id) return `#${el.id}`;
    const classes = getCleanClasses(el);
    if (classes.length > 0) return `.${classes[0]}`;
    return el.tagName.toLowerCase();
  }

  function getLogicalTarget(el) {
    if (!el) return null;
    const node = el.nodeType === Node.TEXT_NODE ? el.parentElement : el;
    if (!node || !node.closest) return node;
    const parentAction = node.closest('button, a, [role="button"], [role="tab"], [role="menuitem"], input[type="submit"], input[type="button"], label, select, summary');
    if (parentAction && !hostElement.contains(parentAction)) return parentAction;
    return node;
  }

  function getCleanSelector(el) {
    if (!el || el === document.body || el === document.documentElement) return null;
    const tag = el.tagName.toLowerCase();

    // 1. Priorytet 1: Oczywiste i unikalne ID
    if (el.id && typeof el.id === 'string' && !el.id.match(/^cdk-|^mat-|:\w+:|\d{5,}/)) {
      const idSel = `#${CSS.escape(el.id)}`;
      try { if (document.querySelectorAll(idSel).length === 1) return idSel; } catch(e){}
    }

    // 2. Priorytet 2: Unikalne i stabilne atrybuty wartościowe
    // Wymuszamy sprawdzanie, czy dany atrybut jest W 100% UNIKALNY na całej stronie
    const uniqueAttrs = ['data-testid', 'data-test', 'data-cy', 'data-qa', 'data-id', 'name', 'aria-label', 'placeholder', 'title', 'alt', 'for'];
    for (const attr of uniqueAttrs) {
      if (el.hasAttribute(attr) && el.getAttribute(attr).trim() !== '') {
        const attrSel = `${tag}[${attr}="${CSS.escape(el.getAttribute(attr))}"]`;
        try { if (document.querySelectorAll(attrSel).length === 1) return attrSel; } catch (e) {}
      }
    }

    // 3. Priorytet 3: Dopasowanie po tekście dla przycisków/linków (bardzo odporne)
    if ((tag === 'button' || tag === 'a' || tag === 'span' || tag === 'label' || el.getAttribute('role') === 'menuitem') && el.textContent.trim()) {
      const text = el.textContent.replace(/\s+/g, ' ').trim();
      if (text.length > 0 && text.length < 50) return { type: 'textMatch', tag, text };
    }

    // 4. Priorytet 4: Złożona kombinacja klas i węzłów rodziców
    const classes = getCleanClasses(el);
    if (classes.length > 0) {
      const fullClassSel = `${tag}.${classes.map(c => CSS.escape(c)).join('.')}`;
      try { if (document.querySelectorAll(fullClassSel).length === 1) return fullClassSel; } catch (e) {}
    }

    let current = el, parts = [], depth = 0;
    while (current && current !== document.body && depth < 3) {
      let part = current.tagName.toLowerCase();
      const curClasses = getCleanClasses(current);
      if (current.id && !current.id.match(/^cdk-|^mat-|:\w+:|\d{5,}/)) {
        part += `#${CSS.escape(current.id)}`;
        parts.unshift(part); break;
      } else if (curClasses.length > 0) {
        part += `.${CSS.escape(curClasses[0])}`;
      }
      parts.unshift(part);
      const candidate = parts.join(' > ');
      try { if (document.querySelectorAll(candidate).length === 1) return candidate; } catch (e) {}
      current = current.parentElement;
      depth++;
    }

    if ((tag === 'button' || tag === 'a' || el.getAttribute('role') === 'menuitem') && el.textContent.trim()) {
      const text = el.textContent.replace(/\s+/g, ' ').trim();
      if (text.length > 0 && text.length < 50) return { type: 'textMatch', tag, text };
    }
    return parts.join(' > ');
  }

  function addFeedItem(type, detail) {
    const emptyNotice = actionFeed.querySelector('div[style*="italic"]');
    if (emptyNotice) emptyNotice.remove();
    const item = document.createElement('div');
    item.className = `feed-item ${type === 'hover' ? 'type-hover' : type === 'force' ? 'type-force' : ''}`;
    item.innerHTML = `<span class="action-type">${type.toUpperCase()}</span><span class="action-info" title="${detail}">${detail}</span>`;
    actionFeed.prepend(item);
    if (actionFeed.children.length > 25) actionFeed.lastElementChild.remove();
  }

  function recordStep(type, targetEl, extra = {}) {
    if (!state.isRecording || !targetEl || hostElement.contains(targetEl)) return;
    const logicalEl = getLogicalTarget(targetEl);
    if (!logicalEl) return;

    const now = Date.now();
    if (type === 'click' && state.lastRecordedEvent.type === 'click' && state.lastRecordedEvent.target === logicalEl && now - state.lastRecordedEvent.time < 300) return;

    const selector = getCleanSelector(logicalEl);
    if (!selector) return;

    const delay = state.lastActionTime === 0 ? 300 : Math.min(Math.max(now - state.lastActionTime, 200), 2000);
    state.lastActionTime = now;
    state.lastRecordedEvent = { type, target: logicalEl, time: now };

    const readableName = getReadableLabel(logicalEl);
    state.recordedActions.push({ type, selector, readableName, delay, ...extra });

    counterDisplay.textContent = state.recordedActions.length;
    collapsedCount.textContent = `[${state.recordedActions.length}]`;

    const selectorLabel = typeof selector === 'string' ? selector : `${selector.tag}:has-text("${selector.text}")`;
    let detail = selectorLabel;

    if (type === 'fill') detail = `WPISANO: "${extra.value}" w ${readableName || selectorLabel}`;
    else if (type === 'click') detail = `KLIK: ${readableName || selectorLabel}`;
    else if (type === 'force') detail = `WYMUSZONO KLIK: ${readableName || selectorLabel}`;
    else if (type === 'key') detail = `KLAWISZ: [${extra.key}] na ${readableName || selectorLabel}`;
    else if (type === 'hover') detail = `ZACHOWANIE (HOVER): ${readableName || selectorLabel}`;

    addFeedItem(type, detail);
  }

  function flushPendingInput(target) {
    if (!target || !state.pendingInputs.has(target)) return;
    const val = state.pendingInputs.get(target);
    state.pendingInputs.delete(target);
    recordStep('fill', target, { value: val });
  }

  document.addEventListener('click', (e) => {
    if (!state.isRecording || e.composedPath().includes(hostElement)) return;
    const rawTarget = e.composedPath ? e.composedPath()[0] : e.target;
    if (!rawTarget) return;

    state.pendingInputs.forEach((_, el) => { if (el !== rawTarget) flushPendingInput(el); });

    // WYKRYCIE ALT+CLICK (AKTYWACJA WYGÓROWANEGO BUTTONA)
    if (e.altKey) {
      e.preventDefault();
      e.stopPropagation();
      recordStep('force', rawTarget); // Zarejestruj specjalny wymuszony klik
    } else {
      recordStep('click', rawTarget);
    }
  }, true);

  document.addEventListener('input', (e) => {
    if (!state.isRecording || e.composedPath().includes(hostElement)) return;
    const target = e.composedPath ? e.composedPath()[0] : e.target;
    if (!target || (target.tagName !== 'INPUT' && target.tagName !== 'TEXTAREA' && !target.isContentEditable)) return;
    const val = target.isContentEditable ? target.innerText : target.value;
    state.pendingInputs.set(target, val);
    clearTimeout(state.inputDebounceTimer);
    state.inputDebounceTimer = setTimeout(() => flushPendingInput(target), 450);
  }, true);

  document.addEventListener('blur', (e) => {
    if (!state.isRecording || e.composedPath().includes(hostElement)) return;
    clearTimeout(state.inputDebounceTimer);
    flushPendingInput(e.composedPath ? e.composedPath()[0] : e.target);
  }, true);

  const trackedKeys = new Set(['Enter', 'Tab', 'Escape', ' ', 'ArrowDown', 'ArrowUp', 'ArrowLeft', 'ArrowRight']);
  document.addEventListener('keydown', (e) => {
    if (!state.isRecording || e.composedPath().includes(hostElement)) return;
    const target = e.composedPath ? e.composedPath()[0] : e.target;
    if (trackedKeys.has(e.key)) {
      clearTimeout(state.inputDebounceTimer);
      flushPendingInput(target);
      recordStep('key', target, { key: e.key === ' ' ? 'Space' : e.key });
    }
  }, true);

  // WYKRYWANIE ZACHOWAŃ: HOVER na istotnych elementach (menu, triggery)
  document.addEventListener('mouseover', (e) => {
    if (!state.isRecording || e.composedPath().includes(hostElement)) return;
    const rawTarget = e.composedPath ? e.composedPath()[0] : e.target;
    const target = getLogicalTarget(rawTarget);
    if (!target) return;

    // Obserwuj hover tylko na interaktywnych elementach (np. nawigacja, menu, przyciski rozwijające)
    const isInteractive = target.matches('a, button, li, [role="menuitem"], .menu, .dropdown-toggle, .nav-item');
    if (!isInteractive) return;

    if (state.lastHoveredElement !== target) {
      clearTimeout(state.hoverTimer);
      state.lastHoveredElement = target;
      // Jeśli użytkownik przytrzyma kursor przez 800ms, to celowe zachowanie
      state.hoverTimer = setTimeout(() => {
        recordStep('hover', target);
      }, 800);
    }
  }, true);

  document.addEventListener('mouseout', (e) => {
    if (state.lastHoveredElement === (e.composedPath ? e.composedPath()[0] : e.target)) {
      clearTimeout(state.hoverTimer);
      state.lastHoveredElement = null;
    }
  }, true);


  btnRec.onclick = () => {
    state.isRecording = true; state.lastActionTime = Date.now();
    panel.classList.add('recording'); btnRec.disabled = true; btnRec.classList.add('is-rec');
    btnStop.disabled = false; btnGen.disabled = true;
    dot.classList.add('active'); collapsedDot.classList.add('active');
    statusBadge.textContent = 'REC'; statusBadge.style.color = '#ef4444';
  };

  btnStop.onclick = () => {
    state.pendingInputs.forEach((_, el) => flushPendingInput(el));
    state.isRecording = false; panel.classList.remove('recording');
    btnRec.disabled = false; btnRec.classList.remove('is-rec');
    btnStop.disabled = true; btnGen.disabled = false;
    dot.classList.remove('active'); collapsedDot.classList.remove('active');
    statusBadge.textContent = 'PAUSED'; statusBadge.style.color = '#38bdf8';
  };

  btnReset.onclick = () => {
    state.recordedActions = []; state.pendingInputs.clear(); state.lastActionTime = 0;
    counterDisplay.textContent = '0'; collapsedCount.textContent = '[0]';
    actionFeed.innerHTML = '<div style="color: #475569; font-style: italic; text-align: center; padding: 6px;">Wyczyszczono historię.</div>';
    outputBox.style.display = 'none'; outputCode.value = '';
    statusBadge.textContent = 'STANDBY'; statusBadge.style.color = '#94a3b8';
  };

  btnCollapse.onclick = () => { panel.style.display = 'none'; collapsedPanel.style.display = 'flex'; };
  collapsedPanel.onclick = () => { collapsedPanel.style.display = 'none'; panel.style.display = 'flex'; };

  btnCopy.onclick = () => {
    outputCode.select();
    navigator.clipboard.writeText(outputCode.value).then(() => {
      btnCopy.textContent = 'SKOPIOWANO!'; setTimeout(() => (btnCopy.textContent = 'KOPIUJ'), 1500);
    });
  };

  btnDownload.onclick = () => {
    if (!outputCode.value) return;
    const blob = new Blob([outputCode.value], { type: 'text/javascript' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `auto_macro_${Date.now()}.user.js`;
    a.click();
    URL.revokeObjectURL(url);
  };

  btnTest.onclick = () => {
    if (!outputCode.value) return;
    btnTest.textContent = 'URUCHAMIAM...';

    // Wstrzyknięcie skryptu do drzewa DOM w celu natychmiastowego wykonania w środowisku przeglądarki
    const testScript = document.createElement('script');
    testScript.textContent = outputCode.value;
    document.body.appendChild(testScript);

    setTimeout(() => { 
      btnTest.textContent = '▶ TESTUJ'; 
      testScript.remove(); // Posprzątanie taga
    }, 2000);
  };

  btnGen.onclick = () => {
    let stepsArrayCode = '';

    state.recordedActions.forEach((act, idx) => {
      const commentDesc = act.readableName ? `${act.type.toUpperCase()}: ${act.readableName}` : act.type.toUpperCase();
      let actionCode = '';

      if (act.type === 'click' || act.type === 'force') {
        const actionFunc = act.type === 'force' ? 'forceActivate' : 'clickReal';
        if (typeof act.selector === 'string') {
          actionCode = `await ${actionFunc}('${act.selector.replace(/'/g, "\\'")}');`;
        } else if (act.selector.type === 'textMatch') {
          actionCode = `await clickByText('${act.selector.tag}', "${act.selector.text.replace(/"/g, '\\"')}", ${act.type === 'force'});`;
        }
      } else if (act.type === 'hover') {
        if (typeof act.selector === 'string') {
          actionCode = `await triggerHover('${act.selector.replace(/'/g, "\\'")}');`;
        } else if (act.selector.type === 'textMatch') {
          actionCode = `await triggerHoverByText('${act.selector.tag}', "${act.selector.text.replace(/"/g, '\\"')}");`;
        }
      } else if (act.type === 'fill') {
        const safeVal = (act.value || '').replace(/"/g, '\\"');
        const selStr = typeof act.selector === 'string' ? act.selector : act.selector.tag;
        actionCode = `await fillSafe('${selStr.replace(/'/g, "\\'")}', "${safeVal}");`;
      } else if (act.type === 'key') {
        const selStr = typeof act.selector === 'string' ? act.selector : (act.selector.tag || 'body');
        actionCode = `await pressKey('${act.key}', '${selStr.replace(/'/g, "\\'")}');`;
      }

      stepsArrayCode += `
      {
        desc: "${commentDesc.replace(/"/g, '\\"')}",
        delay: ${act.delay},
        execute: async () => { ${actionCode} }
      },`;
    });

    const generatedTemplate = `// ==UserScript==
// @name         Interaktywny Odtwarzacz Makra
// @namespace    https://github.com/universal-action-recorder
// @version      2.0.0
// @description  Skrypt posiadający własny interfejs do podglądu i odtwarzania nagranych akcji.
// @match        ${window.location.origin}${window.location.pathname}*
// @run-at       document-idle
// @grant        none
// ==/UserScript==

(function () {
  'use strict';

  // --- ZDEFINIOWANE KROKI MAKRA ---
  const macroSteps = [${stepsArrayCode}
  ];

  const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

  function waitFor(selectorOrFn, timeout = 10000) {
    return new Promise((resolve, reject) => {
      const isFn = typeof selectorOrFn === 'function';
      const check = () => (isFn ? selectorOrFn() : document.querySelector(selectorOrFn));
      const initial = check();
      if (initial && initial.offsetParent !== null) return resolve(initial);
      const timer = setTimeout(() => { observer.disconnect(); reject(new Error('Timeout: ' + selectorOrFn)); }, timeout);
      const observer = new MutationObserver(() => {
        const el = check();
        if (el && el.offsetParent !== null) { clearTimeout(timer); observer.disconnect(); resolve(el); }
      });
      observer.observe(document.body || document.documentElement, { childList: true, subtree: true, attributes: true });
    });
  }

  // SILNIK AKCJI
  function realClick(el) {
    if (!el) return;
    el.scrollIntoView({ behavior: 'smooth', block: 'center' });
    el.focus();
    ['pointerdown', 'mousedown', 'pointerup', 'mouseup', 'click'].forEach(type => {
      el.dispatchEvent(new MouseEvent(type, { bubbles: true, cancelable: true, view: window }));
    });
  }

  function forceActivateTarget(el) {
    if (!el) return;
    el.scrollIntoView({ behavior: 'instant', block: 'center' });
    el.removeAttribute('disabled');
    el.style.pointerEvents = 'auto';
    const events = ['pointerover', 'mouseover', 'mouseenter', 'pointerdown', 'mousedown', 'focus', 'pointerup', 'mouseup', 'click'];
    events.forEach(type => el.dispatchEvent(new MouseEvent(type, { bubbles: true, cancelable: true, view: window })));
  }

  async function clickReal(selector) { try { const el = await waitFor(selector); realClick(el); } catch(e){ console.warn('Nie znaleziono:', selector); } }
  async function forceActivate(selector) { try { const el = await waitFor(selector); forceActivateTarget(el); } catch(e){} }

  async function clickByText(tag, text, force = false) {
    try {
      const el = await waitFor(() => Array.from(document.querySelectorAll(tag)).find(item => item.textContent.replace(/\\\\s+/g, ' ').trim() === text.trim()));
      force ? forceActivateTarget(el) : realClick(el);
    } catch(e){}
  }

  async function triggerHover(selector) {
    try {
      const el = await waitFor(selector);
      el.scrollIntoView({ behavior: 'smooth', block: 'center' });
      ['pointerover', 'mouseover', 'mouseenter'].forEach(type => el.dispatchEvent(new MouseEvent(type, { bubbles: true, cancelable: true, view: window })));
    } catch(e){}
  }

  async function triggerHoverByText(tag, text) {
    try {
      const el = await waitFor(() => Array.from(document.querySelectorAll(tag)).find(item => item.textContent.replace(/\\\\s+/g, ' ').trim() === text.trim()));
      ['pointerover', 'mouseover', 'mouseenter'].forEach(type => el.dispatchEvent(new MouseEvent(type, { bubbles: true, cancelable: true, view: window })));
    } catch(e){}
  }

  async function fillSafe(selector, value) {
    try {
      const el = await waitFor(selector);
      el.scrollIntoView({ behavior: 'smooth', block: 'center' });
      el.focus();
      const nativeInputSetter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value')?.set;
      const nativeAreaSetter = Object.getOwnPropertyDescriptor(window.HTMLTextAreaElement.prototype, 'value')?.set;
      if (el.tagName === 'TEXTAREA' && nativeAreaSetter) nativeAreaSetter.call(el, value);
      else if (nativeInputSetter) nativeInputSetter.call(el, value);
      else el.value = value;
      el.dispatchEvent(new Event('input', { bubbles: true }));
      el.dispatchEvent(new Event('change', { bubbles: true }));
      el.dispatchEvent(new Event('blur', { bubbles: true }));
    } catch(e){}
  }

  async function pressKey(key, targetSelector) {
    let target = document.activeElement || document.body;
    if (targetSelector) { try { const el = document.querySelector(targetSelector); if (el) { el.focus(); target = el; } } catch(e){} }
    const ev = { key, code: key, bubbles: true, cancelable: true, view: window };
    target.dispatchEvent(new KeyboardEvent('keydown', ev));
    target.dispatchEvent(new KeyboardEvent('keyup', ev));
  }

  // INICJALIZACJA INTERFEJSU ODTWARZACZA
  function createPlayerUI() {
    if(document.getElementById('macro-player-host')) return;

    const host = document.createElement('div');
    host.id = 'macro-player-host';
    host.style.cssText = 'position: fixed; top: 16px; right: 16px; z-index: 2147483647;';
    document.documentElement.appendChild(host);

    const shadow = host.attachShadow({ mode: 'open' });

    const style = document.createElement('style');
    style.textContent = \`
      #player { width: 320px; background: #0f172a; border: 1px solid #1e293b; border-top: 3px solid #3b82f6; border-radius: 6px; box-shadow: 0 10px 25px rgba(0,0,0,0.5); font-family: ui-monospace, SFMono-Regular, monospace; font-size: 11px; overflow: hidden; display: flex; flex-direction: column; }
      .header { padding: 10px 12px; background: #0b1120; color: #f8fafc; font-weight: bold; display: flex; justify-content: space-between; align-items: center; }
      .badge { background: #1e293b; color: #94a3b8; padding: 2px 6px; border-radius: 4px; font-size: 10px; }
      .step-list { max-height: 250px; overflow-y: auto; padding: 0; margin: 0; list-style: none; background: #0f172a; }
      .step-item { padding: 8px 12px; border-bottom: 1px solid #1e293b; color: #94a3b8; display: flex; align-items: center; gap: 8px; transition: background 0.2s; }
      .step-item span.idx { color: #3b82f6; font-weight: bold; min-width: 15px; }
      .step-item.active { background: #172554; color: #60a5fa; border-left: 2px solid #3b82f6; }
      .step-item.done { color: #10b981; text-decoration: line-through; opacity: 0.6; }
      .controls { padding: 10px; background: #0b1120; display: flex; gap: 8px; border-top: 1px solid #1e293b; }
      .btn { flex: 1; padding: 8px; cursor: pointer; border: none; font-weight: bold; border-radius: 4px; font-size: 10px; transition: all 0.2s; }
      .btn-play { background: #3b82f6; color: #ffffff; }
      .btn-play:hover:not(:disabled) { background: #2563eb; }
      .btn-play:disabled { opacity: 0.5; cursor: not-allowed; }
      .btn-close { background: #334155; color: #f8fafc; flex: 0.3; }
      .btn-close:hover { background: #475569; }
    \`;

    const ui = document.createElement('div');
    ui.innerHTML = \`
      <div id="player">
        <div class="header">▶ ODTWARZACZ MAKRA <span class="badge">\${macroSteps.length} AKCJI</span></div>
        <ul class="step-list" id="step-list">
          \${macroSteps.map((s, i) => \`<li class="step-item" id="step-\${i}"><span class="idx">\${i+1}.</span> \${s.desc}</li>\`).join('')}
        </ul>
        <div class="controls">
          <button class="btn btn-play" id="btn-play">▶ URUCHOM SEKWENCJĘ</button>
          <button class="btn btn-close" id="btn-close">X</button>
        </div>
      </div>
    \`;

    shadow.appendChild(style);
    shadow.appendChild(ui);

    const btnPlay = shadow.getElementById('btn-play');
    const btnClose = shadow.getElementById('btn-close');
    let isPlaying = false;

    btnClose.onclick = () => host.remove();

    btnPlay.onclick = async () => {
      if (isPlaying) return;
      isPlaying = true;
      btnPlay.textContent = '⏳ WYKONYWANIE...';
      btnPlay.disabled = true;

      for(let i=0; i<macroSteps.length; i++) {
        const li = shadow.getElementById('step-' + i);
        li.classList.add('active');
        if (i > 0) li.scrollIntoView({ behavior: 'smooth', block: 'nearest' });

        await sleep(macroSteps[i].delay);
        try {
          await macroSteps[i].execute();
        } catch(e) { console.error('Błąd w kroku ' + (i+1), e); }

        li.classList.remove('active');
        li.classList.add('done');
      }

      btnPlay.textContent = '✅ ZAKOŃCZONO';
      setTimeout(() => host.remove(), 3000);
    };
  }

  // Wstrzyknij odtwarzacz gdy strona się załaduje
  if (document.readyState === 'complete') createPlayerUI();
  else window.addEventListener('load', createPlayerUI);
})();`;

    outputCode.value = generatedTemplate;
    outputBox.style.display = 'flex';
  };
})();"}

{"title":"NOWY_test","content":"// ==UserScript==
// @name         Sesame & Yard 360 - Carrier Claim Tactical Suite Pro
// @namespace    yard-claim-suite / lycgracj
// @version      8.0
// @description  Kompletny system automatyzacji roszczeń transportowych (Carrier Claims / CPT Breach / No Driver / Seal Defect) dla Sesame Gate i Yard 360.
// @match        https://trans-logistics-eu.amazon.com/yms/sesameGateConsole*
// @match        https://trans-logistics-eu.amazon.com/yms/relayYardHub/*
// @match        https://trans-logistics-eu.amazon.com/ssp/dock/hrz/ob*
// @connect      prod-eu.eu-west-1.idx-backend.aft.amazon.dev
// @connect      prod-eu.eu-west-1.idx-website.aft.amazon.dev
// @grant        GM_xmlhttpRequest
// @grant        GM.xmlHttpRequest
// @run-at       document-idle
// ==/UserScript==

(function () {
  'use strict';

  // =========================================================================
  // 1. STYLE TAKTYCZNE FUI (CLAIM THEME)
  // =========================================================================
  var CENTRAL_STYLES = [
    ':root {',
    '  --fui-bg: #090d12;',
    '  --fui-panel: #111722;',
    '  --fui-card: #161f2e;',
    '  --fui-border: #233147;',
    '  --fui-orange: #f36c00;',
    '  --fui-claim-red: #ef4444;',
    '  --fui-text: #c5d1de;',
    '  --fui-text-bright: #f0f6fc;',
    '  --fui-text-dim: #64748b;',
    '  --fui-green: #10b981;',
    '  --fui-amber: #f59e0b;',
    '  --fui-ktw3: #00ffcc;',
    '  --fui-font: "JetBrains Mono", "Share Tech Mono", monospace, Consolas;',
    '}',
    '',
    '.fui-root, .fui-root * { box-sizing: border-box; border-radius: 0 !important; font-family: var(--fui-font); }',
    '',
    '.fui-btn {',
    '  cursor: pointer; background: #121820; color: var(--fui-orange); border: 1px solid var(--fui-orange);',
    '  font-size: 10px; font-weight: 700; padding: 2px 6px; text-transform: uppercase;',
    '  transition: background 0.15s, color 0.15s; vertical-align: middle;',
    '}',
    '.fui-btn:hover { background: var(--fui-orange); color: #000; }',
    '',
    '.fui-btn-claim {',
    '  background: #450a0a; color: #fca5a5; border: 1px solid var(--fui-claim-red);',
    '  font-size: 10px; font-weight: 900; padding: 3px 8px; cursor: pointer; text-transform: uppercase;',
    '  margin-left: 4px; vertical-align: middle; transition: all 0.15s ease;',
    '}',
    '.fui-btn-claim:hover { background: #b91c1c; color: #fff; box-shadow: 0 0 8px rgba(239,68,68,0.7); }',
    '',
    '.fui-btn-sub { background: #1a2332; color: #8198b5; border: 1px solid var(--fui-border); font-size: 9px; padding: 1px 5px; cursor: pointer; }',
    '.fui-btn-sub:hover { background: #223044; color: #fff; }',
    '',
    '.fui-claim-tag {',
    '  display: inline-block; padding: 2px 5px; font-size: 9px; font-weight: 900;',
    '  background: #7f1d1d; color: #fff; border: 1px solid #ef4444;',
    '  margin-left: 4px; vertical-align: middle; animation: claim-blink 1.5s infinite alternate;',
    '}',
    '@keyframes claim-blink { from { opacity: 0.8; } to { opacity: 1; box-shadow: 0 0 6px rgba(239,68,68,0.8); } }',
    '',
    '.ktw3-tag { display: inline-block; padding: 2px 5px; font-size: 9px; font-weight: 900; background: rgba(0,255,204,0.15); color: var(--fui-ktw3); border: 1px solid var(--fui-ktw3); margin-left: 4px; vertical-align: middle; }',
    '',
    '#claim-tactical-terminal {',
    '  position: fixed; right: 14px; bottom: 14px; z-index: 999990; background: var(--fui-bg);',
    '  color: var(--fui-text); box-shadow: 0 6px 30px rgba(0,0,0,0.95); width: 440px; height: auto;',
    '  min-width: 340px; min-height: 200px; max-width: 94vw; max-height: 90vh; resize: both;',
    '  overflow: hidden; display: flex; flex-direction: column; border: 1px solid var(--fui-border);',
    '  border-top: 3px solid var(--fui-claim-red);',
    '}',
    '.ct-head { cursor: move; user-select: none; display: flex; align-items: center; gap: 8px; padding: 8px 10px; background: var(--fui-panel); border-bottom: 1px solid var(--fui-border); }',
    '.ct-head-title { flex: 1; color: var(--fui-text-bright); font-size: 11px; font-weight: 900; letter-spacing: 0.8px; }',
    '.ct-tabs-bar { display: flex; border-bottom: 1px solid var(--fui-border); background: var(--fui-bg); }',
    '.ct-tab-btn { flex: 1; padding: 6px 2px; border: none; background: var(--fui-bg); color: var(--fui-text-dim); cursor: pointer; font-size: 10px; font-weight: 700; outline: none; }',
    '.ct-tab-btn.active { background: var(--fui-card); color: var(--fui-claim-red); border-bottom: 2px solid var(--fui-claim-red); }',
    '.ct-view { padding: 10px; overflow-y: auto; flex: 1; display: flex; flex-direction: column; gap: 8px; }',
    '.ct-claim-card { border: 1px solid var(--fui-border); background: var(--fui-panel); padding: 8px; display: flex; flex-direction: column; gap: 4px; font-size: 11px; }',
    '.ct-claim-card.critical { border-left: 3px solid var(--fui-claim-red); }',
    '.ct-copy-box { background: #05080c; border: 1px solid var(--fui-border); color: #38bdf8; font-size: 10px; padding: 6px; white-space: pre-wrap; max-height: 140px; overflow-y: auto; }',
    '',
    '#claim-toast-container { position: fixed; bottom: 16px; left: 16px; z-index: 999999; display: flex; flex-direction: column-reverse; gap: 8px; pointer-events: none; }',
    '.claim-toast { pointer-events: auto; min-width: 300px; max-width: 420px; background: #450a0a; color: #fff; font-size: 11px; padding: 10px 12px; border: 1px solid var(--fui-claim-red); box-shadow: 0 4px 20px rgba(0,0,0,0.85); display: flex; flex-direction: column; gap: 4px; }'
  ].join('\n');

  var styleEl = document.createElement('style');
  styleEl.textContent = CENTRAL_STYLES;
  document.head.appendChild(styleEl);

  // =========================================================================
  // 2. HELPERY I AUDIO
  // =========================================================================
  var audioCtx = null;
  function playClaimAlarm() {
    try {
      if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
      if (audioCtx.state === 'suspended') audioCtx.resume();
      var now = audioCtx.currentTime;
      var osc = audioCtx.createOscillator();
      var gain = audioCtx.createGain();

      osc.type = 'sawtooth';
      osc.frequency.setValueAtTime(440, now);
      osc.frequency.exponentialRampToValueAtTime(880, now + 0.15);
      gain.gain.setValueAtTime(0.15, now);
      gain.gain.exponentialRampToValueAtTime(0.001, now + 0.35);

      osc.connect(gain);
      gain.connect(audioCtx.destination);
      osc.start(now);
      osc.stop(now + 0.35);
    } catch (e) {}
  }

  function copyText(text, btnElement, okMsg) {
    var original = btnElement ? btnElement.textContent : '';
    var notify = function () {
      if (btnElement) {
        btnElement.textContent = okMsg || '✔ SKOPIOWANO';
        btnElement.style.background = '#10b981';
        btnElement.style.color = '#000';
        setTimeout(function () {
          btnElement.textContent = original;
          btnElement.style.background = '';
          btnElement.style.color = '';
        }, 1200);
      }
    };
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(text).then(notify).catch(function () {
        fallbackCopy(text);
        notify();
      });
    } else {
      fallbackCopy(text);
      notify();
    }
  }

  function fallbackCopy(text) {
    var ta = document.createElement('textarea');
    ta.value = text;
    ta.style.position = 'fixed';
    ta.style.opacity = '0';
    document.body.appendChild(ta);
    ta.select();
    try { document.execCommand('copy'); } catch (e) {}
    document.body.removeChild(ta);
  }

  function getNode() {
    var m = location.hash.match(/\/(WRO5|WRO6|YWRO|[A-Z0-9]+)\b/i) || location.href.match(/setNodeId=([A-Z0-9]+)/i);
    return m ? m[1].toUpperCase() : 'WRO5';
  }

  function extractMinutes(timeStr) {
    if (!timeStr || timeStr.indexOf(':') === -1) return null;
    var parts = timeStr.split(':').map(Number);
    var target = new Date();
    target.setHours(parts[0], parts[1], 0, 0);
    return Math.round((target.getTime() - new Date().getTime()) / 60000);
  }

  // =========================================================================
  // 3. GENERATOR RAPORTU ROSZCZENIA (CARRIER CLAIM PROTOCOL)
  // =========================================================================
  function buildClaimReport(item) {
    var now = new Date();
    var dateStr = now.toLocaleDateString('pl-PL') + ' ' + now.toLocaleTimeString('pl-PL', { hour: '2-digit', minute: '2-digit' });

    var reasonBullets = [];
    if (!item.hasDriver) reasonBullets.push('❌ BRAK KIEROWCY NA MIEJSCU (NO DRIVER / MISSED DEPARTURE)');
    if (item.sealDefect) reasonBullets.push('❌ BRAK / USZKODZONA PLOMBA ZABEZPIECZAJĄCA (SEAL DEFECT / NO SEAL)');
    if (item.diff !== null && item.diff < 0) reasonBullets.push('❌ SPÓŹNIENIE ODJAZDU (LATE DEPARTURE): ' + Math.abs(item.diff) + ' min po planie');
    if (item.isTransfers) reasonBullets.push('❌ NIEZGODNOŚĆ SPRZĘTU (EMPTY TRANSFERS INITIAL INSTEAD OF LOADED)');
    if (reasonBullets.length === 0) reasonBullets.push('⚠️ ZAGROŻENIE PUNKTUALNOŚCI ODJAZDU (CRITICAL DWELL TIME RISK)');

    var isKtw = (item.lane || '').toUpperCase().includes('KTW3');

    return [
      '=================================================================',
      '🚨 PROTOKÓŁ ROSZCZENIA TRANSPORTOWEGO // CARRIER NON-COMPLIANCE',
      '=================================================================',
      '• Data i godzina raportu : ' + dateStr,
      '• Magazyn / Węzeł (Node) : ' + getNode() + ' | Strefa: ' + (item.loc || 'Brak danych'),
      '• Numer ładunku (VRID)   : ' + (item.vrid || '---'),
      '• Relacja trasy (Lane)   : ' + (item.lane || '---') + (isKtw ? ' [CRITICAL TARGET: KTW3]' : ''),
      '-----------------------------------------------------------------',
      'IDENTYFIKACJA POJAZDU I PRZEWOŹNIKA:',
      '• Przewoźnik (Carrier)   : ' + (item.carrier || '---'),
      '• Numer naczepy (Trailer): ' + (item.trailer || '---'),
      '• Numer ciągnika (Tractor): ' + (item.tractor || '---'),
      '• Status kierowcy        : ' + (item.hasDriver ? 'Obecny na placu' : 'BRAK KIEROWCY (Driver Absent)'),
      '-----------------------------------------------------------------',
      'PARAMETRY CZASOWE I STATUS ZALADUNKU:',
      '• Status procesu         : ' + (item.status || '---'),
      '• Zaplanowany odjazd SDT : ' + (item.baseTime || '---'),
      '• Czas do odjazdu / diff : ' + (item.diff !== null ? item.diff + ' min' : '---'),
      '• Status plomby (Seal)   : ' + (item.sealDefect ? 'BRAK PLOMBY / DEFEKT' : item.seal),
      '-----------------------------------------------------------------',
      'UZASADNIENIE ZGŁOSZENIA ROSZCZENIA (CLAIM REASONS):',
      reasonBullets.join('\n'),
      '-----------------------------------------------------------------',
      'DZIAŁANIE: Zgłoszenie obciążenia przewoźnika (Carrier Dwell/Breach Ticket).',
      'Raport wygenerowany przez: Yard Management Operations // Automated Claim Suite',
      '================================================================='
    ].join('\n');
  }

  // =========================================================================
  // 4. PARSER YARD 360 / APPOINTMENTS (AUTOMATYCZNE WYKRYWANIE ROSZCZEŃ)
  // =========================================================================
  var detectedClaimsList = [];

  function scanYard360ForClaims() {
    var table = document.querySelector('table[data-testid="wranglingTable"]');
    if (!table) return;

    var rows = table.querySelectorAll('tbody tr[data-testid]');
    var currentClaims = [];

    rows.forEach(function (row) {
      var rawText = (row.innerText || '').replace(/&gt;/g, '>').toUpperCase();
      var vrid = row.getAttribute('data-testid') || '';

      // 1. Czas i status
      var timeEl = row.querySelector('[data-testid="departureTimeDisplay"]');
      var timeMatch = timeEl ? timeEl.innerText.match(/\d{2}:\d{2}/) : rawText.match(/\d{2}:\d{2}/);
      var baseTime = timeMatch ? timeMatch[0] : '';
      var diff = extractMinutes(baseTime);

      var statusEl = row.querySelector('[data-testid="loadStatusText"]');
      var status = statusEl ? statusEl.innerText.trim().toUpperCase() : '';

      // 2. Kierowca
      var driverEl = row.querySelector('[data-testid$="DriverStatus"]');
      var hasDriver = Boolean(driverEl && driverEl.innerText.indexOf('—') === -1 && driverEl.innerText.trim() !== '');

      // 3. Lokalizacja i sprzęt
      var locEl = row.querySelector('[data-testid$="Location"]');
      var loc = locEl ? locEl.innerText.replace(/\s+/g, ' ').trim() : '---';

      var eqEl = row.querySelector('[data-testid$="Equipment"]');
      var eqText = eqEl ? eqEl.innerText.replace(/\s+/g, ' ') : '';
      var trailerMatch = eqText.match(/Trailer:[^\w]*ID\s*([A-Z0-9]+)/i) || loc.match(/Trailer:\s*([A-Z0-9-]+)/i);
      var trailer = trailerMatch ? trailerMatch[1] : vrid;
      var tractorMatch = eqText.match(/Tractor:[^\w]*LP\s*([A-Z0-9]+)/i) || loc.match(/Tractor:\s*([A-Z0-9-]+)/i);
      var tractor = tractorMatch ? tractorMatch[1] : '---';

      // 4. Analiza pod roszczenie
      var hasSeal = /\b(SEAL|PLOMBA|SEALED)\b/i.test(rawText);
      var isTransfers = rawText.indexOf('TRANSFERSINITIAL') !== -1;
      var isFinished = status.indexOf('FINISHED') !== -1;
      var isKtw = rawText.indexOf('KTW3') !== -1;
      var lane = isKtw ? 'WRO5->KTW3' : 'WRO5->LANE';

      // Kwalifikacja wady (Claim triggers):
      // - Brak kierowcy po zakończeniu załadunku
      // - Spóźnienie wyjazdu (diff < 0)
      // - Załadowana naczepa bez plomby
      var isClaimQualified = (isFinished && !hasDriver) || (diff !== null && diff <= 10 && !hasDriver) || (diff !== null && diff < 0) || (isFinished && !hasSeal && !isTransfers);

      var itemData = {
        vrid: vrid,
        baseTime: baseTime,
        diff: diff,
        status: status,
        hasDriver: hasDriver,
        loc: loc,
        trailer: trailer,
        tractor: tractor,
        lane: lane,
        carrier: '---',
        seal: hasSeal ? 'OBECNA' : 'BRAK',
        sealDefect: !hasSeal && isFinished && !isTransfers,
        isTransfers: isTransfers,
        isKtw3: isKtw,
        row: row
      };

      if (isClaimQualified) {
        currentClaims.push(itemData);
        injectClaimButton(row, itemData);
      }
    });

    detectedClaimsList = currentClaims;
    renderTerminalClaims(currentClaims);
  }

  function injectClaimButton(row, itemData) {
    var actionCell = row.cells[row.cells.length - 1];
    if (!actionCell || actionCell.querySelector('.fui-btn-claim')) return;

    var btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'fui-btn-claim fui-root';
    btn.textContent = '⚖️ CLAIM';
    btn.title = 'Kopiuj gotowy protokół roszczenia do schowka (Brak kierowcy/Wada)';
    btn.onclick = function (e) {
      e.stopPropagation();
      var report = buildClaimReport(itemData);
      copyText(report, btn, 'CLAIM SKOPIOWANY!');
      playClaimAlarm();
    };

    actionCell.appendChild(btn);

    // Wizualne oznaczenie wiersza z roszczeniem
    for (var i = 0; i < row.cells.length; i++) {
      row.cells[i].style.setProperty('background-color', 'rgba(185, 28, 28, 0.15)', 'important');
      row.cells[i].style.setProperty('border-bottom', '2px solid #ef4444', 'important');
    }
  }

  // =========================================================================
  // 5. TERMINAL TAKTYCZNY ROSZCZEŃ (CARRIER CLAIM TERMINAL HUD)
  // =========================================================================
  function injectClaimTerminal() {
    if (document.getElementById('claim-tactical-terminal')) return;

    var terminal = document.createElement('div');
    terminal.id = 'claim-tactical-terminal';
    terminal.className = 'fui-root';
    terminal.innerHTML = [
      '<div class="ct-head" id="ct-drag-head">',
      '  <span style="color:var(--fui-claim-red);font-weight:900;">⚖️</span>',
      '  <span class="ct-head-title">MODUŁ ROSZCZEŃ TRANSPORTOWYCH // CLAIMS ENGINE</span>',
      '  <button id="ct-btn-min" class="fui-btn-sub">_</button>',
      '</div>',
      '<div class="ct-tabs-bar">',
      '  <button id="ct-tab-list" class="ct-tab-btn active">AKTYWNE ROSZCZENIA (<span id="ct-claim-count">0</span>)</button>',
      '  <button id="ct-tab-manual" class="ct-tab-btn">GENERATOR VRID</button>',
      '</div>',
      '<div class="ct-view" id="ct-view-list">',
      '  <div style="display:flex;justify-content:space-between;align-items:center;">',
      '    <span style="color:var(--fui-text-dim);font-size:10px;">Wykryte wady i przekroczenia CPT:</span>',
      '    <button id="ct-btn-bulk-copy" class="fui-btn-claim" style="font-size:9px;">KOPIUJ ZBIORCZO (BULK)</button>',
      '  </div>',
      '  <div id="ct-claims-container" style="display:flex;flex-direction:column;gap:6px;"></div>',
      '</div>',
      '<div class="ct-view" id="ct-view-manual" style="display:none;">',
      '  <input id="ct-in-vrid" class="fui-input" placeholder="Wpisz VRID do roszczenia..." style="width:100%;text-transform:uppercase;">',
      '  <button id="ct-btn-gen-manual" class="fui-btn" style="width:100%;padding:6px;margin-top:4px;">GENERUJ PROTOKÓŁ ROSZCZENIA</button>',
      '  <div id="ct-out-manual" class="ct-copy-box" style="display:none;margin-top:6px;"></div>',
      '</div>'
    ].join('\n');

    document.body.appendChild(terminal);

    // Obsługa przeciągania
    var head = terminal.querySelector('#ct-drag-head');
    var drag = null;
    head.addEventListener('mousedown', function (e) {
      if (e.target.id === 'ct-btn-min') return;
      var r = terminal.getBoundingClientRect();
      drag = { dx: e.clientX - r.left, dy: e.clientY - r.top };
      terminal.style.left = r.left + 'px'; terminal.style.top = r.top + 'px';
      terminal.style.right = 'auto'; terminal.style.bottom = 'auto';
      e.preventDefault();
    });
    document.addEventListener('mousemove', function (e) {
      if (!drag) return;
      terminal.style.left = Math.max(0, e.clientX - drag.dx) + 'px';
      terminal.style.top = Math.max(0, e.clientY - drag.dy) + 'px';
    });
    document.addEventListener('mouseup', function () { drag = null; });

    // Zwinięcie
    var isMin = false;
    terminal.querySelector('#ct-btn-min').onclick = function () {
      isMin = !isMin;
      terminal.querySelector('#ct-view-list').style.display = isMin ? 'none' : 'flex';
      terminal.querySelector('#ct-view-manual').style.display = 'none';
      terminal.style.height = isMin ? '36px' : 'auto';
      this.textContent = isMin ? '□' : '_';
    };

    // Zakładki
    var tabList = terminal.querySelector('#ct-tab-list');
    var tabManual = terminal.querySelector('#ct-tab-manual');
    var viewList = terminal.querySelector('#ct-view-list');
    var viewManual = terminal.querySelector('#ct-view-manual');

    tabList.onclick = function () {
      tabList.classList.add('active'); tabManual.classList.remove('active');
      viewList.style.display = 'flex'; viewManual.style.display = 'none';
    };
    tabManual.onclick = function () {
      tabManual.classList.add('active'); tabList.classList.remove('active');
      viewManual.style.display = 'flex'; viewList.style.display = 'none';
    };

    // Zbiorcze kopiowanie
    terminal.querySelector('#ct-btn-bulk-copy').onclick = function () {
      if (detectedClaimsList.length === 0) return;
      var fullBulkReport = detectedClaimsList.map(buildClaimReport).join('\n\n');
      copyText(fullBulkReport, this, 'SKOPIOWANO CAŁY RAPORT!');
    };

    // Generator ręczny
    terminal.querySelector('#ct-btn-gen-manual').onclick = function () {
      var vrid = terminal.querySelector('#ct-in-vrid').value.trim().toUpperCase();
      if (!vrid) return;
      var dummyItem = {
        vrid: vrid,
        lane: 'WRO5->KTW3',
        status: 'CLAIM_PENDING',
        hasDriver: false,
        loc: 'YARD',
        sealDefect: true,
        diff: -15
      };
      var report = buildClaimReport(dummyItem);
      var outBox = terminal.querySelector('#ct-out-manual');
      outBox.style.display = 'block';
      outBox.textContent = report;
      copyText(report, this, 'PROTOKÓŁ GOTOWY!');
    };
  }

  function renderTerminalClaims(claims) {
    var countEl = document.getElementById('ct-claim-count');
    var container = document.getElementById('ct-claims-container');
    if (countEl) countEl.textContent = String(claims.length);
    if (!container) return;

    if (claims.length === 0) {
      container.innerHTML = '<div style="color:var(--fui-text-dim);padding:8px;text-align:center;">[ BRAK KWALIFIKUJĄCYCH SIĘ ROSZCZEŃ ]</div>';
      return;
    }

    container.innerHTML = '';
    claims.forEach(function (c) {
      var card = document.createElement('div');
      card.className = 'ct-claim-card critical fui-root';

      var ktwBadge = c.isKtw3 ? '<span class="ktw3-tag">🎯 KTW3</span>' : '';
      var driverStatus = c.hasDriver ? '<span style="color:#10b981">Kierowca obecny</span>' : '<span style="color:#ef4444;font-weight:bold">BRAK KIEROWCY</span>';

      card.innerHTML = [
        '<div style="display:flex;justify-content:space-between;align-items:center;">',
        '  <b>VRID: <span style="color:#38bdf8;">' + c.vrid + '</span></b>' + ktwBadge,
        '  <button class="fui-btn-claim" style="font-size:9px;">KOPIUJ PROTOKÓŁ</button>',
        '</div>',
        '<div>Dok/Strefa: <b style="color:var(--fui-orange);">' + c.loc + '</b> | SDT: <b>' + (c.baseTime || '-') + '</b></div>',
        '<div>Status: <b>' + c.status + '</b> | ' + driverStatus + '</div>',
        '<div style="font-size:10px;color:#fca5a5;">Wada: ' + (c.sealDefect ? 'Brak plomby' : (!c.hasDriver ? 'Brak kierowcy po SDT' : 'Opóźnienie CPT')) + '</div>'
      ].join('');

      card.querySelector('button').onclick = function () {
        var rep = buildClaimReport(c);
        copyText(rep, this, 'OK!');
      };

      container.appendChild(card);
    });
  }

  // =========================================================================
  // 6. CYKL PRACY I INICJALIZACJA
  // =========================================================================
  function runClaimEngine() {
    injectClaimTerminal();
    scanYard360ForClaims();
  }

  function start() {
    runClaimEngine();
    setInterval(runClaimEngine, 8000);

    var debounce = null;
    var obs = new MutationObserver(function () {
      if (debounce) return;
      debounce = setTimeout(function () {
        scanYard360ForClaims();
        debounce = null;
      }, 500);
    });
    obs.observe(document.body, { childList: true, subtree: true });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', start);
  } else {
    start();
  }
})();
"}

