  function normalizePlate(val) {
    return (val || '').toUpperCase().replace(/[\s-]/g, '');
  }

  function loadStoredSet(key, fallbackArray) {
    try {
      var raw = localStorage.getItem(key);
      if (!raw) return new Set(fallbackArray.map(normalizePlate));
      return new Set(JSON.parse(raw).map(normalizePlate));
    } catch (e) {
      return new Set(fallbackArray.map(normalizePlate));
    }
  }

  function saveStoredSet(key, setInstance) {
