  var VRID_PATTERN = /\b1[0-9A-Z]{8}\b/;

  // =========================================================================
  // 3. VRID DETECTION ENGINE
  // =========================================================================
  function findTractorVrid(startNode) {
    if (!startNode) return null;

    if (startNode.getAttribute) {
      var nodeTitle = startNode.getAttribute('title') || '';
      var mTitle = nodeTitle.match(VRID_PATTERN);
      if (mTitle) return mTitle[0];
    }

    var m = (startNode.textContent || '').match(VRID_PATTERN);
    if (m) return m[0];

    var host = startNode.closest('tr, [role="row"], .card, .row, [data-testid*="row"]') || startNode.parentElement;
    if (host) {
      var titleEls = host.querySelectorAll('[title*="VRID"], p[class*="css-"], [data-testid*="tractor"]');
      for (var i = 0; i < titleEls.length; i++) {
        var tAttr = titleEls[i].getAttribute('title') || '';
        var mt = tAttr.match(VRID_PATTERN);
        if (mt) return mt[0];

        var mTxt = (titleEls[i].textContent || '').match(VRID_PATTERN);
        if (mTxt) return mTxt[0];
      }

      var mHost = (host.textContent || '').match(VRID_PATTERN);
      if (mHost) return mHost[0];
    }
    return null;
  }

