  // =========================================================================
  var DOCKMASTER_API_BASE = 'https://prod-eu.eu-west-1.idx-backend.aft.amazon.dev/v1/appointment-detail';
  var isaCache = new Map();

  function fetchAppointmentDetail(isaNumber, siteCode) {
    return new Promise(function (resolve, reject) {
      var url = DOCKMASTER_API_BASE + '/' + siteCode + '/' + isaNumber + '?includeMilkRun=true';
      var refererUrl = 'https://prod-eu.eu-west-1.idx-website.aft.amazon.dev/en_US/' + siteCode + '/appointment/view/' + isaNumber + '/appointmentDetail';
      gmRequest({
        method: 'GET',
        url: url,
        anonymous: false,
        headers: {
          'Referer': refererUrl,
          'X-Requested-With': 'XMLHttpRequest'
        },
        onload: function (res) {
          if (res.status >= 200 && res.status < 300) resolve(res.responseText);
          else reject(new Error('HTTP ' + res.status));
        },
        onerror: reject,
        ontimeout: function () { reject(new Error('Timeout')); },
        timeout: 12000
      });
    });
  }

  function getAttributeValue(xmlDoc, keyName) {
    var entries = xmlDoc.getElementsByTagName('entry');
    for (var i = 0; i < entries.length; i++) {
      var entry = entries[i];
      var keyEl = entry.getElementsByTagName('key')[0];
      if (keyEl && keyEl.textContent === keyName) {
        var outerVal = entry.getElementsByTagName('value')[0];
        if (outerVal) {
          var innerVal = outerVal.getElementsByTagName('value')[0];
          return innerVal ? innerVal.textContent.trim() : null;
        }
      }
    }
    return null;
  }

  function getSimpleTag(xmlDoc, tagName) {
    var el = xmlDoc.getElementsByTagName(tagName)[0];
    return el ? el.textContent.trim() : null;
  }

  function parseAppointmentXml(xmlText) {
    var parser = new DOMParser();
    var xmlDoc = parser.parseFromString(xmlText, 'application/xml');
    return {
      loadType: getAttributeValue(xmlDoc, 'CARRIER_LOAD_TYPE'),
      isPalletized: getAttributeValue(xmlDoc, 'IS_PALLETIZED'),
      location: getAttributeValue(xmlDoc, 'YMS_CURRENT_LOCATION'),
      vrid: getAttributeValue(xmlDoc, 'VRID'),
      palletCount: getSimpleTag(xmlDoc, 'palletCount'),
      cartonCount: getSimpleTag(xmlDoc, 'cartonCount'),
      unitCount: getSimpleTag(xmlDoc, 'unitCount'),
      status: getSimpleTag(xmlDoc, 'status')
    };
  }

  function buildIsaBadgeText(data) {
    if (!data) return null;
    var parts = [];
    var loadType = (data.loadType || '').toUpperCase();
    var isPalletized = (data.isPalletized || '').toUpperCase();

    if (loadType === 'LIVE') parts.push('🟢 LIVE');
    else if (loadType === 'DROP') parts.push('🟡 DROP');
    else if (loadType) parts.push('⚪ ' + loadType);

    if (isPalletized === 'YES') {
      parts.push(data.palletCount ? ('📦 PALETA (' + data.palletCount + ')') : '📦 PALETA');
    } else if (isPalletized === 'NO') {
      parts.push('📄 LUZ');
    }
    return parts.length ? parts.join(' · ') : null;
  }

  function attachIsaBadge(isaNumber, afterEl) {
    if (afterEl.hasAttribute('data-svic-badge')) return;
    afterEl.setAttribute('data-svic-badge', '1');

    var badge = document.createElement('span');
    badge.className = 'svic-isa-badge fui-root';
    badge.textContent = '⏳ ISA...';
    afterEl.insertAdjacentElement('afterend', badge);

    var siteCode = getNode();
    if (isaCache.has(isaNumber)) {
      var cached = isaCache.get(isaNumber);
      if (cached.status === 'done') {
        badge.textContent = buildIsaBadgeText(cached.data) || 'ℹ️ BRAK METADANYCH';
        return;
      }
      if (cached.status === 'error') {
        badge.textContent = '⚠️ BŁĄD ISA';
        return;
      }
      cached.subscribers.push(badge);
      return;
    }

    var entry = { status: 'loading', subscribers: [badge], data: null };
    isaCache.set(isaNumber, entry);

    fetchAppointmentDetail(isaNumber, siteCode)
      .then(function (xmlText) {
        var data = parseAppointmentXml(xmlText);
        entry.status = 'done';
        entry.data = data;
        var text = buildIsaBadgeText(data) || 'ℹ️ BRAK METADANYCH';
        entry.subscribers.forEach(function (b) {
          b.textContent = text;
          b.title = JSON.stringify(data, null, 2);
        });
      })
      .catch(function (err) {
        entry.status = 'error';
        entry.subscribers.forEach(function (b) {
          b.textContent = '⚠️ BŁĄD ISA';
          b.title = String(err);
        });
      });
  }

  // =========================================================================
  // 6. SSP OUTBOUND DOCK API
  // =========================================================================
  var SSP_PATH_PAGE = '/ssp/dock/hrz/ob';
  var SSP_PATH_DATA = '/ssp/dock/hrz/ob/fetchdata?';
  var SSP_WINDOW_MS = 3 * 24 * 3600 * 1000;
  var SSP_CACHE_MS  = 60 * 1000;

  var SSP_CACHE = { ts: 0, map: null, inflight: null };

  function describeSspLoad(load, item) {
    var s = load.status;
    var hasTrailer = !!(item.trailer && (item.trailer.trailerNumber || item.trailer.trailer));
    switch (s) {
      case 'SCHEDULED':
        return hasTrailer
          ? { label: 'Zaplanowana (jest naczepa)', color: '#334155', isReady: false }
          : { label: 'Naczepy brak (plan)', color: '#1e293b', isReady: false };
      case 'READY_FOR_LOADING':
        return { label: 'Gotowa do załadunku', color: '#1e40af', isReady: false };
      case 'TRAILER_ATTACHED':
        return { label: 'Naczepa podpięta', color: '#2563eb', isReady: false };
      case 'LOADING_IN_PROGRESS':
        return { label: 'Ładowanie w toku', color: '#b45309', isReady: false };
      case 'LOADING_PAUSED':
        return { label: 'Wstrzymana', color: '#92400e', isReady: false };
      case 'FINISHED_LOADING':
        return { label: 'ZAŁADOWANA / GOTOWA', color: '#065f46', isReady: true };
      case 'COMPLETED':
        return { label: 'Wyjechała', color: '#0f172a', isReady: false };
      case 'CANCELLED':
        return { label: 'Anulowana', color: '#991b1b', isReady: false };
      default:
        return { label: s || 'Nieznany', color: '#1e293b', isReady: false };
    }
  }

  function getSspDoor(item) {
    if (item.resource && item.resource.length && item.resource[0].label) {
      var r = item.resource[0];
      return r.label + (r.resType === 'YARD' ? ' (plac)' : '');
    }
    if (item.trailer && item.trailer.location) return item.trailer.location;
    return null;
  }

  function fetchSspMap() {
    return fetch(SSP_PATH_PAGE, { credentials: 'include' })
      .then(function (pageResp) {
        if (!pageResp.ok) throw new Error('Błąd OB: ' + pageResp.status);
        return pageResp.text();
      })
      .then(function (html) {
        var doc  = new DOMParser().parseFromString(html, 'text/html');
        var meta = doc.querySelector('meta[name="anti-csrftoken-a2z"]');
        if (!meta || !meta.content) throw new Error('Brak CSRF na stronie OB');
        var token = meta.content;

        var now = Date.now();
        var body = 'entity=getOutboundDockView&nodeId=' + encodeURIComponent(getNode())
          + '&startDate=' + (now - SSP_WINDOW_MS) + '&endDate=' + (now + SSP_WINDOW_MS)
          + '&loadCategories=outboundScheduled%2CoutboundInProgress%2CoutboundReadyToDepart%2CoutboundDeparted%2CoutboundCancelled'
          + '&shippingPurposeType=TRANSSHIPMENT%2CNON-TRANSSHIPMENT%2CSHIP_WITH_AMAZON';

        return fetch(SSP_PATH_DATA, {
          method: 'POST',
          credentials: 'include',
          headers: {
            'Content-Type': 'application/x-www-form-urlencoded; charset=UTF-8',
            'anti-csrftoken-a2z': token
          },
          body: body
        });
      })
      .then(function (resp) {
        if (!resp.ok) throw new Error('Błąd endpointu OB: ' + resp.status);
        return resp.json();
      })
      .then(function (json) {
        var arr = (json.ret && json.ret.aaData) || [];
        var map = {};

        arr.forEach(function (item) {
          var load = item.load;
          if (!load || !load.vrId) return;
          var d = describeSspLoad(load, item);
          map[load.vrId] = {
            vrId:    load.vrId,
            status:  load.status,
            label:   d.label,
            color:   d.color,
            isReady: d.isReady,
            route:   load.route || '',
            door:    getSspDoor(item),
            sdt:     load.scheduledDepartureTime || '',
            adt:     load.actualDepartureTime   || '',
            cpt:     load.criticalPullTime      || '',
            carrier: load.carrier || ''
          };
        });
        return map;
      });
  }

  function getSspMap() {
    if (SSP_CACHE.map && (Date.now() - SSP_CACHE.ts) < SSP_CACHE_MS) {
      return Promise.resolve(SSP_CACHE.map);
    }
    if (SSP_CACHE.inflight) return SSP_CACHE.inflight;
    SSP_CACHE.inflight = fetchSspMap()
      .then(function (map) {
        SSP_CACHE.map = map;
        SSP_CACHE.ts = Date.now();
        SSP_CACHE.inflight = null;
        return map;
      })
      .catch(function (err) {
        SSP_CACHE.inflight = null;
        console.error('[SSP OB] Błąd pobierania:', err);
        return SSP_CACHE.map || {};
      });
    return SSP_CACHE.inflight;
  }

  window.getSSPInfo = function (vrid) {
    return getSspMap().then(function (map) {
      return map[vrid] || null;
    });
  };

