      e.stopPropagation();

      var existing = wrap.querySelector('.svic-loc-picker-menu');
      document.querySelectorAll('.svic-loc-picker-menu').forEach(function (m) { m.remove(); });
      if (existing) return;

      var menu = document.createElement('div');
      menu.className = 'svic-loc-picker-menu fui-root';

      var title = document.createElement('div');
      title.textContent = 'POLA BEZ BUMPERÓW:';
      title.className = 'svic-loc-picker-title';
      menu.appendChild(title);

      Array.from(bumperlessLocations).sort().forEach(function (loc) {
        var item = document.createElement('div');
        item.textContent = loc;
        item.className = 'svic-loc-picker-item';
        item.onclick = function (e2) {
          e2.stopPropagation();
          setLocationInputValue(input, loc, associatedPlate);
          menu.remove();
        };
        menu.appendChild(item);
      });

      wrap.appendChild(menu);
      var onDocClick = function (e3) {
        if (!wrap.contains(e3.target)) {
          menu.remove();
          document.removeEventListener('click', onDocClick);
        }
      };
      setTimeout(function () { document.addEventListener('click', onDocClick); }, 0);
    };

    wrap.appendChild(btn);
    return wrap;
  }

  // =========================================================================
  // 9. AKCJE WIERSZA I AUTO-WERYFIKACJA VRID
  // =========================================================================
  function transferVridToTerminal(vrid, autoTrigger) {
    var p = document.getElementById('sesame-tactical-terminal');
    if (!p || !vrid) return;

    var input = p.querySelector('#stt-vrid-in');
    var btn = p.querySelector('#stt-vrid-btn');
    if (input) {
      input.value = vrid;
      if (autoTrigger && btn) {
        btn.click();
      }
    }
  }

  function executeAutoCheck(vrid, btn, statusSlot) {
    if (!vrid) return;

    btn.textContent = 'SPRAWDZAM...';
    btn.style.opacity = '0.7';

    window.getSSPInfo(vrid)
      .then(function (info) {
        statusSlot.innerHTML = '';
        if (!info) {
          statusSlot.innerHTML = '<span style="color:#ef4444;font-size:10px;font-weight:700">[BRAK W OB]</span>';
          btn.textContent = 'OB: ' + vrid;
          btn.style.opacity = '1';
          return;
        }

        var badge = buildSspBadge(info);
        statusSlot.appendChild(badge);
        btn.textContent = info.isReady ? '✔ GOTOWA' : '⌛ ' + info.label;
        btn.style.borderColor = info.isReady ? '#10b981' : '#f59e0b';
        btn.style.color = info.isReady ? '#10b981' : '#f59e0b';
        btn.style.opacity = '1';
      })
      .catch(function () {
        btn.textContent = 'BŁĄD OB';
        btn.style.borderColor = '#ef4444';
        btn.style.color = '#ef4444';
        btn.style.opacity = '1';
      });
  }

  function createTractorCheckWidget(vrid, hostNode) {
    var wrap = document.createElement('div');
    wrap.className = 'ssp-vrid-action-wrap fui-root';

    var btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'fui-btn';
    btn.textContent = 'OB: ' + vrid;
    btn.title = 'VRID: ' + vrid + ' (Kliknij, aby przenieść do terminala)';

    var statusSlot = document.createElement('span');
    statusSlot.className = 'ssp-result-slot';

    btn.onclick = function (e) {
      e.stopPropagation();
      e.preventDefault();
      var liveVrid = findTractorVrid(hostNode) || vrid;
      transferVridToTerminal(liveVrid, true);
      executeAutoCheck(liveVrid, btn, statusSlot);
    };

    wrap.appendChild(btn);
    wrap.appendChild(statusSlot);

    setTimeout(function () {
      executeAutoCheck(vrid, btn, statusSlot);
    }, 80);

    return wrap;
  }

  // Dedykowany procesor dla <p class="css-5dlbru" title="VRID ...">
  function processPTextVrids(root) {
    var pEls = root.querySelectorAll ? root.querySelectorAll('p[title*="VRID"], p.css-5dlbru, [title^="VRID "]') : [];
    for (var i = 0; i < pEls.length; i++) {
      var pNode = pEls[i];
      if (pNode.hasAttribute('data-ssp-auto-checked')) continue;

      var rawText = (pNode.getAttribute('title') || '') + ' ' + (pNode.textContent || '');
      var match = rawText.match(VRID_PATTERN);
      if (!match) continue;

      pNode.setAttribute('data-ssp-auto-checked', '1');
      var vrid = match[0];

      transferVridToTerminal(vrid, false);

      var hostRow = pNode.closest('tr, [role="row"], .card, .row') || pNode.parentElement;
      var widget = createTractorCheckWidget(vrid, hostRow);
      pNode.insertAdjacentElement('afterend', widget);
    }
  }

  function extractConsolidatedRowDetails(hostRow) {
    var plateCells = hostRow.querySelectorAll('[data-testid="licensePlateNumber"]');
    var plates = [];
    for (var i = 0; i < plateCells.length; i++) {
      var t = plateCells[i].textContent.trim();
      if (t && t !== '---') plates.push(t);
    }

    var vrid = findTractorVrid(hostRow) || '-';
    var isa = '';
    var allNodes = hostRow.querySelectorAll('*');
    for (var j = 0; j < allNodes.length; j++) {
      var el = allNodes[j];
      if (el.children.length === 0) {
        var txt = el.textContent.trim();
        var mIsa = txt.match(/^ISA\s+(\S+)$/);
        if (mIsa) isa = mIsa[1];
      }
    }

    var extraIsa = '';
    if (isa && isaCache.has(isa) && isaCache.get(isa).status === 'done') {
      var d = isaCache.get(isa).data;
      extraIsa = ' | Typ: ' + (d.loadType || '-') + ' | Palety: ' + (d.palletCount || '-');
    }

    var extraOb = '';
    if (vrid !== '-' && SSP_CACHE.map && SSP_CACHE.map[vrid]) {
      var ob = SSP_CACHE.map[vrid];
      extraOb = ' | OB: ' + ob.label + ' (' + (ob.door || 'Brak doku') + ') | CPT: ' + (ob.cpt || '-');
    }

    return 'VRID: ' + vrid + ' | ISA: ' + (isa || '-') + ' | Rej: ' + (plates.join(' / ') || '-') + extraIsa + extraOb;
  }

  function makeQuickCopyBtn(label, val) {
    var btn = document.createElement('button');
    btn.textContent = '📋';
    btn.title = 'Kopiuj ' + label + ': ' + val;
    btn.type = 'button';
    btn.className = 'fui-btn-sub fui-root';
    btn.onclick = function (e) {
      e.stopPropagation();
      copyToClipboard(val, btn, '✔');
    };
    return btn;
  }

  function processVridAndIsaElements(root) {
    var valRegex = /^(VRID|ISA)\s+(\S+)$/;
    var walker = document.createTreeWalker(root, NodeFilter.SHOW_ELEMENT, {
      acceptNode: function (el) {
        if (el.hasAttribute('data-svic-processed') || el.classList.contains('svic-copy-btn')) {
          return NodeFilter.FILTER_REJECT;
        }
        var text = (el.textContent || '').trim();
        return (valRegex.test(text) && el.children.length === 0) ? NodeFilter.FILTER_ACCEPT : NodeFilter.FILTER_SKIP;
      }
    });

    var matches = [];
    while (walker.nextNode()) matches.push(walker.currentNode);

    matches.forEach(function (el) {
      var match = el.textContent.trim().match(valRegex);
      if (!match) return;
      el.setAttribute('data-svic-processed', '1');
      var label = match[1];
      var value = match[2];

      var btn = makeQuickCopyBtn(label, value);
      btn.className += ' svic-copy-btn';
      el.insertAdjacentElement('afterend', btn);

      if (label === 'ISA') {
        attachIsaBadge(value, btn);
      }
    });
  }

  function processPlatesAndRowActions(root) {
    var cells = root.querySelectorAll ? root.querySelectorAll('[data-testid="licensePlateNumber"]') : [];
    for (var i = 0; i < cells.length; i++) {
      var cell = cells[i];
      if (cell.hasAttribute('data-svic-plate-processed')) continue;
      var text = cell.textContent.trim();
      cell.setAttribute('data-svic-plate-processed', '1');
      if (!text || text === '---') continue;

      var btn = makeQuickCopyBtn('Rejestracja', text);
      cell.insertAdjacentElement('afterend', btn);

      var hostRow = cell.closest('tr, [role="row"], .card, .row');
      if (!hostRow && cell.parentElement) {
        hostRow = cell.parentElement.parentElement;
      }

      if (isMegaPlate(text)) {
        showMegaToast(text);
      }

      if (hostRow && !hostRow.hasAttribute('data-svic-row-export-processed')) {
        hostRow.setAttribute('data-svic-row-export-processed', '1');

        (function (row) {
          var fullCopyBtn = document.createElement('button');
          fullCopyBtn.textContent = '📋 FULL';
          fullCopyBtn.title = 'Kopiuj zintegrowane dane wiersza (Sesame + Dockmaster + SSP OB)';
          fullCopyBtn.className = 'fui-btn-sub fui-root';
          fullCopyBtn.style.color = 'var(--fui-orange)';
          fullCopyBtn.style.borderColor = '#334155';
          fullCopyBtn.onclick = function (e) {
            e.stopPropagation();
            var dataString = extractConsolidatedRowDetails(row);
            copyToClipboard(dataString, fullCopyBtn, 'OK!');
          };
          cell.insertAdjacentElement('afterend', fullCopyBtn);
        })(hostRow);
      }
    }
  }

  function processLocationSelectors(root) {
    var containers = root.querySelectorAll ? root.querySelectorAll('[data-testid="gateOperationSummaryLocationSelect"]') : [];
    for (var i = 0; i < containers.length; i++) {
      var container = containers[i];
      if (container.hasAttribute('data-svic-location-widget')) continue;

      var row = container.parentElement;
      var plateCells = [];
      var hops = 0;
      while (row && hops < 8) {
        plateCells = Array.from(row.querySelectorAll('[data-testid="licensePlateNumber"]'));
        if (plateCells.length > 0) break;
        row = row.parentElement;
        hops++;
      }
      if (!row || plateCells.length === 0) continue;

      var megaPlateMatch = null;
      for (var j = 0; j < plateCells.length; j++) {
        if (isMegaPlate(plateCells[j].textContent.trim())) {
          megaPlateMatch = plateCells[j];
          break;
        }
      }
      if (!megaPlateMatch) continue;

      var input = container.querySelector('input');
      if (!input) continue;

      container.setAttribute('data-svic-location-widget', '1');
      var picker = makeLocationPicker(input, megaPlateMatch.textContent.trim());
      container.insertAdjacentElement('afterend', picker);
    }
  }

  function injectTractorAutoCheckWidgets() {
    var selectors = [
      '[data-testid*="tractor"]',
      '[data-testid*="Tractor"]',
      '.tractor-cell',
      '[data-testid*="loadContainer"]',
      '[data-testid*="load-container"]',
      '[data-testid*="LoadContainer"]',
      '.load-container'
    ];

    var targetCells = [];
    try {
      targetCells = Array.from(document.querySelectorAll(selectors.join(',')));
    } catch (e) {
      targetCells = Array.from(document.querySelectorAll('[data-testid*="tractor"], [data-testid*="loadContainer"]'));
    }

    targetCells.forEach(function (cell) {
      if (cell.querySelector('.ssp-vrid-action-wrap')) return;

      var host = cell.closest('tr, [role="row"], .card, .row, [data-testid*="row"]') || cell.parentElement;
      if (!host) return;

      var vrid = findTractorVrid(host);
      if (!vrid) return;

      var terminalInput = document.querySelector('#stt-vrid-in');
      if (terminalInput && !terminalInput.value) {
        terminalInput.value = vrid;
      }

      var widget = createTractorCheckWidget(vrid, host);
      cell.appendChild(widget);
    });
  }

  function renderSspBadgesFromCache() {
    if (!SSP_CACHE.map) return;
    document.querySelectorAll('[data-testid="licensePlateNumber"]').forEach(function (cell) {
      var host = cell.closest('tr, [role="row"], .card, .row, td, div') || cell;
      var vrid = findTractorVrid(host);
      if (!vrid) return;

      var info = SSP_CACHE.map[vrid];
      if (!info) return;

      var existing = host.querySelector('.ssp-ob-badge');
      if (existing) {
        if (existing.dataset.vrid === info.vrId) return;
        existing.remove();
      }

      var badge = buildSspBadge(info);
      cell.insertAdjacentElement('afterend', badge);
    });
  }

  // =========================================================================
  // 10. TERMINAL HUD PANEL
  // =========================================================================
  function createTacticalPanel() {
    var p = document.getElementById('sesame-tactical-terminal');
    if (p) return p;

    p = document.createElement('div');
    p.id = 'sesame-tactical-terminal';
    p.className = 'fui-root';

    p.innerHTML =
      '<div id="stt-head" class="stt-header">'
      + '<span class="stt-header-dot">■</span>'
      + '<b class="stt-header-title">SESAME_TACTICAL_SUITE v6.5</b>'
      + '<span id="stt-clock" class="stt-header-clock"></span>'
      + '<button id="stt-min-btn" class="fui-btn-sub" title="Zwiń / Rozwiń">_</button>'
      + '</div>'
      + '<div id="stt-tabs" class="stt-tabs-bar">'
      + '<button id="stt-tab-search" class="stt-tab-btn active">WYSZUKAJ VRID</button>'
      + '<button id="stt-tab-ready" class="stt-tab-btn">GOTOWE / SLACK</button>'
      + '<button id="stt-tab-cfg" class="stt-tab-btn">⚙️ CONFIG</button>'
      + '</div>'
      + '<div id="stt-content" class="stt-content-area">'
      + '<div id="stt-view-search" class="stt-view">'
      + '<div class="stt-row-flex">'
      + '<input id="stt-vrid-in" class="fui-input" placeholder="Wpisz lub kliknij wiersz..." style="flex:1;text-transform:uppercase;">'
      + '<button id="stt-vrid-btn" class="fui-btn fui-btn-green">SPRAWDŹ</button>'
      + '</div>'
      + '<div id="stt-vrid-card" class="stt-card"></div>'
      + '</div>'
      + '<div id="stt-view-ready" class="stt-view" style="display:none;">'
      + '<div style="display:flex;justify-content:space-between;align-items:center;">'
      + '<span class="stt-label-title">Załadowane (SSP OB Gotowe):</span>'
      + '<button id="stt-slack-bulk" class="fui-btn-slack">KOPIUJ DO SLACKA</button>'
      + '</div>'
      + '<div id="stt-ready-list" class="stt-ready-container"></div>'
      + '</div>'
      + '<div id="stt-view-cfg" class="stt-view" style="display:none;">'
      + '<label class="stt-checkbox-label">'
      + '<input type="checkbox" id="stt-cfg-audio"' + (!isAudioMuted ? ' checked' : '') + '>'
      + '<span>Dźwięk ostrzegawczy MEGA (Tactical Audio Alert)</span>'
      + '</label>'
      + '<label class="stt-label-title">Naczepy MEGA (po przecinku/nowej linii):</label>'
      + '<textarea id="stt-cfg-plates" class="fui-input fui-input-block" style="height:65px;"></textarea>'
      + '<label class="stt-label-title">Pola bez bumperów (HS-xxx):</label>'
      + '<textarea id="stt-cfg-locs" class="fui-input fui-input-block" style="height:55px;"></textarea>'
      + '<button id="stt-cfg-save" class="fui-btn-save">ZAPISZ USTAWIENIA</button>'
      + '</div>'
      + '</div>';

    document.body.appendChild(p);

    try {
      var geom = JSON.parse(localStorage.getItem(STORAGE_KEYS.PANEL_GEOM) || 'null');
      if (geom) {
        if (geom.left) p.style.left = geom.left;
        if (geom.top) p.style.top = geom.top;
        p.style.right = 'auto'; p.style.bottom = 'auto';
        if (geom.w) p.style.width = geom.w;
        if (geom.h) p.style.height = geom.h;
      }
    } catch (e) {}

    var saveGeom = function () {
      try {
        var r = p.getBoundingClientRect();
        localStorage.setItem(STORAGE_KEYS.PANEL_GEOM, JSON.stringify({
          left: Math.round(r.left) + 'px',
          top: Math.round(r.top) + 'px',
          w: p.style.width,
          h: p.style.height
        }));
      } catch (e) {}
    };

    var head = p.querySelector('#stt-head');
    var drag = null;
    head.addEventListener('mousedown', function (e) {
      if (e.target.id === 'stt-min-btn') return;
      var r = p.getBoundingClientRect();
      drag = { dx: e.clientX - r.left, dy: e.clientY - r.top };
      p.style.left = r.left + 'px'; p.style.top = r.top + 'px';
      p.style.right = 'auto'; p.style.bottom = 'auto';
      e.preventDefault();
    });

    document.addEventListener('mousemove', function (e) {
      if (!drag) return;
      var x = Math.max(0, Math.min(e.clientX - drag.dx, window.innerWidth - 40));
      var y = Math.max(0, Math.min(e.clientY - drag.dy, window.innerHeight - 24));
      p.style.left = x + 'px'; p.style.top = y + 'px';
    });

    document.addEventListener('mouseup', function () {
      if (drag) { drag = null; saveGeom(); }
    });

    if (window.ResizeObserver) new ResizeObserver(function () { saveGeom(); }).observe(p);

    var content = p.querySelector('#stt-content');
    var tabs = p.querySelector('#stt-tabs');
    var minBtn = p.querySelector('#stt-min-btn');
    minBtn.onclick = function () {
      var isCollapsed = content.style.display === 'none';
      content.style.display = isCollapsed ? 'flex' : 'none';
      tabs.style.display = isCollapsed ? 'flex' : 'none';
      p.style.height = isCollapsed ? 'auto' : '32px';
      minBtn.textContent = isCollapsed ? '_' : '□';
    };

    var tabSearch = p.querySelector('#stt-tab-search');
    var tabReady = p.querySelector('#stt-tab-ready');
    var tabCfg = p.querySelector('#stt-tab-cfg');
    var viewSearch = p.querySelector('#stt-view-search');
    var viewReady = p.querySelector('#stt-view-ready');
    var viewCfg = p.querySelector('#stt-view-cfg');

    function switchTab(activeTab, activeView) {
      [tabSearch, tabReady, tabCfg].forEach(function (t) { t.classList.remove('active'); });
      [viewSearch, viewReady, viewCfg].forEach(function (v) { v.style.display = 'none'; });
      activeTab.classList.add('active');
      activeView.style.display = 'flex';
    }

    tabSearch.onclick = function () { switchTab(tabSearch, viewSearch); };
    tabReady.onclick = function () {
      switchTab(tabReady, viewReady);
      loadReadyOutboundList();
    };
    tabCfg.onclick = function () {
      switchTab(tabCfg, viewCfg);
      p.querySelector('#stt-cfg-plates').value = Array.from(megaPlates).join(', ');
      p.querySelector('#stt-cfg-locs').value = Array.from(bumperlessLocations).join(', ');
    };

    var execVridSearch = function () {
      var input = p.querySelector('#stt-vrid-in').value.trim().toUpperCase();
      var card = p.querySelector('#stt-vrid-card');
      if (!input) {
        card.style.display = 'block';
        card.style.borderColor = '#b45309';
        card.innerHTML = '<span style="color:#f59e0b">Podaj prawidłowy numer VRID.</span>';
        return;
      }
      card.style.display = 'block';
      card.style.borderColor = '#233147';
      card.innerHTML = '<span style="color:#38bdf8">Przeszukiwanie bazy SSP OB...</span>';

      window.getSSPInfo(input).then(function (info) {
        if (!info) {
          card.style.borderColor = '#ef4444';
          card.innerHTML = '<span style="color:#ef4444;font-weight:bold">VRID: ' + input + ' — BRAK W SYSTEMIE OB</span>';
          return;
        }

        var verdictColor = info.isReady ? '#10b981' : (info.status === 'LOADING_IN_PROGRESS' ? '#f59e0b' : '#ef4444');
        card.style.borderColor = verdictColor;
        card.innerHTML =
          '<div class="stt-card-header">'
          + '<span style="font-weight:900;color:' + verdictColor + '">[ ' + (info.isReady ? 'GOTOWA DO DROGI' : info.label) + ' ]</span>'
          + '<button id="stt-slack-single-btn" class="fui-btn-slack">SLACK</button>'
          + '</div>'
          + '<div><b>VRID:</b> <span style="color:#38bdf8">' + info.vrId + '</span></div>'
          + '<div><b>Lokalizacja/Dok:</b> <span style="color:#f36c00">' + (info.door || 'Brak doku') + '</span></div>'
          + '<div><b>Status:</b> ' + info.label + ' (' + info.status + ')</div>'
          + '<div><b>Trasa:</b> ' + (info.route || '-') + ' | <b>Przewoźnik:</b> ' + (info.carrier || '-') + '</div>'
          + '<div><b>Plan (SDT):</b> ' + (info.sdt || '-') + ' | <b>CPT:</b> <span style="color:#f59e0b">' + (info.cpt || '-') + '</span></div>';

        card.querySelector('#stt-slack-single-btn').onclick = function () {
          copyToClipboard(formatSingleSlack(info), this);
        };
      });
    };

    p.querySelector('#stt-vrid-btn').onclick = execVridSearch;
    p.querySelector('#stt-vrid-in').onkeydown = function (e) { if (e.key === 'Enter') execVridSearch(); };

    function loadReadyOutboundList() {
      var listEl = p.querySelector('#stt-ready-list');
      listEl.innerHTML = '<span style="color:#64748b;padding:4px">Wczytywanie danych z SSP OB...</span>';

      getSspMap().then(function (map) {
        var readyList = Object.values(map).filter(function (i) { return i.isReady; });
        if (!readyList.length) {
          listEl.innerHTML = '<span style="color:#64748b;padding:4px">Brak gotowych ładunków na placu.</span>';
          return;
        }

        listEl.innerHTML = '';
        readyList.forEach(function (item) {
          var row = document.createElement('div');
          row.className = 'stt-ready-item';
          row.innerHTML = '<div><b style="color:#38bdf8">' + item.vrId + '</b> | Dok: <b>' + (item.door || '-') + '</b> | CPT: <b style="color:#f59e0b">' + (item.cpt || '-') + '</b></div>';

          var sBtn = document.createElement('button');
          sBtn.textContent = 'SLACK';
          sBtn.className = 'fui-btn-slack';
          sBtn.onclick = function () { copyToClipboard(formatSingleSlack(item), sBtn, 'OK!'); };
          row.appendChild(sBtn);
          listEl.appendChild(row);
        });

        p.querySelector('#stt-slack-bulk').onclick = function () {
          copyToClipboard(formatListSlack(readyList), this, 'SKOPIOWANO RAPORT!');
        };
      });
    }

    p.querySelector('#stt-cfg-save').onclick = function () {
      var platesRaw = p.querySelector('#stt-cfg-plates').value;
      var locsRaw = p.querySelector('#stt-cfg-locs').value;
      isAudioMuted = !p.querySelector('#stt-cfg-audio').checked;

      megaPlates = new Set(platesRaw.split(/[\n,]+/).map(normalizePlate).filter(Boolean));
      bumperlessLocations = new Set(locsRaw.split(/[\n,]+/).map(normalizePlate).filter(Boolean));

      saveStoredSet(STORAGE_KEYS.MEGA, megaPlates);
      saveStoredSet(STORAGE_KEYS.LOCATIONS, bumperlessLocations);
      localStorage.setItem(STORAGE_KEYS.AUDIO_MUTED, String(isAudioMuted));

      var btn = p.querySelector('#stt-cfg-save');
      copyToClipboard('', btn, 'ZAPISANO!');
      scanAll();
    };

    return p;
  }

  // =========================================================================
  // 11. CYKL GŁÓWNY I INICJALIZACJA
  // =========================================================================
  function scanAll() {
    processPTextVrids(document.body);
    processVridAndIsaElements(document.body);
    processPlatesAndRowActions(document.body);
    processLocationSelectors(document.body);
    injectTractorAutoCheckWidgets();
    renderSspBadgesFromCache();
  }

  function backgroundTick() {
    getSspMap().then(function () {
      renderSspBadgesFromCache();
      var clock = document.getElementById('stt-clock');
      if (clock) clock.textContent = '· ' + new Date().toLocaleTimeString('pl-PL');
    }).catch(function (e) {
      console.error('[Sesame Suite] Błąd odświeżania cyklicznego:', e);
    });
  }

  function start() {
    createTacticalPanel();
    scanAll();
    backgroundTick();
    setInterval(backgroundTick, SSP_CACHE_MS);

    var debounceTimer = null;
    var observer = new MutationObserver(function () {
      if (debounceTimer) return;
      debounceTimer = requestAnimationFrame(function () {
        scanAll();
        debounceTimer = null;
      });
    });

    observer.observe(document.body, { childList: true, subtree: true });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', start);
  } else {
    start();
  }
})();
"}

{"title":"NOWY2","content":"// ==UserScript==
// @name         Sesame Gate Master Suite Pro (Auto-Check Tractor VRID Edition)
// @namespace    sesame-gate-suite / lycgracj
// @version      6.3
// @description  Automatyczna detekcja VRID dla ciągników (Tractor) i naczep, auto-sprawdzanie w SSP OB, transfer do terminala, Dockmaster API, alert MEGA.
// @match        https://trans-logistics-eu.amazon.com/yms/sesameGateConsole*
// @connect      prod-eu.eu-west-1.idx-backend.aft.amazon.dev
// @connect      prod-eu.eu-west-1.idx-website.aft.amazon.dev
// @grant        GM_xmlhttpRequest
// @grant        GM.xmlHttpRequest
// @run-at       document-idle
// ==/UserScript==

(function () {
  'use strict';

  // =========================================================================
  // 1. STYLE SYSTEM (TACTICAL FUI & HUD THEME)
  // =========================================================================
  var FUI_STYLES = [
    ':root {',
    '  --fui-bg: #090d12;',
    '  --fui-panel: #111722;',
    '  --fui-card: #161f2e;',
    '  --fui-border: #233147;',
    '  --fui-border-active: #f36c00;',
    '  --fui-orange: #f36c00;',
    '  --fui-text: #c5d1de;',
    '  --fui-text-bright: #f0f6fc;',
    '  --fui-text-dim: #64748b;',
    '  --fui-green: #10b981;',
    '  --fui-amber: #f59e0b;',
    '  --fui-red: #ef4444;',
    '  --fui-slack: #9333ea;',
    '  --fui-font: "JetBrains Mono", "Share Tech Mono", monospace, Consolas;',
    '}',
    '.fui-root, .fui-root * { box-sizing: border-box; border-radius: 0 !important; font-family: var(--fui-font); }',
    '.fui-btn {',
    '  cursor: pointer; background: #121820; color: var(--fui-orange); border: 1px solid var(--fui-orange);',
    '  font-size: 10px; font-weight: 700; padding: 2px 6px; letter-spacing: 0.5px; text-transform: uppercase;',
    '  transition: background 0.15s, color 0.15s, border-color 0.15s;',
    '}',
    '.fui-btn:hover { background: var(--fui-orange); color: #000; }',
    '.fui-btn:active { transform: translateY(1px); }',
    '.fui-btn-sub { background: #1a2332; color: #8198b5; border: 1px solid var(--fui-border); font-size: 9px; padding: 1px 5px; }',
    '.fui-btn-sub:hover { background: #223044; color: #fff; border-color: #3b82f6; }',
    '.fui-btn-green { background: #064e3b; color: #34d399; border: 1px solid #059669; }',
    '.fui-btn-green:hover { background: #10b981; color: #000; }',
    '.fui-btn-slack { background: #3b0764; color: #d8b4fe; border: 1px solid #7e22ce; }',
    '.fui-btn-slack:hover { background: #9333ea; color: #fff; }',
    '.fui-input {',
    '  background: #090d12; border: 1px solid var(--fui-border); color: var(--fui-orange);',
    '  padding: 4px 6px; font-size: 11px; outline: none;',
    '}',
    '.fui-input:focus { border-color: var(--fui-orange); }',
    '.svic-mega-toast {',
    '  pointer-events: auto; min-width: 290px; max-width: 380px; background: #7f1d1d;',
    '  color: #fff; font-size: 11px; font-weight: bold; line-height: 1.35; padding: 10px 12px;',
    '  border-radius: 0 !important; box-shadow: 0 4px 20px rgba(0,0,0,0.85); border: 1px solid #dc2626;',
    '  display: flex; align-items: flex-start; gap: 8px; animation: fui-mega-pulse 0.9s step-start infinite;',
    '}',
    '@keyframes fui-mega-pulse {',
    '  0%, 49% { background: #7f1d1d; border-color: #ef4444; box-shadow: 0 0 10px rgba(239,68,68,0.5); }',
    '  50%, 100% { background: #b91c1c; border-color: #f87171; box-shadow: 0 0 22px rgba(248,113,113,0.9); }',
    '}'
  ].join('\n');

  var styleEl = document.createElement('style');
  styleEl.textContent = FUI_STYLES;
  document.head.appendChild(styleEl);

  // =========================================================================
  // 2. BAZA DANYCH I PAMIĘĆ LOKALNA
  // =========================================================================
  var DEFAULT_MEGA_PLATES = [
    'DL3744P', 'DL4191P', 'DL4661P', 'DL4950P', 'DL5148P', 'DL5149P', 'DL5254P',
    'DL5256P', 'DL5641P', 'DL5642P', 'DL5877P', 'DL5888P', 'DL5889P', 'DL5905P',
    'DL5906P', 'DL5973P', 'DL5974P', 'DL5996P', 'DL5997P', 'DL6052P', 'DL6054P',
    'DL6056P', 'DL6243P', 'DL6244P', 'DL6245P', 'DL6293P', 'DL6335P', 'DL6345P',
    'DL6347P', 'DL6958P', 'DL6961P', 'DL6962P', 'DL6963P', 'DL6964P', 'DL6965P',
    'DL6315P', 'DL6664P', 'DL6546P', 'DL6547P', 'DL7640P', 'DL7641P', 'DL7642P',
    'DL7643P', 'DL7644P', 'DL7645P', 'DL7646P', 'DL7647P', 'DL7648P', 'DL7649P'
  ];

  var DEFAULT_BUMPERLESS_LOCATIONS = [
    'HS-200', 'HS-201', 'HS-204', 'HS-205', 'HS-206', 'HS-207', 'HS-208',
    'HS-215', 'HS-216', 'HS-217', 'HS-218'
  ];

  var STORAGE_KEYS = {
    MEGA: 'sesame_fui_mega_plates',
    LOCATIONS: 'sesame_fui_bumperless_locations',
    AUDIO_MUTED: 'sesame_fui_audio_muted',
    PANEL_GEOM: 'sesame_fui_panel_geom'
  };

  function normalizePlate(val) {
    return (val || '').toUpperCase().replace(/[\s-]/g, '');
  }

  function loadStoredSet(key, fallbackArray) {
    try {
      var raw = localStorage.getItem(key);
      if (!raw) return new Set(fallbackArray.map(normalizePlate));
      return new Set(JSON.parse(raw).map(normalizePlate));
    } catch (e) {
      return new Set(fallbackArray.map(normalizePlate));
    }
  }

  function saveStoredSet(key, setInstance) {
    localStorage.setItem(key, JSON.stringify(Array.from(setInstance)));
  }

  var megaPlates = loadStoredSet(STORAGE_KEYS.MEGA, DEFAULT_MEGA_PLATES);
  var bumperlessLocations = loadStoredSet(STORAGE_KEYS.LOCATIONS, DEFAULT_BUMPERLESS_LOCATIONS);
  var isAudioMuted = localStorage.getItem(STORAGE_KEYS.AUDIO_MUTED) === 'true';

  function isMegaPlate(val) {
    return megaPlates.has(normalizePlate(val));
  }

  function getNode() {
    var m = location.hash.match(/\/(WRO5|WRO6|YWRO|[A-Z0-9]+)\b/i);
    return m ? m[1].toUpperCase() : 'WRO5';
  }

  var VRID_PATTERN = /\b1[0-9A-Z]{8}\b/;

  // =========================================================================
  // 3. WYSZUKIWANIE VRID ZE STRUKTURY CIĄGNIKA (TRACTOR ENGINE)
  // =========================================================================
  function findTractorVrid(startNode) {
    if (!startNode) return null;

    // 1. Sprawdź tekst bezpośrednio w węźle
    var m = (startNode.textContent || '').match(VRID_PATTERN);
    if (m) return m[0];

    // 2. Szukaj w najbliższych kontenerach ciągnika lub wiersza
    var host = startNode.closest('[data-testid*="tractor"], [data-testid*="Tractor"], [data-testid*="row"], tr, .card') || startNode.parentElement;
    if (host) {
      m = (host.textContent || '').match(VRID_PATTERN);
      if (m) return m[0];

      // Przeszukaj atrybuty danych
      var attrs = ['data-vrid', 'data-load-id', 'title', 'value', 'aria-label'];
      for (var i = 0; i < attrs.length; i++) {
        var attrVal = host.getAttribute ? host.getAttribute(attrs[i]) : null;
        if (attrVal) {
          var mAttr = attrVal.match(VRID_PATTERN);
          if (mAttr) return mAttr[0];
        }
      }
    }

    // 3. Jeśli to komórka ciągnika, szukaj w całym nadrzędnym wierszu
    var topRow = startNode.closest('tr, [role="row"], .card, .row');
    if (topRow) {
      m = (topRow.textContent || '').match(VRID_PATTERN);
      if (m) return m[0];

      // Szukanie etykiety VRID
      var allLeaves = topRow.querySelectorAll('*');
      for (var j = 0; j < allLeaves.length; j++) {
        var leaf = allLeaves[j];
        if (leaf.children.length === 0) {
          var t = leaf.textContent.trim();
          var mV = t.match(/^VRID\s+(\S+)$/);
          if (mV) return mV[1];
          var mPure = t.match(VRID_PATTERN);
          if (mPure) return mPure[0];
        }
      }
    }
    return null;
  }

  // =========================================================================
  // 4. SYNTEZATOR AUDIO & SCHOWEK
  // =========================================================================
  var audioCtx = null;
  function playMegaAlertBeep() {
    if (isAudioMuted) return;
    try {
      if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
      if (audioCtx.state === 'suspended') audioCtx.resume();

      var now = audioCtx.currentTime;
      var osc = audioCtx.createOscillator();
      var gain = audioCtx.createGain();

      osc.type = 'sawtooth';
      osc.frequency.setValueAtTime(940, now);
      osc.frequency.setValueAtTime(1880, now + 0.1);

      gain.gain.setValueAtTime(0.09, now);
      gain.gain.exponentialRampToValueAtTime(0.001, now + 0.25);

      osc.connect(gain);
      gain.connect(audioCtx.destination);

      osc.start(now);
      osc.stop(now + 0.25);
    } catch (e) {}
  }

  function copyToClipboard(text, btnElement, successMsg) {
    if (!successMsg) successMsg = '✔ SKOPIOWANO';
    var notify = function () {
      if (btnElement) {
        var orig = btnElement.textContent;
        btnElement.textContent = successMsg;
        btnElement.style.background = '#10b981';
        btnElement.style.color = '#000';
        btnElement.style.borderColor = '#10b981';
        setTimeout(function () {
          btnElement.textContent = orig;
          btnElement.style.background = '';
          btnElement.style.color = '';
          btnElement.style.borderColor = '';
        }, 1200);
      }
    };

    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(text).then(notify).catch(function () {
        fallbackCopy(text);
        notify();
      });
    } else {
      fallbackCopy(text);
      notify();
    }
  }

  function fallbackCopy(text) {
    var ta = document.createElement('textarea');
    ta.value = text;
    ta.style.position = 'fixed';
    ta.style.opacity = '0';
    document.body.appendChild(ta);
    ta.select();
    try { document.execCommand('copy'); } catch (e) {}
    document.body.removeChild(ta);
  }

  function gmRequest(opts) {
    var impl = (typeof GM_xmlhttpRequest === 'function')
      ? GM_xmlhttpRequest
      : (typeof GM !== 'undefined' && GM.xmlHttpRequest) ? GM.xmlHttpRequest : null;
    if (!impl) {
      if (opts.onerror) opts.onerror(new Error('Brak uprawnien GM_xmlhttpRequest'));
      return;
    }
    impl(opts);
  }

  // =========================================================================
  // 5. DOCKMASTER API
  // =========================================================================
  var DOCKMASTER_API_BASE = 'https://prod-eu.eu-west-1.idx-backend.aft.amazon.dev/v1/appointment-detail';
  var isaCache = new Map();

  function fetchAppointmentDetail(isaNumber, siteCode) {
    return new Promise(function (resolve, reject) {
      var url = DOCKMASTER_API_BASE + '/' + siteCode + '/' + isaNumber + '?includeMilkRun=true';
      var refererUrl = 'https://prod-eu.eu-west-1.idx-website.aft.amazon.dev/en_US/' + siteCode + '/appointment/view/' + isaNumber + '/appointmentDetail';
      gmRequest({
        method: 'GET',
        url: url,
        anonymous: false,
        headers: {
          'Referer': refererUrl,
          'X-Requested-With': 'XMLHttpRequest'
        },
        onload: function (res) {
          if (res.status >= 200 && res.status < 300) resolve(res.responseText);
          else reject(new Error('HTTP ' + res.status));
        },
        onerror: reject,
        ontimeout: function () { reject(new Error('Timeout')); },
        timeout: 12000
      });
    });
  }

  function getAttributeValue(xmlDoc, keyName) {
    var entries = xmlDoc.getElementsByTagName('entry');
    for (var i = 0; i < entries.length; i++) {
      var entry = entries[i];
      var keyEl = entry.getElementsByTagName('key')[0];
      if (keyEl && keyEl.textContent === keyName) {
        var outerVal = entry.getElementsByTagName('value')[0];
        if (outerVal) {
          var innerVal = outerVal.getElementsByTagName('value')[0];
          return innerVal ? innerVal.textContent.trim() : null;
        }
      }
    }
    return null;
  }

  function getSimpleTag(xmlDoc, tagName) {
    var el = xmlDoc.getElementsByTagName(tagName)[0];
    return el ? el.textContent.trim() : null;
  }

  function parseAppointmentXml(xmlText) {
    var parser = new DOMParser();
    var xmlDoc = parser.parseFromString(xmlText, 'application/xml');
    return {
      loadType: getAttributeValue(xmlDoc, 'CARRIER_LOAD_TYPE'),
      isPalletized: getAttributeValue(xmlDoc, 'IS_PALLETIZED'),
      location: getAttributeValue(xmlDoc, 'YMS_CURRENT_LOCATION'),
      vrid: getAttributeValue(xmlDoc, 'VRID'),
      palletCount: getSimpleTag(xmlDoc, 'palletCount'),
      cartonCount: getSimpleTag(xmlDoc, 'cartonCount'),
      unitCount: getSimpleTag(xmlDoc, 'unitCount'),
      status: getSimpleTag(xmlDoc, 'status')
    };
  }

  function buildIsaBadgeText(data) {
    if (!data) return null;
    var parts = [];
    var loadType = (data.loadType || '').toUpperCase();
    var isPalletized = (data.isPalletized || '').toUpperCase();

    if (loadType === 'LIVE') parts.push('🟢 LIVE');
    else if (loadType === 'DROP') parts.push('🟡 DROP');
    else if (loadType) parts.push('⚪ ' + loadType);

    if (isPalletized === 'YES') {
      parts.push(data.palletCount ? ('📦 PALETA (' + data.palletCount + ')') : '📦 PALETA');
    } else if (isPalletized === 'NO') {
      parts.push('📄 LUZ');
    }
    return parts.length ? parts.join(' · ') : null;
  }

  function attachIsaBadge(isaNumber, afterEl) {
    if (afterEl.hasAttribute('data-svic-badge')) return;
    afterEl.setAttribute('data-svic-badge', '1');

    var badge = document.createElement('span');
    badge.className = 'fui-root';
    badge.style.cssText = 'display:block;margin-top:2px;font-size:10px;line-height:1.2;padding:2px 5px;background:#0d141f;color:#c5d1de;border:1px solid #233147;border-left:3px solid #f36c00;width:fit-content;';
    badge.textContent = '⏳ ISA...';
    afterEl.insertAdjacentElement('afterend', badge);

    var siteCode = getNode();
    if (isaCache.has(isaNumber)) {
      var cached = isaCache.get(isaNumber);
      if (cached.status === 'done') {
        badge.textContent = buildIsaBadgeText(cached.data) || 'ℹ️ BRAK METADANYCH';
        return;
      }
      if (cached.status === 'error') {
        badge.textContent = '⚠️ BLAD ISA';
        return;
      }
      cached.subscribers.push(badge);
      return;
    }

    var entry = { status: 'loading', subscribers: [badge], data: null };
    isaCache.set(isaNumber, entry);

    fetchAppointmentDetail(isaNumber, siteCode)
      .then(function (xmlText) {
        var data = parseAppointmentXml(xmlText);
        entry.status = 'done';
        entry.data = data;
        var text = buildIsaBadgeText(data) || 'ℹ️ BRAK METADANYCH';
        entry.subscribers.forEach(function (b) {
          b.textContent = text;
          b.title = JSON.stringify(data, null, 2);
        });
      })
      .catch(function (err) {
        entry.status = 'error';
        entry.subscribers.forEach(function (b) {
          b.textContent = '⚠️ BLAD ISA';
          b.title = String(err);
        });
      });
  }

  // =========================================================================
  // 6. SSP OUTBOUND DOCK STATUS
  // =========================================================================
  var SSP_PATH_PAGE = '/ssp/dock/hrz/ob';
  var SSP_PATH_DATA = '/ssp/dock/hrz/ob/fetchdata?';
  var SSP_WINDOW_MS = 3 * 24 * 3600 * 1000;
  var SSP_CACHE_MS  = 60 * 1000;

  var SSP_CACHE = { ts: 0, map: null, inflight: null };

  function describeSspLoad(load, item) {
    var s = load.status;
    var hasTrailer = !!(item.trailer && (item.trailer.trailerNumber || item.trailer.trailer));
    switch (s) {
      case 'SCHEDULED':
        return hasTrailer
          ? { label: 'Zaplanowana (jest naczepa)', color: '#334155', isReady: false }
          : { label: 'Naczepy brak (plan)', color: '#1e293b', isReady: false };
      case 'READY_FOR_LOADING':
        return { label: 'Gotowa do zaladunku', color: '#1e40af', isReady: false };
      case 'TRAILER_ATTACHED':
        return { label: 'Naczepa podpieta', color: '#2563eb', isReady: false };
      case 'LOADING_IN_PROGRESS':
        return { label: 'Ladowanie w toku', color: '#b45309', isReady: false };
      case 'LOADING_PAUSED':
        return { label: 'Wstrzymana', color: '#92400e', isReady: false };
      case 'FINISHED_LOADING':
        return { label: 'ZALADOWANA / GOTOWA', color: '#065f46', isReady: true };
      case 'COMPLETED':
        return { label: 'Wyjechala', color: '#0f172a', isReady: false };
      case 'CANCELLED':
        return { label: 'Anulowana', color: '#991b1b', isReady: false };
      default:
        return { label: s || 'Nieznany', color: '#1e293b', isReady: false };
    }
  }

  function getSspDoor(item) {
    if (item.resource && item.resource.length && item.resource[0].label) {
      var r = item.resource[0];
      return r.label + (r.resType === 'YARD' ? ' (plac)' : '');
    }
    if (item.trailer && item.trailer.location) return item.trailer.location;
    return null;
  }

  function fetchSspMap() {
    return fetch(SSP_PATH_PAGE, { credentials: 'include' })
      .then(function (pageResp) {
        if (!pageResp.ok) throw new Error('Blad OB: ' + pageResp.status);
        return pageResp.text();
      })
      .then(function (html) {
        var doc  = new DOMParser().parseFromString(html, 'text/html');
        var meta = doc.querySelector('meta[name="anti-csrftoken-a2z"]');
        if (!meta || !meta.content) throw new Error('Brak CSRF na stronie OB');
        var token = meta.content;

        var now = Date.now();
        var body = 'entity=getOutboundDockView&nodeId=' + encodeURIComponent(getNode())
          + '&startDate=' + (now - SSP_WINDOW_MS) + '&endDate=' + (now + SSP_WINDOW_MS)
          + '&loadCategories=outboundScheduled%2CoutboundInProgress%2CoutboundReadyToDepart%2CoutboundDeparted%2CoutboundCancelled'
          + '&shippingPurposeType=TRANSSHIPMENT%2CNON-TRANSSHIPMENT%2CSHIP_WITH_AMAZON';

        return fetch(SSP_PATH_DATA, {
          method: 'POST',
          credentials: 'include',
          headers: {
            'Content-Type': 'application/x-www-form-urlencoded; charset=UTF-8',
            'anti-csrftoken-a2z': token
          },
          body: body
        });
      })
      .then(function (resp) {
        if (!resp.ok) throw new Error('Blad endpointu OB: ' + resp.status);
        return resp.json();
      })
      .then(function (json) {
        var arr = (json.ret && json.ret.aaData) || [];
        var map = {};

        arr.forEach(function (item) {
          var load = item.load;
          if (!load || !load.vrId) return;
          var d = describeSspLoad(load, item);
          map[load.vrId] = {
            vrId:    load.vrId,
            status:  load.status,
            label:   d.label,
            color:   d.color,
            isReady: d.isReady,
            route:   load.route || '',
            door:    getSspDoor(item),
            sdt:     load.scheduledDepartureTime || '',
            adt:     load.actualDepartureTime   || '',
            cpt:     load.criticalPullTime      || '',
            carrier: load.carrier || ''
          };
        });
        return map;
      });
  }

  function getSspMap() {
    if (SSP_CACHE.map && (Date.now() - SSP_CACHE.ts) < SSP_CACHE_MS) {
      return Promise.resolve(SSP_CACHE.map);
    }
    if (SSP_CACHE.inflight) return SSP_CACHE.inflight;
    SSP_CACHE.inflight = fetchSspMap()
      .then(function (map) {
        SSP_CACHE.map = map;
        SSP_CACHE.ts = Date.now();
        SSP_CACHE.inflight = null;
        return map;
      })
      .catch(function (err) {
        SSP_CACHE.inflight = null;
        console.error('[SSP OB] Blad pobierania:', err);
        return SSP_CACHE.map || {};
      });
    return SSP_CACHE.inflight;
  }

  window.getSSPInfo = function (vrid) {
    return getSspMap().then(function (map) {
      return map[vrid] || null;
    });
  };

  function buildSspBadge(info) {
    var b = document.createElement('span');
    b.className = 'fui-root';
    b.dataset.vrid = info.vrId;
    b.style.cssText =
      'display:inline-block;margin-left:4px;padding:2px 5px;'
      + 'font-size:10px;font-weight:700;line-height:1.2;color:#ffffff;vertical-align:middle;'
      + 'background:' + info.color + ';white-space:nowrap;letter-spacing:0.3px;'
      + 'border:1px solid #233147;border-left:3px solid ' + (info.isReady ? '#10b981' : '#f59e0b') + ';';

    var parts = [];
    if (info.isReady) parts.push('✔ GOTOWA');
    if (info.door) parts.push('[' + info.door + ']');
    parts.push(info.label);
    if (info.sdt) parts.push('PLAN: ' + info.sdt);

    b.textContent = parts.join(' · ');
    return b;
  }

  // =========================================================================
  // 7. FORMATY SLACK
  // =========================================================================
  function formatSingleSlack(info) {
    var icon = info.isReady ? ':white_check_mark:' : (info.status === 'LOADING_IN_PROGRESS' ? ':hourglass_flowing_sand:' : ':warning:');
    return icon + ' *[' + getNode() + ' OUTBOUND STATUS]*\n'
      + '• *VRID:* `' + info.vrId + '`\n'
      + '• *Status:* *' + info.label + '* (`' + info.status + '`)\n'
      + '• *Gotowość:* ' + (info.isReady ? '*GOTOWA DO DROGI*' : '_W TRAKCIE / NIEGOTOWA_') + '\n'
      + '• *Drzwi/Plac:* `' + (info.door || 'Brak') + '` | *Trasa:* `' + (info.route || '-') + '`\n'
      + '• *Przewoźnik:* ' + (info.carrier || '-') + '\n'
      + '• *Plan (SDT):* ' + (info.sdt || '-') + ' | *CPT:* `' + (info.cpt || '-') + '`';
