  function formatListSlack(loads) {
    var now = new Date().toLocaleTimeString('pl-PL', { hour: '2-digit', minute: '2-digit' });
    var text = ':truck: *[' + getNode() + '] Raport gotowości Outbound (' + now + ')*\n'
      + 'Łącznie gotowych ładunków: *' + loads.length + '*\n\n';
    loads.forEach(function (l, idx) {
      text += (idx + 1) + '. `' + l.vrId + '` | Dok: *' + (l.door || 'Plac') + '* | Trasa: *' + (l.route || '-') + '* | CPT: `' + (l.cpt || '-') + '`\n';
    });
