  // =========================================================================
  // 8. MEGA ALERT & SZYBKI WYBÓR PÓL
  // =========================================================================
  var TOAST_CONTAINER_ID = 'svic-mega-toast-container';
  var activeMegaToasts = new Map();

  function ensureToastContainer() {
    var container = document.getElementById(TOAST_CONTAINER_ID);
    if (!container) {
      container = document.createElement('div');
      container.id = TOAST_CONTAINER_ID;
      container.className = 'fui-root';
      container.style.cssText = 'position:fixed;bottom:16px;right:16px;z-index:999999;display:flex;flex-direction:column-reverse;gap:8px;pointer-events:none;';
      document.body.appendChild(container);
    }
    return container;
  }

  function showMegaToast(value) {
    var plateKey = normalizePlate(value);
    if (activeMegaToasts.has(plateKey)) return;

    var container = ensureToastContainer();
    var toast = document.createElement('div');
    toast.className = 'svic-mega-toast fui-root';

    var text = document.createElement('span');
    text.textContent = '⚠️ MEGA: ' + value + ' — Kierowca na pole bez bumperów!';
    toast.appendChild(text);

    var closeBtn = document.createElement('button');
    closeBtn.textContent = '✖';
    closeBtn.style.cssText = 'margin-left:auto;cursor:pointer;background:none;border:none;color:#fff;font-size:13px;font-weight:bold;';
    closeBtn.onclick = function (e) {
      e.stopPropagation();
      toast.remove();
      activeMegaToasts.delete(plateKey);
    };
    toast.appendChild(closeBtn);

    container.appendChild(toast);
    activeMegaToasts.set(plateKey, toast);
    playMegaAlertBeep();
  }

  function dismissMegaToast(plateKey) {
    var toast = activeMegaToasts.get(plateKey);
    if (toast) {
      toast.remove();
      activeMegaToasts.delete(plateKey);
    }
  }

  function setLocationInputValue(input, val, associatedPlate) {
    var setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
    setter.call(input, val);
    input.dispatchEvent(new Event('input', { bubbles: true }));

    if (bumperlessLocations.has(normalizePlate(val)) && associatedPlate) {
      dismissMegaToast(normalizePlate(associatedPlate));
    }
  }

  function makeLocationPicker(input, associatedPlate) {
    var wrap = document.createElement('span');
    wrap.className = 'fui-root';
    wrap.style.cssText = 'position:relative;display:inline-block;margin-left:4px;vertical-align:middle;';

    var btn = document.createElement('button');
    btn.textContent = '📍';
    btn.title = 'Wybór pola bez bumperów (HS-xxx)';
    btn.type = 'button';
    btn.className = 'fui-btn';
    btn.style.padding = '2px 4px';

    btn.onclick = function (e) {
      e.preventDefault();
      e.stopPropagation();

      var existing = wrap.querySelector('.svic-loc-picker-menu');
      document.querySelectorAll('.svic-loc-picker-menu').forEach(function (m) { m.remove(); });
      if (existing) return;

      var menu = document.createElement('div');
      menu.className = 'svic-loc-picker-menu fui-root';
      menu.style.cssText = 'position:absolute;top:100%;left:0;z-index:10000;background:#090d12;border:1px solid #f36c00;box-shadow:0 4px 16px rgba(0,0,0,0.85);min-width:130px;max-height:220px;overflow-y:auto;padding:2px 0;';

      var title = document.createElement('div');
      title.textContent = 'POLA BEZ BUMPERÓW:';
      title.style.cssText = 'padding:3px 6px;font-size:9px;font-weight:bold;color:#f36c00;border-bottom:1px solid #233147;background:#111722;';
      menu.appendChild(title);

      Array.from(bumperlessLocations).sort().forEach(function (loc) {
        var item = document.createElement('div');
        item.textContent = loc;
        item.style.cssText = 'padding:4px 6px;font-size:11px;cursor:pointer;color:#c5d1de;';
        item.onmouseenter = function () { item.style.background = '#1a2332'; item.style.color = '#f36c00'; };
        item.onmouseleave = function () { item.style.background = 'transparent'; item.style.color = '#c5d1de'; };
        item.onclick = function (e2) {
          e2.stopPropagation();
          setLocationInputValue(input, loc, associatedPlate);
          menu.remove();
        };
        menu.appendChild(item);
      });

      wrap.appendChild(menu);
      var onDocClick = function (e3) {
        if (!wrap.contains(e3.target)) {
          menu.remove();
          document.removeEventListener('click', onDocClick);
        }
      };
      setTimeout(function () { document.addEventListener('click', onDocClick); }, 0);
    };

    wrap.appendChild(btn);
    return wrap;
  }

  // =========================================================================
  // 9. AUTOMATYCZNA OBSŁUGA VRID W INTERFEJSIE
  // =========================================================================
  function transferVridToTerminal(vrid, autoTrigger) {
    var p = document.getElementById('sesame-tactical-terminal');
    if (!p || !vrid) return;

    var input = p.querySelector('#stt-vrid-in');
    var btn = p.querySelector('#stt-vrid-btn');
    if (input) {
      input.value = vrid;
      if (autoTrigger && btn) {
        btn.click();
      }
    }
  }

  function executeAutoCheck(vrid, btn, statusSlot) {
    if (!vrid) return;

    btn.textContent = 'SPRAWDZAM...';
    btn.style.opacity = '0.7';

    window.getSSPInfo(vrid)
      .then(function (info) {
        statusSlot.innerHTML = '';
        if (!info) {
          statusSlot.innerHTML = '<span style="color:#ef4444;font-size:10px;font-weight:700">[BRAK W OB]</span>';
          btn.textContent = 'OB: ' + vrid;
          btn.style.opacity = '1';
          return;
        }

        var badge = buildSspBadge(info);
        statusSlot.appendChild(badge);
        btn.textContent = info.isReady ? '✔ GOTOWA' : '⌛ ' + info.label;
        btn.style.borderColor = info.isReady ? '#10b981' : '#f59e0b';
        btn.style.color = info.isReady ? '#10b981' : '#f59e0b';
        btn.style.opacity = '1';
      })
      .catch(function () {
        btn.textContent = 'BLAD OB';
        btn.style.borderColor = '#ef4444';
        btn.style.color = '#ef4444';
        btn.style.opacity = '1';
      });
  }

  function createTractorCheckWidget(vrid, hostNode) {
    var wrap = document.createElement('div');
    wrap.className = 'ssp-vrid-action-wrap fui-root';
    wrap.style.cssText = 'display:inline-flex;align-items:center;gap:4px;margin:2px 0;';

    var btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'fui-btn';
    btn.textContent = 'OB: ' + vrid;
    btn.title = 'VRID Ciągnika: ' + vrid + ' (Kliknij, aby wysłać do terminala)';

    var statusSlot = document.createElement('span');
    statusSlot.className = 'ssp-result-slot';

    btn.onclick = function (e) {
      e.stopPropagation();
      e.preventDefault();
      var liveVrid = findTractorVrid(hostNode) || vrid;
      transferVridToTerminal(liveVrid, true);
      executeAutoCheck(liveVrid, btn, statusSlot);
    };

    wrap.appendChild(btn);
    wrap.appendChild(statusSlot);

    // AUTO-SPRAWDZENIE: Natychmiast po wstrzyknięciu do DOM
    setTimeout(function () {
      executeAutoCheck(vrid, btn, statusSlot);
    }, 100);

    return wrap;
  }

  function extractConsolidatedRowDetails(hostRow) {
    var plateCells = hostRow.querySelectorAll('[data-testid="licensePlateNumber"]');
    var plates = [];
    for (var i = 0; i < plateCells.length; i++) {
      var t = plateCells[i].textContent.trim();
      if (t && t !== '---') plates.push(t);
    }

    var vrid = findTractorVrid(hostRow) || '-';
    var isa = '';
    var allNodes = hostRow.querySelectorAll('*');
    for (var j = 0; j < allNodes.length; j++) {
      var el = allNodes[j];
      if (el.children.length === 0) {
        var txt = el.textContent.trim();
        var mIsa = txt.match(/^ISA\s+(\S+)$/);
        if (mIsa) isa = mIsa[1];
      }
    }

    var extraIsa = '';
    if (isa && isaCache.has(isa) && isaCache.get(isa).status === 'done') {
      var d = isaCache.get(isa).data;
      extraIsa = ' | Typ: ' + (d.loadType || '-') + ' | Palety: ' + (d.palletCount || '-');
    }

    var extraOb = '';
    if (vrid !== '-' && SSP_CACHE.map && SSP_CACHE.map[vrid]) {
      var ob = SSP_CACHE.map[vrid];
      extraOb = ' | OB: ' + ob.label + ' (' + (ob.door || 'Brak doku') + ') | CPT: ' + (ob.cpt || '-');
    }

    return 'VRID: ' + vrid + ' | ISA: ' + (isa || '-') + ' | Rej: ' + (plates.join(' / ') || '-') + extraIsa + extraOb;
  }

  function makeQuickCopyBtn(label, val) {
    var btn = document.createElement('button');
    btn.textContent = '📋';
    btn.title = 'Kopiuj ' + label + ': ' + val;
    btn.type = 'button';
    btn.className = 'fui-btn-sub fui-root';
    btn.style.cssText = 'margin-left:4px;vertical-align:middle;';
    btn.onclick = function (e) {
      e.stopPropagation();
      copyToClipboard(val, btn, '✔');
    };
    return btn;
  }

  function processVridAndIsaElements(root) {
    var valRegex = /^(VRID|ISA)\s+(\S+)$/;
    var walker = document.createTreeWalker(root, NodeFilter.SHOW_ELEMENT, {
      acceptNode: function (el) {
        if (el.hasAttribute('data-svic-processed') || el.classList.contains('svic-copy-btn')) {
          return NodeFilter.FILTER_REJECT;
        }
        var text = (el.textContent || '').trim();
        return (valRegex.test(text) && el.children.length === 0) ? NodeFilter.FILTER_ACCEPT : NodeFilter.FILTER_SKIP;
      }
    });

    var matches = [];
    while (walker.nextNode()) matches.push(walker.currentNode);

    matches.forEach(function (el) {
      var match = el.textContent.trim().match(valRegex);
      if (!match) return;
      el.setAttribute('data-svic-processed', '1');
      var label = match[1];
      var value = match[2];

      var btn = makeQuickCopyBtn(label, value);
      btn.className += ' svic-copy-btn';
      el.insertAdjacentElement('afterend', btn);

      if (label === 'ISA') {
        attachIsaBadge(value, btn);
      }
    });
  }

  function processPlatesAndRowActions(root) {
    var cells = root.querySelectorAll ? root.querySelectorAll('[data-testid="licensePlateNumber"]') : [];
    for (var i = 0; i < cells.length; i++) {
      var cell = cells[i];
      if (cell.hasAttribute('data-svic-plate-processed')) continue;
      var text = cell.textContent.trim();
      cell.setAttribute('data-svic-plate-processed', '1');
      if (!text || text === '---') continue;

      var btn = makeQuickCopyBtn('Rejestracja', text);
      cell.insertAdjacentElement('afterend', btn);

      var hostRow = cell.closest('tr, [role="row"], .card, .row');
      if (!hostRow && cell.parentElement) {
        hostRow = cell.parentElement.parentElement;
      }

      if (isMegaPlate(text)) {
        showMegaToast(text);
      }

      if (hostRow && !hostRow.hasAttribute('data-svic-row-export-processed')) {
        hostRow.setAttribute('data-svic-row-export-processed', '1');

        (function (row) {
          var fullCopyBtn = document.createElement('button');
          fullCopyBtn.textContent = '📋 FULL';
          fullCopyBtn.title = 'Kopiuj zintegrowane dane wiersza (Sesame + Dockmaster + SSP OB)';
          fullCopyBtn.className = 'fui-btn-sub fui-root';
          fullCopyBtn.style.cssText = 'margin-left:6px;vertical-align:middle;color:var(--fui-orange);border-color:#334155;';
          fullCopyBtn.onclick = function (e) {
            e.stopPropagation();
            var dataString = extractConsolidatedRowDetails(row);
            copyToClipboard(dataString, fullCopyBtn, 'OK!');
          };
          cell.insertAdjacentElement('afterend', fullCopyBtn);
        })(hostRow);
      }
    }
  }

  function processLocationSelectors(root) {
    var containers = root.querySelectorAll ? root.querySelectorAll('[data-testid="gateOperationSummaryLocationSelect"]') : [];
    for (var i = 0; i < containers.length; i++) {
      var container = containers[i];
      if (container.hasAttribute('data-svic-location-widget')) continue;

      var row = container.parentElement;
      var plateCells = [];
      var hops = 0;
      while (row && hops < 8) {
        plateCells = Array.from(row.querySelectorAll('[data-testid="licensePlateNumber"]'));
        if (plateCells.length > 0) break;
        row = row.parentElement;
        hops++;
      }
      if (!row || plateCells.length === 0) continue;

      var megaPlateMatch = null;
      for (var j = 0; j < plateCells.length; j++) {
        if (isMegaPlate(plateCells[j].textContent.trim())) {
          megaPlateMatch = plateCells[j];
          break;
        }
      }
      if (!megaPlateMatch) continue;

      var input = container.querySelector('input');
      if (!input) continue;

      container.setAttribute('data-svic-location-widget', '1');
      var picker = makeLocationPicker(input, megaPlateMatch.textContent.trim());
      container.insertAdjacentElement('afterend', picker);
    }
  }

  // Wstrzykiwanie widgetu sprawdzania ciągnika z auto-startem
  function injectTractorAutoCheckWidgets() {
    var selectors = [
      '[data-testid*="tractor"]',
      '[data-testid*="Tractor"]',
      '.tractor-cell',
      '[data-testid*="loadContainer"]',
      '[data-testid*="load-container"]',
      '[data-testid*="LoadContainer"]',
      '.load-container'
    ];

    var targetCells = [];
    try {
      targetCells = Array.from(document.querySelectorAll(selectors.join(',')));
    } catch (e) {
      targetCells = Array.from(document.querySelectorAll('[data-testid*="tractor"], [data-testid*="loadContainer"]'));
    }

    targetCells.forEach(function (cell) {
      if (cell.querySelector('.ssp-vrid-action-wrap')) return;

      var host = cell.closest('tr, [role="row"], .card, .row, [data-testid*="row"]') || cell.parentElement;
      if (!host) return;

      var vrid = findTractorVrid(host);
      if (!vrid) return;

      // Transfer do inputa w panelu (jeśli jest pusty)
      var terminalInput = document.querySelector('#stt-vrid-in');
      if (terminalInput && !terminalInput.value) {
        terminalInput.value = vrid;
      }

      var widget = createTractorCheckWidget(vrid, host);
      cell.appendChild(widget);
    });
  }

  function renderSspBadgesFromCache() {
    if (!SSP_CACHE.map) return;
    document.querySelectorAll('[data-testid="licensePlateNumber"]').forEach(function (cell) {
      var host = cell.closest('tr, [role="row"], .card, .row, td, div') || cell;
      var vrid = findTractorVrid(host);
      if (!vrid) return;

      var info = SSP_CACHE.map[vrid];
      if (!info) return;

      var existing = host.querySelector('.ssp-ob-badge');
      if (existing) {
        if (existing.dataset.vrid === info.vrId) return;
        existing.remove();
      }

      var badge = buildSspBadge(info);
      badge.className += ' ssp-ob-badge';
      badge.style.display = 'block';
      badge.style.marginTop = '2px';
      cell.insertAdjacentElement('afterend', badge);
    });
  }

