    document.body.appendChild(p);

    // Geometria okna
    try {
      var geom = JSON.parse(localStorage.getItem(STORAGE_KEYS.PANEL_GEOM) || 'null');
      if (geom) {
        if (geom.left) p.style.left = geom.left;
        if (geom.top) p.style.top = geom.top;
        p.style.right = 'auto'; p.style.bottom = 'auto';
        if (geom.w) p.style.width = geom.w;
        if (geom.h) p.style.height = geom.h;
      }
    } catch (e) {}

    var saveGeom = function () {
      try {
        var r = p.getBoundingClientRect();
        localStorage.setItem(STORAGE_KEYS.PANEL_GEOM, JSON.stringify({
          left: Math.round(r.left) + 'px',
          top: Math.round(r.top) + 'px',
          w: p.style.width,
          h: p.style.height
        }));
      } catch (e) {}
    };

