      tabs.style.display = isCollapsed ? 'flex' : 'none';
      p.style.height = isCollapsed ? 'auto' : '32px';
      minBtn.textContent = isCollapsed ? '_' : '□';
    };

    // Nawigacja zakładkami
    var tabSearch = p.querySelector('#stt-tab-search');
    var tabReady = p.querySelector('#stt-tab-ready');
    var tabCfg = p.querySelector('#stt-tab-cfg');
    var viewSearch = p.querySelector('#stt-view-search');
    var viewReady = p.querySelector('#stt-view-ready');
    var viewCfg = p.querySelector('#stt-view-cfg');

    function switchTab(activeTab, activeView) {
      [tabSearch, tabReady, tabCfg].forEach(function (t) {
        t.style.background = '#090d12';
        t.style.color = '#64748b';
        t.style.borderBottom = 'none';
      });
      [viewSearch, viewReady, viewCfg].forEach(function (v) { v.style.display = 'none'; });
      activeTab.style.background = '#161f2e';
      activeTab.style.color = '#f36c00';
      activeTab.style.borderBottom = '2px solid #f36c00';
      activeView.style.display = 'flex';
    }

    tabSearch.onclick = function () { switchTab(tabSearch, viewSearch); };
    tabReady.onclick = function () {
      switchTab(tabReady, viewReady);
      loadReadyOutboundList();
    };
    tabCfg.onclick = function () {
      switchTab(tabCfg, viewCfg);
      p.querySelector('#stt-cfg-plates').value = Array.from(megaPlates).join(', ');
      p.querySelector('#stt-cfg-locs').value = Array.from(bumperlessLocations).join(', ');
    };

    // Obsługa sprawdzania VRID w panelu
    var execVridSearch = function () {
      var input = p.querySelector('#stt-vrid-in').value.trim().toUpperCase();
      var card = p.querySelector('#stt-vrid-card');
      if (!input) {
        card.style.display = 'block';
        card.style.borderColor = '#b45309';
        card.innerHTML = '<span style="color:#f59e0b">Podaj prawidłowy numer VRID.</span>';
        return;
      }
      card.style.display = 'block';
      card.style.borderColor = '#233147';
      card.innerHTML = '<span style="color:#38bdf8">Przeszukiwanie bazy SSP OB...</span>';

      window.getSSPInfo(input).then(function (info) {
        if (!info) {
          card.style.borderColor = '#ef4444';
          card.innerHTML = '<span style="color:#ef4444;font-weight:bold">VRID: ' + input + ' — BRAK W SYSTEMIE OB</span>';
          return;
        }

        var verdictColor = info.isReady ? '#10b981' : (info.status === 'LOADING_IN_PROGRESS' ? '#f59e0b' : '#ef4444');
        card.style.borderColor = verdictColor;
        card.innerHTML =
          '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px;border-bottom:1px solid #233147;padding-bottom:4px">'
          + '<span style="font-weight:900;color:' + verdictColor + '">[ ' + (info.isReady ? 'GOTOWA DO DROGI' : info.label) + ' ]</span>'
          + '<button id="stt-slack-single-btn" class="fui-btn-slack" style="padding:1px 6px;">SLACK</button>'
          + '</div>'
          + '<div><b>VRID:</b> <span style="color:#38bdf8">' + info.vrId + '</span></div>'
          + '<div><b>Lokalizacja/Dok:</b> <span style="color:#f36c00">' + (info.door || 'Brak doku') + '</span></div>'
          + '<div><b>Status:</b> ' + info.label + ' (' + info.status + ')</div>'
          + '<div><b>Trasa:</b> ' + (info.route || '-') + ' | <b>Przewoźnik:</b> ' + (info.carrier || '-') + '</div>'
          + '<div><b>Plan (SDT):</b> ' + (info.sdt || '-') + ' | <b>CPT:</b> <span style="color:#f59e0b">' + (info.cpt || '-') + '</span></div>';

        card.querySelector('#stt-slack-single-btn').onclick = function () {
          copyToClipboard(formatSingleSlack(info), this);
        };
      });
    };

    p.querySelector('#stt-vrid-btn').onclick = execVridSearch;
    p.querySelector('#stt-vrid-in').onkeydown = function (e) { if (e.key === 'Enter') execVridSearch(); };

    function loadReadyOutboundList() {
      var listEl = p.querySelector('#stt-ready-list');
      listEl.innerHTML = '<span style="color:#64748b;padding:4px">Wczytywanie danych z SSP OB...</span>';

      getSspMap().then(function (map) {
        var readyList = Object.values(map).filter(function (i) { return i.isReady; });
        if (!readyList.length) {
          listEl.innerHTML = '<span style="color:#64748b;padding:4px">Brak gotowych ładunków na placu.</span>';
          return;
        }

        listEl.innerHTML = '';
        readyList.forEach(function (item) {
          var row = document.createElement('div');
          row.style.cssText = 'padding:4px 6px;background:#111722;border:1px solid #233147;display:flex;justify-content:space-between;align-items:center;font-size:10px;';
          row.innerHTML = '<div><b style="color:#38bdf8">' + item.vrId + '</b> | Dok: <b>' + (item.door || '-') + '</b> | CPT: <b style="color:#f59e0b">' + (item.cpt || '-') + '</b></div>';

          var sBtn = document.createElement('button');
          sBtn.textContent = 'SLACK';
          sBtn.className = 'fui-btn-slack';
          sBtn.style.padding = '1px 5px';
          sBtn.onclick = function () { copyToClipboard(formatSingleSlack(item), sBtn, 'OK!'); };
          row.appendChild(sBtn);
          listEl.appendChild(row);
        });

        p.querySelector('#stt-slack-bulk').onclick = function () {
          copyToClipboard(formatListSlack(readyList), this, 'SKOPIOWANO RAPORT!');
        };
      });
    }

    p.querySelector('#stt-cfg-save').onclick = function () {
      var platesRaw = p.querySelector('#stt-cfg-plates').value;
      var locsRaw = p.querySelector('#stt-cfg-locs').value;
      isAudioMuted = !p.querySelector('#stt-cfg-audio').checked;

      megaPlates = new Set(platesRaw.split(/[\n,]+/).map(normalizePlate).filter(Boolean));
      bumperlessLocations = new Set(locsRaw.split(/[\n,]+/).map(normalizePlate).filter(Boolean));

      saveStoredSet(STORAGE_KEYS.MEGA, megaPlates);
      saveStoredSet(STORAGE_KEYS.LOCATIONS, bumperlessLocations);
      localStorage.setItem(STORAGE_KEYS.AUDIO_MUTED, String(isAudioMuted));

      var btn = p.querySelector('#stt-cfg-save');
      copyToClipboard('', btn, 'ZAPISANO!');
      scanAll();
    };

    return p;
  }

  // =========================================================================
  // 11. CYKL GŁÓWNY I INICJALIZACJA
  // =========================================================================
  function scanAll() {
    processVridAndIsaElements(document.body);
    processPlatesAndRowActions(document.body);
    processLocationSelectors(document.body);
    injectTractorAutoCheckWidgets();
    renderSspBadgesFromCache();
  }

  function backgroundTick() {
    getSspMap().then(function () {
      renderSspBadgesFromCache();
      var clock = document.getElementById('stt-clock');
      if (clock) clock.textContent = '· ' + new Date().toLocaleTimeString('pl-PL');
    }).catch(function (e) {
      console.error('[Sesame Suite] Blad odswiezania cyklicznego:', e);
    });
  }

  function start() {
    createTacticalPanel();
    scanAll();
    backgroundTick();
    setInterval(backgroundTick, SSP_CACHE_MS);

    var debounceTimer = null;
    var observer = new MutationObserver(function () {
      if (debounceTimer) return;
      debounceTimer = requestAnimationFrame(function () {
        scanAll();
        debounceTimer = null;
      });
    });

    observer.observe(document.body, { childList: true, subtree: true });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', start);
  } else {
    start();
  }
})();
"}

{"title":"NOWY_DOKUMENT bi","content":"// ==UserScript==
// @name         Sesame ↔ SSP OB Dock Status (Slack Reporter)
// @namespace    http://tampermonkey.net/
// @version      1.5
// @description  Czyta dane z SSP OB, dodaje weryfikację gotowości w Sesame oraz generator raportów na Slacka w pływającym panelu.
// @match        https://trans-logistics-eu.amazon.com/yms/sesameGateConsole*
// @grant        none
// @run-at       document-idle
// ==/UserScript==

(function () {
    'use strict';

    // ---------------- Konfiguracja ----------------
    const PATH_PAGE  = '/ssp/dock/hrz/ob';
    const PATH_DATA  = '/ssp/dock/hrz/ob/fetchdata?';
    const WINDOW_MS  = 3 * 24 * 3600 * 1000;          // zakres: ±3 dni
    const CACHE_MS   = 60 * 1000;                      // odświeżaj dane co 60 s
    const VRID_RE    = /\b1[0-9A-Z]{8}\b/g;

    function getNode() {
        const m = location.hash.match(/\/(WRO5|WRO6|YWRO)\b/i);
        return m ? m[1].toUpperCase() : 'WRO5';
    }

    // ---------------- Mapowanie statusów ----------------
    function describe(load, item) {
        const s = load.status;
        const hasTrailer = !!(item.trailer && (item.trailer.trailerNumber || item.trailer.trailer));
        switch (s) {
            case 'SCHEDULED':
                return hasTrailer
                    ? { label: 'Zaplanowana (naczepa jest)', color: '#4b5563', group: 'ready', isReady: false }
                    : { label: 'Naczepy brak (zaplanowana)',   color: '#6b7280', group: 'absent', isReady: false };
            case 'READY_FOR_LOADING': 
                return { label: 'Gotowa do załadunku', color: '#1d4ed8', group: 'ready', isReady: false };
            case 'TRAILER_ATTACHED':  
                return { label: 'Naczepa podpięta',     color: '#2563eb', group: 'ready', isReady: false };
            case 'LOADING_IN_PROGRESS':
                return { label: 'Ładowanie w toku',     color: '#d97706', group: 'loading', isReady: false };
            case 'LOADING_PAUSED':    
                return { label: 'Ładowanie wstrzymane', color: '#b45309', group: 'loading', isReady: false };
            case 'FINISHED_LOADING':  
                return { label: 'Załadowana / gotowa',  color: '#15803d', group: 'ready', isReady: true };
            case 'COMPLETED':         
                return { label: 'Wyjechała',            color: '#374151', group: 'departed', isReady: false };
            case 'CANCELLED':         
                return { label: 'Anulowana',            color: '#b91c1c', group: 'absent', isReady: false };
            default:                  
                return { label: s || 'Nieznany',       color: '#4b5563', group: 'unknown', isReady: false };
        }
    }

    function getDoor(item) {
        if (item.resource && item.resource.length && item.resource[0].label) {
            const r = item.resource[0];
            return r.label + (r.resType === 'YARD' ? ' (plac)' : '');
        }
        if (item.trailer && item.trailer.location) return item.trailer.location;
        return null;
    }

    // ---------------- Pobieranie danych z SSP ----------------
    let CACHE = { ts: 0, map: null, inflight: null };

    async function fetchMap() {
        const pageResp = await fetch(PATH_PAGE, { credentials: 'include' });
        if (!pageResp.ok) throw new Error(`Błąd pobierania strony OB: ${pageResp.status}`);
        const html = await pageResp.text();
        const doc  = new DOMParser().parseFromString(html, 'text/html');
        const meta = doc.querySelector('meta[name="anti-csrftoken-a2z"]');
        if (!meta || !meta.content) throw new Error('Brak tokena CSRF na stronie OB');
        const token = meta.content;

        const now = Date.now();
        const body = `entity=getOutboundDockView&nodeId=${encodeURIComponent(getNode())}`
            + `&startDate=${now - WINDOW_MS}&endDate=${now + WINDOW_MS}`
            + `&loadCategories=outboundScheduled%2CoutboundInProgress%2CoutboundReadyToDepart%2CoutboundDeparted%2CoutboundCancelled`
            + `&shippingPurposeType=TRANSSHIPMENT%2CNON-TRANSSHIPMENT%2CSHIP_WITH_AMAZON`;

        const resp = await fetch(PATH_DATA, {
            method: 'POST',
            credentials: 'include',
            headers: {
                'Content-Type': 'application/x-www-form-urlencoded; charset=UTF-8',
                'anti-csrftoken-a2z': token
            },
            body
        });

        if (!resp.ok) throw new Error(`Błąd endpointu danych: ${resp.status}`);
        const text = await resp.text();
        let json;
        try {
            json = JSON.parse(text);
        } catch (e) {
            throw new Error('Niepoprawny format JSON z endpointu');
        }

        const arr = (json.ret && json.ret.aaData) || [];
        const map = {};

        arr.forEach(item => {
            const load = item.load;
            if (!load || !load.vrId) return;
            const d = describe(load, item);
            map[load.vrId] = {
                vrId:    load.vrId,
                status:  load.status,
                label:   d.label,
                color:   d.color,
                group:   d.group,
                isReady: d.isReady,
                route:   load.route || '',
                door:    getDoor(item),
                sdt:     load.scheduledDepartureTime || '',
                adt:     load.actualDepartureTime   || '',
                saa:     load.scheduledArrivalTime  || '',
                aaa:     load.actualArrivalTime     || '',
                cpt:     load.criticalPullTime      || '',
                carrier: load.carrier || ''
            };
        });
        return map;
    }

    async function getMap() {
        if (CACHE.map && (Date.now() - CACHE.ts) < CACHE_MS) return CACHE.map;
        if (CACHE.inflight) return CACHE.inflight;
        CACHE.inflight = fetchMap()
            .then(map => { 
                CACHE.map = map; 
                CACHE.ts = Date.now(); 
                CACHE.inflight = null; 
                return map; 
            })
            .catch(err => { 
                CACHE.inflight = null; 
                console.error('[SSP] Fetch error:', err); 
                return CACHE.map || {}; 
            });
        return CACHE.inflight;
    }

    window.getSSPInfo = async (vrid) => (await getMap())[vrid] || null;

    // ---------------- Generator Slack Format ----------------
    function formatSingleSlack(info) {
        const icon = info.isReady ? ':white_check_mark:' : (info.status === 'LOADING_IN_PROGRESS' ? ':hourglass_flowing_sand:' : ':warning:');
        return `${icon} *[${getNode()} OUTBOUND STATUS]*\n`
            + `• *VRID:* \`${info.vrId}\`\n`
            + `• *Status:* *${info.label}* (\`${info.status}\`)\n`
            + `• *Gotowość:* ${info.isReady ? '*GOTOWA DO DROGI*' : '_W TRAKCIE / NIEGOTOWA_'}\n`
            + `• *Drzwi/Plac:* \`${info.door || 'Brak'}\` | *Trasa:* \`${info.route || '-'}\`\n`
            + `• *Przewoźnik:* ${info.carrier || '-'}\n`
            + `• *Plan (SDT):* ${info.sdt || '-'} | *CPT:* \`${info.cpt || '-'}\``;
    }

    function formatListSlack(loads) {
        const now = new Date().toLocaleTimeString('pl-PL', { hour: '2-digit', minute: '2-digit' });
        let text = `:truck: *[${getNode()}] Raport gotowości Outbound (${now})*\n`;
        text += `Łącznie gotowych ładunków: *${loads.length}*\n\n`;

        loads.forEach((l, idx) => {
            text += `${idx + 1}. \`${l.vrId}\` | Drzwi: *${l.door || 'Plac'}* | Trasa: *${l.route || '-'}* | CPT: \`${l.cpt || '-'}\`\n`;
        });
        return text;
    }

    async function copyToClipboard(text, btnElement, successMsg = 'SKOPIOWANO!') {
        try {
            await navigator.clipboard.writeText(text);
            const orig = btnElement.textContent;
            btnElement.textContent = successMsg;
            btnElement.style.background = '#238636';
            setTimeout(() => {
                btnElement.textContent = orig;
                btnElement.style.background = '';
            }, 1800);
        } catch (err) {
            prompt('Kopiuj ręcznie (Ctrl+C):', text);
        }
    }

    // ---------------- Renderowanie Plakietek ----------------
    function buildBadge(info) {
        const b = document.createElement('span');
        b.className = 'ssp-ob-badge';
        b.dataset.vrid = info.vrId;
        b.style.cssText =
            `display:inline-block;margin-left:4px;padding:3px 6px;border-radius:0 !important;`
            + `font-size:11px;font-weight:700;line-height:1.2;color:#ffffff;vertical-align:middle;`
            + `background:${info.color};white-space:nowrap;letter-spacing:0.3px;`
            + `border-left:3px solid ${info.isReady ? '#22c55e' : '#f59e0b'};font-family:monospace;`;

        const parts = [];
        if (info.isReady) parts.push('✔ GOTOWA');
        if (info.door) parts.push('[' + info.door + ']');
        parts.push(info.label);
        if (info.group === 'departed' && info.adt) parts.push('WYJAZD: ' + info.adt);
        else if (info.sdt) parts.push('PLAN: ' + info.sdt);

        b.textContent = parts.join(' · ');
        return b;
    }

    // ---------------- Generator Przycisku Akcji ----------------
    function createCheckWidget(vrid) {
        const wrap = document.createElement('div');
        wrap.className = 'ssp-vrid-action-wrap';
        wrap.style.cssText = 'display:inline-flex;align-items:center;gap:4px;margin:2px 0;font-family:monospace;';

        const btn = document.createElement('button');
        btn.type = 'button';
        btn.className = 'ssp-check-btn';
        btn.textContent = 'OB CZY GOTOWA?';
        btn.title = `Sprawdź status w SSP OB dla VRID: ${vrid}`;
        btn.style.cssText =
            'padding:2px 6px;font-size:10px;font-weight:700;background:#0d1117;color:#f36c00;'
            + 'border:1px solid #f36c00;border-radius:0 !important;cursor:pointer;white-space:nowrap;'
            + 'letter-spacing:0.5px;';

        const statusSlot = document.createElement('span');
        statusSlot.className = 'ssp-result-slot';

        btn.onclick = async (e) => {
            e.stopPropagation();
            e.preventDefault();
            btn.textContent = 'SPRAWDZAM...';
            btn.style.opacity = '0.7';

            try {
                const info = await window.getSSPInfo(vrid);
                statusSlot.innerHTML = '';
                if (!info) {
                    statusSlot.innerHTML = '<span style="color:#ef4444;font-size:10px;font-weight:700">[BRAK W OB]</span>';
                    btn.textContent = 'OB CZY GOTOWA?';
                    btn.style.opacity = '1';
                    return;
                }

                const badge = buildBadge(info);
                statusSlot.appendChild(badge);
                btn.textContent = info.isReady ? '✔ GOTOWA' : '⌛ W TOKU';
                btn.style.borderColor = info.isReady ? '#22c55e' : '#f59e0b';
                btn.style.color = info.isReady ? '#22c55e' : '#f59e0b';
                btn.style.opacity = '1';
            } catch (err) {
                btn.textContent = 'BŁĄD';
                btn.style.borderColor = '#ef4444';
                btn.style.color = '#ef4444';
                btn.style.opacity = '1';
            }
        };

        wrap.appendChild(btn);
        wrap.appendChild(statusSlot);
        return wrap;
    }

    function injectActionButtons() {
        const selectors = [
            '[data-testid*="loadContainer"]',
            '[data-testid*="load-container"]',
            '[data-testid*="LoadContainer"]',
            '[data-testid*="tractor"]',
            '[data-testid*="Tractor"]',
            '.load-container',
            '.tractor-cell'
        ];

        let targetCells = [];
        try {
            targetCells = Array.from(document.querySelectorAll(selectors.join(',')));
        } catch (e) {
            targetCells = Array.from(document.querySelectorAll('[data-testid*="tractor"], [data-testid*="loadContainer"]'));
        }

        if (!targetCells.length) {
            document.querySelectorAll('td, div, span, label').forEach(el => {
                const t = (el.textContent || '').trim();
                if (el.children.length === 0 && (/load\s*container/i.test(t) || /tractor/i.test(t))) {
                    const parent = el.closest('tr, [role="row"], .card, .row') || el.parentElement;
                    if (parent && !targetCells.includes(parent)) targetCells.push(parent);
                }
            });
        }

        targetCells.forEach(cell => {
            if (cell.querySelector('.ssp-vrid-action-wrap')) return;

            const host = cell.closest('tr, [role="row"], .card, .row, [data-testid*="row"]') || cell.parentElement;
            if (!host) return;

            const hostText = host.textContent || '';
            VRID_RE.lastIndex = 0;
            const match = VRID_RE.exec(hostText);
            if (!match) return;

            const vrid = match[0];
            const widget = createCheckWidget(vrid);

            if (cell.tagName === 'TD' || cell.tagName === 'DIV') {
                cell.appendChild(widget);
            } else {
                host.appendChild(widget);
            }
        });
    }

    function renderBadges(map) {
        if (!map || !Object.keys(map).length) return;

        document.querySelectorAll('[data-testid="licensePlateNumber"]').forEach(cell => {
            const host = cell.closest('td, div, span') || cell;
            const txt = (host.textContent || '') + ' ' + (cell.textContent || '');
            VRID_RE.lastIndex = 0;
            const m = VRID_RE.exec(txt);
            if (!m) return;
            const info = map[m[0]];
            if (!info) return;

            const existing = host.querySelector('.ssp-ob-badge');
            if (existing) {
                if (existing.dataset.vrid === info.vrId) return;
                existing.remove();
            }

            const badge = buildBadge(info);
            badge.style.display = 'block';
            badge.style.marginTop = '3px';
            host.appendChild(badge);
        });

        injectActionButtons();
    }

    // ---------------- Panel diagnostyczny + Slack Tool ----------------
    function statusPanel() {
        let p = document.getElementById('ssp-ob-panel');
        if (p) return p;
        const LS = 'ssp-ob-panel-geom';
        p = document.createElement('div');
        p.id = 'ssp-ob-panel';
        p.style.cssText =
            'position:fixed;right:12px;bottom:12px;z-index:999999;background:#0d1117;color:#c9d1d9;'
            + 'font:12px/1.4 monospace;border-radius:0 !important;box-shadow:0 4px 18px rgba(0,0,0,0.7);'
            + 'width:360px;height:auto;min-width:280px;min-height:140px;max-width:90vw;max-height:90vh;'
            + 'resize:both;overflow:hidden;display:flex;flex-direction:column;border:1px solid #30363d;';

        p.innerHTML =
            `<div id="ssp-ob-head" style="cursor:move;user-select:none;display:flex;align-items:center;gap:6px;`
                + `padding:6px 8px;background:#161b22;border-bottom:1px solid #30363d;">`
                + `<span style="color:#f36c00;font-weight:900">■</span>`
                + `<b style="flex:1;color:#f0f6fc;letter-spacing:0.5px">SSP OB STATUS</b>`
                + `<span id="ssp-ob-when" style="opacity:0.6;font-size:10px"></span>`
                + `<button id="ssp-ob-big" title="Maksymalizuj / Przywróć" style="padding:0 5px;border:1px solid #30363d;`
                    + `background:#21262d;color:#c9d1d9;cursor:pointer;font-size:11px;line-height:16px;border-radius:0 !important">⤢</button>`
            + `</div>`
            + `<div style="display:flex;border-bottom:1px solid #30363d;background:#0d1117">`
                + `<button id="ssp-tab-search" style="flex:1;padding:5px;border:none;background:#21262d;color:#fff;cursor:pointer;font-family:monospace;font-size:11px;font-weight:700">WYSZUKAJ VRID</button>`
                + `<button id="ssp-tab-ready" style="flex:1;padding:5px;border:none;background:#0d1117;color:#8b949e;cursor:pointer;font-family:monospace;font-size:11px;font-weight:700">GOTOWE / RAPORT</button>`
            + `</div>`
            + `<div id="ssp-view-search" style="padding:8px;overflow:auto;flex:1;display:flex;flex-direction:column;gap:6px">`
                + `<div style="display:flex;gap:4px">`
                    + `<input id="ssp-ob-in" placeholder="Wpisz VRID..." style="flex:1;padding:4px 6px;border-radius:0 !important;border:1px solid #30363d;background:#0d1117;color:#58a6ff;font-family:monospace;font-size:12px;text-transform:uppercase">`
                    + `<button id="ssp-ob-check" style="padding:4px 8px;border-radius:0 !important;border:1px solid #238636;background:#238636;color:#ffffff;cursor:pointer;font-weight:700;font-family:monospace">SPRAWDŹ</button>`
                + `</div>`
                + `<div id="ssp-ob-status-card" style="display:none;padding:6px 8px;border:1px solid #30363d;background:#161b22;font-size:11px;line-height:1.5"></div>`
                + `<div id="ssp-ob-out"></div>`
            + `</div>`
            + `<div id="ssp-view-ready" style="padding:8px;overflow:auto;flex:1;display:none;flex-direction:column;gap:6px">`
                + `<div style="display:flex;justify-content:space-between;align-items:center">`
                    + `<span style="font-weight:700;font-size:11px">Załadowane (OB Gotowe):</span>`
                    + `<button id="ssp-slack-bulk-btn" style="padding:3px 8px;border:1px solid #4a154b;background:#4a154b;color:#fff;cursor:pointer;font-size:10px;font-weight:700">KOPIUJ DO SLACKA</button>`
                + `</div>`
                + `<div id="ssp-ready-list" style="overflow-y:auto;max-height:220px;display:flex;flex-direction:column;gap:4px;border:1px solid #21262d;padding:4px"></div>`
            + `</div>`;

        document.body.appendChild(p);

        // Nawigacja zakładkami
        const tabSearch = p.querySelector('#ssp-tab-search');
        const tabReady = p.querySelector('#ssp-tab-ready');
        const viewSearch = p.querySelector('#ssp-view-search');
        const viewReady = p.querySelector('#ssp-view-ready');

        tabSearch.onclick = () => {
            tabSearch.style.background = '#21262d'; tabSearch.style.color = '#fff';
            tabReady.style.background = '#0d1117'; tabReady.style.color = '#8b949e';
            viewSearch.style.display = 'flex'; viewReady.style.display = 'none';
        };

        tabReady.onclick = async () => {
            tabReady.style.background = '#21262d'; tabReady.style.color = '#fff';
            tabSearch.style.background = '#0d1117'; tabSearch.style.color = '#8b949e';
            viewSearch.style.display = 'none'; viewReady.style.display = 'flex';
            await refreshReadyList();
        };

        async function refreshReadyList() {
            const listEl = p.querySelector('#ssp-ready-list');
            listEl.innerHTML = '<span style="color:#8b949e">Wczytywanie listy...</span>';
            const map = await getMap();
            const readyItems = Object.values(map).filter(i => i.isReady);

            if (!readyItems.length) {
                listEl.innerHTML = '<span style="color:#8b949e">Brak gotowych załadunków.</span>';
                return;
            }

            listEl.innerHTML = '';
            readyItems.forEach(i => {
                const row = document.createElement('div');
                row.style.cssText = 'padding:3px 5px;background:#161b22;border:1px solid #30363d;display:flex;justify-content:space-between;align-items:center;font-size:10px;';
                row.innerHTML = `<div><b style="color:#58a6ff">${i.vrId}</b> | Dok: <b>${i.door || '-'}</b> | CPT: <b>${i.cpt || '-'}</b></div>`;

                const cBtn = document.createElement('button');
                cBtn.textContent = 'SLACK';
                cBtn.style.cssText = 'padding:1px 5px;background:#21262d;border:1px solid #4a154b;color:#e2a8e5;cursor:pointer;font-size:9px;font-weight:700';
                cBtn.onclick = () => copyToClipboard(formatSingleSlack(i), cBtn, 'OK!');
                row.appendChild(cBtn);
                listEl.appendChild(row);
            });

            p.querySelector('#ssp-slack-bulk-btn').onclick = function() {
                copyToClipboard(formatListSlack(readyItems), this, 'SKOPIOWANO RAPORT!');
            };
        }

        // Zapamiętywanie pozycji panelu
        try {
            const g = JSON.parse(localStorage.getItem(LS) || 'null');
            if (g) {
                if (g.left) p.style.left = g.left;
                if (g.top) p.style.top = g.top;
                p.style.right = 'auto'; p.style.bottom = 'auto';
                if (g.w) p.style.width = g.w;
                if (g.h) p.style.height = g.h;
            }
        } catch (e) {}

        const saveGeom = () => {
            try {
                const r = p.getBoundingClientRect();
                localStorage.setItem(LS, JSON.stringify({
                    left: `${Math.round(r.left)}px`,
                    top: `${Math.round(r.top)}px`,
                    w: p.style.width,
                    h: p.style.height
                }));
            } catch (e) {}
        };

        const head = p.querySelector('#ssp-ob-head');
        let drag = null;
        head.addEventListener('mousedown', e => {
            if (e.target.id === 'ssp-ob-big') return;
            const r = p.getBoundingClientRect();
            drag = { dx: e.clientX - r.left, dy: e.clientY - r.top };
            p.style.left = `${r.left}px`; p.style.top = `${r.top}px`;
            p.style.right = 'auto'; p.style.bottom = 'auto';
            e.preventDefault();
        });

        document.addEventListener('mousemove', e => {
            if (!drag) return;
            let x = Math.max(0, Math.min(e.clientX - drag.dx, window.innerWidth - 40));
            let y = Math.max(0, Math.min(e.clientY - drag.dy, window.innerHeight - 24));
            p.style.left = `${x}px`; p.style.top = `${y}px`;
        });

        document.addEventListener('mouseup', () => {
            if (drag) { drag = null; saveGeom(); }
        });

        if (window.ResizeObserver) new ResizeObserver(() => saveGeom()).observe(p);

        // Wyszukiwanie VRID + formatowanie do Slacka
        const checkAction = async () => {
            const v = p.querySelector('#ssp-ob-in').value.trim().toUpperCase();
            const out = p.querySelector('#ssp-ob-out');
            const card = p.querySelector('#ssp-ob-status-card');

            if (!v) {
                card.style.display = 'block';
                card.style.borderColor = '#d97706';
                card.innerHTML = '<span style="color:#f59e0b">Podaj numer VRID.</span>';
                return;
            }

            card.style.display = 'block';
            card.style.borderColor = '#30363d';
            card.innerHTML = '<span style="color:#58a6ff">Weryfikacja bazy OB...</span>';
            out.innerHTML = '';

            const info = await window.getSSPInfo(v);
            if (!info) {
                card.style.borderColor = '#ef4444';
                card.innerHTML = `<b style="color:#ef4444">VRID: ${v} — BRAK W SYSTEMIE SSP OB</b>`;
                return;
            }

            let verdictColor = info.isReady ? '#22c55e' : (info.status === 'LOADING_IN_PROGRESS' ? '#f59e0b' : '#ef4444');
            let verdictText = info.isReady ? 'GOTOWA DO DROGI (ZAŁADOWANA)' : (info.status === 'LOADING_IN_PROGRESS' ? 'W TRAKCIE ŁADOWANIA' : 'NIEGOTOWA');

            card.style.borderColor = verdictColor;
            card.innerHTML = `
                <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:4px">
                    <span style="font-weight:900;color:${verdictColor};font-size:11px">[ ${verdictText} ]</span>
                    <button id="ssp-slack-single-btn" style="padding:2px 6px;border:1px solid #4a154b;background:#4a154b;color:#fff;cursor:pointer;font-size:10px;font-weight:700">KOPIUJ DO SLACKA</button>
                </div>
                <div><b>VRID:</b> <span style="color:#58a6ff">${info.vrId}</span></div>
                <div><b>Lokalizacja/Drzwi:</b> <span style="color:#f36c00">${info.door || 'Brak'}</span></div>
                <div><b>Status:</b> ${info.label} (${info.status})</div>
                <div><b>Trasa:</b> ${info.route || '-'} | <b>Przewoźnik:</b> ${info.carrier || '-'}</div>
                <div><b>Plan (SDT):</b> ${info.sdt || '-'} | <b>CPT:</b> ${info.cpt || '-'}</div>
            `;

            p.querySelector('#ssp-slack-single-btn').onclick = function() {
                copyToClipboard(formatSingleSlack(info), this);
            };

            out.appendChild(buildBadge(info));
        };

        p.querySelector('#ssp-ob-check').onclick = checkAction;
        p.querySelector('#ssp-ob-in').addEventListener('keydown', e => {
            if (e.key === 'Enter') checkAction();
        });

        return p;
    }

    // ---------------- Główna pętla ----------------
    async function tick() {
        try {
            const map = await getMap();
            renderBadges(map);
            const w = document.getElementById('ssp-ob-when');
            if (w) w.textContent = '· ' + new Date().toLocaleTimeString('pl-PL');
        } catch (e) {
            console.error('[SSP] Błąd tick:', e);
        }
    }

    function start() {
        statusPanel();
        tick();
        setInterval(tick, CACHE_MS);

        let debounceTimer = null;
        const obs = new MutationObserver(() => {
            if (debounceTimer) clearTimeout(debounceTimer);
            debounceTimer = setTimeout(() => {
                if (CACHE.map) renderBadges(CACHE.map);
                injectActionButtons();
            }, 250);
        });

        obs.observe(document.body, { childList: true, subtree: true });
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', start);
    } else {
        start();
    }
})();
"}

{"title":"NOWY_DOKUMENTk","content":"// ==UserScript==
// @name         Sesame ↔ SSP OB Dock Status
// @namespace    http://tampermonkey.net/
// @version      1.4
// @description  Czyta dane z Outbound Dock Management (/ssp/dock/hrz/ob), dodaje przycisk weryfikacji gotowości przy pozycjach Sesame Tractor oraz Load Container, doklejając statusy VRID.
// @match        https://trans-logistics-eu.amazon.com/yms/sesameGateConsole*
// @grant        none
// @run-at       document-idle
// ==/UserScript==

(function () {
    'use strict';

    // ---------------- Konfiguracja ----------------
    const PATH_PAGE  = '/ssp/dock/hrz/ob';
    const PATH_DATA  = '/ssp/dock/hrz/ob/fetchdata?';
    const WINDOW_MS  = 3 * 24 * 3600 * 1000;          // zakres: ±3 dni
    const CACHE_MS   = 60 * 1000;                      // odświeżaj dane co 60 s
    const VRID_RE    = /\b1[0-9A-Z]{8}\b/g;

    function getNode() {
        const m = location.hash.match(/\/(WRO5|WRO6|YWRO)\b/i);
        return m ? m[1].toUpperCase() : 'WRO5';
    }

    // ---------------- Mapowanie statusów ----------------
    function describe(load, item) {
        const s = load.status;
        const hasTrailer = !!(item.trailer && (item.trailer.trailerNumber || item.trailer.trailer));
        switch (s) {
            case 'SCHEDULED':
                return hasTrailer
                    ? { label: 'Zaplanowana (naczepa jest)', color: '#4b5563', group: 'ready', isReady: false }
                    : { label: 'Naczepy brak (zaplanowana)',   color: '#6b7280', group: 'absent', isReady: false };
            case 'READY_FOR_LOADING': 
                return { label: 'Gotowa do załadunku', color: '#1d4ed8', group: 'ready', isReady: false };
            case 'TRAILER_ATTACHED':  
                return { label: 'Naczepa podpięta',     color: '#2563eb', group: 'ready', isReady: false };
            case 'LOADING_IN_PROGRESS':
                return { label: 'Ładowanie w toku',     color: '#d97706', group: 'loading', isReady: false };
            case 'LOADING_PAUSED':    
                return { label: 'Ładowanie wstrzymane', color: '#b45309', group: 'loading', isReady: false };
            case 'FINISHED_LOADING':  
                return { label: 'Załadowana / gotowa',  color: '#15803d', group: 'ready', isReady: true };
            case 'COMPLETED':         
                return { label: 'Wyjechała',            color: '#374151', group: 'departed', isReady: false };
            case 'CANCELLED':         
                return { label: 'Anulowana',            color: '#b91c1c', group: 'absent', isReady: false };
            default:                  
                return { label: s || 'Nieznany',       color: '#4b5563', group: 'unknown', isReady: false };
        }
    }

    function getDoor(item) {
        if (item.resource && item.resource.length && item.resource[0].label) {
            const r = item.resource[0];
            return r.label + (r.resType === 'YARD' ? ' (plac)' : '');
        }
        if (item.trailer && item.trailer.location) return item.trailer.location;
        return null;
    }

    // ---------------- Pobieranie danych z SSP ----------------
    let CACHE = { ts: 0, map: null, inflight: null };

    async function fetchMap() {
        const pageResp = await fetch(PATH_PAGE, { credentials: 'include' });
        if (!pageResp.ok) throw new Error(`Błąd pobierania strony OB: ${pageResp.status}`);
        const html = await pageResp.text();
        const doc  = new DOMParser().parseFromString(html, 'text/html');
        const meta = doc.querySelector('meta[name="anti-csrftoken-a2z"]');
        if (!meta || !meta.content) throw new Error('Brak tokena CSRF na stronie OB');
        const token = meta.content;

        const now = Date.now();
        const body = `entity=getOutboundDockView&nodeId=${encodeURIComponent(getNode())}`
            + `&startDate=${now - WINDOW_MS}&endDate=${now + WINDOW_MS}`
            + `&loadCategories=outboundScheduled%2CoutboundInProgress%2CoutboundReadyToDepart%2CoutboundDeparted%2CoutboundCancelled`
            + `&shippingPurposeType=TRANSSHIPMENT%2CNON-TRANSSHIPMENT%2CSHIP_WITH_AMAZON`;

        const resp = await fetch(PATH_DATA, {
            method: 'POST',
            credentials: 'include',
            headers: {
                'Content-Type': 'application/x-www-form-urlencoded; charset=UTF-8',
                'anti-csrftoken-a2z': token
            },
            body
        });

        if (!resp.ok) throw new Error(`Błąd endpointu danych: ${resp.status}`);
        const text = await resp.text();
        let json;
        try {
            json = JSON.parse(text);
        } catch (e) {
            throw new Error('Niepoprawny format JSON z endpointu');
        }

        const arr = (json.ret && json.ret.aaData) || [];
        const map = {};

        arr.forEach(item => {
            const load = item.load;
            if (!load || !load.vrId) return;
            const d = describe(load, item);
            map[load.vrId] = {
                vrId:    load.vrId,
                status:  load.status,
                label:   d.label,
                color:   d.color,
                group:   d.group,
                isReady: d.isReady,
                route:   load.route || '',
                door:    getDoor(item),
                sdt:     load.scheduledDepartureTime || '',
                adt:     load.actualDepartureTime   || '',
                saa:     load.scheduledArrivalTime  || '',
                aaa:     load.actualArrivalTime     || '',
                cpt:     load.criticalPullTime      || '',
                carrier: load.carrier || ''
            };
        });
        return map;
    }

    async function getMap() {
        if (CACHE.map && (Date.now() - CACHE.ts) < CACHE_MS) return CACHE.map;
        if (CACHE.inflight) return CACHE.inflight;
        CACHE.inflight = fetchMap()
            .then(map => { 
                CACHE.map = map; 
                CACHE.ts = Date.now(); 
                CACHE.inflight = null; 
                return map; 
            })
            .catch(err => { 
                CACHE.inflight = null; 
                console.error('[SSP] Fetch error:', err); 
                return CACHE.map || {}; 
            });
        return CACHE.inflight;
    }

    window.getSSPInfo = async (vrid) => (await getMap())[vrid] || null;

    // ---------------- Renderowanie Plakietek ----------------
    function buildBadge(info) {
        const b = document.createElement('span');
        b.className = 'ssp-ob-badge';
        b.dataset.vrid = info.vrId;
        b.style.cssText =
            `display:inline-block;margin-left:4px;padding:3px 6px;border-radius:0 !important;`
            + `font-size:11px;font-weight:700;line-height:1.2;color:#ffffff;vertical-align:middle;`
            + `background:${info.color};white-space:nowrap;letter-spacing:0.3px;`
            + `border-left:3px solid ${info.isReady ? '#22c55e' : '#f59e0b'};font-family:monospace;`;

        const parts = [];
        if (info.isReady) parts.push('✔ GOTOWA');
        if (info.door) parts.push('[' + info.door + ']');
        parts.push(info.label);
        if (info.group === 'departed' && info.adt) parts.push('WYJAZD: ' + info.adt);
        else if (info.sdt) parts.push('PLAN: ' + info.sdt);

        b.textContent = parts.join(' · ');
        b.title =
            `VRID: ${info.vrId}\n` +
            `Gotowość: ${info.isReady ? 'GOTOWA DO DROGI' : 'W TRAKCIE / NIEGOTOWA'}\n` +
            `Status: ${info.label} (${info.status})\n` +
            `Trasa: ${info.route}\n` +
            (info.door ? `Drzwi/miejsce: ${info.door}\n` : '') +
            `Planowany wyjazd (SDT): ${info.sdt || '-'}\n` +
            `Faktyczny wyjazd (ADT): ${info.adt || '-'}\n` +
            `Przyjazd naczepy: ${info.aaa || '-'}\n` +
            `CPT: ${info.cpt || '-'}\n` +
            `Przewoźnik: ${info.carrier || '-'}`;
        return b;
    }

    // ---------------- Generator Przycisku Akcji ----------------
    function createCheckWidget(vrid) {
        const wrap = document.createElement('div');
        wrap.className = 'ssp-vrid-action-wrap';
        wrap.style.cssText = 'display:inline-flex;align-items:center;gap:4px;margin:2px 0;font-family:monospace;';

        const btn = document.createElement('button');
        btn.type = 'button';
        btn.className = 'ssp-check-btn';
        btn.textContent = 'OB CZY GOTOWA?';
        btn.title = `Sprawdź status w SSP OB dla VRID: ${vrid}`;
        btn.style.cssText =
            'padding:2px 6px;font-size:10px;font-weight:700;background:#0d1117;color:#f36c00;'
            + 'border:1px solid #f36c00;border-radius:0 !important;cursor:pointer;white-space:nowrap;'
            + 'letter-spacing:0.5px;';

        const statusSlot = document.createElement('span');
        statusSlot.className = 'ssp-result-slot';

        btn.onclick = async (e) => {
            e.stopPropagation();
            e.preventDefault();
            btn.textContent = 'SPRAWDZAM...';
            btn.style.opacity = '0.7';

            try {
                const info = await window.getSSPInfo(vrid);
                statusSlot.innerHTML = '';
                if (!info) {
                    statusSlot.innerHTML = '<span style="color:#ef4444;font-size:10px;font-weight:700">[BRAK W OB]</span>';
                    btn.textContent = 'OB CZY GOTOWA?';
                    btn.style.opacity = '1';
                    return;
                }

                const badge = buildBadge(info);
                statusSlot.appendChild(badge);
                btn.textContent = info.isReady ? '✔ GOTOWA' : '⌛ W TOKU';
                btn.style.borderColor = info.isReady ? '#22c55e' : '#f59e0b';
                btn.style.color = info.isReady ? '#22c55e' : '#f59e0b';
                btn.style.opacity = '1';
            } catch (err) {
                btn.textContent = 'BŁĄD';
                btn.style.borderColor = '#ef4444';
                btn.style.color = '#ef4444';
                btn.style.opacity = '1';
            }
        };

        wrap.appendChild(btn);
        wrap.appendChild(statusSlot);
        return wrap;
    }

    // ---------------- Obsługa Tractor & Load Container ----------------
    function injectActionButtons() {
        // Selektory dla Tractor oraz Load Container
        const selectors = [
            '[data-testid*="loadContainer"]',
            '[data-testid*="load-container"]',
            '[data-testid*="LoadContainer"]',
            '[data-testid*="tractor"]',
            '[data-testid*="Tractor"]',
            '.load-container',
            '.tractor-cell'
        ];

        let targetCells = [];
        try {
            targetCells = Array.from(document.querySelectorAll(selectors.join(',')));
        } catch (e) {
            targetCells = Array.from(document.querySelectorAll('[data-testid*="tractor"], [data-testid*="loadContainer"]'));
        }

        // Fallback: przeszukiwanie węzłów tekstowych zawierających "Load Container" lub "Tractor"
        if (!targetCells.length) {
            document.querySelectorAll('td, div, span, label').forEach(el => {
                const t = (el.textContent || '').trim();
                if (el.children.length === 0 && (/load\s*container/i.test(t) || /tractor/i.test(t))) {
                    const parent = el.closest('tr, [role="row"], .card, .row') || el.parentElement;
                    if (parent && !targetCells.includes(parent)) targetCells.push(parent);
                }
            });
        }

        targetCells.forEach(cell => {
            if (cell.querySelector('.ssp-vrid-action-wrap')) return;

            // Szukanie wiersza/karty nadrzędnej
            const host = cell.closest('tr, [role="row"], .card, .row, [data-testid*="row"]') || cell.parentElement;
            if (!host) return;

            const hostText = host.textContent || '';
            VRID_RE.lastIndex = 0;
            const match = VRID_RE.exec(hostText);
            if (!match) return;

            const vrid = match[0];
            const widget = createCheckWidget(vrid);

            // Wstawienie widgetu do komórki lub jako element blokowy pod etykietą
            if (cell.tagName === 'TD' || cell.tagName === 'DIV') {
                cell.appendChild(widget);
            } else {
                host.appendChild(widget);
            }
        });
    }

    // ---------------- Standardowe renderowanie w Sesame ----------------
    function renderBadges(map) {
        if (!map || !Object.keys(map).length) return;

        document.querySelectorAll('[data-testid="licensePlateNumber"]').forEach(cell => {
            const host = cell.closest('td, div, span') || cell;
            const txt = (host.textContent || '') + ' ' + (cell.textContent || '');
            VRID_RE.lastIndex = 0;
            const m = VRID_RE.exec(txt);
            if (!m) return;
            const info = map[m[0]];
            if (!info) return;

            const existing = host.querySelector('.ssp-ob-badge');
            if (existing) {
                if (existing.dataset.vrid === info.vrId) return;
                existing.remove();
            }

            const badge = buildBadge(info);
            badge.style.display = 'block';
            badge.style.marginTop = '3px';
            host.appendChild(badge);
        });

        // Wstrzyknij przyciski akcji
        injectActionButtons();
    }

    // ---------------- Panel diagnostyczny ----------------
    function statusPanel() {
        let p = document.getElementById('ssp-ob-panel');
        if (p) return p;
        const LS = 'ssp-ob-panel-geom';
        p = document.createElement('div');
        p.id = 'ssp-ob-panel';
        p.style.cssText =
            'position:fixed;right:12px;bottom:12px;z-index:999999;background:#0d1117;color:#c9d1d9;'
            + 'font:12px/1.4 monospace;border-radius:0 !important;box-shadow:0 4px 18px rgba(0,0,0,0.7);'
            + 'width:320px;height:auto;min-width:250px;min-height:120px;max-width:90vw;max-height:90vh;'
            + 'resize:both;overflow:hidden;display:flex;flex-direction:column;border:1px solid #30363d;';

        p.innerHTML =
            '<div id="ssp-ob-head" style="cursor:move;user-select:none;display:flex;align-items:center;gap:6px;'
                + 'padding:6px 8px;background:#161b22;border-bottom:1px solid #30363d;">'
                + '<span style="color:#f36c00;font-weight:900">■</span>'
                + '<b style="flex:1;color:#f0f6fc;letter-spacing:0.5px">SSP OB STATUS</b>'
                + '<span id="ssp-ob-when" style="opacity:0.6;font-size:10px"></span>'
                + '<button id="ssp-ob-big" title="Maksymalizuj / Przywróć" style="padding:0 5px;border:1px solid #30363d;'
                    + 'background:#21262d;color:#c9d1d9;cursor:pointer;font-size:11px;line-height:16px;border-radius:0 !important">⤢</button>'
            + '</div>'
            + '<div style="padding:8px;overflow:auto;flex:1;display:flex;flex-direction:column;gap:6px">'
                + '<div style="display:flex;gap:4px">'
                    + '<input id="ssp-ob-in" placeholder="Wpisz VRID..." style="flex:1;padding:4px 6px;border-radius:0 !important;border:1px solid #30363d;background:#0d1117;color:#58a6ff;font-family:monospace;font-size:12px;text-transform:uppercase">'
                    + '<button id="ssp-ob-check" style="padding:4px 10px;border-radius:0 !important;border:1px solid #238636;background:#238636;color:#ffffff;cursor:pointer;font-weight:700;font-family:monospace">CZY GOTOWA?</button>'
                + '</div>'
                + '<div id="ssp-ob-status-card" style="display:none;padding:6px 8px;border:1px solid #30363d;background:#161b22;font-size:11px;line-height:1.5"></div>'
                + '<div id="ssp-ob-out"></div>'
            + '</div>';
        document.body.appendChild(p);

        try {
            const g = JSON.parse(localStorage.getItem(LS) || 'null');
            if (g) {
                if (g.left) p.style.left = g.left;
                if (g.top) p.style.top = g.top;
                p.style.right = 'auto';
                p.style.bottom = 'auto';
                if (g.w) p.style.width = g.w;
                if (g.h) p.style.height = g.h;
            }
        } catch (e) {}

        const saveGeom = () => {
            try {
                const r = p.getBoundingClientRect();
                localStorage.setItem(LS, JSON.stringify({
                    left: `${Math.round(r.left)}px`,
                    top: `${Math.round(r.top)}px`,
                    w: p.style.width,
                    h: p.style.height
                }));
            } catch (e) {}
        };

        const head = p.querySelector('#ssp-ob-head');
        let drag = null;

        head.addEventListener('mousedown', e => {
            if (e.target.id === 'ssp-ob-big') return;
            const r = p.getBoundingClientRect();
            drag = { dx: e.clientX - r.left, dy: e.clientY - r.top };
            p.style.left = `${r.left}px`;
            p.style.top = `${r.top}px`;
            p.style.right = 'auto';
            p.style.bottom = 'auto';
            e.preventDefault();
        });

        document.addEventListener('mousemove', e => {
            if (!drag) return;
            let x = e.clientX - drag.dx;
            let y = e.clientY - drag.dy;
            x = Math.max(0, Math.min(x, window.innerWidth - 40));
            y = Math.max(0, Math.min(y, window.innerHeight - 24));
            p.style.left = `${x}px`;
            p.style.top = `${y}px`;
        });

        document.addEventListener('mouseup', () => {
            if (drag) {
                drag = null;
                saveGeom();
            }
        });

        if (window.ResizeObserver) {
            new ResizeObserver(() => saveGeom()).observe(p);
        }

        let big = false;
        let prev = null;
        p.querySelector('#ssp-ob-big').onclick = () => {
            if (!big) {
                prev = { w: p.style.width, h: p.style.height, left: p.style.left, top: p.style.top };
                p.style.width = '70vw';
                p.style.height = '70vh';
                p.style.left = '15vw';
                p.style.top = '15vh';
                p.style.right = 'auto';
                p.style.bottom = 'auto';
                big = true;
            } else {
                if (prev) {
                    p.style.width = prev.w;
                    p.style.height = prev.h;
                    p.style.left = prev.left;
                    p.style.top = prev.top;
                }
                big = false;
            }
            saveGeom();
        };

        const checkAction = async () => {
            const v = p.querySelector('#ssp-ob-in').value.trim().toUpperCase();
            const out = p.querySelector('#ssp-ob-out');
            const card = p.querySelector('#ssp-ob-status-card');

            if (!v) {
                card.style.display = 'block';
                card.style.borderColor = '#d97706';
                card.innerHTML = '<span style="color:#f59e0b">Podaj numer VRID.</span>';
                return;
            }

            card.style.display = 'block';
            card.style.borderColor = '#30363d';
            card.innerHTML = '<span style="color:#58a6ff">Weryfikacja bazy OB...</span>';
            out.innerHTML = '';

            const info = await window.getSSPInfo(v);

            if (!info) {
                card.style.borderColor = '#ef4444';
                card.innerHTML = `<b style="color:#ef4444">VRID: ${v} — BRAK W SYSTEMIE SSP OB</b>`;
                return;
            }

            let verdictColor = '#ef4444';
            let verdictText = 'NIEGOTOWA';

            if (info.isReady) {
                verdictColor = '#22c55e';
                verdictText = 'GOTOWA DO DROGI (ZAŁADOWANA)';
            } else if (info.status === 'LOADING_IN_PROGRESS') {
                verdictColor = '#f59e0b';
                verdictText = 'W TRAKCIE ŁADOWANIA';
            } else if (info.status === 'COMPLETED') {
                verdictColor = '#8b949e';
                verdictText = 'WYJECHAŁA Z WĘZŁA';
            } else if (info.status === 'READY_FOR_LOADING') {
                verdictColor = '#38bdf8';
                verdictText = 'OCZEKUJE NA ZAŁADUNEK';
            }

            card.style.borderColor = verdictColor;
            card.innerHTML = `
                <div style="font-weight:900;color:${verdictColor};margin-bottom:4px;font-size:12px">
                    STATUS: [ ${verdictText} ]
                </div>
                <div><b>VRID:</b> <span style="color:#58a6ff">${info.vrId}</span></div>
                <div><b>Lokalizacja/Drzwi:</b> <span style="color:#f36c00">${info.door || 'Brak przypisania'}</span></div>
                <div><b>Etap:</b> ${info.label} (${info.status})</div>
                <div><b>Trasa:</b> ${info.route || '-'} | <b>Przewoźnik:</b> ${info.carrier || '-'}</div>
                <div><b>Plan (SDT):</b> ${info.sdt || '-'}| <b>Wyjazd (ADT):</b> ${info.adt || '-'}</div>
            `;

            out.appendChild(buildBadge(info));
        };

        p.querySelector('#ssp-ob-check').onclick = checkAction;
        p.querySelector('#ssp-ob-in').addEventListener('keydown', e => {
            if (e.key === 'Enter') checkAction();
        });

        return p;
    }

    // ---------------- Główna pętla ----------------
    async function tick() {
        try {
            const map = await getMap();
            renderBadges(map);
            const w = document.getElementById('ssp-ob-when');
            if (w) w.textContent = '· ' + new Date().toLocaleTimeString('pl-PL');
        } catch (e) {
            console.error('[SSP] Błąd pętli tick:', e);
        }
    }

    function start() {
        statusPanel();
        tick();
        setInterval(tick, CACHE_MS);

        let debounceTimer = null;
        const obs = new MutationObserver(() => {
            if (debounceTimer) clearTimeout(debounceTimer);
            debounceTimer = setTimeout(() => {
                if (CACHE.map) renderBadges(CACHE.map);
                injectActionButtons();
            }, 250);
        });

        obs.observe(document.body, { childList: true, subtree: true });
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', start);
    } else {
        start();
    }
})();
"}

{"title":"NOWY_DOKUMENT","content":"// =========================================================================
// OXY_OS // YARD 360 DEDICATED INJECTOR (Appointments Engine)
// URL: https://trans-logistics-eu.amazon.com/yms/relayYardHub/*
// =========================================================================

var pollIntervalId = null;
var pollIntervalMs = 10000;
var isParsing = false;
var tableObserver = null;
var quickFilterTerm = "";

// Konfiguracja trybu kierunków
var PRIMARY_ROUTE = "WRO5->KTW3";
var routeFilterMode = "SINGLE"; // "SINGLE" (tylko WRO5->KTW3) lub "ALL" (wszystkie)

// Odczyt zapamiętanego trybu
if (typeof chrome !== "undefined" && chrome.storage && chrome.storage.local) {
  chrome.storage.local.get(["y360_route_mode"], function (res) {
    if (res.y360_route_mode) {
      routeFilterMode = res.y360_route_mode;
      updateHudModeButton();
    }
  });
}

function extractMinutes(timeStr) {
  if (!timeStr || timeStr.indexOf(":") === -1) return null;
  var parts = timeStr.split(":").map(Number);
  var target = new Date();
  target.setHours(parts[0], parts[1], 0, 0);
  return Math.round((target.getTime() - new Date().getTime()) / 60000);
}

function parseRouteFromRow(rawText) {
  var clean = (rawText || "").replace(/&gt;/g, ">").toUpperCase();
  var match = clean.match(/\b([A-Z]{3,4}\d)\s*(?:->|>|TO|-)\s*([A-Z]{3,4}\d)\b/);
  if (match) return match[1] + "->" + match[2];
  if (clean.indexOf("WRO5") !== -1 && clean.indexOf("KTW3") !== -1) return PRIMARY_ROUTE;
  return PRIMARY_ROUTE;
}

function parseYard360Table() {
  if (isParsing) return;
  isParsing = true;

  try {
    var table = document.querySelector('table[data-testid="wranglingTable"]');
    if (!table) return;

    var rows = table.querySelectorAll('tbody tr[data-testid]');
    var extractedData = [];
    var routeCounts = {};

    rows.forEach(function (row) {
      var rawText = (row.innerText || "").replace(/&gt;/g, ">");
      var vrid = row.getAttribute("data-testid") || "";

      // Filtrowanie z paska HUD
      if (quickFilterTerm) {
        row.style.display = rawText.toLowerCase().indexOf(quickFilterTerm) !== -1 ? "" : "none";
      } else {
        row.style.display = "";
      }

      // 1. Czas odjazdu (SDT)
      var timeEl = row.querySelector('[data-testid="departureTimeDisplay"]');
      var timeMatch = timeEl ? timeEl.innerText.match(/\d{2}:\d{2}/) : rawText.match(/\d{2}:\d{2}/);
      var baseTime = timeMatch ? timeMatch[0] : "";

      // 2. Status załadunku
      var statusEl = row.querySelector('[data-testid="loadStatusText"]');
      var status = statusEl ? statusEl.innerText.trim() : "";
      var statusUpper = status.toUpperCase();

      // 3. Kierowca
      var driverEl = row.querySelector('[data-testid$="DriverStatus"]');
      var hasDriver = Boolean(driverEl && driverEl.innerText.indexOf("—") === -1 && driverEl.innerText.trim() !== "");

      // 4. Lokalizacje (Trailer / Tractor)
      var locEl = row.querySelector('[data-testid$="Location"]');
      var loc = locEl ? locEl.innerText.replace(/\s+/g, " ").trim() : "---";

      // 5. Sprzęt (Naczepa i Ciągnik)
      var eqEl = row.querySelector('[data-testid$="Equipment"]');
      var eqText = eqEl ? eqEl.innerText.replace(/\s+/g, " ") : "";

      var trailerMatch = eqText.match(/Trailer:[^\w]*ID\s*([A-Z0-9]+)/i) || loc.match(/Trailer:\s*([A-Z0-9-]+)/i);
      var trailer = trailerMatch ? trailerMatch[1] : vrid;

      var tractorMatch = eqText.match(/Tractor:[^\w]*LP\s*([A-Z0-9]+)/i) || loc.match(/Tractor:\s*([A-Z0-9-]+)/i);
      var tractor = tractorMatch ? tractorMatch[1] : "---";

      // 6. Typ ładunku
      var typeEl = row.querySelector('[data-testid$="LoadType"]');
      var loadType = typeEl ? typeEl.innerText.trim().toUpperCase() : "";

      var hasSeal = /\b(SEAL|PLOMBA|SEALED)\b/i.test(rawText);
      var isFinished = statusUpper.indexOf("FINISHED") !== -1;
      var isTransfers = rawText.toUpperCase().indexOf("TRANSFERSINITIAL") !== -1;
      var isEmpty = isTransfers || /\b(EMPTY|EMP|MT)\b/i.test(rawText);

      // 7. Relacja
      var route = parseRouteFromRow(rawText);
      var isTarget = (routeFilterMode === "ALL") || (route === PRIMARY_ROUTE);

      if (isTarget) {
        if (!routeCounts[route]) {
          routeCounts[route] = { full: 0, empty: 0, driver: 0 };
        }
        if (hasSeal || isFinished || loadType.indexOf("LOADED") !== -1) {
          routeCounts[route].full++;
          if (hasDriver) routeCounts[route].driver++;
        } else {
          routeCounts[route].empty++;
        }
      }

      extractedData.push({
        baseTime: baseTime,
        status: status,
        lane: route,
        loc: loc,
        ref: vrid,
        trailer: trailer,
        tractor: tractor,
        hasDriver: hasDriver,
        seal: hasSeal ? "SEAL" : "---",
        account: isTransfers ? "TRANSFERSINITIAL" : loadType
      });

      // 8. Wymuszone kolorowanie wierszy w Relay Yard Hub
      var diff = extractMinutes(baseTime);
      var bgColor = "";
      var borderColor = "";

      if (isFinished || loadType.indexOf("LOADED") !== -1 || hasSeal) {
        bgColor = "rgba(3, 195, 20, 0.12)";
        borderColor = "#03C314";
      } else if (isEmpty) {
        bgColor = "rgba(243, 108, 0, 0.12)";
        borderColor = "#f36c00";
      } else if (diff !== null && diff <= 15) {
        bgColor = "rgba(255, 0, 0, 0.15)";
        borderColor = "#ff0000";
      }

      for (var c = 0; c < row.cells.length; c++) {
        var cell = row.cells[c];
        if (bgColor) {
          cell.style.setProperty("background-color", bgColor, "important");
          cell.style.setProperty("border-bottom", "2px solid " + borderColor, "important");
        } else {
          cell.style.removeProperty("background-color");
          cell.style.removeProperty("border-bottom");
        }
      }
    });

    renderYardHubHUD(routeCounts);

    // Wysyłamy dane do panelu bocznego
    if (typeof chrome !== "undefined" && chrome.runtime && chrome.runtime.id) {
      try {
        chrome.runtime.sendMessage({ type: "YMS_UPDATE_DATA", payload: routeCounts }, function () {
          var ignore = chrome.runtime.lastError;
        });
        chrome.runtime.sendMessage({ type: "SSP_UPDATE_DATA", payload: extractedData }, function () {
          var ignore = chrome.runtime.lastError;
        });
      } catch (e) {}
    }
  } finally {
    setTimeout(function () { isParsing = false; }, 50);
  }
}

function updateHudModeButton() {
  var btn = document.getElementById("y360-btn-toggle-mode");
  if (btn) {
    btn.innerText = routeFilterMode === "SINGLE" ? "TRYB: 1 KIERUNEK" : "TRYB: WSZYSTKIE";
    btn.style.color = routeFilterMode === "SINGLE" ? "#f36c00" : "#03C314";
  }
}

function renderYardHubHUD(counts) {
  var existing = document.getElementById("y360-top-hud");
  if (!existing) {
    var style = document.createElement("style");
    style.textContent = [
      "@import url('https://fonts.googleapis.com/css2?family=JetBrains+Mono&display=swap');",
      "#y360-top-hud { position: sticky; top: 0; left: 0; width: 100%; min-height: 32px; background: #121212; border-bottom: 2px solid #f36c00; color: #e0e0e0; font-family: 'JetBrains Mono', monospace; font-size: 11px; z-index: 999999; display: flex; align-items: center; padding: 2px 10px; gap: 10px; box-sizing: border-box; }",
      ".y360-hud-sec { display: flex; align-items: center; gap: 8px; border-right: 1px dashed #333; padding-right: 10px; }",
      ".y360-hud-title { color: #f36c00; font-weight: bold; font-size: 12px; letter-spacing: 1px; }",
      ".y360-hud-input { background: #1e1e1e; border: 1px solid #333; color: #fff; font-family: inherit; font-size: 11px; padding: 2px 6px; width: 100px; outline: none; }",
      ".y360-hud-btn { background: #1e1e1e; border: 1px solid #333; color: #aaa; font-family: inherit; font-size: 10px; font-weight: bold; padding: 3px 8px; cursor: pointer; text-transform: uppercase; }",
      ".y360-hud-btn:hover { border-color: #f36c00; color: #f36c00; }",
      ".y360-hud-badge { display: flex; align-items: center; gap: 6px; background: rgba(255,255,255,0.03); border: 1px solid #2a2a2a; padding: 2px 8px; }",
      ".y360-drv-tag { color: #00ff15; font-size: 9px; margin-left: 2px; text-shadow: 0 0 3px rgba(0,255,21,0.5); }"
    ].join("\n");
    (document.head || document.documentElement).appendChild(style);

    var hudHTML = [
      "<div id='y360-top-hud'>",
      "  <div class='y360-hud-sec'>",
      "      <span class='y360-hud-title'>YARD 360</span>",
      "      <span style='color:#03C314; font-size:9px; border:1px solid #03C314; padding:1px 4px;'>ONLINE</span>",
      "  </div>",
      "  <div class='y360-hud-sec'>",
      "      <input type='text' id='y360-filter-box' class='y360-hud-input' placeholder='[ szukaj ]'>",
      "      <button id='y360-btn-toggle-mode' class='y360-hud-btn'>TRYB: 1 KIERUNEK</button>",
      "      <button id='y360-btn-force-refresh' class='y360-hud-btn'>ODŚWIEŻ</button>",
      "  </div>",
      "  <div class='y360-hud-sec' id='y360-routes-slot' style='overflow-x:auto;'></div>",
      "  <div style='margin-left:auto; font-size:10px; color:#666;'>OXY_OS // APPOINTMENTS</div>",
      "</div>"
    ].join("\n");
    document.body.insertAdjacentHTML("afterbegin", hudHTML);

    document.getElementById("y360-filter-box").addEventListener("input", function (e) {
      quickFilterTerm = e.target.value.toLowerCase().trim();
      parseYard360Table();
    });

    document.getElementById("y360-btn-toggle-mode").addEventListener("click", function () {
      routeFilterMode = routeFilterMode === "SINGLE" ? "ALL" : "SINGLE";
      if (typeof chrome !== "undefined" && chrome.storage && chrome.storage.local) {
        chrome.storage.local.set({ y360_route_mode: routeFilterMode });
      }
      updateHudModeButton();
      parseYard360Table();
    });

    document.getElementById("y360-btn-force-refresh").addEventListener("click", function () {
      var nativeBtn = document.querySelector('[data-testid="dataRefresherButton"]');
      if (nativeBtn) nativeBtn.click();
      parseYard360Table();
    });

    updateHudModeButton();
  }

  var slot = document.getElementById("y360-routes-slot");
  if (!slot) return;

  var routes = Object.keys(counts);
  if (routes.length === 0) {
    routes = [PRIMARY_ROUTE];
    counts[PRIMARY_ROUTE] = { full: 0, empty: 0, driver: 0 };
  }

  var html = "";
  routes.forEach(function (r) {
    var d = counts[r] || { full: 0, empty: 0, driver: 0 };
    html += [
      "<div class='y360-hud-badge'>",
      "    <b style='color:#f36c00;'>" + r + "</b>",
      "    <span style='color:#888;'>EMP:</span> <b style='color:#CE9105;'>" + d.empty + "</b>",
      "    <span style='color:#888; margin-left:4px;'>FULL:</span> <b style='color:#03C314;'>" + d.full + "</b>",
      "    <span class='y360-drv-tag'>[DRV: " + d.driver + "]</span>",
      "</div>"
    ].join(" ");
  });

  slot.innerHTML = html;
}

function initYard360Observer() {
  var attach = function () {
    var table = document.querySelector('table[data-testid="wranglingTable"]');
    if (!table) return false;

    if (tableObserver) tableObserver.disconnect();
    tableObserver = new MutationObserver(function () {
      parseYard360Table();
    });

    tableObserver.observe(table, { childList: true, subtree: true, attributes: false, characterData: false });
    parseYard360Table();
    return true;
  };

  if (!attach()) {
    var bootObs = new MutationObserver(function (_m, obs) {
      if (attach()) obs.disconnect();
    });
    bootObs.observe(document.body, { childList: true, subtree: true });
  }

  if (pollIntervalId) clearInterval(pollIntervalId);
  pollIntervalId = setInterval(parseYard360Table, pollIntervalMs);
}

// Inicjalizacja skryptu
if (document.readyState === "loading") {
  document.addEventListener("DOMContentLoaded", initYard360Observer);
} else {
  initYard360Observer();
}
"}

{"title":"css_all","content":"// ==UserScript==
// @name         YMS Master Theme Engine - 100% Selector & Class Coverage
// @namespace    http://tampermonkey.net/
// @version      4.0
// @description  Wszystkie 327 selektorów z Twojego kodu CSS + Auto-tuner DOM + Live Editor
// @match        *://*/*
// @grant        GM_addStyle
// @grant        GM_getValue
// @grant        GM_setValue
// @run-at       document-start
// ==/UserScript==

(function () {
    'use strict';

    // =========================================================================
    // 1. DOKŁADNA TREŚĆ TWOJEGO PLIKU CSS (ZMIENNE :ROOT + WSZYSTKIE REGUŁY)
    // =========================================================================
    const RAW_YMS_CSS = `
:root {
	--gree: #00ee34;
	--red: #c50000;
	--warning-color: #fff20021;
	--warning-border: #fff200;
	--bg-color: #1a1a1a;
	--bg: #121212;
	--bg-primary: #1e1e1e;
	--bg-secondary: #252526;
	--bg-tertiary: #2e2e2e;
	--border-color: #2a2a2a;
	--panel-bg: #2a2a2a;
	--card-bg: #303030;
	--input-bg: #2d2d30;
	--highlight: #e48100;
	--text-color: #e0e0e0;
	--text-primary: #e0e0e0;
	--text-muted: #858585;
	--text-inverse: #000;
	--screen-bg: #0d0d0d;
	--screen-border: #2a2a2a;
	--border-color-hover: #444;
	--hover-bg: #3c3c3c;
	--grid-color: rgba(255, 255, 255, 0.03);
	--pattern-color: rgba(255, 255, 255, 0.03);
	--rgba-warning-color: 255, 193, 7;
	--rgba-success-color: 40, 167, 69;
	--rgba-danger-color: 220, 53, 69;
	--rgba-info-color: 23, 162, 184;
	--rgba-vs-vi-color: 59, 130, 246;
	--rgba-tak-color: 22, 163, 74;
	--rgba-nie-color: 220, 38, 38;
	--vs-trailer-text: #4db6ac;
	--r-trailer-text: #64b5f6;
	--missing-scac-text: #e57373;
	--visit-inbound-text: #ffb74d;
	--visit-outbound-text: #81c784;
	--tak-bg: rgba(34, 197, 94, 0.15);
	--nie-bg: rgba(239, 68, 68, 0.15);
	--vs-vi-bg: rgba(96, 165, 250, 0.15);
	--highlight-bg: rgba(243, 108, 0, 0.15);
	--latest-bg: rgba(189, 189, 189, 0.15);
	--highlight-soft: var(--highlight-bg);
	--filter-icon: invert(1) brightness(0.9) saturate(0.9);
	--filter-icon-hover: invert(36%) sepia(83%) saturate(2030%) hue-rotate(353deg) brightness(97%) contrast(108%);
	--filter-icon-success: invert(55%) sepia(44%) saturate(551%) hue-rotate(89deg) brightness(93%) contrast(97%);
	--filter-icon-danger: invert(36%) sepia(83%) saturate(2030%) hue-rotate(353deg) brightness(97%) contrast(108%);
	--metal-gradient: linear-gradient(165deg, var(--panel-bg) 0%, var(--bg-primary) 45%, var(--bg-tertiary) 100%);
	--stripe-accent: rgba(255, 255, 255, 0.06);
	--bg-stripe-pattern: linear-gradient(135deg,
	var(--bg-tertiary) 0%,
