        const cleanCSS = css.replace(/:root\s*\{[\s\S]*?\}/, '');
        const ruleBlocks = cleanCSS.split('}');
        const selectorSet = new Set();

        ruleBlocks.forEach(block => {
            const braceIdx = block.indexOf('{');
            if (braceIdx > -1) {
                const rawSelectors = block.slice(0, braceIdx).trim();
                rawSelectors.split(',').forEach(sel => {
                    const s = sel.trim().replace(/\n/g, ' ');
                    if (s && !s.startsWith('@') && !s.includes('::')) {
                        selectorSet.add(s);
                    }
                });
            }
        });
        return Array.from(selectorSet);
