                    <span class="yms-s-name" title="${sel}">${sel}</span>
                    <span class="yms-s-badge" title="Znalezione pasujące węzły w DOM">${count}</span>
                `;

                // Kliknięcie w selektor podświetla znalezione elementy neonem na 2 sekundy
                row.addEventListener('click', () => {
                    try {
                        const els = document.querySelectorAll(sel);
                        els.forEach(el => {
                            const prev = el.style.outline;
                            el.style.outline = '2px solid #e48100';
                            setTimeout(() => { el.style.outline = prev; }, 2000);
                        });
                    } catch(e) {}
                });

                viewSels.appendChild(row);
            });
        }

        filterInput.addEventListener('input', () => {
            if (activeTab === 'vars') renderVars();
            else renderSelectors();
        });

        document.getElementById('yms-action-save').addEventListener('click', () => {
            GM_setValue('YMS_VARS_PERSISTED', currentVariables);
            alert('ZAPISANO ZMIENNE W PAMIĘCI PRZEGLĄDARKI');
        });

        document.getElementById('yms-action-reset').addEventListener('click', () => {
            currentVariables = Object.assign({}, defaultVariables);
            GM_setValue('YMS_VARS_PERSISTED', currentVariables);
            compileAndInjectCSS();
            renderVars();
        });

        document.getElementById('yms-action-tune').addEventListener('click', () => {
            scanAndTuneAll();
            renderSelectors();
            alert('WYMUSZONO STROJENIE DLA WSZYSTKICH ELEMENTÓW DOM');
        });
    });
})();
"}

