.tcp-widget .a-no-js .a-switch-row .a-switch-label {
    color: var(--text-muted);
}

.tcp-widget .a-carousel-button:focus {
    border-color: var(--border-color-hover);
}

.tcp-widget ol.a-carousel {
    color: var(--text-muted);
}

.tcp-widget #header .header-leftpanel .menuWrapper .labelBox .labelList .labelListItem {
    filter: var(--filter-icon);
}

.nav-tabs .nav-link:focus,
    .nav-tabs .nav-link:hover {
    border-color: var(--border-color-hover);
}

.form-control {
    background: var(--bg-color);
    border-color: var(--border-color);
}

.form_wrapper,
    .nav-tabs .nav-item.show .nav-link,
    .nav-tabs .nav-link.active {
    background: var(--bg-color);
    border-color: var(--border-color-hover);
}



}"}

{"title":"op","content":"// ==UserScript==
// @name         YMS Design Changes2
// @namespace    https://phonetool.amazon.com/users/johjason
// @version      0.4.0.0
// @description  Various design changes to make the YMS Dashboard neater, easier and more functional. With Settings Panel and dynamic CSS loading.
// @author       johjason & You
// @downloadURL  https://axzile.corp.amazon.com/-/carthamus/download_script/yms-design-changes.user.js
// @updateURL    https://axzile.corp.amazon.com/-/carthamus/download_script/yms-design-changes.user.js
// @match        https://trans-logistics.amazon.com/yms/shipclerk/*
// @match        https://trans-logistics-eu.amazon.com/yms/shipclerk/*
// @icon         https://images-na.ssl-images-amazon.com/images/G/01/TransCentral/images/favicon.ico
// @grant        GM_addStyle
// @require      https://code.jquery.com/jquery-3.7.0.min.js
// @run-at       document-end
// ==/UserScript==

/* globals $ */

(function (window, document) {
    window.onload = init;

    // Domyślna konfiguracja
    const defaultConfig = {
        bgColor: "",
        textColor: "",
        searchRoute: "WRO5->BCN4",
        routeColor: "#ffeb3b",
        metrics: {
            emptyazng: true,
            dockempty: true,
            taggedazng: true,
            loadedAZNG: true,
            ddemptydiv: true,
            tdrout: true,
            psemptydiv: true,
            nonazng: true,
            tractors: true,
            nicarts: true,
            wro5bcn4div: true
        },
        cssUrls: {
            light: "https://drive.corp.amazon.com/view/TOM%20Utilities/TamperMonkey/YMS%20Design%20Changes/newstyle.css?ver=1.5",
            dark: "https://drive.corp.amazon.com/view/TOM%20Utilities/TamperMonkey/YMS%20Design%20Changes/newstyle.dark.css?ver=1.5"
        }
    };

    // Pobranie konfiguracji z localStorage
    let ymsConfig = JSON.parse(localStorage.getItem('ymsSettingsConfig')) || defaultConfig;

    // Zapewnienie, że w istniejącej konfiguracji istnieje obiekt cssUrls (wsteczna kompatybilność)
    if (!ymsConfig.cssUrls) ymsConfig.cssUrls = defaultConfig.cssUrls;

    // -----------------------------------------------------------------------------------------
    // ZARZĄDZANIE GŁÓWNYMI STYLAMI (DYNAMIC LINK INJECTION)
    // -----------------------------------------------------------------------------------------
    function applyThemeCSS(isDark) {
        let linkEl = document.getElementById("yms-dynamic-theme-css");
        if (!linkEl) {
            linkEl = document.createElement("link");
            linkEl.id = "yms-dynamic-theme-css";
            linkEl.rel = "stylesheet";
            document.head.appendChild(linkEl);
        }
        // Przełączanie między podanymi w ustawieniach linkami
        linkEl.href = isDark ? ymsConfig.cssUrls.dark : ymsConfig.cssUrls.light;
    }

    // Aplikuj domyślny jasny motyw przy starcie
    applyThemeCSS(false);

    // Dodanie niezbędnych wbudowanych stylów modala i customowych funkcji
    GM_addStyle(`

  @import url('https://fonts.googleapis.com/css2?family=JetBrains+Mono&family=Share+Tech+Mono&display=swap');
:root {
    --background: oklch(0.2267 0 0);
    /* #1c1c1c */
    --foreground: oklch(0.9696 0 0);
    /* Near-white */

    --card: oklch(0.2156 0 0);
    /* #191919 */
    --card-foreground: oklch(0.9696 0 0);

    --primary: oklch(0.6469 0.2036 35.49);
    /* #F05023 (Brand Orange) */
    --primary-foreground: oklch(1 0 0);

    --secondary: oklch(0.2697 0 0);
    /* #262626 */
    --secondary-foreground: oklch(0.8054 0 0);

    --border: oklch(0.2697 0 0);
    /* #262626 */
    --radius: 10px;
    /* 0.625rem */
    --font-sans: "Inter", ui-sans-serif, system-ui, sans-serif;
    --font-mono: "JetBrains Mono", ui-monospace, monospace;
}



        .oxy-copy-btn {
     background: transparent;
     color: var(--primary);
     border: 1px solid var(--border);
     border-radius: 0 !important;
     font-family: "Share Tech Mono", monospace;
     font-size: 10px;
     text-transform: uppercase;
     cursor: pointer;
     user-select: none;
     transition: all 0.3s ease-in-out;
     height: 20px;
 }

 .oxy-copy-btn:hover {
     background: #f36c00;
     color: #FFFFFF;
 }

 .oxy-copy-btn:active {
     opacity: 0.8;
 }

 #trailerdashboard .empty,
 #trailerdashboard .emptyalert {
     display: inline-block;
     min-width: 1.5em;
 }

 #trailerdashboard .emptyalert {
     color: #c00;
     font-weight: bold;
 }

 .vehicleIdGroup-LP {
     display: flex;
     align-items: center;
 }

 .shipclerk-bold-label {
     font-size: 12px;
     display: flex;
     align-items: center;
 }

 .shipclerk-seals {
     color: #f36c00 !important;
     display: flex;
     justify-content: left;
     align-items: center;
     height: 30px !important;
     width: 10rem;
     transition: all 0.2s;
     z-index: 99;
     font-size: 1rem;
     background: transparent;
     padding-left: 0.5rem;
 }

 .shipclerk-seals:hover {
     background: #000;
     transform: scale(3);
     color: #FFFFFF !important;
 }

 .vehicle-number-LP {
     color: rgb(0, 72, 188);
     transition: all 0.15s;
     padding: 0.1rem 0.2rem;
     height: 20px;
 }

 .vehicle-number-LP:hover {
     background: #1d1d1d;
     color: rgb(50, 188, 0);
     transform: scale(4) translateX(0px);
     background: #000;
 }

 /* Style panelu ustawień */
 #yms-settings-modal {
     display: flex ;
     position: fixed;
     top: 5%;
     left: 50%;
     transform: translateX(-50%);
     background: #2a2a2a;
     color: #fff;
     padding: 15px;
     z-index: 10000;
     border: 2px solid #f36c00;
     border-radius: 8px;
     box-shadow: 0 10px 30px rgba(0, 0, 0, 0.8);
     width: 500px;
     font-family: Arial, sans-serif;
     max-height: 90vh;
     overflow-y: auto;
       flex-direction: column;
 }

 #yms-settings-modal h2 {
     color: #f36c00;
     margin-top: 0;
     border-bottom: 1px solid #555;
     padding-bottom: 10px;
 }

 #yms-settings-modal h3 {
     font-size: 14px;
     margin-bottom: 5px;
     color: #ff9900;
 }

 #yms-settings-modal .setting-group {
     margin-bottom: 15px;
     background: #1a1a1a;
     padding: 10px;
     display: flex;
     flex-direction: column;
     align-items: flex-start;
 }

 #yms-settings-modal label {
     display: block;
     font-size: 13px;
     margin-bottom: 5px;
     cursor: pointer;
 }

 #yms-settings-modal input[type="text"] {
    width: 100%;
    padding: 5px;
    box-sizing: border-box;
    background: #212121;
    color: #b0b0b0;
    border: 1px solid #212121;
    margin-bottom: 8px;
 }

 .yms-btn {
     background: #f36c00;
     color: #fff;
     border: 1px solid #f36c00;
     cursor: pointer;
     font-weight: bold;
     width: 100%;
     }

 .yms-btn:hover {
     background: #d35400;
 }

 #open-yms-settings {
         margin-left: 20px;
    background: #2a2a2a;
    /* border: 1px solid #f36c00; */
    color: #f36c00;
    padding: 1px 10px;
    cursor: pointer;
    font-weight: bold;
    position: fixed;
    right: 20%;
    top: 5px;
    z-index: 999;
 }

 #open-yms-settings:hover {
     background: #f36c00;
     color: #fff;
 }

#yms-btn-close{
   margin-left: 20px;
     background: #2a2a2a;
     border: 1px solid #f36c00;
     color: #f36c00;
     padding: 2px 10px;
     cursor: pointer;
     font-weight: bold;
}

.bg{
  display: flex;
     justify-content: left;
     align-items: center;
}
    `);

    // Iniekcja kolorów z customizatora
    function applyCustomColors() {
        let customStyle = document.getElementById("yms-custom-colors-style");
        if (!customStyle) {
            customStyle = document.createElement("style");
            customStyle.id = "yms-custom-colors-style";
            document.head.appendChild(customStyle);
        }
        let cssRules = "";
        if (ymsConfig.bgColor) cssRules += `body, .app-body, .flex-container { background-color: ${ymsConfig.bgColor} !important; } `;
        if (ymsConfig.textColor) cssRules += `body, span, div, td, th { color: ${ymsConfig.textColor} !important; } `;
        customStyle.innerHTML = cssRules;
    }
    applyCustomColors();

    function init() {
        "use strict";

        // 1. Zbudowanie Kontenerów Opcji i Przycisku Ustawień
        document.getElementById("mainContainer").insertAdjacentHTML(
            "beforebegin",
            `
            <div id="custom-options-container" style="display:flex; align-items:center; flex-wrap:wrap;">
                <h3 id="dark-mode-label" style="margin-right:10px;"><t>Dark Mode:</t></h3>
                <div id="dark-mode-switch" style="margin-right:20px;">
                    <input id="dark-mode-toggle" type="checkbox">
                    <label for="dark-mode-toggle"></label>
                </div>
                <h3 id="filterTrailer-label" style="margin-right:10px;"><t>Tagged Trailers:</t></h3>
                <div>
                    <input id="filterTrailer-toggle" type="checkbox">
                    <label for="filterTrailer"></label>
                </div>
                <button id="open-yms-settings">⚙️ Settings</button>
            </div>
            `
        );

        // 2. Wbudowanie Panelu Konfiguracyjnego (Modal)
        document.body.insertAdjacentHTML('beforeend', `
            <div id="yms-settings-modal">
                <h2>Ustawienia YMS Dashboard</h2>

                <div class="setting-group">
                    <h3>1. Kolory strony (Zostaw puste dla domyślnych z CSS)</h3>
                    <label>Kolor tła: <input type="color" id="cfg-bg-color" value="${ymsConfig.bgColor || '#ffffff'}"></label>
                    <label>Kolor tekstu: <input type="color" id="cfg-text-color" value="${ymsConfig.textColor || '#000000'}"></label>
                </div>

                <div class="setting-group" id="cfg-metrics-group">
                    <h3>2. Elementy na górnym pasku</h3>
                    <label><input type="checkbox" data-id="emptyazng"> AZNG Empties in PS</label>
                    <label><input type="checkbox" data-id="dockempty"> AZNG Empties on DD</label>
                    <label><input type="checkbox" data-id="taggedazng"> Tagged AZNG Trailers</label>
                    <label><input type="checkbox" data-id="loadedAZNG"> Loaded AZNG w/ No VRID</label>
                    <label><input type="checkbox" data-id="ddemptydiv"> Open Dock Doors</label>
                    <label><input type="checkbox" data-id="tdrout"> Doors TDR'd Out</label>
                    <label><input type="checkbox" data-id="psemptydiv"> Open Slips</label>
                    <label><input type="checkbox" data-id="nonazng"> OnSite Non AZNG Emptys</label>
                    <label><input type="checkbox" data-id="tractors"> Tractors</label>
                    <label><input type="checkbox" data-id="nicarts"> NICART Loads</label>
                    <label><input type="checkbox" data-id="wro5bcn4div"> Dynamiczny Alert Trasy</label>
                </div>

                <div class="setting-group">
                    <h3>3. Dostrajanie wyszukiwania danych</h3>
                    <label>Obserwowana trasa (np. WRO5->BCN4):</label>
                    <input type="text" id="cfg-search-route" value="${ymsConfig.searchRoute}">
                    <label style="margin-top:5px;">Kolor podświetlenia trasy: <input type="color" id="cfg-route-color" value="${ymsConfig.routeColor}"></label>
                </div>

                <div class="setting-group">
                    <h3>4. Arkusze stylów (CSS URLs)</h3>
                    <label>Standardowy / Jasny motyw (URL):</label>
                    <input type="text" id="cfg-css-light" value="${ymsConfig.cssUrls.light}">
                    <label>Ciemny motyw (URL):</label>
                    <input type="text" id="cfg-css-dark" value="${ymsConfig.cssUrls.dark}">
                </div>
                <div class="bg">
                <button id="save-yms-settings" class="yms-btn">Zapisz i Odśwież widok</button>
                <button id="close-yms-settings" style="yms-btn-close">Anuluj</button>
              </div>
            </div>
        `);

        // Obsługa modala ustawień
        $("#open-yms-settings").click(function() {
            $("#cfg-metrics-group input[type='checkbox']").each(function() {
                let id = $(this).data("id");
                $(this).prop("checked", ymsConfig.metrics[id] !== false);
            });
            $("#yms-settings-modal").fadeIn();
        });

        $("#close-yms-settings").click(function() {
            $("#yms-settings-modal").fadeOut();
        });

        $("#save-yms-settings").click(function() {
            ymsConfig.bgColor = $("#cfg-bg-color").val() !== "#ffffff" && $("#cfg-bg-color").val() !== "#000000" ? $("#cfg-bg-color").val() : "";
            ymsConfig.textColor = $("#cfg-text-color").val() !== "#ffffff" && $("#cfg-text-color").val() !== "#000000" ? $("#cfg-text-color").val() : "";
            ymsConfig.searchRoute = $("#cfg-search-route").val() || "WRO5->BCN4";
            ymsConfig.routeColor = $("#cfg-route-color").val();

            // Zapis URL-i do CSS
            ymsConfig.cssUrls.light = $("#cfg-css-light").val() || defaultConfig.cssUrls.light;
            ymsConfig.cssUrls.dark = $("#cfg-css-dark").val() || defaultConfig.cssUrls.dark;

            $("#cfg-metrics-group input[type='checkbox']").each(function() {
                let id = $(this).data("id");
                ymsConfig.metrics[id] = $(this).is(":checked");
            });

            localStorage.setItem('ymsSettingsConfig', JSON.stringify(ymsConfig));

            // Odśwież i zaaplikuj zaktualizowane ustawienia
            applyCustomColors();
            applyThemeCSS(document.getElementById("dark-mode-toggle").checked);
            updateTopBarVisibility();
            $("#yms-settings-modal").fadeOut();
            emptyAZNG();
        });

        // ----------------------------------------------------------------------
        // Funkcje Dark Mode i Filter
        document.getElementById("dark-mode-toggle").addEventListener("change", function () {
            // Zamiast wczytywać GM_addStyle(GM_getResourceText(...)), przelączamy linki CSS
            applyThemeCSS(this.checked);
        });

        document.getElementById("filterTrailer-toggle").addEventListener("change", function () {
            if (document.getElementById("filterTrailer-toggle").checked) {
                $("#ship-clerk-dashboard-table tbody tr").show();
                var targChecked = $(".flex-container.row").filter(function () {
                    return $(this).children(".yard-asset-yellow,.yard-asset-red").length == 0;
                });
                var targCheckedEmpty = $(".masterYardLP td:nth-child(2):not('[class^=col2]')");
                var targCheckedCombined = targChecked.add(targCheckedEmpty);
                $(targCheckedCombined).closest("tr").not("tr tr").hide();
            } else {
                $("#ship-clerk-dashboard-table tbody tr").show();
                var targUnchecked = $(".flex-container.row").filter(function () {
                    return $(this).children(".yard-asset-yellow,.yard-asset-red").length == 0;
                });
                var targUncheckedEmpty = $(".masterYardLP td:nth-child(2):not('[class^=col2]')");
                var targUncheckedCombined = targUnchecked.add(targUncheckedEmpty);
                $(targUncheckedCombined).closest("tr").not("tr tr").show();
            }
        });

        function updateTopBarVisibility() {
            for (let metricId in ymsConfig.metrics) {
                let elem = document.getElementById(metricId);
                if (elem && elem.parentElement) {
                    elem.parentElement.style.display = ymsConfig.metrics[metricId] ? "" : "none";
                }
            }
        }

        if (window.location.href.indexOf("shipclerk/#/yard") > -1) {
            document.styleSheets[0].insertRule(".note-present-icon {flex-shrink: 0;}");
            document.getElementById("mainContainer").insertAdjacentHTML(
                "beforebegin",
                `
                <div id="trailerdashboard">
                    <h2 style="text-align: center;"><div id="emptyazng">AZNG Empties in PS: <span id="val-emptyazng" class="empty">0</span></div></h2>
                    <h2 style="text-align: center;"><div id="dockempty">AZNG Empties on DD: <span id="val-dockempty" class="empty">0</span></div></h2>
                    <h2 style="text-align: center;"><div id="taggedazng">Tagged AZNG Trailers: <span id="val-taggedazng" class="empty">0</span></div></h2>
                    <h2 style="text-align: center;"><div id="loadedAZNG">Loaded AZNG w/ No VRID: <span id="val-loadedazng" class="empty">0</span></div></h2>
                    <h2 style="text-align: center;"><div id="ddemptydiv">Open Dock Doors: <span id="val-ddempty" class="empty">0</span></div></h2>
                    <h2 style="text-align: center;"><div id="tdrout">Doors TDR'd Out: <span id="val-tdrout" class="empty">0</span></div></h2>
                    <h2 style="text-align: center;"><div id="psemptydiv">Open Slips: <span id="val-psempty" class="empty">0</span></div></h2>
                    <h2 style="text-align: center;"><div id="nonazng">OnSite Non AZNG Emptys: <span id="val-nonazng" class="empty">0</span></div></h2>
                    <h2 style="text-align: center;"><div id="tractors">Tractors: <span id="val-tractors" class="empty">0</span></div></h2>
                    <h2 style="text-align: center;"><div id="nicarts">NICART Loads: <span id="val-nicarts" class="empty">0</span></div></h2>
                    <h2 style="text-align: center;"><div id="wro5bcn4div">${ymsConfig.searchRoute}: <span id="val-wro5bcn4" class="empty">0</span></div></h2>
                </div>
                `
            );

            updateTopBarVisibility();

            function emptyAZNG() {
                var tagged = 0, nicarts = 0, nonazng = 0, nonoff = 0;
                var tractorsYard = $(".yard-asset-icon-TRACTOR").length;
                var noTDR = $(".NoTDR").length;
                var psEmpty = $("tr.empty-location > td.col1 > div.location-type-ParkingLocation").length;
                var ddEmpty = $("tr.empty-location > td.col1 > div.location-type-ProcessingLocation").length;
                var emptyAZNGinPS = 0, emptyAZNGinDD = 0, empty3PinPS = 0, loadedAZNGnoVRID = 0;

                var dynamicRouteCount = $(`span[title='${ymsConfig.searchRoute}']`).length;

                $("tr.ng-scope").each(function () {
                    if ($(this).find(".location-type-ParkingLocation").length > 0 && $(this).find(".yardasset-empty").length > 0 && $(this).find('.ownerOperatorCodeGroup :contains("AZNG")').length > 0) emptyAZNGinPS++;
                    if ($(this).find(".location-type-ProcessingLocation").length > 0 && $(this).find(".yardasset-empty").length > 0 && $(this).find('.ownerOperatorCodeGroup :contains("AZNG")').length > 0) emptyAZNGinDD++;
                    if ($(this).find(".location-type-ParkingLocation").length > 0 && $(this).find(".yardasset-empty").length > 0 && $(this).find('.ownerOperatorCodeGroup :not(:contains("AZNG"))').length > 0) empty3PinPS++;
                    if ($(this).find(".yardAsset-unavailable").length > 0 && $(this).find('.ownerOperatorCodeGroup :contains("AZNG")').length > 0) tagged++;
                });

                var wholerows = document.querySelectorAll("tr.ng-scope");
                Array.prototype.forEach.call(wholerows, function (col) {
                    if (col.innerHTML.match(/highlight yardasset-full"/) && col.innerHTML.match(/AZNG/) && !col.innerHTML.match(/vrid/)) loadedAZNGnoVRID++;
                    else if (col.innerHTML.match(/highlight yardasset-empty"/) && !col.innerHTML.match(/TRACTOR highlight yardasset-empty"/) && !col.innerHTML.match(/AZNG/) && !col.innerHTML.match(/vrid/)) nonazng++;
                    else if (col.innerHTML.match(/highlight yardasset-empty"/) && !col.innerHTML.match(/AZNG/) && !col.innerHTML.match(/vrid/) && !col.innerHTML.match(/LDLB/) && !col.innerHTML.match(/BSPC/) && !col.innerHTML.match(/BRDZ/) && !col.innerHTML.match(/DUMMY/) && (!col.innerHTML.match(/class="col1 /) || col.innerHTML.match(/OSY/))) nonoff++;
                    if ((col.innerHTML.match(/TransfersEmptyCar/) || col.innerHTML.match(/NICARTS/i)) && !col.innerHTML.match(/yard-asset-icon-TRACTOR/)) nicarts++;
                });

                var tag = (psEmpty < 5) ? "emptyalert" : "empty";
                var tagtag = (tagged > 2) ? "emptyalert" : "empty";

                document.getElementById("emptyazng").innerHTML = `AZNG Empties in PS: <span id="val-emptyazng" class="${tag}">${emptyAZNGinPS}</span>`;
                document.getElementById("taggedazng").innerHTML = `Tagged AZNG Trailers: <span id="val-taggedazng" class="${tagtag}">${tagged}</span>`;
                document.getElementById("dockempty").innerHTML = `AZNG Empties on DD: <span id="val-dockempty" class="empty">${emptyAZNGinDD}</span>`;
                document.getElementById("loadedAZNG").innerHTML = `Loaded AZNG w/ No VRID: <span id="val-loadedazng" class="empty">${loadedAZNGnoVRID}</span>`;
                document.getElementById("nicarts").innerHTML = `NICART Loads: <span id="val-nicarts" class="empty">${nicarts}</span>`;
                document.getElementById("tractors").innerHTML = `Tractors: <span id="val-tractors" class="empty">${tractorsYard}</span>`;
                document.getElementById("nonazng").innerHTML = `OnSite Non AZNG emptys: <span id="val-nonazng" class="empty">${empty3PinPS}</span>`;
                document.getElementById("psemptydiv").innerHTML = `Open Slips: <span id="val-psempty" class="empty">${psEmpty}</span>`;
                document.getElementById("ddemptydiv").innerHTML = `Open Dock Doors: <span id="val-ddempty" class="empty">${ddEmpty}</span>`;
                document.getElementById("tdrout").innerHTML = `Doors TDR'd Out: <span id="val-tdrout" class="empty">${noTDR}</span>`;
                document.getElementById("wro5bcn4div").innerHTML = `${ymsConfig.searchRoute}: <span id="val-wro5bcn4" class="empty">${dynamicRouteCount}</span>`;
            }

            setInterval(emptyAZNG, 60000);
            setTimeout(emptyAZNG, 10000);
        }

        // ------------------------------------------------------------------------------------------------------------
        function addLicensePlateCopyButtons() {
            $("span[ng-if='yardAsset.vehicleNumber'], span[ng-if='yardAsset.licensePlateIdentifier && yardAsset.licensePlateIdentifier.registrationIdentifier']").each(function () {
                var numberHtml = $(this).html() || "";
                var number = numberHtml.split("<br>")[0].trim();

                if ($(this).parent().parent().find("button.oxy-copy-btn").length < 1) {
                    var copyButton = $("<button>", {
                        class: "oxy-copy-btn superuserTooltip",
                        title: "COPY TO CLIPBOARD",
                        text: "COPY",
                    }).click(function (e) {
                        e.preventDefault();
                        navigator.clipboard.writeText(number.split(" ")[0]).then(() => {
                            let ref = $(this);
                            ref.text("COPIED!");
                            setTimeout(function () { ref.text("COPY"); }, 2000);
                        });
                    });
                    $(this).parent().parent().append($("<br>")).append(copyButton);
                }
            });
        }

        function checkAndAddButtons() {
            if ($("#noteTextArea").is(":visible")) {
                if ($("#sealStatusDiv").length === 0 && typeof addSealStatusButtons === "function") addSealStatusButtons();
                if ($("#pageToggleButton").length === 0 && typeof createToggleButton === "function") createToggleButton();
                $("#pageToggleButton").show();

                if ($("#pageToggleButton").text() === "Next Page") {
                    $("#sealStatusDiv").show();
                    if ($("#page2Content").length > 0) $("#page2Content").hide();
                } else {
                    $("#sealStatusDiv").hide();
                    if ($("#page2Content").length === 0 && typeof createPage2 === "function") createPage2();
                    $("#page2Content").show();
                }
            } else {
                $("#sealStatusDiv, #page2Content, #pageToggleButton").hide();
            }
            addLicensePlateCopyButtons();

            $(`span[title='${ymsConfig.searchRoute}']`).each(function () {
                if (!$(this).hasClass("dynamic-route-colored")) {
                    $(this).addClass("dynamic-route-colored");
                    $(this).css({
                        "background-color": ymsConfig.routeColor,
                        "color": "#d50000",
                        "font-weight": "bold",
                        "padding": "2px 5px",
                        "border-radius": "3px",
                        "border": "1px solid #d50000"
                    });

                    let hex = ymsConfig.routeColor.replace('#', '');
                    let r = parseInt(hex.substring(0, 2), 16), g = parseInt(hex.substring(2, 4), 16), b = parseInt(hex.substring(4, 6), 16);

                    $(this).closest("tr.ng-scope").css({
                        "box-shadow": `inset 0 0 0 2px ${ymsConfig.routeColor}`,
                        "background-color": `rgba(${r}, ${g}, ${b}, 0.15)`
                    });
                }
            });
        }

        setInterval(function () { checkAndAddButtons(); }, 1500);

        // ------------------------------------------------------------------------------------------
        var isTopSectionVisible = true;
        var toggleButton;

        function toggleChanges() {
            var topbarData = document.getElementById("topbarData");
            var searchResults = document.querySelector(".ship-clerk-search-results");
            var tcpWidget = document.querySelector(".tcp-widget");
            var scrollTable = document.querySelector(".scrolltable");
            var topSection = document.getElementById("top-section");

            if (topbarData && searchResults && tcpWidget && scrollTable && topSection) {
                if (topbarData.style.visibility === "hidden") {
                    topbarData.style.visibility = "visible"; topbarData.style.opacity = "1"; topbarData.style.zIndex = "1";
                    toggleButton.innerHTML = "Collapse";
                } else {
                    topbarData.style.visibility = "hidden"; topbarData.style.opacity = "0"; topbarData.style.zIndex = "-999";
                    toggleButton.innerHTML = "Grow";
                }

                if (searchResults.style.marginTop === "-179px") {
                    searchResults.style.marginTop = "0"; searchResults.style.zIndex = "auto";
                } else {
                    searchResults.style.marginTop = "-179px"; searchResults.style.zIndex = "999";
                }

                tcpWidget.style.visibility = tcpWidget.style.visibility === "collapse" ? "visible" : "collapse";
                scrollTable.style.height = scrollTable.style.height === "150%" ? "100%" : "150%";

                if (isTopSectionVisible) {
                    topSection.style.display = "none"; isTopSectionVisible = false;
                } else {
                    topSection.style.display = "-webkit-flex"; isTopSectionVisible = true;
                }
            }
        }

        function addToggleButton() {
            var clearButtonGroup = document.getElementById("clearButtonGroup");
            if (clearButtonGroup) {
                clearButtonGroup.style.display = "flex";
                clearButtonGroup.style.justifyContent = "center";
                clearButtonGroup.style.alignItems = "center";
                toggleButton = document.createElement("button");
                toggleButton.innerHTML = "Collapse";
                toggleButton.style.cursor = "pointer";
                toggleButton.addEventListener("click", toggleChanges);
                clearButtonGroup.appendChild(toggleButton);
            }
        }
        setTimeout(addToggleButton, 5000);
    }
})(window, document);
"}

{"title":"beta","content":"// ==UserScript==
// @name         YMS Design Changes v2
// @namespace    https://phonetool.amazon.com/users/johjason
// @version      0.5.5.0
// @description  Various design changes to make the YMS Dashboard neater, easier and more functional. With Settings Panel and dynamic CSS loading.
// @author       johjason & You
// @match        https://trans-logistics.amazon.com/yms/shipclerk/*
// @match        https://trans-logistics-eu.amazon.com/yms/shipclerk/*
// @include      /^http:\/\/127\.0\.0\.1:\d+\/demo\/shipclerk\//
// @include      /^http:\/\/localhost:\d+\/demo\/shipclerk\//
// @include      /^file:.*?\/demo\/shipclerk\//
// @icon         https://images-na.ssl-images-amazon.com/images/G/01/TransCentral/images/favicon.ico
// @grant        GM_addStyle
// @require      https://code.jquery.com/jquery-3.7.0.min.js
// @run-at       document-end
// ==/UserScript==

/* globals $ */

(function (window, document) {
    "use strict";

    const STORAGE_KEY = "ymsSettingsConfig";

    const METRIC_DEFINITIONS = [
        { id: "emptyazng", label: "AZNG Empties in PS", labelPl: "Puste AZNG w PS" },
        { id: "dockempty", label: "AZNG Empties on DD", labelPl: "Puste AZNG na DD" },
        { id: "taggedazng", label: "Tagged AZNG Trailers", labelPl: "Otagowane naczepy AZNG" },
        { id: "loadedAZNG", label: "Loaded AZNG w/ No VRID", labelPl: "Załadowane AZNG bez VRID" },
        { id: "ddemptydiv", label: "Open Dock Doors", labelPl: "Wolne drzwi doków" },
        { id: "tdrout", label: "Doors TDR'd Out", labelPl: "Drzwi z TDR out" },
        { id: "psemptydiv", label: "Open Slips", labelPl: "Wolne slipy" },
        { id: "nonazng", label: "OnSite Non AZNG Emptys", labelPl: "Puste non-AZNG onsite" },
        { id: "tractors", label: "Tractors", labelPl: "Ciągniki" },
        { id: "nicarts", label: "NICART Loads", labelPl: "Ładunki NICART" },
        { id: "wro5bcn4div", label: "Dynamic Route Alert", labelPl: "Alert trasy" }
    ];

    const defaultConfig = {
        bgColor: "",
        textColor: "",
        searchRoute: "WRO5->BCN4",
        routeColor: "#ffeb3b",
        routeSealColor: "#22c55e",
        darkMode: false,
        filterTrailer: false,
        metrics: Object.fromEntries(METRIC_DEFINITIONS.map((m) => [m.id, true])),
        display: {
            showOptionsBar: true,
            showDarkModeToggle: true,
            showFilterTrailer: true,
            showSettingsButton: true,
            showCollapseButton: true,
            showCopyButtons: true,
            showRouteHighlight: true,
            showSealButtons: true,
            compactDashboard: false,
            dashboardLayout: "grid",
            highlightRowOnRoute: true,
            usePolishLabels: true
        },
        alerts: {
            psEmptyMin: 5,
            taggedMax: 2
        },
        cssUrls: {
            light: "https://drive.corp.amazon.com/view/TOM%20Utilities/TamperMonkey/YMS%20Design%20Changes/newstyle.css?ver=1.5",
            dark: "https://drive.corp.amazon.com/view/TOM%20Utilities/TamperMonkey/YMS%20Design%20Changes/newstyle.dark.css?ver=1.5"
        }
        // cssUrls → arkusze z klasami YMS (.app-body, .scrolltable, .yardasset-empty, …)
    };

    function deepMerge(target, source) {
        const out = { ...target };
        for (const key of Object.keys(source || {})) {
            if (source[key] && typeof source[key] === "object" && !Array.isArray(source[key])) {
                out[key] = deepMerge(out[key] || {}, source[key]);
            } else if (source[key] !== undefined) {
                out[key] = source[key];
            }
        }
        return out;
    }

    function isDemoPage() {
        return /\/demo\/shipclerk\b/i.test(window.location.pathname)
            || (window.location.protocol === "file:" && /demo[\\/]+shipclerk/i.test(window.location.pathname));
    }

    const DEMO_CSS_URLS = {
        light: "../../styles/newstyle.css",
        dark: "../../styles/newstyle.dark.css"
    };

    function applyDemoCssDefaults() {
        const light = ymsConfig.cssUrls?.light || "";
        if (light.includes("drive.corp.amazon.com") || !light) {
            ymsConfig.cssUrls = { ...DEMO_CSS_URLS };
        }
    }

    function loadConfig() {
        try {
            const saved = JSON.parse(localStorage.getItem(STORAGE_KEY));
            return deepMerge(defaultConfig, saved || {});
        } catch {
            return structuredClone(defaultConfig);
        }
    }

    let ymsConfig = loadConfig();
    if (isDemoPage()) applyDemoCssDefaults();

    function saveConfig() {
        localStorage.setItem(STORAGE_KEY, JSON.stringify(ymsConfig));
    }

    function metricLabel(def) {
        return ymsConfig.display.usePolishLabels ? def.labelPl : def.label;
    }

    function applyThemeCSS(isDark) {
        document.documentElement.setAttribute("data-yms-theme", isDark ? "dark" : "light");

        let linkEl = document.getElementById("yms-dynamic-theme-css");
        if (!linkEl) {
            linkEl = document.createElement("link");
            linkEl.id = "yms-dynamic-theme-css";
            linkEl.rel = "stylesheet";
            document.head.appendChild(linkEl);
        }
        linkEl.href = isDark ? ymsConfig.cssUrls.dark : ymsConfig.cssUrls.light;
    }

    applyThemeCSS(ymsConfig.darkMode);

    GM_addStyle(`
@import url('https://fonts.googleapis.com/css2?family=JetBrains+Mono&family=Share+Tech+Mono&display=swap');

html[data-yms-theme="light"],
html:not([data-yms-theme]) {
    --yms-bg: #eef1f5;
    --yms-fg: #1a1a1a;
    --yms-surface: #ffffff;
    --yms-surface-2: #f7f9fc;
    --yms-surface-3: #e8ecf2;
    --yms-border: #c8cdd4;
    --yms-border-strong: #a8b0bc;
    --yms-muted: #64748b;
    --yms-card: rgba(0, 0, 0, 0.05);
    --yms-row-alt: rgba(0, 0, 0, 0.03);
    --yms-modal-bg: #ffffff;
    --yms-modal-surface: #f3f4f6;
    --yms-modal-border: #d1d5db;
    --yms-input-bg: #ffffff;
    --yms-input-fg: #1a1a1a;
    --yms-input-border: #cbd5e1;
    --yms-btn-secondary-bg: #ffffff;
    --yms-shadow: rgba(0, 0, 0, 0.12);
    --yms-banner-bg: #fff7ed;
    --yms-banner-fg: #c2410c;
    --yms-link: #0048bc;
    --yms-link-hover-bg: #1d1d1d;
    --yms-link-hover-fg: #32bc00;
    --yms-unavailable-bg: #fef3c7;
    --yms-tcp-fg: #64748b;
    --background: #ffffff;
    --foreground: #1a1a1a;
    --card: #f3f4f6;
    --card-foreground: #1a1a1a;
    --primary: #f36c00;
    --primary-foreground: #ffffff;
    --secondary: #e8ecf2;
    --secondary-foreground: #374151;
    --border: #cbd5e1;
}

html[data-yms-theme="dark"] {
    --yms-bg: #121212;
    --yms-fg: #e8e8e8;
    --yms-surface: #1e1e1e;
    --yms-surface-2: #161616;
    --yms-surface-3: #252525;
    --yms-border: #333333;
    --yms-border-strong: #444444;
    --yms-muted: #9ca3af;
    --yms-card: rgba(255, 255, 255, 0.07);
    --yms-row-alt: rgba(255, 255, 255, 0.04);
    --yms-modal-bg: #2a2a2a;
    --yms-modal-surface: #1a1a1a;
    --yms-modal-border: #555555;
    --yms-input-bg: #212121;
    --yms-input-fg: #e0e0e0;
    --yms-input-border: #333333;
    --yms-btn-secondary-bg: #2a2a2a;
    --yms-shadow: rgba(0, 0, 0, 0.8);
    --yms-banner-bg: #1f2937;
    --yms-banner-fg: #fb923c;
    --yms-link: #60a5fa;
    --yms-link-hover-bg: #000000;
    --yms-link-hover-fg: #32bc00;
    --yms-unavailable-bg: #422006;
    --yms-tcp-fg: #9ca3af;
    --background: #1c1c1c;
    --foreground: #f5f5f5;
    --card: #191919;
    --card-foreground: #f5f5f5;
    --primary: #f36c00;
    --primary-foreground: #ffffff;
    --secondary: #262626;
    --secondary-foreground: #cccccc;
    --border: #333333;
}

:root {
    --radius: 0px;
    --font-sans:  var(--font-mono):
    --font-mono: "JetBrains Mono", ui-monospace, monospace;
}

/* UI wstrzykiwane przez skrypt – klasy YMS strony są w newstyle.css / newstyle.dark.css */


*{

  scrollbar-width: none;
  border-radius: 0 !important;
  outline: none !important;
  font-family: var(--font-mono:);

}
.vehicle-number-LP {
    display: flex;
    align-items: flex-end;
    /* flex-wrap: wrap; */
    gap: 8px 16px;
    /* margin-bottom: 4px; */
    padding: 4px 8px;
    background: var(--yms-surface);
    border: 1px solid var(--yms-border);
    color: var(--yms-fg);
}

#custom-options-container h3,
#custom-options-container label {
    color: var(--yms-fg);
}

#custom-options-container.is-hidden {
    display: none !important;
}

.yms-hidden {
    display: none !important;
}

.oxy-copy-btn {
    background: transparent;
    color: var(--primary);
    border: 1px solid var(--border);
    border-radius: 0 !important;
    font-family: var(--font-mono:);
    font-size: 11px;
    text-transform: uppercase;
    cursor: pointer;
    user-select: none;
    transition: all 0.3s ease-in-out;
    height: 20px;
}

.oxy-copy-btn:hover {
    background: var(--primary);
    color: var(--primary-foreground);
}

.oxy-copy-btn:active {
    opacity: 0.8;
}

#trailerdashboard {
    display: grid;
    gap: 4px 16px;
    padding: 8px 12px;
    margin-bottom: 8px;
    background: var(--yms-surface);
    border: 1px solid var(--yms-border);
    border-radius: 0px;
}

#trailerdashboard.layout-grid {
    grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
}

#trailerdashboard.layout-list {
    grid-template-columns: 1fr;
}

#trailerdashboard.layout-compact {
    grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));
    font-size: 12px;
}

#trailerdashboard .metric-item {
    display: flex;
    align-items: center;
    justify-content: center;
    min-height: 28px;
    padding: 2px 6px;
    background: var(--yms-card);
    border: 1px solid var(--yms-border);
    border-radius: 0px;
    color: var(--yms-fg);
}

#trailerdashboard .metric-item h2,
#trailerdashboard .metric-item div {
    color: var(--yms-fg);
}

#trailerdashboard .metric-item h2 {
    margin: 0;
    font-size: inherit;
    font-weight: normal;
    text-align: center;
}

#trailerdashboard .empty,
#trailerdashboard .emptyalert {
    display: inline-block;
    min-width: 1.5em;
}

#trailerdashboard .emptyalert {
    color: #ef4444;
    font-weight: bold;
}

.vehicleIdGroup-LP {
    display: flex;
    align-items: center;
}

.shipclerk-bold-label {
    font-size: 12px;
    display: flex;
    align-items: center;
    color: var(--yms-fg);
}

.shipclerk-seals {
    display: flex;
    justify-content: left;
    align-items: center;
    height: 25px !important;
    width: 10rem;
    transition: all 0.2s;
    z-index: 199;
    font-size: 1rem;
    padding-left: 0.5rem;
  background: var(--yms-bg);
}

.shipclerk-seals:hover {
    transform: scale(3);
}

.vehicle-number-LP {
    transition: all 0.15s;
    padding: 0rem 1rem;

}

.vehicle-number-LP:hover {
    transform: scale(4) translateX(0px);
}

.dynamic-route-colored {
    font-weight: bold;
    padding: 2px 5px;
    border-radius: 3px;
    display: inline-block;
}

.dynamic-route-no-seal {
    border: 1px solid #d50000;
}

.dynamic-route-has-seal {
    border: 1px solid #15803d;
}

tr.dynamic-route-row-highlight td {
    transition: background-color 0.2s ease, box-shadow 0.2s ease;
}

#yms-settings-modal {
    display: none;
    position: fixed;
    top: 2%;
    left: 50%;
    transform: translateX(-50%);
    background: var(--yms-modal-bg);
    color: var(--yms-fg);
    padding: 0;
    z-index: 10000;
    border: 1px solid var(--primary);
    box-shadow: 0 10px 30px var(--yms-shadow);
    width: min(800px, 90vw);
    font-family: Arial, sans-serif;
    max-height: 95vh;
    overflow: hidden;
    flex-direction: column;



}

#yms-settings-modal.is-open {
    display: flex;
}

#yms-settings-modal .yms-modal-header {
    padding: 12px 15px;
    border-bottom: 1px solid var(--yms-modal-border);
    flex-shrink: 0;
    background: var(--yms-modal-bg);
}

#yms-settings-modal .yms-modal-body {
    padding: 12px 15px;
    overflow-y: auto;
    flex: 1;
    background: var(--yms-modal-bg);
}

#yms-settings-modal h2 {
    color: var(--primary);
    margin: 0;
    font-size: 18px;
}

#yms-settings-modal h3 {
    font-size: 13px;
    margin: 0 0 8px;
    color: var(--primary);
}

#yms-settings-modal .setting-group {
    margin-bottom: 12px;
    background: var(--yms-modal-surface);
    padding: 10px;
    border-radius: 6px;
    border: 1px solid var(--yms-border);
  display: flex;
    flex-direction: column
}

#yms-settings-modal label {
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: 13px;
    margin-bottom: 6px;
    cursor: pointer;
    color: var(--yms-fg);
}

#yms-settings-modal label.yms-inline {
    display: inline-flex;
    margin-right: 12px;
}

#yms-settings-modal input[type="text"],
#yms-settings-modal input[type="number"],
#yms-settings-modal select {
    width: 100%;
    padding: 6px 8px;
    box-sizing: border-box;
    background: var(--yms-input-bg);
    color: var(--yms-input-fg);
    border: 1px solid var(--yms-input-border);
    border-radius: 4px;
    margin-bottom: 6px;
}

#yms-settings-modal input[type="color"] {
    width: 48px;
    height: 28px;
    padding: 0;
    border: none;
    background: transparent;
    cursor: pointer;
}

#yms-settings-modal .metrics-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 2px 12px;
}

#yms-settings-modal .yms-actions-row {
    display: flex;
    gap: 8px;
    margin-top: 6px;
}

.yms-btn {
    background: var(--primary);
    color: var(--primary-foreground);
    border: 1px solid var(--primary);
    cursor: pointer;
    font-weight: bold;
    flex: 1;
}

.yms-btn:hover {
    filter: brightness(0.9);
}

.yms-btn-secondary {
    background: var(--yms-btn-secondary-bg);
    color: var(--primary);
    border: 1px solid var(--primary);
}

.yms-btn-secondary:hover {
    background: var(--primary);
    color: var(--primary-foreground);
}

#yms-settings-modal .yms-modal-footer {
    display: flex;
    gap: 8px;
    padding: 12px 15px;
    border-top: 1px solid var(--yms-modal-border);
    flex-shrink: 0;
    background: var(--yms-modal-bg);
}

#open-yms-settings {
    margin-left: 20px;
    background: var(--yms-btn-secondary-bg);
    color: var(--primary);
    cursor: pointer;
    font-weight: bold;
    position: fixed;
    right: 20%;
    top: 5px;
    z-index: 9999;
    border: 1px solid var(--yms-border);
    border-radius: 4px;
}

#open-yms-settings:hover {
    background: var(--primary);
    color: var(--primary-foreground);
}

#noteTextArea {
    background: var(--yms-input-bg);
    color: var(--yms-input-fg);
    border: 1px solid var(--yms-input-border);
}

#yms-collapse-toggle {
    background: var(--yms-surface);
    color: var(--yms-fg);
    border: 1px solid var(--yms-border);
    padding: 4px 12px;
    border-radius: 4px;
}

#yms-collapse-toggle:hover {
    background: var(--primary);
    color: var(--primary-foreground);
    border-color: var(--primary);
}
    `);

    function applyCustomColors() {
        let customStyle = document.getElementById("yms-custom-colors-style");
        if (!customStyle) {
            customStyle = document.createElement("style");
            customStyle.id = "yms-custom-colors-style";
            document.head.appendChild(customStyle);
        }
        let cssRules = "";
        if (ymsConfig.bgColor) {
            cssRules += `body, .app-body, .flex-container { background-color: ${ymsConfig.bgColor} !important; } `;
        }
        if (ymsConfig.textColor) {
            cssRules += `body, span, div, td, th { color: ${ymsConfig.textColor} !important; } `;
        }
        customStyle.textContent = cssRules;
    }

    applyCustomColors();

    let emptyAZNGFn = null;
    let toggleButton = null;
    let isTopSectionVisible = true;

    function buildMetricsCheckboxes() {
        return METRIC_DEFINITIONS.map((def) =>
            `<label><input type="checkbox" data-metric="${def.id}"> ${def.labelPl} <span style="opacity:0.6;font-size:11px;">(${def.label})</span></label>`
        ).join("");
    }

    function buildSettingsModal() {
        if (document.getElementById("yms-settings-modal")) return;

        document.body.insertAdjacentHTML("beforeend", `
            <div id="yms-settings-modal">
                <div class="yms-modal-header">
                    <h2>Ustawienia YMS Dashboard</h2>
                </div>
                <div class="yms-modal-body">
                    <div class="setting-group">
                        <h3>Kolory strony (puste = domyślne z CSS)</h3>
                        <label>Kolor tła: <input type="color" id="cfg-bg-color"></label>
                        <label>Kolor tekstu: <input type="color" id="cfg-text-color"></label>
                        <label><input type="checkbox" id="cfg-clear-colors"> Wyczyść niestandardowe kolory</label>
                    </div>

                    <div class="setting-group">
                        <h3>Pasek opcji i elementy UI</h3>
                        <label><input type="checkbox" id="cfg-show-options-bar"> Pokaż pasek opcji</label>
                        <label><input type="checkbox" id="cfg-show-dark-toggle"> Przełącznik Dark Mode</label>
                        <label><input type="checkbox" id="cfg-show-filter-trailer"> Filtr otagowanych naczep</label>
                        <label><input type="checkbox" id="cfg-show-settings-btn"> Przycisk ustawień</label>
                        <label><input type="checkbox" id="cfg-show-collapse-btn"> Przycisk Collapse/Grow</label>
                        <label><input type="checkbox" id="cfg-show-copy-buttons"> Przyciski COPY przy tablicach</label>
                        <label><input type="checkbox" id="cfg-show-route-highlight"> Podświetlanie obserwowanej trasy</label>
                        <label><input type="checkbox" id="cfg-highlight-row-route"> Podświetlanie całego wiersza trasy</label>
                        <label><input type="checkbox" id="cfg-show-seal-buttons"> Przyciski pieczęci (seal status)</label>
                        <label><input type="checkbox" id="cfg-polish-labels"> Polskie etykiety metryk</label>
                    </div>

                    <div class="setting-group" id="cfg-metrics-group">
                        <h3>Metryki na dashboardzie</h3>
                        <div class="yms-actions-row">
                            <button type="button" id="cfg-metrics-all" class="yms-btn yms-btn-secondary ">Zaznacz wszystkie</button>
                            <button type="button" id="cfg-metrics-none" class="yms-btn yms-btn-secondary">Odznacz wszystkie</button>
                        </div>
                        <div class="metrics-grid" style="margin-top:8px;">
                            ${buildMetricsCheckboxes()}
                        </div>
                    </div>

                    <div class="setting-group">
                        <h3>Układ dashboardu metryk</h3>
                        <label>Układ:
                            <select id="cfg-dashboard-layout">
                                <option value="grid">Siatka (domyślny)</option>
                                <option value="list">Lista (pionowo)</option>
                                <option value="compact">Kompaktowy</option>
                            </select>
                        </label>
                    </div>

                    <div class="setting-group">
                        <h3>Trasa i progi alertów</h3>
                        <label>Obserwowana trasa (np. WRO5->BCN4):</label>
                        <input type="text" id="cfg-search-route" placeholder="WRO5->BCN4">
                        <label>Kolor podświetlenia trasy (bez seal): <input type="color" id="cfg-route-color"></label>
                        <label>Kolor trasy z seal: <input type="color" id="cfg-route-seal-color"></label>
                        <label>Alert gdy wolne slipy &lt; <input type="number" id="cfg-ps-empty-min" min="0" max="99" style="width:60px;margin:0;"></label>
                        <label>Alert gdy otagowane AZNG &gt; <input type="number" id="cfg-tagged-max" min="0" max="99" style="width:60px;margin:0;"></label>
                    </div>

                    <div class="setting-group">
                        <h3>Arkusze stylów (CSS URLs)</h3>
                        <label>Jasny motyw (URL):</label>
                        <input type="text" id="cfg-css-light">
                        <label>Ciemny motyw (URL):</label>
                        <input type="text" id="cfg-css-dark">
                    </div>
                </div>
                <div class="yms-modal-footer">
                    <button type="button" id="save-yms-settings" class="yms-btn">Zapisz</button>
                    <button type="button" id="reset-yms-settings" class="yms-btn yms-btn-secondary">Przywróć domyślne</button>
                    <button type="button" id="close-yms-settings" class="yms-btn yms-btn-secondary">Anuluj</button>
                </div>
            </div>
        `);

        bindSettingsEvents();
    }

    function populateSettingsForm() {
        $("#cfg-bg-color").val(ymsConfig.bgColor || "#ffffff");
        $("#cfg-text-color").val(ymsConfig.textColor || "#000000");
        $("#cfg-clear-colors").prop("checked", !ymsConfig.bgColor && !ymsConfig.textColor);
        $("#cfg-search-route").val(ymsConfig.searchRoute);
        $("#cfg-route-color").val(ymsConfig.routeColor);
        $("#cfg-route-seal-color").val(ymsConfig.routeSealColor || "#22c55e");
        $("#cfg-ps-empty-min").val(ymsConfig.alerts.psEmptyMin);
        $("#cfg-tagged-max").val(ymsConfig.alerts.taggedMax);
        $("#cfg-css-light").val(ymsConfig.cssUrls.light);
        $("#cfg-css-dark").val(ymsConfig.cssUrls.dark);
        $("#cfg-dashboard-layout").val(ymsConfig.display.dashboardLayout);

        const d = ymsConfig.display;
        $("#cfg-show-options-bar").prop("checked", d.showOptionsBar);
        $("#cfg-show-dark-toggle").prop("checked", d.showDarkModeToggle);
        $("#cfg-show-filter-trailer").prop("checked", d.showFilterTrailer);
        $("#cfg-show-settings-btn").prop("checked", d.showSettingsButton);
        $("#cfg-show-collapse-btn").prop("checked", d.showCollapseButton);
        $("#cfg-show-copy-buttons").prop("checked", d.showCopyButtons);
        $("#cfg-show-route-highlight").prop("checked", d.showRouteHighlight);
        $("#cfg-highlight-row-route").prop("checked", d.highlightRowOnRoute);
        $("#cfg-show-seal-buttons").prop("checked", d.showSealButtons);
        $("#cfg-polish-labels").prop("checked", d.usePolishLabels);

        $("#cfg-metrics-group input[data-metric]").each(function () {
            const id = $(this).data("metric");
            $(this).prop("checked", ymsConfig.metrics[id] !== false);
        });
    }

    function readSettingsForm() {
        if ($("#cfg-clear-colors").is(":checked")) {
            ymsConfig.bgColor = "";
            ymsConfig.textColor = "";
        } else {
            ymsConfig.bgColor = $("#cfg-bg-color").val();
            ymsConfig.textColor = $("#cfg-text-color").val();
        }

        ymsConfig.searchRoute = ($("#cfg-search-route").val() || "WRO5->BCN4").trim();
        ymsConfig.routeColor = $("#cfg-route-color").val();
        ymsConfig.routeSealColor = $("#cfg-route-seal-color").val() || "#22c55e";
        ymsConfig.alerts.psEmptyMin = parseInt($("#cfg-ps-empty-min").val(), 10) || 5;
        ymsConfig.alerts.taggedMax = parseInt($("#cfg-tagged-max").val(), 10) || 2;
        ymsConfig.cssUrls.light = $("#cfg-css-light").val() || defaultConfig.cssUrls.light;
        ymsConfig.cssUrls.dark = $("#cfg-css-dark").val() || defaultConfig.cssUrls.dark;

        ymsConfig.display.showOptionsBar = $("#cfg-show-options-bar").is(":checked");
        ymsConfig.display.showDarkModeToggle = $("#cfg-show-dark-toggle").is(":checked");
        ymsConfig.display.showFilterTrailer = $("#cfg-show-filter-trailer").is(":checked");
        ymsConfig.display.showSettingsButton = $("#cfg-show-settings-btn").is(":checked");
        ymsConfig.display.showCollapseButton = $("#cfg-show-collapse-btn").is(":checked");
        ymsConfig.display.showCopyButtons = $("#cfg-show-copy-buttons").is(":checked");
        ymsConfig.display.showRouteHighlight = $("#cfg-show-route-highlight").is(":checked");
        ymsConfig.display.highlightRowOnRoute = $("#cfg-highlight-row-route").is(":checked");
        ymsConfig.display.showSealButtons = $("#cfg-show-seal-buttons").is(":checked");
        ymsConfig.display.usePolishLabels = $("#cfg-polish-labels").is(":checked");
        ymsConfig.display.dashboardLayout = $("#cfg-dashboard-layout").val() || "grid";

        $("#cfg-metrics-group input[data-metric]").each(function () {
            ymsConfig.metrics[$(this).data("metric")] = $(this).is(":checked");
        });
    }

    function closeSettingsModal() {
        $("#yms-settings-modal").removeClass("is-open");
    }

    function openSettingsModal() {
        populateSettingsForm();
        $("#yms-settings-modal").addClass("is-open");
    }

    function bindSettingsEvents() {
        $("#open-yms-settings").on("click", openSettingsModal);
        $("#close-yms-settings").on("click", closeSettingsModal);

        $("#cfg-metrics-all").on("click", () => {
            $("#cfg-metrics-group input[data-metric]").prop("checked", true);
        });
        $("#cfg-metrics-none").on("click", () => {
            $("#cfg-metrics-group input[data-metric]").prop("checked", false);
        });

        $("#save-yms-settings").on("click", () => {
            readSettingsForm();
            saveConfig();
            applyCustomColors();
            applyThemeCSS(document.getElementById("dark-mode-toggle")?.checked ?? ymsConfig.darkMode);
            applyDisplaySettings();
            updateTopBarVisibility();
            applyDashboardLayout();
            refreshRouteHighlights(true);
            if (emptyAZNGFn) emptyAZNGFn();
            closeSettingsModal();
        });

        $("#reset-yms-settings").on("click", () => {
            if (confirm("Przywrócić wszystkie ustawienia do domyślnych?")) {
                ymsConfig = structuredClone(defaultConfig);
                saveConfig();
                populateSettingsForm();
            }
        });

        $("#yms-settings-modal").on("click", (e) => {
            if (e.target.id === "yms-settings-modal") closeSettingsModal();
        });
    }

    function applyDisplaySettings() {
        const d = ymsConfig.display;
        const optionsBar = document.getElementById("custom-options-container");

        if (optionsBar) {
            optionsBar.classList.toggle("is-hidden", !d.showOptionsBar);
        }

        $("#dark-mode-label, #dark-mode-switch").toggleClass("yms-hidden", !d.showDarkModeToggle);
        $("#filterTrailer-label").toggleClass("yms-hidden", !d.showFilterTrailer);
        $("#filterTrailer-toggle").closest("div").toggleClass("yms-hidden", !d.showFilterTrailer);
        $("#open-yms-settings").toggleClass("yms-hidden", !d.showSettingsButton);

        if (toggleButton) {
            toggleButton.style.display = d.showCollapseButton ? "" : "none";
        }

        $(".oxy-copy-btn").toggle(d.showCopyButtons);

        if (!d.showSealButtons) {
            $("#sealStatusDiv, #page2Content, #pageToggleButton").hide();
        }
    }

    function applyDashboardLayout() {
        const dash = document.getElementById("trailerdashboard");
        if (!dash) return;
        dash.classList.remove("layout-grid", "layout-list", "layout-compact");
        const layout = ymsConfig.display.dashboardLayout;
        dash.classList.add(`layout-${layout === "compact" ? "compact" : layout === "list" ? "list" : "grid"}`);
    }

    function updateTopBarVisibility() {
        METRIC_DEFINITIONS.forEach((def) => {
            const elem = document.getElementById(def.id);
            if (elem) {
                const wrapper = elem.closest(".metric-item") || elem.parentElement;
                if (wrapper) {
                    wrapper.style.display = ymsConfig.metrics[def.id] !== false ? "" : "none";
                }
            }
        });
    }

    function buildDashboardHTML() {
        const items = METRIC_DEFINITIONS.map((def) => {
            const text = metricLabel(def);
            const valId = def.id === "loadedAZNG" ? "val-loadedazng" : `val-${def.id.replace(/div$/, "")}`;
            return `<div class="metric-item"><h2><div id="${def.id}">${text}: <span id="${valId}" class="empty">0</span></div></h2></div>`;
        }).join("");

        return `<div id="trailerdashboard" class="layout-grid">${items}</div>`;
    }

    function emptyAZNG() {
        if (!document.getElementById("trailerdashboard")) return;

        let tagged = 0;
        let nicarts = 0;
        const tractorsYard = $(".yard-asset-icon-TRACTOR").length;
        const noTDR = $(".NoTDR").length;
        const psEmpty = $("tr.empty-location > td.col1 > div.location-type-ParkingLocation").length;
        const ddEmpty = $("tr.empty-location > td.col1 > div.location-type-ProcessingLocation").length;
        let emptyAZNGinPS = 0;
        let emptyAZNGinDD = 0;
        let empty3PinPS = 0;
        let loadedAZNGnoVRID = 0;

        const dynamicRouteCount = $(`span[title='${ymsConfig.searchRoute}']`).length;

        $("tr.ng-scope").each(function () {
            const $row = $(this);
            if ($row.find(".location-type-ParkingLocation").length && $row.find(".yardasset-empty").length && $row.find('.ownerOperatorCodeGroup :contains("AZNG")').length) emptyAZNGinPS++;
            if ($row.find(".location-type-ProcessingLocation").length && $row.find(".yardasset-empty").length && $row.find('.ownerOperatorCodeGroup :contains("AZNG")').length) emptyAZNGinDD++;
            if ($row.find(".location-type-ParkingLocation").length && $row.find(".yardasset-empty").length && $row.find('.ownerOperatorCodeGroup :not(:contains("AZNG"))').length) empty3PinPS++;
            if ($row.find(".yardAsset-unavailable").length && $row.find('.ownerOperatorCodeGroup :contains("AZNG")').length) tagged++;
        });

        document.querySelectorAll("tr.ng-scope").forEach((col) => {
            const html = col.innerHTML;
            if (/highlight yardasset-full"/.test(html) && /AZNG/.test(html) && !/vrid/.test(html)) loadedAZNGnoVRID++;
            if ((/TransfersEmptyCar/.test(html) || /NICARTS/i.test(html)) && !/yard-asset-icon-TRACTOR/.test(html)) nicarts++;
        });

        const psTag = psEmpty < ymsConfig.alerts.psEmptyMin ? "emptyalert" : "empty";
        const taggedTag = tagged > ymsConfig.alerts.taggedMax ? "emptyalert" : "empty";

        const updates = {
            emptyazng: { label: metricLabel(METRIC_DEFINITIONS[0]), val: emptyAZNGinPS, cls: psTag },
            dockempty: { label: metricLabel(METRIC_DEFINITIONS[1]), val: emptyAZNGinDD, cls: "empty" },
            taggedazng: { label: metricLabel(METRIC_DEFINITIONS[2]), val: tagged, cls: taggedTag },
            loadedAZNG: { label: metricLabel(METRIC_DEFINITIONS[3]), val: loadedAZNGnoVRID, cls: "empty" },
            ddemptydiv: { label: metricLabel(METRIC_DEFINITIONS[4]), val: ddEmpty, cls: "empty" },
            tdrout: { label: metricLabel(METRIC_DEFINITIONS[5]), val: noTDR, cls: "empty" },
            psemptydiv: { label: metricLabel(METRIC_DEFINITIONS[6]), val: psEmpty, cls: "empty" },
            nonazng: { label: metricLabel(METRIC_DEFINITIONS[7]), val: empty3PinPS, cls: "empty" },
            tractors: { label: metricLabel(METRIC_DEFINITIONS[8]), val: tractorsYard, cls: "empty" },
            nicarts: { label: metricLabel(METRIC_DEFINITIONS[9]), val: nicarts, cls: "empty" },
            wro5bcn4div: { label: ymsConfig.searchRoute, val: dynamicRouteCount, cls: "empty" }
        };

        Object.keys(updates).forEach((id) => {
            const el = document.getElementById(id);
            if (!el) return;
            const u = updates[id];
            const spanId = id === "loadedAZNG" ? "val-loadedazng" : `val-${id.replace(/div$/, "")}`;
            el.innerHTML = `${u.label}: <span id="${spanId}" class="${u.cls}">${u.val}</span>`;
        });
    }

    emptyAZNGFn = emptyAZNG;
    window.YMS_refreshMetrics = function () {
        if (emptyAZNGFn) emptyAZNGFn();
    };

    function applyFilterTrailer(checked) {
        $("#ship-clerk-dashboard-table tbody tr").show();
        const untagged = $(".flex-container.row").filter(function () {
            return $(this).children(".yard-asset-yellow,.yard-asset-red").length === 0;
        });
        const emptyCells = $(".masterYardLP td:nth-child(2):not('[class^=col2]')");
        const combined = untagged.add(emptyCells);
        const rows = $(combined).closest("tr").not("tr tr");
        if (checked) {
            rows.hide();
        } else {
            rows.show();
        }
    }

    function hexToRgb(hex) {
        const h = (hex || "#000000").replace("#", "");
        return {
            r: parseInt(h.substring(0, 2), 16) || 0,
            g: parseInt(h.substring(2, 4), 16) || 0,
            b: parseInt(h.substring(4, 6), 16) || 0
        };
    }

    const SEAL_NEGATIVE = /no\s*seal|seal\s*(broken|missing|invalid|open)|unsealed|brak\s*piecz/i;

    function rowHasSeal($row) {
        const $tr = $row.closest("tr.ng-scope").length ? $row.closest("tr.ng-scope") : $row;

        if ($tr.find(".seal-present, .has-seal, .yard-asset-seal, .seal-icon, .sealIdentifierGroup, .shipclerk-seals, [class*='seal-present'], [class*='SealPresent']").length) {
            return true;
        }

        if ($tr.find("[ng-if]").filter(function () {
            const ngIf = ($(this).attr("ng-if") || "").toLowerCase();
            if (ngIf.includes("== null")) return false;

            const text = $(this).text().trim();
            if (text.toLowerCase().includes("seal") && text.length > 0 && !SEAL_NEGATIVE.test(text)) {
                return true;
            }
            return false;
        }).length) {
            return true;
        }

        if ($tr.find("[title]").filter(function () {
            const title = ($(this).attr("title") || "").toLowerCase();
            return title.includes("seal") && !SEAL_NEGATIVE.test($(this).attr("title") || "");
        }).length) {
            return true;
        }

        const html = $tr.html() || "";
        if (/sealIdentifier|sealNumber|yardAsset\.seal|seal-present/i.test(html)) return true;

        const rawText = $tr.text() || "";
        if (/\bseal\s*[:#]?\s*[A-Z0-9-]{3,}/i.test(rawText) && !SEAL_NEGATIVE.test(rawText)) return true;

        return false;
    }

    function clearRouteHighlights() {
        $(".dynamic-route-colored").each(function () {
            $(this)
                .removeClass("dynamic-route-colored dynamic-route-has-seal dynamic-route-no-seal")
                .css({ "background-color": "", color: "", "font-weight": "", padding: "", "border-radius": "", border: "" });
        });
        $("tr.dynamic-route-row-highlight").each(function () {
            $(this).removeClass("dynamic-route-row-highlight").css({ "box-shadow": "", "background-color": "" });
        });
    }

    function applyRouteRowHighlight($span, color, hasSeal) {
        if (!ymsConfig.display.highlightRowOnRoute) return;
        const rgb = hexToRgb(color);
        $span.closest("tr.ng-scope").addClass("dynamic-route-row-highlight").css({
            "box-shadow": `inset 0 0 0 2px ${color}`,
            "background-color": `rgba(${rgb.r}, ${rgb.g}, ${rgb.b}, ${hasSeal ? 0.22 : 0.15})`
        });
    }

    function refreshRouteHighlights(clearExisting) {
        if (clearExisting) clearRouteHighlights();
        if (!ymsConfig.display.showRouteHighlight) return;

        const sealColor = ymsConfig.routeSealColor || "#22c55e";

        $(`span[title='${ymsConfig.searchRoute}']`).each(function () {
            const $span = $(this);
            if ($span.hasClass("dynamic-route-colored")) return;

            const hasSeal = rowHasSeal($span);
            const color = hasSeal ? sealColor : ymsConfig.routeColor;

            $span.addClass("dynamic-route-colored");
            $span.addClass(hasSeal ? "dynamic-route-has-seal" : "dynamic-route-no-seal");
            $span.css({
                "background-color": color,
                color: hasSeal ? "#ffffff" : "#d50000",
                "font-weight": "bold",
                padding: "2px 5px",
                "border-radius": "3px",
                border: hasSeal ? "1px solid #15803d" : "1px solid #d50000"
            });

            applyRouteRowHighlight($span, color, hasSeal);
        });
    }

    function addLicensePlateCopyButtons() {
        if (!ymsConfig.display.showCopyButtons) return;

        $("span[ng-if='yardAsset.vehicleNumber'], span[ng-if='yardAsset.licensePlateIdentifier && yardAsset.licensePlateIdentifier.registrationIdentifier']").each(function () {
            const numberHtml = $(this).html() || "";
            const number = numberHtml.split("<br>")[0].trim();

            if ($(this).parent().parent().find("button.oxy-copy-btn").length < 1) {
                const copyButton = $("<button>", {
                    class: "oxy-copy-btn superuserTooltip",
                    title: "COPY TO CLIPBOARD",
                    text: "COPY"
                }).on("click", function (e) {
                    e.preventDefault();
                    const btn = $(this);
                    navigator.clipboard.writeText(number.split(" ")[0]).then(() => {
                        btn.text("COPIED!");
                        setTimeout(() => btn.text("COPY"), 2000);
                    });
                });
                $(this).parent().parent().append($("<br>")).append(copyButton);
            }
        });
    }

    function checkAndAddButtons() {
        if ($("#noteTextArea").is(":visible") && ymsConfig.display.showSealButtons) {
            if ($("#sealStatusDiv").length === 0 && typeof addSealStatusButtons === "function") addSealStatusButtons();
            if ($("#pageToggleButton").length === 0 && typeof createToggleButton === "function") createToggleButton();
            $("#pageToggleButton").show();

            if ($("#pageToggleButton").text() === "Next Page") {
                $("#sealStatusDiv").show();
                if ($("#page2Content").length > 0) $("#page2Content").hide();
            } else {
                $("#sealStatusDiv").hide();
                if ($("#page2Content").length === 0 && typeof createPage2 === "function") createPage2();
                $("#page2Content").show();
            }
        } else if (!ymsConfig.display.showSealButtons) {
            $("#sealStatusDiv, #page2Content, #pageToggleButton").hide();
        } else {
            $("#sealStatusDiv, #page2Content, #pageToggleButton").hide();
        }

        addLicensePlateCopyButtons();
        refreshRouteHighlights(false);
    }

    function toggleChanges() {
        const topbarData = document.getElementById("topbarData");
        const searchResults = document.querySelector(".ship-clerk-search-results");
        const tcpWidget = document.querySelector(".tcp-widget");
        const scrollTable = document.querySelector(".scrolltable");
        const topSection = document.getElementById("top-section");

        if (!topbarData || !searchResults || !tcpWidget || !scrollTable || !topSection) return;

        if (topbarData.style.visibility === "hidden") {
            topbarData.style.visibility = "visible";
            topbarData.style.opacity = "1";
            topbarData.style.zIndex = "1";
            toggleButton.innerHTML = "Collapse";
        } else {
            topbarData.style.visibility = "hidden";
            topbarData.style.opacity = "0";
            topbarData.style.zIndex = "-999";
            toggleButton.innerHTML = "Grow";
        }

        if (searchResults.style.marginTop === "-179px") {
            searchResults.style.marginTop = "0";
            searchResults.style.zIndex = "auto";
        } else {
            searchResults.style.marginTop = "-179px";
            searchResults.style.zIndex = "999";
        }

        tcpWidget.style.visibility = tcpWidget.style.visibility === "collapse" ? "visible" : "collapse";
        scrollTable.style.height = scrollTable.style.height === "150%" ? "100%" : "150%";

        if (isTopSectionVisible) {
            topSection.style.display = "none";
            isTopSectionVisible = false;
        } else {
            topSection.style.display = "-webkit-flex";
            isTopSectionVisible = true;
        }
    }

    function addToggleButton() {
        const clearButtonGroup = document.getElementById("clearButtonGroup");
        if (!clearButtonGroup || document.getElementById("yms-collapse-toggle")) return;

        clearButtonGroup.style.display = "flex";
        clearButtonGroup.style.justifyContent = "center";
        clearButtonGroup.style.alignItems = "center";

        toggleButton = document.createElement("button");
        toggleButton.id = "yms-collapse-toggle";
        toggleButton.innerHTML = "Collapse";
        toggleButton.style.cursor = "pointer";
        toggleButton.addEventListener("click", toggleChanges);
        clearButtonGroup.appendChild(toggleButton);

        if (!ymsConfig.display.showCollapseButton) {
            toggleButton.style.display = "none";
        }
    }

    function isYardView() {
        return window.location.href.indexOf("shipclerk/#/yard") > -1
            || (window.location.pathname.indexOf("shipclerk") > -1 && window.location.hash === "#/yard");
    }

    let initialized = false;
    let bootStarted = false;

    function init() {
        if (initialized) return;

        const mainContainer = document.getElementById("mainContainer");
        if (!mainContainer) return;

        initialized = true;

        mainContainer.insertAdjacentHTML("beforebegin", `
            <div id="custom-options-container">
                <h3 id="dark-mode-label" style="margin:0;"><t>Dark Mode:</t></h3>
                <div id="dark-mode-switch">
                    <input id="dark-mode-toggle" type="checkbox">
                    <label for="dark-mode-toggle"></label>
                </div>
                <h3 id="filterTrailer-label" style="margin:0;"><t>Tagged Trailers:</t></h3>
                <div>
                    <input id="filterTrailer-toggle" type="checkbox">
                    <label for="filterTrailer-toggle"></label>
                </div>
                <button type="button" id="open-yms-settings">⚙️ Settings</button>
            </div>
        `);

        buildSettingsModal();

        const darkToggle = document.getElementById("dark-mode-toggle");
        darkToggle.checked = ymsConfig.darkMode;
        darkToggle.addEventListener("change", function () {
            ymsConfig.darkMode = this.checked;
            saveConfig();
            applyThemeCSS(this.checked);
            applyCustomColors();
        });

        const filterToggle = document.getElementById("filterTrailer-toggle");
        filterToggle.checked = ymsConfig.filterTrailer;
        filterToggle.addEventListener("change", function () {
            ymsConfig.filterTrailer = this.checked;
            saveConfig();
            applyFilterTrailer(this.checked);
        });

        if (isYardView()) {
            try {
                document.styleSheets[0].insertRule(".note-present-icon {flex-shrink: 0;}");
            } catch { /* ignore */ }

            mainContainer.insertAdjacentHTML("beforebegin", buildDashboardHTML());
            applyDashboardLayout();
            updateTopBarVisibility();
            applyFilterTrailer(ymsConfig.filterTrailer);

            setInterval(emptyAZNG, 60000);
            setTimeout(emptyAZNG, 500);
        }

        applyDisplaySettings();
        setInterval(checkAndAddButtons, 1500);
        setTimeout(addToggleButton, 5000);
    }

    function boot() {
        if (initialized || bootStarted) return;
        bootStarted = true;

        if (document.getElementById("mainContainer")) {
            init();
            return;
        }
        const observer = new MutationObserver(function () {
            if (document.getElementById("mainContainer")) {
                observer.disconnect();
                init();
            }
        });
        if (document.body) {
            observer.observe(document.body, { childList: true, subtree: true });
        }
        setTimeout(function () {
            observer.disconnect();
            init();
        }, 15000);
    }

    if (document.readyState === "complete") {
        boot();
    } else {
        window.addEventListener("load", boot);
        document.addEventListener("DOMContentLoaded", boot);
    }
})(window, document);
"}

{"title":"yyyyy","content":"// ==UserScript==
// @name         SSP Complete + OTD Unified v2
// @version      5.3
// @description  Unified SSP: departures + OTD/OTD-X, resizable draggable panel, VRID highlight, minimize cards
// @author       @rudnluka WRO5
// @match        https://trans-logistics-eu.amazon.com/ssp/dock/*
// @run-at       document-idle
// @connect      amazon.com
// @require      http://ajax.googleapis.com/ajax/libs/jquery/3.7.1/jquery.min.js
// @require      https://gist.github.com/raw/2625891/waitForKeyElements.js
// @grant        GM_addStyle
// @grant        GM_xmlhttpRequest
// @author       @rudnluka WRO5
// ==/UserScript==

/* global $, waitForKeyElements */
(function () {
    'use strict';

    const CONFIG = {
        timeThresholds: { urgent: 15, warning: 30, upcoming: 60 },
        otdLateOffsetMin: 30,
        colors: {
            scheduled: '#808187', finished: '#03C314', progress: '#CE9105',
            paused: '#FF00E0', cancelled: '#FF0000', twenty: '#FF0000',
            hjb1: '#04DD20', container: '#DD04DC',
            urgentAlert: '#ff5252', warningAlert: '#ffab40', upcomingAlert: '#69f0ae'
        },
        updateInterval: 30000,
        otdRefreshInterval: 120000,
        otdWindowMin: 60,
        otdAccounts: ["TransfersInitialPlacement", "ATSSeaWarehouseTransfersGround", "ATSWarehouseTransfers", "ATSWarehouseTransfersIntermodal"],
        otdxAccounts: ["FleetManagementEquipmentRepositioning", "BobtailMovementAnnotation"],
        selectors: { dataTableRows: "table.dataTable.display tbody tr, table.dataTable.stripe tbody tr" },
        panelMinWidth: 420, panelMaxWidth: 1100, panelMinHeight: 200
    };

    let otdAlerts = [];
    let otdxAlerts = [];
    let otdLate = [];    // OTD trucks that DEPARTED late
    let otdxLate = [];   // OTD-X trucks that DEPARTED late
    let activeTab = 'departures';
    let minimizedVrids = new Set(JSON.parse(sessionStorage.getItem('ssp-minimized') || '[]'));
    function saveMinimized() { sessionStorage.setItem('ssp-minimized', JSON.stringify([...minimizedVrids])); }

    function applyStyles() {
        GM_addStyle(`
            #ssp-unified-panel {
                position: fixed; top: 60px; right: 16px;
                width: 500px; height: 70vh;
                background: #1e2433; color: #e8ecf4;
                border-radius: 10px;
                box-shadow: 0 6px 28px rgba(0,0,0,0.55), 0 0 0 1px #3b4564;
                z-index: 99999;
                font-family: 'Segoe UI', system-ui, sans-serif; font-size: 12px;
                display: flex; flex-direction: column; overflow: hidden;
                min-width: ${CONFIG.panelMinWidth}px; min-height: ${CONFIG.panelMinHeight}px;
            }
            #ssp-unified-panel.collapsed { height: 44px !important; min-height: 44px; overflow: hidden; }
            .ssp-resize-left { position: absolute; top: 0; left: -4px; width: 8px; height: 100%; cursor: ew-resize; z-index: 100001; }
            .ssp-resize-bottom { position: absolute; bottom: -4px; left: 0; width: 100%; height: 8px; cursor: ns-resize; z-index: 100001; }
            .ssp-resize-corner { position: absolute; bottom: -4px; left: -4px; width: 14px; height: 14px; cursor: nesw-resize; z-index: 100002; }

            #ssp-panel-header {
                display: flex; align-items: center; justify-content: space-between;
                padding: 9px 14px; background: #161b27;
                border-bottom: 1px solid #2d3548; cursor: move; user-select: none; flex-shrink: 0;
            }
            .panel-title { font-size: 13px; font-weight: 700; color: #fff; }
            .panel-controls { display: flex; align-items: center; gap: 5px; }
            .panel-btn {
                background: none; border: 1px solid #3b4564; color: #a0aec0;
                padding: 3px 7px; border-radius: 4px; cursor: pointer; font-size: 12px;
                transition: all 0.15s; line-height: 1;
            }
            .panel-btn:hover { border-color: #7c8dff; color: #fff; background: rgba(124,141,255,0.1); }

            #ssp-panel-tabs { display: flex; background: #1a2030; border-bottom: 1px solid #2d3548; flex-shrink: 0; }
            .ssp-tab {
                flex: 1; padding: 8px 10px; text-align: center; cursor: pointer;
                font-size: 11px; font-weight: 600; color: #7a8599;
                border-bottom: 2px solid transparent; transition: all 0.15s;
                display: flex; align-items: center; justify-content: center; gap: 5px;
            }
            .ssp-tab:hover { color: #e8ecf4; background: rgba(124,141,255,0.06); }
            .ssp-tab.active { color: #fff; border-bottom-color: #7c8dff; background: rgba(124,141,255,0.1); }
            .tab-badge { background: #ef4444; color: #fff; font-size: 9px; padding: 1px 5px; border-radius: 8px; font-weight: 700; min-width: 16px; text-align: center; }
            .tab-badge.zero { background: #3b4564; color: #7a8599; }

            #ssp-panel-content { overflow-y: auto; flex: 1; padding: 10px; min-height: 0; }
            #ssp-panel-content::-webkit-scrollbar { width: 5px; }
            #ssp-panel-content::-webkit-scrollbar-track { background: #161b27; }
            #ssp-panel-content::-webkit-scrollbar-thumb { background: #3b4564; border-radius: 4px; }

            .ssp-card {
                background: #262f3f; border-radius: 8px; padding: 10px 12px;
                margin-bottom: 8px; border-left: 4px solid #3b4564;
                transition: all 0.15s; position: relative;
            }
            .ssp-card:hover { background: #2e3a4e; transform: translateX(2px); }
            .ssp-card.urgent { border-left-color: #ef4444; }
            .ssp-card.warning { border-left-color: #f59e0b; }
            .ssp-card.upcoming { border-left-color: #22c55e; }
            .ssp-card.overdue { border-left-color: #ef4444; background: rgba(239,68,68,0.1); }
            .ssp-card.minimized .card-row2 { display: none; }

            .card-row1 { display: flex; justify-content: space-between; align-items: center; margin-bottom: 5px; }
            .card-time { font-weight: 700; font-size: 14px; font-family: 'Cascadia Code','JetBrains Mono',monospace; }
            .card-badges { display: flex; align-items: center; gap: 5px; }
            .card-status { font-size: 9px; padding: 2px 6px; border-radius: 3px; font-weight: 700; text-transform: uppercase; }
            .card-row2 { display: grid; grid-template-columns: 1fr 1fr; gap: 4px 12px; font-size: 11px; color: #b0bbd0; }
            .card-row2 .lbl { color: #6b7a94; font-weight: 600; }

            /* Minimize toggle — white dash top right */
            .card-minimize {
                position: absolute; top: 7px; right: 8px;
                background: none; border: none; cursor: pointer;
                padding: 2px 5px; border-radius: 3px; transition: opacity 0.15s;
                opacity: 0.35; line-height: 1;
            }
            .card-minimize:hover { opacity: 1; }
            .card-minimize::after {
                content: ''; display: block; width: 12px; height: 2px;
                background: #ffffff; border-radius: 1px;
            }
            .ssp-card.minimized .card-minimize::after { width: 8px; height: 8px; background: none; border: 2px solid #fff; border-radius: 2px; }

            .vrid-link { color: #7cb3ff; text-decoration: none; font-weight: 700; cursor: pointer; transition: color 0.15s; }
            .vrid-link:hover { color: #a8d0ff; text-decoration: underline; }
            .vrid-copy { cursor: pointer; margin-left: 4px; font-size: 10px; opacity: 0.6; transition: opacity 0.15s; }
            .vrid-copy:hover { opacity: 1; }

            .source-badge {
                display: inline-flex; align-items: center; gap: 2px;
                font-size: 9px; font-weight: 700; padding: 2px 6px; border-radius: 3px;
            }
            .source-badge.ssp { background: rgba(34,197,94,0.2); color: #4ade80; border: 1px solid rgba(34,197,94,0.4); }
            .source-badge.fleet { background: rgba(168,85,247,0.2); color: #c084fc; border: 1px solid rgba(168,85,247,0.4); }

            .for-late { font-size: 10px; color: #fca5a5; font-weight: 600; margin-left: 6px; font-family: monospace; }

            .otd-table { width: 100%; border-collapse: collapse; font-size: 11px; }
            .otd-table th { color: #7a8599; font-weight: 600; text-align: left; padding: 4px 6px; border-bottom: 1px solid #2d3548; font-size: 10px; text-transform: uppercase; position: sticky; top: 0; background: #1e2433; }
            .otd-table td { padding: 5px 6px; border-bottom: 1px solid #1a2030; }
            .otd-table .overdue-row { background: rgba(239,68,68,0.1); }
            .otd-table .warn-row { background: rgba(245,158,11,0.07); }
            .time-critical { color: #f87171; font-weight: 700; font-family: monospace; }
            .time-warn { color: #fbbf24; font-weight: 700; font-family: monospace; }
            .time-orange { color: #fb923c; font-weight: 700; font-family: monospace; }
            .time-ok { color: #4ade80; font-weight: 700; font-family: monospace; }

            .ssp-section-hdr { font-size: 11px; font-weight: 700; color: #8b9ab5; text-transform: uppercase; margin: 12px 0 6px; padding-bottom: 4px; border-bottom: 1px solid #2d3548; display: flex; align-items: center; gap: 6px; }
            .ssp-section-hdr .cnt { color: #7c8dff; }
            .ssp-empty { text-align: center; padding: 20px; color: #5a6a82; font-style: italic; }
            #ssp-panel-footer { padding: 6px 14px; background: #161b27; border-top: 1px solid #2d3548; font-size: 10px; color: #5a6a82; display: flex; justify-content: space-between; flex-shrink: 0; }

            @keyframes urgPulse { 0%,100%{opacity:1} 50%{opacity:0.55} }
            .urgent-pulse { animation: urgPulse 1.5s infinite; }
            @keyframes blinkAnim { 0%,100%{opacity:1} 50%{opacity:0.3} }
            .blink { animation: blinkAnim 1s infinite; }
            .ssp-highlight-vrid { outline: 3px solid #fbbf24 !important; background: rgba(251,191,36,0.15) !important; }
        `);
    }

    function fill(v) { return v.toString().padStart(2, '0'); }

    function getWarehouseID() {
        const params = new URLSearchParams(window.location.search);
        const site = params.get('nodeId') || params.get('warehouseId') || '';
        if (site) return site.toUpperCase();
        const el = document.querySelector('[data-warehouse-id], [data-node-id], .node-id');
        if (el) return (el.getAttribute('data-warehouse-id') || el.getAttribute('data-node-id') || el.textContent).trim().toUpperCase();
        return 'WRO5';
    }

    function getDateRange() {
        // For Fleet departures: yesterday 17:00 to today 23:59
        const start = new Date(); start.setDate(start.getDate() - 1); start.setHours(17, 0, 0, 0);
        const end = new Date(); end.setHours(23, 59, 59, 999);
        return { start, end };
    }

    function getDateRangeForLate() {
        // For OTD/OTD-X Late tabs: today 00:00 to 23:59, apiStart = yesterday (like the OTD script)
        const start = new Date(); start.setHours(0, 0, 0, 0);
        const end = new Date(); end.setHours(23, 59, 59, 999);
        const apiStart = new Date(start); apiStart.setDate(apiStart.getDate() - 1);
        return { start, end, apiStart };
    }

    function buildFmcBody(warehouseId, dateRange, shipperAccounts) {
        const s = dateRange.apiStart || dateRange.start, e = dateRange.end;
        return JSON.stringify({
            stopLocationType: "facility", dateRangeType: "PLANNED_YARD", stopStatuses: [],
            onlyDelayed: false, delayTypes: "LATE_ARRIVAL_OR_DEPARTURE", delayReason: "ALL",
            disruptionTypes: [], executionStatuses: ["PLANNED", "IN_TRANSIT", "COMPLETED"],
            planStatuses: [], shipperAccounts: shipperAccounts,
            stopActionType: "PICKUP", carriers: null, searchByIds: false, assetOwner: "",
            stopFacilities: [], stopFacilityCodes: [warehouseId], facilityLanes: [],
            useRelativeTime: false, driverState: "ANY", driverId: "",
            tenderStatuses: [], subcarrier: "", assetStatus: "ANY", assetId: "",
            searchTimeZone: "Europe/Berlin", page: 0, pageSize: 1000,
            fromDate: fill(s.getMonth() + 1) + '/' + fill(s.getDate()) + '/' + s.getFullYear(),
            fromTime: fill(s.getHours()) + ':' + fill(s.getMinutes()),
            toDate: fill(e.getMonth() + 1) + '/' + fill(e.getDate()) + '/' + e.getFullYear(),
            toTime: fill(e.getHours()) + ':' + fill(e.getMinutes()),
            bookmarkedSavedSearch: false, executionViewModePreference: "vrs"
        });
    }

    function parseOtdTrucks(responseText, dateRange) {
        const data = JSON.parse(responseText);
        const records = data.returnedObject ? data.returnedObject.records : [];
        const now = Date.now();
        const windowMs = CONFIG.otdWindowMin * 60 * 1000;
        const offsetMs = CONFIG.otdLateOffsetMin * 60 * 1000;
        const alerts = [];

        records.forEach(truck => {
            const stop = truck.aggregatedStops && truck.aggregatedStops[0];
            if (!stop || !stop.actions || !stop.actions[0]) return;
            if (stop.status === 'DEPARTED') return;
            // Accept ARRIVED and PLANNED (not DEPARTED)
            if (stop.status !== 'ARRIVED' && stop.status !== 'PLANNED') return;

            const action = stop.actions[0];
            const plannedDep = action.plannedYardDepartureTime;
            if (!plannedDep) return;
            if (plannedDep < dateRange.start.getTime() || plannedDep > dateRange.end.getTime()) return;

            const vrid = truck.vehicleRunId || '';
            if (!vrid || vrid === '-') return;

            const forLateTime = plannedDep + offsetMs;
            const timeToLate = forLateTime - now;

            // ARRIVED: show if within 60min of becoming late OR already late
            // PLANNED: show if already late (overdue)
            if (stop.status === 'ARRIVED' && timeToLate > windowMs) return;
            if (stop.status === 'PLANNED' && timeToLate > 0) return;

            alerts.push({
                vrid, route: truck.facilityLaneString || '-',
                planned: plannedDep, forLateTime, timeToLate,
                overdue: timeToLate < 0, status: stop.status
            });
        });
        alerts.sort((a, b) => a.timeToLate - b.timeToLate);
        return alerts;
    }

    // Parse delayed trucks (same logic as OTD - Delayed Trucks in FMC script)
    function parseDelayedTrucks(responseText, dateRange) {
        const data = JSON.parse(responseText);
        const records = data.returnedObject ? data.returnedObject.records : [];
        const now = Date.now();
        const rangeStart = dateRange.start.getTime();
        const rangeEnd = dateRange.end.getTime();
        const delayed = [];
        records.forEach(truck => {
            const stop = truck.aggregatedStops && truck.aggregatedStops[0];
            if (!stop || !stop.actions || !stop.actions[0]) return;
            const action = stop.actions[0];
            if (action.plannedYardDepartureTime < rangeStart || action.plannedYardDepartureTime > rangeEnd) return;
            let delta = NaN;
            if (stop.status === 'DEPARTED') delta = action.actualYardDepartureTime - action.plannedYardDepartureTime;
            else if (stop.status === 'ARRIVED') delta = now - action.plannedYardDepartureTime;
            else if (stop.status === 'PLANNED' && action.plannedYardDepartureTime < now) delta = now - action.plannedYardDepartureTime;
            if (isNaN(delta) || delta < 60000) return;
            const vrid = truck.vehicleRunId || '';
            if (!vrid || vrid === '-') return;
            delayed.push({
                vrid, route: truck.facilityLaneString || '-',
                status: stop.status, planned: action.plannedYardDepartureTime,
                delay: delta, delayMin: Math.round(delta / 60000),
                comment: (action.departureDelayReasonDetail || '').trim()
            });
        });
        delayed.sort((a, b) => b.delay - a.delay);
        return delayed;
    }

    function fetchOtdData() {
        const wh = getWarehouseID();
        const fleetRange = getDateRange(); // yesterday 17:00 to today 23:59 (for departures)
        const lateRange = getDateRangeForLate(); // today 00:00 to 23:59 (for OTD/Fleet Late tabs)

        // Fetch for departures (fleet trucks on site)
        GM_xmlhttpRequest({
            url: 'https://trans-logistics-eu.amazon.com/fmc/search/execution/by-criteria',
            method: 'POST', headers: { 'Content-Type': 'application/json' },
            data: buildFmcBody(wh, fleetRange, CONFIG.otdAccounts),
            onload: r => { otdAlerts = r.status === 200 ? parseOtdTrucks(r.responseText, fleetRange) : []; renderPanel(); }
        });
        GM_xmlhttpRequest({
            url: 'https://trans-logistics-eu.amazon.com/fmc/search/execution/by-criteria',
            method: 'POST', headers: { 'Content-Type': 'application/json' },
            data: buildFmcBody(wh, fleetRange, CONFIG.otdxAccounts),
            onload: r => { otdxAlerts = r.status === 200 ? parseOtdTrucks(r.responseText, fleetRange) : []; renderPanel(); }
        });

        // Fetch for Late tabs (today's delayed trucks)
        GM_xmlhttpRequest({
            url: 'https://trans-logistics-eu.amazon.com/fmc/search/execution/by-criteria',
            method: 'POST', headers: { 'Content-Type': 'application/json' },
            data: buildFmcBody(wh, lateRange, CONFIG.otdAccounts),
            onload: r => { otdLate = r.status === 200 ? parseDelayedTrucks(r.responseText, lateRange) : []; renderPanel(); }
        });
        GM_xmlhttpRequest({
            url: 'https://trans-logistics-eu.amazon.com/fmc/search/execution/by-criteria',
            method: 'POST', headers: { 'Content-Type': 'application/json' },
            data: buildFmcBody(wh, lateRange, CONFIG.otdxAccounts),
            onload: r => { otdxLate = r.status === 200 ? parseDelayedTrucks(r.responseText, lateRange) : []; renderPanel(); }
        });
    }

    function getSourceLabel(vrid) {
        if (!vrid) return null;
        if (otdAlerts.find(a => a.vrid === vrid)) return 'ssp';
        if (otdxAlerts.find(a => a.vrid === vrid)) return 'fleet';
        return null;
    }

    function highlightVridOnPage(vrid) {
        document.querySelectorAll('.ssp-highlight-vrid').forEach(el => el.classList.remove('ssp-highlight-vrid'));
        let found = false;
        $('table tbody tr').each(function () {
            if ($(this).text().includes(vrid)) {
                $(this).addClass('ssp-highlight-vrid');
                if (!found) { this.scrollIntoView({ behavior: 'smooth', block: 'center' }); found = true; }
            }
        });
        if (!found) { try { window.find(vrid); } catch (e) { } }
        setTimeout(() => { document.querySelectorAll('.ssp-highlight-vrid').forEach(el => el.classList.remove('ssp-highlight-vrid')); }, 8000);
    }

    function createPanel() {
        const panel = document.createElement('div');
        panel.id = 'ssp-unified-panel';
        panel.innerHTML = `
            <div class="ssp-resize-left"></div>
            <div class="ssp-resize-bottom"></div>
            <div class="ssp-resize-corner"></div>
            <div id="ssp-panel-header">
                <div class="panel-title">⚡ SSP Command Center</div>
                <div class="panel-controls">
                    <button class="panel-btn" id="ssp-size-btn" title="Toggle size">◀▶</button>
                    <button class="panel-btn" id="ssp-refresh-btn" title="Refresh (Ctrl+R)">🔄</button>
                    <button class="panel-btn" id="ssp-collapse-btn" title="Collapse (Ctrl+T)">▲</button>
                </div>
            </div>
            <div id="ssp-panel-tabs">
                <div class="ssp-tab active" data-tab="departures">
                    ⏰ Departures <span class="tab-badge zero" id="badge-departures">0</span>
                </div>
                <div class="ssp-tab" data-tab="otd">
                    🟠 OTD Late <span class="tab-badge zero" id="badge-otd">0</span>
                </div>
                <div class="ssp-tab" data-tab="otdx">
                    🟣 Fleet Late <span class="tab-badge zero" id="badge-otdx">0</span>
                </div>
            </div>
            <div id="ssp-panel-content"></div>
            <div id="ssp-panel-footer">
                <span id="ssp-footer-status">Loading...</span>
                <span id="ssp-footer-time"></span>
            </div>
        `;
        document.body.appendChild(panel);

        document.getElementById('ssp-collapse-btn').addEventListener('click', toggleCollapse);
        document.getElementById('ssp-refresh-btn').addEventListener('click', refreshAll);
        document.getElementById('ssp-size-btn').addEventListener('click', toggleSize);

        panel.querySelectorAll('.ssp-tab').forEach(tab => {
            tab.addEventListener('click', () => {
                panel.querySelectorAll('.ssp-tab').forEach(t => t.classList.remove('active'));
                tab.classList.add('active');
                activeTab = tab.dataset.tab;
                renderPanel();
            });
        });

        makeDraggable(panel);
        setupResize(panel);

        document.getElementById('ssp-panel-header').addEventListener('dblclick', () => {
            panel.style.top = '60px'; panel.style.right = '16px'; panel.style.left = 'auto';
            panel.style.width = '500px'; panel.style.height = '70vh';
        });

        // Delegated events
        panel.addEventListener('click', e => {
            const link = e.target.closest('.vrid-link');
            if (link) { e.preventDefault(); if (link.dataset.vrid) highlightVridOnPage(link.dataset.vrid); }

            const cp = e.target.closest('.vrid-copy');
            if (cp) { e.stopPropagation(); navigator.clipboard.writeText(cp.dataset.vrid).then(() => { cp.textContent = '✓'; setTimeout(() => { cp.textContent = '📋'; }, 1200); }); }

            const minBtn = e.target.closest('.card-minimize');
            if (minBtn) {
                e.stopPropagation();
                const vrid = minBtn.dataset.vrid;
                if (minimizedVrids.has(vrid)) minimizedVrids.delete(vrid);
                else minimizedVrids.add(vrid);
                saveMinimized();
                renderPanel();
            }
        });
    }

    function makeDraggable(panel) {
        const header = panel.querySelector('#ssp-panel-header');
        let startX, startY;
        header.onmousedown = e => {
            if (e.target.closest('.panel-btn')) return;
            e.preventDefault(); startX = e.clientX; startY = e.clientY;
            document.onmousemove = e2 => {
                panel.style.top = `${panel.offsetTop - (startY - e2.clientY)}px`;
                panel.style.left = `${panel.offsetLeft - (startX - e2.clientX)}px`;
                panel.style.right = 'auto';
                startX = e2.clientX; startY = e2.clientY;
            };
            document.onmouseup = () => { document.onmousemove = null; document.onmouseup = null; };
        };
    }

    function setupResize(panel) {
        function start(e, mode) {
            e.preventDefault(); e.stopPropagation();
            const sx = e.clientX, sy = e.clientY, sw = panel.offsetWidth, sh = panel.offsetHeight, sl = panel.offsetLeft;
            document.onmousemove = e2 => {
                if (mode === 'left' || mode === 'corner') {
                    const nw = Math.min(CONFIG.panelMaxWidth, Math.max(CONFIG.panelMinWidth, sw + (sx - e2.clientX)));
                    panel.style.width = nw + 'px'; panel.style.left = (sl - (nw - sw)) + 'px'; panel.style.right = 'auto';
                }
                if (mode === 'bottom' || mode === 'corner') { panel.style.height = Math.max(CONFIG.panelMinHeight, sh + (e2.clientY - sy)) + 'px'; }
            };
            document.onmouseup = () => { document.onmousemove = null; document.onmouseup = null; };
        }
        panel.querySelector('.ssp-resize-left').addEventListener('mousedown', e => start(e, 'left'));
        panel.querySelector('.ssp-resize-bottom').addEventListener('mousedown', e => start(e, 'bottom'));
        panel.querySelector('.ssp-resize-corner').addEventListener('mousedown', e => start(e, 'corner'));
    }

    function toggleCollapse() {
        const p = document.getElementById('ssp-unified-panel'), b = document.getElementById('ssp-collapse-btn');
        p.classList.toggle('collapsed'); b.textContent = p.classList.contains('collapsed') ? '▼' : '▲';
    }

    let sizeToggled = false;
    function toggleSize() { sizeToggled = !sizeToggled; document.getElementById('ssp-unified-panel').style.width = sizeToggled ? '750px' : '500px'; }

    function renderPanel() {
        const content = document.getElementById('ssp-panel-content');
        if (!content) return;

        const depCount = countDepartures();
        updateBadge('badge-departures', depCount);
        updateBadge('badge-otd', otdLate.length);
        updateBadge('badge-otdx', otdxLate.length);

        switch (activeTab) {
            case 'departures': renderDeparturesTab(content); break;
            case 'otd': renderLateTab(content, otdLate, 'OTD Late'); break;
            case 'otdx': renderLateTab(content, otdxLate, 'OTD-X Late'); break;
        }

        const now = new Date();
        const ft = document.getElementById('ssp-footer-time');
        if (ft) ft.textContent = `${fill(now.getHours())}:${fill(now.getMinutes())}:${fill(now.getSeconds())}`;
        const fs = document.getElementById('ssp-footer-status');
        if (fs) fs.textContent = `Late: OTD ${otdLate.length} | Fleet ${otdxLate.length} | Dep: ${depCount}`;

        // Page title: show urgent count (departures within <15min or overdue)
        const urgentCount = countUrgent();
        if (urgentCount > 0) document.title = `🚨(${urgentCount} urgent) SSP Dock`;
        else document.title = 'SSP Dock';
    }

    function countUrgent() {
        let count = 0;
        const now = new Date();
        const nowMs = now.getTime();
        const offsetMs = CONFIG.otdLateOffsetMin * 60000;
        // SSP table urgents: SDT within 15min OR past SDT but before LATE
        $('tr').each(function () {
            if ($(this).find('td').length < 7) return;
            const m = $(this).text().match(/\d{2}:\d{2}/);
            if (!m) return;
            const [h, min] = m[0].split(':').map(Number);
            const sdt = new Date(); sdt.setHours(h, min, 0, 0);
            const lateTime = sdt.getTime() + offsetMs;
            if (nowMs > lateTime) return; // already past late
            const timeDiff = (sdt - now) / 60000;
            if (timeDiff <= CONFIG.timeThresholds.urgent) count++;
        });
        // OTD/OTD-X trucks that are overdue or within urgent window
        [...otdAlerts, ...otdxAlerts].forEach(t => {
            if (t.overdue || t.timeToLate / 60000 <= CONFIG.timeThresholds.urgent) count++;
        });
        return count;
    }

    function updateBadge(id, count) { const b = document.getElementById(id); if (!b) return; b.textContent = count; b.classList.toggle('zero', count === 0); }

    function countDepartures() {
        let count = 0; const now = new Date(); const nowMs = now.getTime();
        const offsetMs = CONFIG.otdLateOffsetMin * 60000;
        $('tr').each(function () {
            if ($(this).find('td').length < 7) return;
            const m = $(this).text().match(/\d{2}:\d{2}/);
            if (!m) return;
            const [h, min] = m[0].split(':').map(Number);
            const sdt = new Date(); sdt.setHours(h, min, 0, 0);
            const lateTime = sdt.getTime() + offsetMs;
            if (nowMs > lateTime) return;
            const timeDiff = (sdt - now) / 60000;
            if (timeDiff <= CONFIG.timeThresholds.upcoming) count++;
        });
        return count;
    }

    function renderDeparturesTab(container) {
        const now = new Date();
        const sections = { urgent: [], warning: [], upcoming: [] };

        // 1. SSP table rows (these are "SSP" source)
        $('tr').each(function () {
            try {
                const row = $(this);
                const cells = row.find('td');
                // Skip rows that don't have enough columns (headers, empty rows)
                if (cells.length < 7) return;

                const m = row.text().match(/\d{2}:\d{2}/);
                if (!m) return;
                const [hours, minutes] = m[0].split(':').map(Number);
                const depTime = new Date(); depTime.setHours(hours, minutes, 0, 0);
                const lateTime = new Date(depTime.getTime() + CONFIG.otdLateOffsetMin * 60000);
                // Skip if already past LATE time (SDT + 30min)
                if (now > lateTime) return;
                // timeDiff: minutes until SDT (can be negative if past SDT)
                const timeDiff = (depTime - now) / 60000;
                // Skip if more than 60min away
                if (timeDiff > CONFIG.timeThresholds.upcoming) return;

                const vrId = cells.eq(6).text().trim();
                const status = cells.eq(3).text().trim();
                // Skip if no meaningful status
                if (!status) return;

                const data = {
                    timeText: m[0], timeDiff: Math.round(timeDiff),
                    status: status,
                    carrier: cells.eq(8).text().trim(),
                    trailer: cells.eq(9).text().trim(),
                    location: cells.eq(5).text().trim(),
                    vrId: vrId || '-', source: 'ssp'
                };

                if (timeDiff <= CONFIG.timeThresholds.urgent) sections.urgent.push(data);
                else if (timeDiff <= CONFIG.timeThresholds.warning) sections.warning.push(data);
                else sections.upcoming.push(data);
            } catch (e) { /* skip */ }
        });

        // 2. OTD + OTD-X trucks (ARRIVED) — merge into departures
        const sspVrids = new Set();
        [...sections.urgent, ...sections.warning, ...sections.upcoming].forEach(d => { if (d.vrId) sspVrids.add(d.vrId); });

        const allOtdArrived = [
            ...otdAlerts.filter(t => t.status === 'ARRIVED').map(t => ({ ...t, src: 'ssp' })),
            ...otdxAlerts.filter(t => t.status === 'ARRIVED').map(t => ({ ...t, src: 'fleet' }))
        ];

        allOtdArrived.forEach(truck => {
            if (sspVrids.has(truck.vrid)) return;
            const forLateMin = Math.round(truck.timeToLate / 60000);
            const depTimeObj = new Date(truck.planned);
            const data = {
                timeText: `${fill(depTimeObj.getHours())}:${fill(depTimeObj.getMinutes())}`,
                timeDiff: forLateMin, status: truck.status || 'ARRIVED',
                carrier: '-', trailer: '-', location: '-',
                route: truck.route, vrId: truck.vrid,
                source: truck.src, forLateTime: truck.forLateTime, overdue: truck.overdue
            };
            if (truck.overdue || forLateMin <= CONFIG.timeThresholds.urgent) sections.urgent.push(data);
            else if (forLateMin <= CONFIG.timeThresholds.warning) sections.warning.push(data);
            else sections.upcoming.push(data);
        });

        Object.keys(sections).forEach(k => sections[k].sort((a, b) => a.timeDiff - b.timeDiff));

        let html = '';
        if (sections.urgent.length > 0) {
            html += `<div class="ssp-section-hdr" style="color:${CONFIG.colors.urgentAlert}">🔴 Urgent (&lt;${CONFIG.timeThresholds.urgent}min) <span class="cnt">${sections.urgent.length}</span></div>`;
            sections.urgent.forEach(d => { html += buildCard(d, 'urgent'); });
        }
        if (sections.warning.length > 0) {
            html += `<div class="ssp-section-hdr" style="color:${CONFIG.colors.warningAlert}">🟠 Warning (&lt;${CONFIG.timeThresholds.warning}min) <span class="cnt">${sections.warning.length}</span></div>`;
            sections.warning.forEach(d => { html += buildCard(d, 'warning'); });
        }
        if (sections.upcoming.length > 0) {
            html += `<div class="ssp-section-hdr" style="color:${CONFIG.colors.upcomingAlert}">🟢 Upcoming (&lt;${CONFIG.timeThresholds.upcoming}min) <span class="cnt">${sections.upcoming.length}</span></div>`;
            sections.upcoming.forEach(d => { html += buildCard(d, 'upcoming'); });
        }
        if (!html) html = '<div class="ssp-empty">✓ No upcoming departures</div>';
        container.innerHTML = html;
    }

    function buildCard(data, category) {
        const color = category === 'urgent' ? CONFIG.colors.urgentAlert : category === 'warning' ? CONFIG.colors.warningAlert : CONFIG.colors.upcomingAlert;
        const statusKey = data.status.toLowerCase().replace(/\s/g, '');
        const statusColor = CONFIG.colors[statusKey] || '#8b9ab5';

        // Source badge: SSP (green) or Fleet (purple)
        let sourceBadge = '';
        if (data.source === 'ssp') {
            // Check if it's also on OTD list
            const otdMatch = getSourceLabel(data.vrId);
            if (otdMatch === 'ssp') sourceBadge = '<span class="source-badge ssp">SSP</span>';
            else if (otdMatch === 'fleet') sourceBadge = '<span class="source-badge fleet">Fleet</span>';
            else sourceBadge = '<span class="source-badge ssp">SSP</span>';
        } else if (data.source === 'fleet') {
            sourceBadge = '<span class="source-badge fleet">Fleet</span>';
        }

        // === TIME DISPLAY LOGIC ===
        // SDT = scheduled departure time (from table or FMC planned)
        // LATE = SDT + 30min
        // Phase 1: before SDT → show countdown to SDT
        // Phase 2: after SDT, before LATE → "SDT!" + countdown to late
        // Phase 3: after LATE → "LATE" + time since late (negative)

        const now = Date.now();
        const offsetMs = CONFIG.otdLateOffsetMin * 60 * 1000; // 30min

        // Parse SDT from timeText (HH:MM)
        const [hh, mm] = data.timeText.split(':').map(Number);
        const sdtDate = new Date(); sdtDate.setHours(hh, mm, 0, 0);
        const sdtMs = sdtDate.getTime();
        const lateMs = sdtMs + offsetMs;

        let timeDisplay = '';
        let phaseHtml = '';

        if (now < sdtMs) {
            // Phase 1: before SDT
            const minToSdt = Math.round((sdtMs - now) / 60000);
            timeDisplay = `${data.timeText} <small style="opacity:0.7;font-size:11px">(${minToSdt}min)</small>`;
        } else if (now >= sdtMs && now < lateMs) {
            // Phase 2: SDT passed, counting down to LATE
            const minToLate = Math.round((lateMs - now) / 60000);
            timeDisplay = `${data.timeText} <small style="color:#fbbf24;font-size:11px">(SDT!)</small>`;
            phaseHtml = `<span class="for-late" style="color:#fbbf24">⏳ ${minToLate}min to late</span>`;
        } else {
            // Phase 3: LATE
            const minSinceLate = Math.round((now - lateMs) / 60000);
            timeDisplay = `${data.timeText} <small style="color:#f87171;font-size:11px">(LATE!)</small>`;
            phaseHtml = `<span class="for-late blink" style="color:#f87171">(-${minSinceLate}min)</span>`;
        }

        const isMin = minimizedVrids.has(data.vrId);
        const minClass = isMin ? ' minimized' : '';
        const pulseClass = (category === 'urgent' || data.overdue) ? ' urgent-pulse' : '';

        // Minimize button — white line
        const minBtn = `<button class="card-minimize" data-vrid="${data.vrId}" title="${isMin ? 'Expand' : 'Minimize'}"></button>`;

        const carrierLine = data.source === 'fleet' && data.route
            ? `<span><span class="lbl">Route:</span> ${data.route}</span>`
            : `<span><span class="lbl">Carrier:</span> ${data.carrier || '-'}</span>`;

        return `
            <div class="ssp-card ${category}${data.overdue ? ' overdue' : ''}${pulseClass}${minClass}">
                ${minBtn}
                <div class="card-row1">
                    <span class="card-time" style="color:${color}">
                        ${timeDisplay}
                        ${phaseHtml}
                    </span>
                    <div class="card-badges">
                        ${sourceBadge}
                        <span class="card-status" style="background:${statusColor}22;color:${statusColor};border:1px solid ${statusColor}44">${data.status}</span>
                    </div>
                </div>
                <div class="card-row2">
                    <span>
                        <span class="lbl">VRID:</span>
                        <a class="vrid-link" data-vrid="${data.vrId}" title="Find on page">${data.vrId}</a>
                        <span class="vrid-copy" data-vrid="${data.vrId}" title="Copy">📋</span>
                    </span>
                    <span><span class="lbl">Trailer:</span> ${data.trailer || '-'}</span>
                    ${carrierLine}
                    <span><span class="lbl">Loc:</span> ${data.location || '-'}</span>
                </div>
            </div>
        `;
    }

    function renderLateTab(container, lateTrucks, label) {
        if (lateTrucks.length === 0) { container.innerHTML = `<div class="ssp-empty">✓ No ${label} — all on time</div>`; return; }
        let html = `<table class="otd-table"><thead><tr><th>VRID</th><th>Route</th><th>Planned</th><th>Delay</th><th>Status</th></tr></thead><tbody>`;
        lateTrucks.forEach(t => {
            const d = new Date(t.planned);
            const plannedStr = `${fill(d.getHours())}:${fill(d.getMinutes())}`;
            const h = Math.floor(t.delay / 3600000), m = Math.floor((t.delay % 3600000) / 60000);
            const delayStr = h > 0 ? `${h}h ${fill(m)}m` : `${m}m`;
            const delayCls = t.delay >= 7200000 ? 'time-critical' : t.delay >= 3600000 ? 'time-orange' : 'time-warn';
            const statusCls = t.status === 'DEPARTED' ? '#4ade80' : t.status === 'ARRIVED' ? '#fbbf24' : '#94a3b8';
            html += `<tr>
                <td><a class="vrid-link" data-vrid="${t.vrid}" title="Find on page"><strong>${t.vrid}</strong></a><span class="vrid-copy" data-vrid="${t.vrid}">📋</span></td>
                <td>${t.route}</td>
                <td>${plannedStr}</td>
                <td class="${delayCls}">+${delayStr}</td>
                <td style="color:${statusCls};font-size:10px;font-weight:600">${t.status}</td>
            </tr>`;
        });
        html += '</tbody></table>';
        container.innerHTML = html;
    }

    function colorTableRow(jNode) {
        const text = jNode.text(), c = CONFIG.colors;
        if (text.includes("Scheduled")) jNode.css("color", c.scheduled);
        else if (text.includes("Finished")) jNode.css("color", c.finished);
        else if (text.includes("Progress")) jNode.css("color", c.progress);
        else if (text.includes("Paused")) jNode.css("color", c.paused);
        else if (text.includes("Cancelled")) jNode.css("color", c.cancelled);
        jNode.find('td:contains("twenty")').css("color", c.twenty);
        jNode.find('td:contains("HJB1")').css("color", c.hjb1);
        jNode.find('td:contains("container")').css("color", c.container);
    }

    function refreshAll() { renderPanel(); fetchOtdData(); }

    function setupShortcuts() {
        document.addEventListener('keydown', e => {
            if (e.ctrlKey && e.key === 'r') { e.preventDefault(); refreshAll(); }
            else if (e.ctrlKey && e.key === 't') { e.preventDefault(); toggleCollapse(); }
        });
    }

    function init() {
        applyStyles();
        createPanel();
        setupShortcuts();
        renderPanel();
        fetchOtdData();
        setInterval(renderPanel, CONFIG.updateInterval);
        setInterval(fetchOtdData, CONFIG.otdRefreshInterval);
        waitForKeyElements(CONFIG.selectors.dataTableRows, colorTableRow);
    }

    if (document.readyState === 'complete') setTimeout(init, 1500);
    else window.addEventListener('load', () => setTimeout(init, 1500));
})();
"}

{"title":"fast theme","content":"/* Tymczasowe blokowanie animacji przy zmianie motywu */
:root.theme-switching,
:root.theme-switching *,
:root.theme-switching *::before,
:root.theme-switching *::after {
    transition: 0s !important;
    transition-duration: 0s !important;
    transition-delay: 0s !important;
}


-- js --

// Obsługa przełącznika motywów z blokadą animacji
  const themeToggleBtn = document.getElementById("theme-toggle");
  if (themeToggleBtn) {
    themeToggleBtn.addEventListener("click", () => {
      // 1. Dodaj klasę blokującą tranzycje
      document.documentElement.classList.add("theme-switching");

      const currentTheme = document.documentElement.getAttribute("data-theme");

      if (currentTheme === "dark") {
        document.documentElement.removeAttribute("data-theme");
        themeToggleBtn.innerHTML = "Ciemny motyw";
      } else {
        document.documentElement.setAttribute("data-theme", "dark");
        themeToggleBtn.innerHTML = "Jasny motyw";
      }

      // 2. Wymuś reflow (przeliczenie stylów), aby przeglądarka od razu zaaplikowała brak tranzycji
      window.getComputedStyle(document.documentElement).cssText;

      // 3. Zdejmij klasę po minimalnym opóźnieniu
      setTimeout(() => {
        document.documentElement.classList.remove("theme-switching");
      }, 50); 
    });
  }"}

