{"title":"nnn","content":"// ==UserScript==
// @name         Formatuj rejestracje poziomo (zamiana <br> na spację)
// @namespace    http://tampermonkey.net/
// @version      1.0
// @description  Zamienia pionowe znaczniki <br> w tablicach rejestracyjnych AngularJS na poziomą spację (np. "NO354AC PL")
// @author       Assistant
// @match        *://*/*
// @grant        none
// ==/UserScript==

(function () {
  'use strict';

  // Opcje konfiguracyjne - możesz dowolnie modyfikować kolory i separator
  const CONFIG = {
    separator: ' - ',              // Znak rozdzielający zamiast łamania wiersza
    separatorColor: '#2563eb',      // Wyrazisty kolor myślnika (np. niebieski)
    countryColor: '#1d4ed8',        // Kolor tekstu kraju (PL)
    countryBg: '#dbeafe',           // Tło plakietki kraju (styl rejestracji UE)
    enableBadge: true               // Czy kod kraju ma posiadać estetyczne tło
  };

  /**
   * Wstrzykuje regułę CSS, która natychmiastowo układa elementy w poziomie,
   * eliminując jakiekolwiek mignięcia przed wykonaniem operacji na drzewie DOM.
   */
  const injectHorizontalStyle = () => {
    try {
      const styleId = 'license-plate-horizontal-style';
      if (document.getElementById(styleId)) return;

      const style = document.createElement('style');
      style.id = styleId;
      style.textContent = `
        /* Zamiana pionowego układu na poziomy i ukrycie natywnego łamania wiersza */
        span[ng-if*="licensePlateIdentifier"],
        span.ng-binding {
          display: inline-flex !important;
          align-items: center !important;
          white-space: nowrap !important;
        }
        span[ng-if*="licensePlateIdentifier"] br,
        .ng-binding br {
          display: none !important;
        }
      `;
      (document.head || document.documentElement).appendChild(style);
    } catch (error) {
      console.warn('[FormatPlate] Błąd podczas dodawania stylów CSS:', error);
    }
  };

  /**
   * Znajduje elementy rejestracji i podmienia fizyczne węzły <br> na kolorowy znak "-"
   * oraz formatuje kod kraju w postaci czytelnej plakietki.
   * @param {Element|Document} rootNode - Węzeł początkowy do przeszukania
   */
  const replaceBrWithSpace = (rootNode = document) => {
    try {
      // Szukamy elementów z dyrektywą ng-if tablicy rejestracyjnej lub klasą ng-binding
      const selector = 'span[ng-if*="licensePlateIdentifier"], span.ng-binding';
      const spans = rootNode.querySelectorAll ? rootNode.querySelectorAll(selector) : [];

      spans.forEach((span) => {
        // Sprawdzamy, czy wewnątrz span znajduje się znacznik <br>
        const breakElements = span.querySelectorAll('br');
        if (breakElements.length > 0) {
          breakElements.forEach((br) => {
            // Wstawienie stylizowanego węzła z myślnikiem
            const separatorSpan = document.createElement('span');
            separatorSpan.className = 'license-plate-separator';
            separatorSpan.textContent = CONFIG.separator;
            separatorSpan.style.color = CONFIG.separatorColor;
            separatorSpan.style.fontWeight = 'bold';
            separatorSpan.style.margin = '0 2px';

            // Formatowanie i kolorowanie węzła z kodem kraju (np. "PL")
            const nextNode = br.nextSibling;
            if (nextNode && nextNode.nodeType === Node.TEXT_NODE && nextNode.textContent.trim()) {
              const countrySpan = document.createElement('span');
              countrySpan.className = 'license-plate-country';
              countrySpan.textContent = nextNode.textContent.trim();
              countrySpan.style.color = CONFIG.countryColor;
              countrySpan.style.fontWeight = '600';

              if (CONFIG.enableBadge) {
                countrySpan.style.backgroundColor = CONFIG.countryBg;
                countrySpan.style.padding = '1px 5px';
                countrySpan.style.borderRadius = '3px';
                countrySpan.style.fontSize = '0.85em';
              }

              nextNode.parentNode.replaceChild(countrySpan, nextNode);
            }

            // Podmiana znacznika <br> na przygotowany myślnik
            br.parentNode.replaceChild(separatorSpan, br);
          });
        }
      });
    } catch (error) {
      console.warn('[FormatPlate] Błąd przetwarzania elementów:', error);
    }
  };

  /**
   * AngularJS dynamicznie przeładowuje elementy (np. podczas przewijania,
   * filtrowania, paginacji). MutationObserver automatycznie przetwarza nowe wiersze.
   */
  const observeDynamicContent = () => {
    const observer = new MutationObserver((mutations) => {
      for (const mutation of mutations) {
        if (mutation.type === 'childList') {
          mutation.addedNodes.forEach((node) => {
            if (node.nodeType === Node.ELEMENT_NODE) {
              replaceBrWithSpace(node);
            }
          });
        }
      }
    });

    observer.observe(document.body || document.documentElement, {
      childList: true,
      subtree: true,
    });
  };

  /**
   * Główna funkcja startowa uruchamiana po załadowaniu drzewa DOM.
   */
  const initialize = () => {
    injectHorizontalStyle();
    replaceBrWithSpace(document);
    observeDynamicContent();
  };

  // Uruchomienie skryptu w zależności od stanu dokumentu
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initialize);
  } else {
    initialize();
  }
})();"}

{"title":"ss","content":"// ==UserScript==
// @name         YMS Design Changes v2
// @namespace    https://phonetool.amazon.com/users/johjason
// @version      0.5.7.0
// @description  Various design changes to make the YMS Dashboard neater, easier and more functional. With Settings Panel, dynamic CSS loading and fixed seal/copy handlers.
// @author       johjason & You
// @match        https://trans-logistics.amazon.com/yms/shipclerk/*
// @match        https://trans-logistics-eu.amazon.com/yms/shipclerk/*
// @include      /^http:\/\/127\.0\.0\.1:\d+\/demo\/shipclerk\//
// @include      /^http:\/\/localhost:\d+\/demo\/shipclerk\//
// @include      /^file:.*?\/demo\/shipclerk\//
// @icon         https://images-na.ssl-images-amazon.com/images/G/01/TransCentral/images/favicon.ico
// @grant        GM_addStyle
// @grant        GM_setClipboard
// @require      https://code.jquery.com/jquery-3.7.0.min.js
// @run-at       document-end
// ==/UserScript==

/* globals $ */

(function (window, document) {
    "use strict";

    const STORAGE_KEY = "ymsSettingsConfig";

