    const injectHorizontalStyle = () => {
        try {
            const styleId = 'license-plate-horizontal-style';
            if (document.getElementById(styleId)) return;

            const style = document.createElement('style');
            style.id = styleId;
            style.textContent = `
                span[ng-if*="licensePlateIdentifier"] {
                    display: inline-flex !important;
                    align-items: center !important;
                    white-space: nowrap !important;
                }
                span[ng-if*="licensePlateIdentifier"] br {
