        } catch (error) {
            console.warn('[FormatPlate] Błąd stylów:', error);
        }
    };

    const replaceBrWithSpace = (rootNode = document) => {
        try {
            const spans = rootNode.querySelectorAll ? rootNode.querySelectorAll('span[ng-if*="licensePlateIdentifier"]') : [];
            for (let i = 0; i < spans.length; i++) {
                const span = spans[i];
                const breakElements = span.querySelectorAll('br');
                if (breakElements.length === 0) continue;

                breakElements.forEach((br) => {
                    const separatorSpan = document.createElement('span');
                    separatorSpan.className = 'license-plate-separator';
                    separatorSpan.textContent = CONFIG.separator;
                    separatorSpan.style.color = CONFIG.separatorColor;
                    separatorSpan.style.fontWeight = 'bold';
                    separatorSpan.style.margin = '0 2px';

                    const nextNode = br.nextSibling;
                    if (nextNode && nextNode.nodeType === Node.TEXT_NODE && nextNode.textContent.trim()) {
                        const countrySpan = document.createElement('span');
                        countrySpan.className = 'license-plate-country';
                        countrySpan.textContent = nextNode.textContent.trim();
                        countrySpan.style.color = CONFIG.countryColor;
                        countrySpan.style.fontWeight = '600';

                        if (CONFIG.enableBadge) {
                            countrySpan.style.backgroundColor = CONFIG.countryBg;
                            countrySpan.style.padding = '1px 4px';
                            countrySpan.style.fontSize = '0.85em';
                        }
                        nextNode.parentNode.replaceChild(countrySpan, nextNode);
                    }
                    br.parentNode.replaceChild(separatorSpan, br);
                });
            }
        } catch (error) {
            console.warn('[FormatPlate] Błąd przetwarzania elementów:', error);
        }
    };

    function extractCleanPlate(targetEl) {
        if (!targetEl) return "";

        for (let i = 0; i < targetEl.childNodes.length; i++) {
            const node = targetEl.childNodes[i];
            if (node.nodeType === Node.TEXT_NODE) {
                const txt = node.textContent.trim();
                if (txt) return txt;
            }
        }

        const clone = targetEl.cloneNode(true);
        const trash = clone.querySelectorAll('.license-plate-separator, .license-plate-country, .oxy-copy-btn, br, button');
        trash.forEach(el => el.remove());
        const raw = clone.textContent || "";
        return raw.split(/[\r\n\t_]/)[0].trim().replace(/<[^>]*>/g, '');
    }

    function copyTextToClipboard(text, onSuccess) {
        if (!text) return;
        if (typeof GM_setClipboard === "function") {
            GM_setClipboard(text);
            if (onSuccess) onSuccess();
            return;
        }
        if (navigator.clipboard && window.isSecureContext) {
            navigator.clipboard.writeText(text).then(() => {
                if (onSuccess) onSuccess();
            }).catch(() => fallbackCopy(text, onSuccess));
        } else {
            fallbackCopy(text, onSuccess);
        }
    }

    function fallbackCopy(text, onSuccess) {
        const ta = document.createElement("textarea");
        ta.value = text;
        ta.style.position = "fixed";
        ta.style.left = "-9999px";
        document.body.appendChild(ta);
        ta.select();
        try {
            document.execCommand("copy");
            if (onSuccess) onSuccess();
        } catch (e) {
            console.error("Copy failed", e);
        }
        document.body.removeChild(ta);
    }

    const observeDynamicContent = () => {
        const observer = new MutationObserver((mutations) => {
            for (let i = 0; i < mutations.length; i++) {
                const mutation = mutations[i];
                if (mutation.type === 'childList') {
                    for (let j = 0; j < mutation.addedNodes.length; j++) {
                        const node = mutation.addedNodes[j];
                        if (node.nodeType === Node.ELEMENT_NODE) {
                            replaceBrWithSpace(node);
                        }
                    }
                }
            }
        });

        observer.observe(document.body || document.documentElement, {
            childList: true,
            subtree: true
