        $("#cfg-text-color").val(ymsConfig.textColor || "#000000");
        $("#cfg-clear-colors").prop("checked", !ymsConfig.bgColor && !ymsConfig.textColor);
        $("#cfg-search-route").val(ymsConfig.searchRoute);
        $("#cfg-route-color").val(ymsConfig.routeColor);
        $("#cfg-route-seal-color").val(ymsConfig.routeSealColor || "#22c55e");
        $("#cfg-ps-empty-min").val(ymsConfig.alerts.psEmptyMin);
        $("#cfg-tagged-max").val(ymsConfig.alerts.taggedMax);
        $("#cfg-css-light").val(ymsConfig.cssUrls.light);
        $("#cfg-css-dark").val(ymsConfig.cssUrls.dark);
        $("#cfg-dashboard-layout").val(ymsConfig.display.dashboardLayout);

        const d = ymsConfig.display;
        $("#cfg-show-options-bar").prop("checked", d.showOptionsBar);
        $("#cfg-show-dark-toggle").prop("checked", d.showDarkModeToggle);
        $("#cfg-show-filter-trailer").prop("checked", d.showFilterTrailer);
        $("#cfg-show-settings-btn").prop("checked", d.showSettingsButton);
        $("#cfg-show-collapse-btn").prop("checked", d.showCollapseButton);
        $("#cfg-show-copy-buttons").prop("checked", d.showCopyButtons);
        $("#cfg-show-route-highlight").prop("checked", d.showRouteHighlight);
        $("#cfg-highlight-row-route").prop("checked", d.highlightRowOnRoute);
        $("#cfg-show-seal-buttons").prop("checked", d.showSealButtons);
        $("#cfg-polish-labels").prop("checked", d.usePolishLabels);

        $("#cfg-metrics-group input[data-metric]").each(function () {
            const id = $(this).data("metric");
            $(this).prop("checked", ymsConfig.metrics[id] !== false);
        });
