    function hexToRgb(hex) {
        const h = (hex || "#000000").replace("#", "");
        return {
            r: parseInt(h.substring(0, 2), 16) || 0,
            g: parseInt(h.substring(2, 4), 16) || 0,
            b: parseInt(h.substring(4, 6), 16) || 0
        };
    }

    const SEAL_NEGATIVE_VALUES = /^(none|null|undefined|brak|brak\s*piecz[eę]ci|no\s*seal|-)$/i;
    const SEAL_INVALID_PHRASES = /no\s*seal|seal\s*(broken|missing|invalid|open)|unsealed|brak\s*piecz/i;

    function rowHasSeal(target) {
        if (!target) return false;

        let el = null;
        if (typeof jQuery !== "undefined" && target instanceof jQuery) {
            el = target[0];
        } else if (target.nodeType) {
            el = target;
        }

        if (!el) return false;

        const tr = el.tagName === "TR" ? el : el.closest("tr");
        if (!tr) return false;

        const sealCandidates = tr.querySelectorAll(
            ".shipclerk-seals, .sealIdentifierGroup, .seal-present, .has-seal, " +
            ".yard-asset-seal, [class*='seal-present'], [class*='SealPresent'], " +
            "span[ng-if*='sealIdentifier'], span[ng-if*='sealNumber'], span[ng-if*='yardAsset.seal']"
        );

        for (let i = 0; i < sealCandidates.length; i++) {
            const candidate = sealCandidates[i];
            const txt = candidate.textContent.trim();

            if (txt && !SEAL_NEGATIVE_VALUES.test(txt) && !SEAL_INVALID_PHRASES.test(txt)) {
                return true;
            }

            const title = candidate.getAttribute("title")?.trim();
            if (title && !SEAL_NEGATIVE_VALUES.test(title) && !SEAL_INVALID_PHRASES.test(title)) {
                return true;
            }
        }

        const rawText = tr.textContent || "";
        if (SEAL_INVALID_PHRASES.test(rawText)) {
            return false;
        }

        const sealMatch = rawText.match(/\bseal(?:#|:|\s+)([A-Z0-9-]{3,})/i);
        if (sealMatch && sealMatch[1] && !SEAL_NEGATIVE_VALUES.test(sealMatch[1])) {
            return true;
        }

        return false;
    }

    function clearRouteHighlights() {
        $(".dynamic-route-colored").each(function () {
            $(this)
                .removeClass("dynamic-route-colored dynamic-route-has-seal dynamic-route-no-seal")
                .css({ "background-color": "", color: "", "font-weight": "", padding: "", border: "" });
        });
        $("tr.dynamic-route-row-highlight").each(function () {
            $(this).removeClass("dynamic-route-row-highlight").css({ "box-shadow": "", "background-color": "" });
        });
    }

    function applyRouteRowHighlight($span, color, hasSeal) {
        if (!ymsConfig.display.highlightRowOnRoute) return;
        const rgb = hexToRgb(color);
        const tr = $span[0]?.closest("tr");
        if (!tr) return;

        $(tr).addClass("dynamic-route-row-highlight").css({
            "box-shadow": `inset 0 0 0 2px ${color}`,
            "background-color": `rgba(${rgb.r}, ${rgb.g}, ${rgb.b}, ${hasSeal ? 0.22 : 0.15})`
        });
    }

    function refreshRouteHighlights(clearExisting) {
        if (clearExisting) clearRouteHighlights();
        if (!ymsConfig.display.showRouteHighlight || !ymsConfig.searchRoute) return;

        const sealColor = ymsConfig.routeSealColor || "#22c55e";

        $(`span[title='${ymsConfig.searchRoute}']`).each(function () {
            const $span =$(this);
            if ($span.hasClass("dynamic-route-colored")) return;

            const hasSeal = rowHasSeal($span);
            const color = hasSeal ? sealColor : ymsConfig.routeColor;

            $span.addClass("dynamic-route-colored");
            $span.addClass(hasSeal ? "dynamic-route-has-seal" : "dynamic-route-no-seal");
            $span.css({
                "background-color": color,
                color: hasSeal ? "#ffffff" : "#d50000",
                "font-weight": "bold",
                padding: "2px 5px",
                border: hasSeal ? "1px solid #15803d" : "1px solid #d50000"
            });

            applyRouteRowHighlight($span, color, hasSeal);
        });
    }

    function addLicensePlateCopyButtons() {
        if (!ymsConfig.display.showCopyButtons) return;

        const selector = "span[ng-if='yardAsset.vehicleNumber']:not([data-oxy-copy]), span[ng-if='yardAsset.licensePlateIdentifier && yardAsset.licensePlateIdentifier.registrationIdentifier']:not([data-oxy-copy])";
        const targets = document.querySelectorAll(selector);

        for (let i = 0; i < targets.length; i++) {
            const span = targets[i];
            span.setAttribute("data-oxy-copy", "true");

            const container = span.parentElement?.parentElement;
            if (!container || container.querySelector(".oxy-copy-btn")) continue;

            const copyButton = document.createElement("button");
            copyButton.className = "oxy-copy-btn superuserTooltip";
            copyButton.title = "Kopiuj do schowka";
            copyButton.textContent = "COPY";
            copyButton.type = "button";

            copyButton.addEventListener("click", function (e) {
                e.preventDefault();
                e.stopPropagation();

                const cleanNumber = extractCleanPlate(span);
                copyTextToClipboard(cleanNumber, () => {
                    copyButton.textContent = "COPIED!";
                    setTimeout(() => {
                        copyButton.textContent = "COPY";
                    }, 1500);
                });
            });

            container.appendChild(document.createElement("br"));
            container.appendChild(copyButton);
        }
    }

    function checkAndAddButtons() {
        if ($("#noteTextArea").is(":visible") && ymsConfig.display.showSealButtons) {
            if ($("#sealStatusDiv").length === 0 && typeof addSealStatusButtons === "function") addSealStatusButtons();
            if ($("#pageToggleButton").length === 0 && typeof createToggleButton === "function") createToggleButton();
            $("#pageToggleButton").show();

            if ($("#pageToggleButton").text() === "Next Page") {
                $("#sealStatusDiv").show();
                if ($("#page2Content").length > 0) $("#page2Content").hide();
            } else {
                $("#sealStatusDiv").hide();
                if ($("#page2Content").length === 0 && typeof createPage2 === "function") createPage2();
                $("#page2Content").show();
            }
        } else if (!ymsConfig.display.showSealButtons) {
            $("#sealStatusDiv, #page2Content, #pageToggleButton").hide();
        } else {
            $("#sealStatusDiv, #page2Content, #pageToggleButton").hide();
        }

        addLicensePlateCopyButtons();
        refreshRouteHighlights(false);
    }

    function toggleChanges() {
        const topbarData = document.getElementById("topbarData");
        const searchResults = document.querySelector(".ship-clerk-search-results");
        const tcpWidget = document.querySelector(".tcp-widget");
        const scrollTable = document.querySelector(".scrolltable");
        const topSection = document.getElementById("top-section");

        if (!topbarData || !searchResults || !tcpWidget || !scrollTable || !topSection) return;

        if (topbarData.style.visibility === "hidden") {
            topbarData.style.visibility = "visible";
            topbarData.style.opacity = "1";
            topbarData.style.zIndex = "1";
            toggleButton.innerHTML = "Collapse";
        } else {
            topbarData.style.visibility = "hidden";
            topbarData.style.opacity = "0";
            topbarData.style.zIndex = "-999";
            toggleButton.innerHTML = "Grow";
        }

        if (searchResults.style.marginTop === "-179px") {
            searchResults.style.marginTop = "0";
            searchResults.style.zIndex = "auto";
        } else {
            searchResults.style.marginTop = "-179px";
            searchResults.style.zIndex = "999";
        }

        tcpWidget.style.visibility = tcpWidget.style.visibility === "collapse" ? "visible" : "collapse";
        scrollTable.style.height = scrollTable.style.height === "150%" ? "100%" : "150%";

        if (isTopSectionVisible) {
            topSection.style.display = "none";
            isTopSectionVisible = false;
        } else {
            topSection.style.display = "-webkit-flex";
            isTopSectionVisible = true;
        }
    }

    function addToggleButton() {
        const clearButtonGroup = document.getElementById("clearButtonGroup");
        if (!clearButtonGroup || document.getElementById("yms-collapse-toggle")) return;

        clearButtonGroup.style.display = "flex";
        clearButtonGroup.style.justifyContent = "center";
        clearButtonGroup.style.alignItems = "center";

        toggleButton = document.createElement("button");
        toggleButton.id = "yms-collapse-toggle";
        toggleButton.innerHTML = "Collapse";
        toggleButton.style.cursor = "pointer";
        toggleButton.addEventListener("click", toggleChanges);
        clearButtonGroup.appendChild(toggleButton);

        if (!ymsConfig.display.showCollapseButton) {
            toggleButton.style.display = "none";
        }
    }

    function isYardView() {
        return window.location.href.indexOf("shipclerk/#/yard") > -1
            || (window.location.pathname.indexOf("shipclerk") > -1 && window.location.hash === "#/yard");
    }

    let initialized = false;
    let bootStarted = false;

    function init() {
        if (initialized) return;

        const mainContainer = document.getElementById("mainContainer");
        if (!mainContainer) return;

        initialized = true;

        injectHorizontalStyle();
        replaceBrWithSpace(document);
        observeDynamicContent();

        mainContainer.insertAdjacentHTML("beforebegin", `
            <div id="custom-options-container">
                <h3 id="dark-mode-label" style="margin:0;"><t>Dark Mode:</t></h3>
                <div id="dark-mode-switch">
                    <input id="dark-mode-toggle" type="checkbox">
                    <label for="dark-mode-toggle"></label>
                </div>
                <h3 id="filterTrailer-label" style="margin:0;"><t>Tagged Trailers:</t></h3>
                <div>
                    <input id="filterTrailer-toggle" type="checkbox">
                    <label for="filterTrailer-toggle"></label>
                </div>
                <button type="button" id="open-yms-settings">⚙️ Settings</button>
            </div>
        `);

        buildSettingsModal();

        const darkToggle = document.getElementById("dark-mode-toggle");
        darkToggle.checked = ymsConfig.darkMode;
        darkToggle.addEventListener("change", function () {
            ymsConfig.darkMode = this.checked;
            saveConfig();
            applyThemeCSS(this.checked);
            applyCustomColors();
        });

        const filterToggle = document.getElementById("filterTrailer-toggle");
        filterToggle.checked = ymsConfig.filterTrailer;
        filterToggle.addEventListener("change", function () {
            ymsConfig.filterTrailer = this.checked;
            saveConfig();
            applyFilterTrailer(this.checked);
        });

        if (isYardView()) {
            try {
                document.styleSheets[0].insertRule(".note-present-icon {flex-shrink: 0;}");
            } catch { /* ignore */ }

            mainContainer.insertAdjacentHTML("beforebegin", buildDashboardHTML());
            applyDashboardLayout();
            updateTopBarVisibility();
            applyFilterTrailer(ymsConfig.filterTrailer);

            setInterval(emptyAZNG, 60000);
            setTimeout(emptyAZNG, 500);
        }

        applyDisplaySettings();
        setInterval(checkAndAddButtons, 1500);
        setTimeout(addToggleButton, 4000);
    }

    function boot() {
        if (initialized || bootStarted) return;
        bootStarted = true;

        if (document.getElementById("mainContainer")) {
            init();
            return;
        }
        const observer = new MutationObserver(function () {
            if (document.getElementById("mainContainer")) {
                observer.disconnect();
                init();
            }
        });
        if (document.body) {
            observer.observe(document.body, { childList: true, subtree: true });
        }
        setTimeout(function () {
            observer.disconnect();
            init();
        }, 12000);
    }

    if (document.readyState === "complete" || document.readyState === "interactive") {
        boot();
    } else {
        window.addEventListener("load", boot);
        document.addEventListener("DOMContentLoaded", boot);
    }

})(window, document);
"}

{"title":"ccccc","content":"@import url('https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@400;500;700;800&display=swap');

/* ==========================================================================
   RESET SYSTEMOWY & KONTRASTY PRZEMYSŁOWE (ZERO BORDER-RADIUS)
   ========================================================================== */
*,
*::before,
*::after {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
    border-radius: 0 !important;
    outline: none !important;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
}

:root {
    /* PALETA PODSTAWOWA // DARK INDUSTRIAL CHASSIS */
    --body-bg: #141414;
    --chassis-bg: #1c1c1c;
    --panel-bg: #262626;
    --bg-panel: #262626;
    --bg-tertiary: #2e2e2e;
    --card-bg: #1e1e1e;
    --hover-bg: #3c3c3c;
    --input-bg: #161616;
    --border-color: #2a2a2a;
    --border-hover: #444444;
    --border-color-hover: #444444;
    --text-color: #e0e0e0;
    --text-primary: #e5e5e5;
    --text-muted: #858585;
    --text-inverse: #121212;

    /* TELEMETRIA & AKCENTY SYGNAŁOWE */
    --highlight-color: #f36c00;
    --highlight-hover: #ff851b;
    --glow-highlight: rgba(243, 108, 0, 0.55);
    --hazard-red: #ef4444;
    --hazard-bg: rgba(239, 68, 68, 0.12);
    --led-green: #22c55e;
    --led-off: #444444;
    --vs-blue: #3b82f6;

    /* KOLORY IDENTYFIKACJI FLOTY */
    --vehicle-tractor: #60a5fa;
    --vehicle-boxtruck: #fb923c;

    /* HARDWARE CIENIE & INSETY PROFILOWANE */
    --shadow-drop: rgba(32, 32, 32, 0.4) 0px 0px 0px 2px,
                   rgba(0, 0, 0, 0.65) 0px 4px 6px -1px,
                   rgba(255, 255, 255, 0.08) 0px 1px 0px inset;

    --shadow-inset: inset 0px 0px 0px 2px rgba(32, 32, 32, 0.4),
                    inset 0px 4px 6px -1px rgba(0, 0, 0, 0.65),
                    inset 0px 1px 0px rgba(255, 255, 255, 0.08);

    --shadow-hover: rgba(32, 32, 32, 0.2) 0px 0px 0px 1px,
                    rgba(0, 0, 0, 0.325) 0px 2px 3px -0.5px,
                    rgba(255, 255, 255, 0.04) 0px 0.5px 0px inset;

    --shadow-active: inset 0px 4px 6px rgba(0, 0, 0, 0.9),
                     inset 0px 0px 0px 1px rgba(15, 15, 15, 0.85),
                     inset 0px -1px 1px rgba(255, 255, 255, 0.05);

    /* TYPOGRAFIA & PRZEJŚCIA */
    --font-family: "JetBrains Mono", monaco, courier, monospace;
    --font-main: var(--font-family);
    --color-grid-line: rgba(255, 255, 255, 0.025);
    --transition-speed: 0.15s;
    --transition-ease: ease;
    --transition-ui: background-color var(--transition-speed) var(--transition-ease),
                     color var(--transition-speed) var(--transition-ease),
                     border-color var(--transition-speed) var(--transition-ease),
                     box-shadow var(--transition-speed) var(--transition-ease);
}

/* ==========================================================================
   KONTENERY BAZOWE .btn-bg ORAZ ARCHITEKTURA PRZYCISKÓW
   ========================================================================== */
.btn-bg {
    --padding: 0.125rem;
    --gap: 0.125rem;
    display: inline-flex;
    justify-content: center;
    align-items: center;
    box-shadow: var(--shadow-inset);
    padding: var(--padding);
    gap: var(--gap);
    position: relative;
    overflow: hidden;
    width: fit-content;
    border: 1px solid var(--border-color);
    background: var(--card-bg);
    user-select: none;
    vertical-align: middle;
}

.btn-bg.pulse-alert {
    border-color: var(--hazard-red);
    animation: evacPulseAlert 1.5s infinite ease-in-out;
}

@keyframes evacPulseAlert {
    0%, 100% {
        box-shadow: var(--shadow-inset), 0 0 0 0 rgba(239, 68, 68, 0.5);
    }
    50% {
        box-shadow: var(--shadow-inset), 0 0 0 6px rgba(239, 68, 68, 0);
    }
}

.fui-btn,
.btn {
    box-shadow: var(--shadow-drop);
    border: 1px solid var(--border-color);
    background: var(--bg-tertiary);
    color: var(--text-color);
    padding: 0 0.85rem;
    height: 28px;
    font-family: var(--font-family);
    font-weight: 800;
    cursor: pointer;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.45rem;
    outline: none !important;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.06em;
    position: relative;
    white-space: nowrap;
    transition: var(--transition-ui);
    user-select: none;
}

.fui-btn:hover,
.btn:hover:not(:disabled) {
    background: var(--hover-bg);
    color: #ffffff;
    border-color: var(--border-color-hover);
    box-shadow: var(--shadow-hover);
}

.fui-btn:active,
.btn:active:not(:disabled) {
    background: var(--card-bg) !important;
    color: var(--text-color) !important;
    box-shadow: var(--shadow-active) !important;
    transform: translateY(1px);
}

.fui-btn:disabled,
.btn:disabled {
    opacity: 0.4;
    cursor: not-allowed;
    filter: grayscale(1);
    box-shadow: none;
}

/* WARIANTY AKCENTÓW PRZYCISKÓW */
.btn-accent,
.fui-btn.btn-accent {
    color: #000000 !important;
    background: var(--highlight-color) !important;
    border-color: var(--highlight-hover) !important;
}

.btn-accent:hover,
.fui-btn.btn-accent:hover {
    background: var(--highlight-hover) !important;
    box-shadow: 0 0 8px var(--glow-highlight);
}

.btn-danger,
.fui-btn.btn-danger {
    color: #ffffff !important;
    background: var(--hazard-red) !important;
    border-color: #b91c1c !important;
}

.btn-danger:hover,
.fui-btn.btn-danger:hover {
    background: #dc2626 !important;
    box-shadow: 0 0 8px rgba(239, 68, 68, 0.6);
}

.btn-sm {
    height: 24px;
    font-size: 0.65rem;
    padding: 0 0.55rem;
}

/* LICZNIKI / BADGE WEWNĄTRZ PRZYCISKÓW */
.evac-count {
    background: #000000;
    color: var(--highlight-color);
    border: 1px solid var(--border-color);
    padding: 1px 6px;
    font-size: 0.75rem;
    font-weight: 800;
    letter-spacing: 0.04em;
    margin-left: 4px;
    box-shadow: var(--shadow-inset);
}

/* ==========================================================================
   OKNO MODALNE // INDUSTRIAL VIEWPORT & BEZEL
   ========================================================================== */
.evac-modal-overlay,
.modal-overlay {
    position: fixed;
    inset: 0;
    width: 100vw;
    height: 100vh;
    background-color: rgba(10, 10, 10, 0.88);
    backdrop-filter: blur(2px);
    z-index: 10000;
    display: flex;
    justify-content: center;
    align-items: center;
    padding: 1rem;
    user-select: none;
}

.evac-modal-window,
.evac-box,
.modal {
    background-color: var(--chassis-bg);
    border: 1px solid var(--border-hover);
    box-shadow: 0 25px 50px rgba(0, 0, 0, 0.95), var(--shadow-drop);
    width: 100%;
    max-width: 1040px;
    max-height: 90vh;
    display: flex;
    flex-direction: column;
    position: relative;
    color: var(--text-color);
    font-family: var(--font-family);
    overflow: hidden;
}

.evac-header,
.modal-header {
    background: #181818;
    color: var(--text-color);
    padding: 0.75rem 1rem;
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-shrink: 0;
    border-bottom: 2px solid var(--hazard-red);
}

.evac-title,
.modal-title {
    font-size: 0.85rem;
    font-weight: 800;
    letter-spacing: 0.08em;
    color: var(--hazard-red);
    text-transform: uppercase;
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.evac-header-btns {
    display: flex;
    gap: 0.4rem;
    align-items: center;
}

.hazard-stripe {
    height: 5px;
    background: repeating-linear-gradient(-45deg,
            var(--card-bg),
            var(--card-bg) 8px,
            var(--hazard-red) 8px,
            var(--hazard-red) 16px);
    border-bottom: 1px solid var(--border-color);
    width: 100%;
    flex-shrink: 0;
}

/* ==========================================================================
   TABELA DANYCH TELEMETRYCZNYCH // INDUSTRIAL GRID
   ========================================================================== */
.evac-body,
.table-responsive-container {
    width: 100%;
    overflow-x: auto;
    overflow-y: auto;
    flex: 1;
    background: var(--input-bg);
    padding: 0.5rem;
    box-shadow: var(--shadow-inset);
}

table.data-table,
.evac-body table {
    width: 100%;
    border-collapse: collapse;
    font-size: 0.72rem;
    letter-spacing: 0.04em;
    min-width: 760px;
}

table thead th,
.evac-body table th {
    background-color: var(--bg-tertiary);
    color: var(--text-muted);
    padding: 0.6rem 0.85rem;
    font-weight: 800;
    text-transform: uppercase;
    text-align: left;
    border-bottom: 2px solid var(--border-color);
    border-right: 1px solid var(--border-color);
    position: sticky;
    top: 0;
    z-index: 2;
    box-shadow: inset 0 -1px 0 var(--border-hover);
}

table tbody tr,
.evac-body table tbody tr {
    border-bottom: 1px solid var(--border-color);
    transition: background-color 0.1s ease;
}

table tbody tr:hover,
.evac-body table tbody tr:hover {
    background-color: var(--hover-bg);
}

table tbody td,
.evac-body table td {
    padding: 0.5rem 0.85rem;
    color: var(--text-color);
    border-right: 1px solid var(--border-color);
    vertical-align: middle;
}

/* TYPOWANIE WIERSZY TELEMETRII */
.type-badge-t,
.vehicle-type-tractor {
    color: var(--vehicle-tractor) !important;
    font-weight: 800;
}

.type-badge-b,
.vehicle-type-boxtruck {
    color: var(--vehicle-boxtruck) !important;
    font-weight: 800;
}

.comment-cell {
    color: #ffffff;
    font-weight: 700;
}

.no-plate {
    color: var(--hazard-red);
    font-weight: 800;
}

.row-has-days-in-yard {
    border-left: 4px solid var(--hazard-red) !important;
    background: var(--hazard-bg);
}

/* ==========================================================================
   SEKCJA KODU QR & ODBIORNIK AIR-GAP
   ========================================================================== */
#evac_qr_view {
    background: #141414;
    padding: 1rem;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.75rem;
    border-bottom: 1px solid var(--border-color);
    box-shadow: var(--shadow-inset);
}

.qr-bezel-frame,
.qr-frame {
    background: #ffffff;
    border: 3px solid var(--border-hover);
    padding: 8px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    box-shadow: 0 4px 20px rgba(0, 0, 0, 0.8), var(--shadow-drop);
    aspect-ratio: 1 / 1;
}

.qr-frame canvas,
.qr-code-image {
    display: block;
    image-rendering: pixelated;
    image-rendering: crisp-edges;
    aspect-ratio: 1 / 1;
}

.endpoint-display {
    font-size: 0.68rem;
    color: var(--text-muted);
    text-transform: uppercase;
    letter-spacing: 0.06em;
}

.endpoint-display code {
    color: var(--highlight-color);
    font-weight: 800;
}

/* ==========================================================================
   STOPKA PODSUMOWANIA (TELEMETRY SUMMARY FOOTER)
   ========================================================================== */
.evac-summary {
    padding: 0.65rem 1rem;
    background: #181818;
    font-weight: 800;
    font-size: 0.72rem;
    border-top: 1px solid var(--border-color);
    flex-shrink: 0;
    color: var(--text-color);
    display: flex;
    justify-content: space-between;
    align-items: center;
    text-transform: uppercase;
    letter-spacing: 0.05em;
}

.evac-summary strong {
    font-size: 0.82rem;
}

/* ==========================================================================
   WSKAŹNIKI LED & PODZESPOŁY SYGNAŁOWE
   ========================================================================== */
.led-indicator {
    width: 7px;
    height: 7px;
    background: var(--led-off);
    border: 1px solid var(--border-color);
    box-shadow: var(--shadow-inset);
    flex-shrink: 0;
    display: inline-block;
}

.led-indicator.led-active {
    background: var(--highlight-color);
    box-shadow: 0 0 6px var(--highlight-color);
    border-color: var(--highlight-color);
}

.led-indicator.led-green {
    background: var(--led-green);
    box-shadow: 0 0 6px var(--led-green);
    border-color: var(--led-green);
}

/* ==========================================================================
   REGUŁY WYDRUKU (A4 LANDSCAPE // CLEAN PRINT)
   ========================================================================== */
@media print {
    body * {
        visibility: hidden !important;
    }

    .evac-modal-overlay,
    .evac-modal-overlay * {
        visibility: visible !important;
    }

    .evac-modal-overlay {
        position: absolute;
        inset: 0;
        background: #ffffff !important;
        color: #000000 !important;
        padding: 0 !important;
    }

    .evac-box,
    .evac-modal-window {
        width: 100% !important;
        max-width: none !important;
        max-height: none !important;
        box-shadow: none !important;
        border: none !important;
        background: #ffffff !important;
        color: #000000 !important;
    }

    .evac-header {
        background: #eeeeee !important;
        color: #000000 !important;
        border-bottom: 2px solid #000000 !important;
    }

    .evac-header h2 {
        color: #000000 !important;
    }

    .evac-body {
        background: #ffffff !important;
        color: #000000 !important;
        padding: 0 !important;
    }

    table th {
        background: #eeeeee !important;
        color: #000000 !important;
        border-bottom: 2px solid #000000 !important;
    }

    table td {
        border-bottom: 1px solid #cccccc !important;
        color: #000000 !important;
    }

    .evac-header-btns,
    #evac_qr_view,
    .hazard-stripe {
        display: none !important;
    }

    @page {
        size: A4 landscape;
        margin: 0.5cm;
    }
}
"}

