{"title":"EW","content":"// ==UserScript==
// @name         WRO5 YMS EVACUATION LIST & MOBILE QR
// @namespace    https://phonetool.amazon.com/users/mamorett
// @version      2.2.0
// @description  Evacuation list - Tractors & Box Trucks on yard with notes/comments transfer via QR
// @match        https://trans-logistics.amazon.com/yms/shipclerk/*
// @match        https://trans-logistics-eu.amazon.com/yms/shipclerk/*
// @grant        GM_addStyle
// @require      https://cdnjs.cloudflare.com/ajax/libs/qrious/4.0.2/qrious.min.js
// @require      https://cdnjs.cloudflare.com/ajax/libs/lz-string/1.5.0/lz-string.min.js
// @run-at       document-end
// ==/UserScript==

/* globals QRious, LZString, angular */

(function () {
  'use strict';

  const EVAC_BTN_ID = 'yms_evac_btn_v1';
  const EVAC_MODAL_ID = 'yms_evac_modal_v1';
  const REFRESH_MS = 5000;
  const STORAGE_KEY_ENDPOINT = 'YMS_EVAC_MOBILE_ENDPOINT';
  const DEFAULT_ENDPOINT = 'mobile.html';

  function getEndpoint() {
    return localStorage.getItem(STORAGE_KEY_ENDPOINT) || DEFAULT_ENDPOINT;
  }

  GM_addStyle(`
:root {
  --oi-bg-1: #d32f2f;
  --oi-text-2: #fff;
  --oi-border-3: #b71c1c;
  --oi-shadow-4: rgba(211,47,47,0.5);
  --oi-shadow-5: rgba(211,47,47,0);
  --oi-bg-6: rgba(0,0,0,0.75);
  --oi-shadow-7: rgba(0,0,0,0.5);
  --oi-border-8: #333;
  --oi-bg-9: #181818;
  --oi-bg-10: #242424;
  --oi-accent-orange: #f36c00;
  --oi-accent-blue: #60a5fa;
}

*, *::before, *::after {
  border-radius: 0 !important;
  box-sizing: border-box;
}

#${EVAC_BTN_ID} {
  background: var(--oi-bg-1); color: var(--oi-text-2); border: 2px solid var(--oi-border-3);
  padding: 6px 14px; cursor: pointer;
  font-weight: 900; font-size: 13px; font-family: "JetBrains Mono", Consolas, monospace;
  display: inline-flex; align-items: center; gap: 8px;
  animation: evacPulse 1.5s infinite;
  user-select: none;
}
@keyframes evacPulse {
  0%,100% { box-shadow: 0 0 0 0 var(--oi-shadow-4); }
  50% { box-shadow: 0 0 0 8px var(--oi-shadow-5); }
}
#${EVAC_BTN_ID} .evac-count {
  background: var(--oi-text-2); color: var(--oi-bg-1); font-weight: 900;
  padding: 2px 8px; font-size: 14px;
}
#${EVAC_MODAL_ID} {
  position: fixed; inset: 0; background: var(--oi-bg-6);
  display: flex; align-items: center; justify-content: center; z-index: 10000;
  font-family: "JetBrains Mono", Consolas, monospace;
}
#${EVAC_MODAL_ID} .evac-box {
  background: #141414; padding: 0; width: 980px;
  max-height: 90vh; display: flex; flex-direction: column;
  box-shadow: 0 12px 40px var(--oi-shadow-7); overflow: hidden;
  border: 1px solid var(--oi-border-8);
}
#${EVAC_MODAL_ID} .evac-header {
  background: var(--oi-bg-1); color: var(--oi-text-2); padding: 10px 16px;
  display: flex; justify-content: space-between; align-items: center;
  flex-shrink: 0;
}
#${EVAC_MODAL_ID} .evac-header h2 { margin: 0; font-size: 15px; font-weight: 900; letter-spacing: 0.05em; }
#${EVAC_MODAL_ID} .evac-header-btns { display: flex; gap: 6px; }
#${EVAC_MODAL_ID} .evac-header-btns button {
  background: #181818; color: var(--oi-text-2); border: 1px solid #444; padding: 5px 12px;
  font-weight: 800; cursor: pointer; font-size: 11px; text-transform: uppercase;
}
#${EVAC_MODAL_ID} .evac-header-btns button:hover { background: #262626; }
#${EVAC_MODAL_ID} .evac-header-btns button.accent {
  background: var(--oi-accent-orange); color: #000; border-color: var(--oi-accent-orange);
}
#${EVAC_MODAL_ID} .evac-header-btns button.accent:hover { background: #ff851b; }

#${EVAC_MODAL_ID} .evac-body { overflow: auto; padding: 10px 14px; flex: 1; background: var(--oi-bg-9); color: #e5e5e5; }
#${EVAC_MODAL_ID} table {
  width: 100%; border-collapse: collapse; font-size: 12px;
}
#${EVAC_MODAL_ID} th {
  background: #202020; color: #aaa; padding: 8px 10px;
