  `);

  function findLocation(row) {
    var locEl = row.querySelector('a[ng-click="showLocation(location)"].ng-binding');
    if (locEl) return locEl.textContent.trim();
    var prev = row.previousElementSibling;
    while (prev) {
      locEl = prev.querySelector('a[ng-click="showLocation(location)"].ng-binding');
      if (locEl) return locEl.textContent.trim();
      prev = prev.previousElementSibling;
    }
    return '';
  }

  function getPlate(row) {
    var el = row.querySelector('[class*="vehicleId"] .ng-binding');
    if (el && el.textContent.trim()) return el.textContent.trim();
    try {
      var scope = angular.element(row).scope();
      var ya = scope && (scope.yardAsset || scope.asset || (scope.row && scope.row.yardAsset));
      if (ya && ya.vehicleNumber) return ya.vehicleNumber;
    } catch (e) {}
    return '';
  }

  function extractTime(row) {
    try {
      var scope = angular.element(row).scope();
      var ya = scope && (scope.yardAsset || scope.asset || (scope.row && scope.row.yardAsset));
      if (ya) {
        if (ya.timeInYard && String(ya.timeInYard).trim()) return String(ya.timeInYard).trim();
        if (ya.dwellTime && String(ya.dwellTime).trim()) return String(ya.dwellTime).trim();
        if (ya.timeElapsed && String(ya.timeElapsed).trim()) return String(ya.timeElapsed).trim();

        var inDate = ya.checkInDate || ya.arrivalDate || ya.gateInDate;
        if (inDate) {
          var diffMs = Date.now() - new Date(inDate).getTime();
          if (diffMs > 0) {
            var totalMin = Math.floor(diffMs / 60000);
            var d = Math.floor(totalMin / 1440);
            var h = Math.floor((totalMin % 1440) / 60);
            var m = totalMin % 60;
            var parts = [];
            if (d > 0) parts.push(d + 'd');
            if (h > 0) parts.push(h + 'h');
            parts.push(m + 'm');
            return parts.join(' ');
          }
        }
      }
    } catch (e) {}

    var el = row.querySelector('[yms-time-elapsed], [ng-bind*="timeElapsed"], [ng-bind*="dwellTime"], .dwell-time');
    if (el && el.textContent.trim()) return el.textContent.trim();

    var titleEl = row.querySelector('td[title*="d"], td[title*="h"], td[title*="min"], td[title*="hour"]');
    if (titleEl && titleEl.getAttribute('title')) return titleEl.getAttribute('title').trim();

    var cells = row.querySelectorAll('td');
    for (var i = 0; i < cells.length; i++) {
      var txt = cells[i].textContent.trim();
      if (/^(\d+\s*d)?\s*(\d+\s*h)?\s*(\d+\s*m(in)?)?$/i.test(txt) && txt.length > 0 && /\d/.test(txt)) {
        return txt;
      }
      if (/^\d{1,3}:\d{2}(:\d{2})?$/.test(txt)) {
        return txt;
      }
    }

    return '0m';
  }

  function parseMinutes(timeStr) {
    if (!timeStr) return 0;
    var s = timeStr.toLowerCase();
    var mins = 0;
    var d = s.match(/(\d+(?:[.,]\d+)?)\s*(?:d|day|dni)/);
    if (d) mins += parseFloat(d[1].replace(',', '.')) * 1440;
    var h = s.match(/(\d+(?:[.,]\d+)?)\s*(?:h|hr|hour|godz)/);
    if (h) mins += parseFloat(h[1].replace(',', '.')) * 60;
    var m = s.match(/(\d+)\s*(?:m|min)/);
    if (m) mins += parseInt(m[1], 10);

    if (mins === 0) {
      var colon = s.match(/^(\d+):(\d{1,2})/);
      if (colon) mins = parseInt(colon[1], 10) * 60 + parseInt(colon[2], 10);
    }
    return Math.round(mins);
  }

  function getEvacData() {
    var rows = document.querySelectorAll('tr.ng-scope');
    var results = [];
    var countT = 0;
    var countB = 0;

    rows.forEach(function (row) {
      try {
        var hasTractor = !!row.querySelector('.yard-asset-icon-TRACTOR');
        var hasBoxTruck = !!row.querySelector('.yard-asset-icon-BOX_TRUCK');
        if (!hasTractor && !hasBoxTruck) return;

        var location = findLocation(row);
        if (location.toUpperCase().startsWith('OS-')) return;

        var type = hasTractor ? 'T' : 'B';
        if (type === 'T') countT++;
        else countB++;

        var plate = getPlate(row);
        var time = extractTime(row);
        var dwellMins = parseMinutes(time);

        // POBIERANIE KOMENTARZA / NOTATKI
        var noteEl = row.querySelector('#noteContainer p.block-with-text, [ng-bind*="note"], .notes-cell');
        var comment = noteEl ? noteEl.textContent.trim() : '';

        // Sprawdzenie plomby i dopisanie do komentarza jeśli występuje
        var sealEl = row.querySelector('.sealIdentifierGroup, .shipclerk-seals');
        if (sealEl && !/no\s*seal/i.test(sealEl.textContent)) {
          var sTxt = sealEl.textContent.trim();
          comment = comment ? (comment + ' | SEAL: ' + sTxt) : ('SEAL: ' + sTxt);
        }

        results.push({
          plate: plate,
          type: type,
          location: location,
          time: time,
          dwellMins: dwellMins,
          comment: comment
        });
      } catch (e) {}
    });

    return { results: results, totalUnits: results.length, tractors: countT, boxTrucks: countB };
  }

  // Budowa ładunku QR: ID|TYP|LOKALIZACJA|MINUTY|KOMENTARZ
  function buildCompactPayload(results) {
    var rows = results.map(function (r) {
      var id = (r.plate || 'BRAK_ID').replace(/[|~]/g, ' ').trim();
      var loc = (r.location || '').replace(/[|~]/g, ' ').trim();
      var cmt = (r.comment || '').replace(/[|~]/g, ' ').trim();
      return id + '|' + r.type + '|' + loc + '|' + r.dwellMins + '|' + cmt;
    });
    return Date.now() + '~' + rows.join('~');
  }

  function updateBtnCount() {
    var btn = document.getElementById(EVAC_BTN_ID);
    if (!btn) return;
    btn.querySelector('.evac-count').textContent = getEvacData().totalUnits;
  }

  function esc(s) {
    return String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  }

  function showEvacModal() {
    var prev = document.getElementById(EVAC_MODAL_ID);
    if (prev) prev.remove();

    var data = getEvacData();
    var now = new Date().toLocaleString('pl-PL');
    var endpoint = getEndpoint();

    var tableRows = '';
    data.results.forEach(function (r, i) {
      var typeBadge = r.type === 'T'
        ? '<span class="type-badge-t">TRACTOR</span>'
        : '<span class="type-badge-b">BOX TRUCK</span>';

      var plateHtml = r.plate
        ? '<strong>' + esc(r.plate) + '</strong>'
        : '<span class="no-plate">⚠ BRAK LP</span>';

      tableRows += '<tr>' +
        '<td>' + (i + 1) + '</td>' +
        '<td>' + typeBadge + '</td>' +
        '<td>' + plateHtml + '</td>' +
        '<td>' + esc(r.location) + '</td>' +
        '<td>' + esc(r.time) + '</td>' +
        '<td class="comment-cell">' + (esc(r.comment) || '<span style="color:#666">—</span>') + '</td>' +
        '</tr>';
    });

    var overlay = document.createElement('div');
    overlay.id = EVAC_MODAL_ID;
    overlay.innerHTML =
      '<div class="evac-box">' +
        '<div class="evac-header">' +
          '<h2>\uD83D\uDEA8 EVACUATION LIST — ' + now + '</h2>' +
          '<div class="evac-header-btns">' +
            '<button id="evac_qr_btn" class="accent">\u26A1 KOD QR (MOBILE)</button>' +
            '<button id="evac_print_btn">\uD83D\uDDA8 DRUKUJ</button>' +
            '<button id="evac_close_btn">\u2715 ZAMKNIJ</button>' +
          '</div>' +
        '</div>' +
        '<div id="evac_qr_view">' +
          '<div class="qr-frame"><canvas id="evac_qr_canvas"></canvas></div>' +
          '<div style="font-size:11px;color:#aaa;text-transform:uppercase;">Cel: <code style="color:var(--oi-accent-orange);">' + esc(endpoint) + '</code></div>' +
          '<div style="display:flex;gap:6px;">' +
            '<button id="evac_copy_link" style="background:#242424;color:#fff;border:1px solid #444;padding:4px 10px;font-size:11px;cursor:pointer;">KOPIUJ LINK</button>' +
            '<button id="evac_open_tab" style="background:#242424;color:#fff;border:1px solid #444;padding:4px 10px;font-size:11px;cursor:pointer;">OTW\u00D3RZ W OKNIE</button>' +
            '<button id="evac_set_endpoint" style="background:#242424;color:#aaa;border:1px solid #444;padding:4px 8px;font-size:11px;cursor:pointer;">\u2699 URL</button>' +
          '</div>' +
        '</div>' +
        '<div class="evac-body" id="evac_table_view">' +
          '<table>' +
            '<thead><tr>' +
              '<th style="width:40px;">#</th>' +
              '<th style="width:110px;">TYP</th>' +
              '<th style="width:140px;">NR REJESTRACYJNY</th>' +
              '<th style="width:100px;">POLE</th>' +
              '<th style="width:120px;">CZAS NA YARD</th>' +
              '<th>KOMENTARZ</th>' +
            '</tr></thead>' +
            '<tbody>' + (tableRows || '<tr><td colspan="6" style="text-align:center;padding:20px">Brak pojazd\u00F3w na placu</td></tr>') + '</tbody>' +
          '</table>' +
        '</div>' +
        '<div class="evac-summary">' +
          '<div>CI\u0104GNIKI: ' + data.tractors + ' &nbsp;|&nbsp; BOX TRUCK: ' + data.boxTrucks + '</div>' +
          '<div>\u0141\u0104CZNIE POJAZD\u00D3W: <span style="color:var(--oi-bg-1);font-size:14px;">' + data.totalUnits + '</span></div>' +
        '</div>' +
      '</div>';

    document.body.appendChild(overlay);

    overlay.addEventListener('click', function (e) { if (e.target === overlay) overlay.remove(); });
    document.getElementById('evac_close_btn').addEventListener('click', function () { overlay.remove(); });
    document.getElementById('evac_print_btn').addEventListener('click', function () { window.print(); });

    var qrBtn = document.getElementById('evac_qr_btn');
    var qrView = document.getElementById('evac_qr_view');
    var tableView = document.getElementById('evac_table_view');
    var qrGenerated = false;
    var mobileUrl = '';

    qrBtn.addEventListener('click', function () {
      if (qrView.style.display === 'flex') {
        qrView.style.display = 'none';
        tableView.style.display = 'block';
        qrBtn.textContent = '⚡ KOD QR (MOBILE)';
      } else {
        qrView.style.display = 'flex';
        tableView.style.display = 'none';
        qrBtn.textContent = '📋 POKAŻ LISTĘ';

        if (!qrGenerated) {
          var payload = buildCompactPayload(data.results);
          var compressed = LZString.compressToEncodedURIComponent(payload);
          mobileUrl = endpoint + '#d=' + compressed;

          new QRious({
            element: document.getElementById('evac_qr_canvas'),
            value: mobileUrl,
            size: 260,
            background: '#ffffff',
            foreground: '#000000',
            level: 'L',
            padding: 0
          });
          qrGenerated = true;
        }
      }
    });

    document.getElementById('evac_copy_link').addEventListener('click', function () {
      if (!mobileUrl) return;
      navigator.clipboard.writeText(mobileUrl).then(function () {
        document.getElementById('evac_copy_link').textContent = '✔ SKOPIOWANO!';
        setTimeout(function () {
          document.getElementById('evac_copy_link').textContent = 'KOPIUJ LINK';
        }, 2000);
      });
    });

    document.getElementById('evac_open_tab').addEventListener('click', function () {
      if (mobileUrl) window.open(mobileUrl, '_blank');
    });

    document.getElementById('evac_set_endpoint').addEventListener('click', function () {
      var next = prompt('Wpisz adres do mobile.html (np. mobile.html lub link):', endpoint);
      if (next && next.trim()) {
        localStorage.setItem(STORAGE_KEY_ENDPOINT, next.trim());
        showEvacModal();
      }
    });
  }

  function insertBtn() {
    if (document.getElementById(EVAC_BTN_ID)) return;
    var btn = document.createElement('button');
    btn.id = EVAC_BTN_ID;
    btn.innerHTML = '\uD83D\uDEA8 EVACUATION LIST <span class="evac-count">0</span>';
    btn.addEventListener('click', showEvacModal);

    var superContainer = document.getElementById('yms_super_integrated_container_v1');
    if (superContainer) {
      superContainer.appendChild(btn);
    } else {
      var main = document.getElementById('mainContainer');
      if (main && main.parentNode) main.parentNode.insertBefore(btn, main);
      else document.body.insertAdjacentElement('afterbegin', btn);
    }
  }

  var retries = 0;
  var initInterval = setInterval(function () {
    insertBtn();
    if (document.getElementById(EVAC_BTN_ID) || ++retries > 20) {
      clearInterval(initInterval);
      updateBtnCount();
      setInterval(updateBtnCount, REFRESH_MS);
    }
  }, 500);

  window.addEventListener('hashchange', function () {
    setTimeout(function () { insertBtn(); updateBtnCount(); }, 300);
  });
})();
"}

