{"title":"sides","content":"const CONFIG = {
  timeThresholds: {
    stage30: 30,
    stage15: 15,
    stage5: 5,
    urgent: 10,
    warning: 30,
    upcoming: 60,
  },
  colors: {
    lateAlert: "#8B0000",
    urgentAlert: "#FF0000",
    progress: "#CE9105",
    finished: "#03C314",
    outCol: "#555555",
    fleAlert: "#F36C00",
  },
  toast: { autoClose: true, duration: 12000 },
  voice: { enabled: true, rate: 1.0, pitch: 1.2 },
  notifications: { enabled: true },
};

let routeDisplayMode = "SINGLE"; // "SINGLE" lub "ALL"
const PRIMARY_ROUTE = "WRO5->KTW3";

function loadSettingsFromStorage() {
  if (typeof chrome !== "undefined" && chrome.storage && chrome.storage.local) {
    chrome.storage.local.get(["hudSettings", "routeDisplayMode"], (res) => {
      if (res.hudSettings) {
        Object.assign(CONFIG.timeThresholds, res.hudSettings.timeThresholds || {});
        Object.assign(CONFIG.toast, res.hudSettings.toast || {});
        Object.assign(CONFIG.voice, res.hudSettings.voice || {});
        Object.assign(CONFIG.notifications, res.hudSettings.notifications || {});
        syncSettingsUI();
      }
      if (res.routeDisplayMode) {
        routeDisplayMode = res.routeDisplayMode;
        updateRouteModeButton();
      }
    });
  }
}

function saveSettingsToStorage() {
  if (typeof chrome !== "undefined" && chrome.storage && chrome.storage.local) {
    chrome.storage.local.set({
      hudSettings: {
        timeThresholds: CONFIG.timeThresholds,
        toast: CONFIG.toast,
        voice: CONFIG.voice,
        notifications: CONFIG.notifications,
      },
      routeDisplayMode: routeDisplayMode,
    });
  }
}

const sspStatusState = { hasData: false, dataCount: 0, paused: false };
const trailerAlertStages = new Map();
const spokenFingerprints = new Set();

let selectedVoice = null;
let sharedAudioCtx = null;
let cachedYmsPayload = null;
let latestSspData = [];

class VoiceQueueBuffer {
  constructor() {
    this.queue = [];
    this.isProcessing = false;
  }

  enqueue(text) {
    if (!CONFIG.voice.enabled || !text) return;
    const cleanText = text.trim();
    if (this.queue.includes(cleanText)) return;
    this.queue.push(cleanText);
    this.processNext();
  }

  processNext() {
    if (this.isProcessing || this.queue.length === 0) return;
    if (!("speechSynthesis" in window)) return;

    this.isProcessing = true;
    const currentText = this.queue.shift();

    playPreChime(() => {
      try {
        window.speechSynthesis.cancel();
        const utterance = new SpeechSynthesisUtterance(currentText);
        utterance.lang = "pl-PL";
        utterance.rate = CONFIG.voice.rate;
        utterance.pitch = CONFIG.voice.pitch;
        if (selectedVoice) utterance.voice = selectedVoice;

        utterance.onend = () => {
          this.isProcessing = false;
          setTimeout(() => this.processNext(), 200);
        };

        utterance.onerror = () => {
          this.isProcessing = false;
          setTimeout(() => this.processNext(), 100);
        };

        window.speechSynthesis.speak(utterance);
      } catch (e) {
        this.isProcessing = false;
        this.processNext();
      }
    });
  }

  clear() {
    this.queue = [];
    if ("speechSynthesis" in window) window.speechSynthesis.cancel();
    this.isProcessing = false;
  }
}

const voiceBuffer = new VoiceQueueBuffer();

function loadVoices() {
  if (!("speechSynthesis" in window)) return;
  const voices = window.speechSynthesis.getVoices();
  selectedVoice =
    voices.find((v) => v.lang.includes("pl") && v.name.toLowerCase().includes("zofia")) ||
    voices.find((v) => v.lang.includes("pl") && v.name.toLowerCase().includes("paulina")) ||
    voices.find((v) => v.lang.includes("pl")) ||
    null;
}

if ("speechSynthesis" in window) {
  loadVoices();
  window.speechSynthesis.onvoiceschanged = loadVoices;
}

function playPreChime(callback) {
  try {
    const AudioContextClass = window.AudioContext || window.webkitAudioContext;
    if (!sharedAudioCtx || sharedAudioCtx.state === "closed") {
      sharedAudioCtx = new AudioContextClass();
    }
    if (sharedAudioCtx.state === "suspended") {
      sharedAudioCtx.resume();
    }

    const osc = sharedAudioCtx.createOscillator();
    const gain = sharedAudioCtx.createGain();

    osc.connect(gain);
    gain.connect(sharedAudioCtx.destination);

    const now = sharedAudioCtx.currentTime;
    osc.type = "sine";
    osc.frequency.setValueAtTime(600, now);
    osc.frequency.exponentialRampToValueAtTime(1200, now + 0.1);
    gain.gain.setValueAtTime(0.25, now);
    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.3);

    osc.start(now);
    osc.stop(now + 0.3);

    osc.onended = () => {
      osc.disconnect();
      gain.disconnect();
      if (typeof callback === "function") callback();
    };
  } catch (e) {
    if (typeof callback === "function") callback();
  }
}

function triggerSystemNotification(title, body) {
  if (!CONFIG.notifications.enabled) return;
  if ("Notification" in window && Notification.permission === "granted") {
    new Notification(title, { body: body });
  }
}

function calculateMinutes(baseTime) {
  if (!baseTime || !baseTime.includes(":")) return null;
  const [h, m] = baseTime.split(":").map(Number);
  const target = new Date();
  target.setHours(h, m + 30, 0, 0);
  return Math.round((target - new Date()) / 60000);
}

function getAddedTimeStr(baseTime) {
  if (!baseTime || !baseTime.includes(":")) return "--:--";
  const [h, m] = baseTime.split(":").map(Number);
  const target = new Date();
  target.setHours(h, m + 30, 0, 0);
  return `${target.getHours().toString().padStart(2, "0")}:${target.getMinutes().toString().padStart(2, "0")}`;
}

function extractLane(text) {
  const clean = String(text || "").replace(/&gt;/g, ">").toUpperCase();
  const match = clean.match(/\b([A-Z]{3,4}\d)\s*(?:->|>|TO|-)\s*([A-Z]{3,4}\d)\b/);
  if (match) return `${match[1]}->${match[2]}`;
  if (clean.includes("WRO5") && clean.includes("KTW3")) return PRIMARY_ROUTE;
  return null;
}

function detectDirection(lane = "", loc = "", ref = "", status = "", trailer = "", seal = "", account = "") {
  const rawText = `${lane} ${loc} ${ref} ${status} ${trailer} ${seal} ${account}`.replace(/&gt;/g, ">");
  const textUpper = rawText.toUpperCase();
  const detectedLane = extractLane(textUpper) || lane;

  if (detectedLane && detectedLane !== "---") {
    const isTransfers = textUpper.includes("TRANSFERSINITIAL");
    const hasSeal = /\b(SEAL|PLOMBA|SEALED)\b/i.test(textUpper) || Boolean(seal && seal !== "---" && seal !== "NO");
    const isFinished = status.toUpperCase().includes("FINISHED");
    const isEmpty = isTransfers || /\b(EMPTY|EMP|MT)\b/i.test(textUpper);

    let loadStatus = "";
    if (hasSeal || isFinished) {
      loadStatus = `<span style="color: ${CONFIG.colors.finished}; font-weight: bold;">[PEŁNA / SEAL / FIN]</span>`;
    } else if (isEmpty) {
      loadStatus = `<span style="color: ${CONFIG.colors.progress}; font-weight: bold;">[PUSTA]</span>`;
    } else {
      loadStatus = `<span style="color: var(--text-muted); font-weight: bold;">[W TRAKCIE]</span>`;
    }

    return `<div class="data-row" style="border-left: 2px solid #f36c00; padding-left: 4px; background: rgba(243, 108, 0, 0.05); margin-bottom: 4px; border-radius: 0 !important;"><span>DIR:</span> <b>${detectedLane} ${loadStatus}</b></div>`;
  }
  return "";
}

function escapeHtmlAttr(value) {
  return String(value || "")
    .replace(/&/g, "&amp;")
    .replace(/"/g, "&quot;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");
}

function vridClickRow(ref, hasDriver) {
  const safe = escapeHtmlAttr(ref);
  const drvBadge = hasDriver
    ? `<span style="color: var(--col-finished); font-weight: 700; font-size: 10px; margin-left: 6px;" title="Kierowca na miejscu">[DRV]</span>`
    : "";
  if (!ref || ref === "---") {
    return `<div class="data-row"><span>VRID:</span> <b style="display:inline-flex; align-items:center;">---${drvBadge}</b></div>`;
  }
  return `<div class="data-row"><span>VRID:</span> <b style="display:inline-flex; align-items:center;"><span class="ssp-vrid-click" data-vrid="${safe}" title="Wstaw VRID do wyszukiwarki">${safe}</span>${drvBadge}</b></div>`;
}

function updateSSPHeaderStatus() {
  const el = document.getElementById("ssp-header-status");
  if (!el) return;
  el.textContent = `${sspStatusState.paused ? "PAUZA" : "ODŚWIEŻANIE"} · ${sspStatusState.hasData ? `DANE: ${sspStatusState.dataCount}` : "DANE: —"}`;
  el.classList.toggle("ssp-status-paused", sspStatusState.paused);
  el.classList.toggle("ssp-status-hasdata", sspStatusState.hasData);
}

function renderYmsRoutes() {
  const container = document.getElementById("yms-routes-container");
  if (!container || !cachedYmsPayload) return;

  let html = "";
  for (const [route, data] of Object.entries(cachedYmsPayload)) {
    const isSingle = routeDisplayMode === "SINGLE";
    if (isSingle && route !== PRIMARY_ROUTE) continue;

    // Pobieramy dodatkowe FINISHED z bazy SSP dla tej konkretnej relacji
    const sspFinishedCount = latestSspData.filter((item) => {
      const isFin = (item.status || "").toUpperCase().includes("FINISHED");
      const itemLane = extractLane(item.lane || item.ref) || item.lane;
      return isFin && itemLane === route;
    }).length;

    const baseFull = Number(data.full) || 0;
    const totalFull = baseFull + sspFinishedCount;

    html += `
        <div style="display: flex; justify-content: space-between; align-items: center; background: var(--bg-tertiary); border: 1px solid var(--border-color); padding: 6px 8px; border-left: 3px solid var(--highlight-color); box-shadow: var(--shadow-drop);">
            <span style="color: var(--highlight-color); font-weight: 700; font-size: 12px; font-family: var(--font-family);">${route.replace(/&gt;/g, ">")}</span>
            <div style="font-size: 11px; font-family: var(--font-family);">
                <span style="color: var(--text-muted);">FULL:</span> 
                <b style="color: var(--col-finished); font-size: 13px;">${totalFull}</b>
                <span style="color: #00ff15; font-size: 9px; margin-left: 4px; text-shadow: 0 0 3px rgba(0,255,21,0.5);" title="Gotowi Kierowcy">[DRV: ${data.driver || 0}]</span>
                <span style="color: var(--border-color); margin: 0 4px;">|</span>
                <span style="color: var(--text-muted);">EMP:</span> 
                <b style="color: var(--col-progress); font-size: 13px;">${data.empty || 0}</b>
            </div>
        </div>`;
  }

  container.innerHTML = html || `<div style="color:var(--text-muted); font-size:11px; padding:6px;">[ BRAK TRAS DLA WYBRANEGO TRYBU ]</div>`;
}

chrome.runtime.onMessage.addListener((message) => {
  if (message.type === "SSP_UPDATE_DATA") {
    latestSspData = message.payload || [];
    sspStatusState.hasData = true;
    sspStatusState.dataCount = latestSspData.length;
    updateSSPHeaderStatus();
    renderSidebar(latestSspData);
    renderYmsRoutes();
  } else if (message.type === "YMS_UPDATE_DATA") {
    cachedYmsPayload = message.payload;
    renderYmsRoutes();
  }
});

function sendRichToast(item, alertType, diff) {
  if (typeof chrome !== "undefined" && chrome.tabs) {
    chrome.tabs.query({ active: true, currentWindow: true }, (tabs) => {
      const tabId = tabs[0]?.id;
      if (tabId) {
        chrome.tabs.sendMessage(
          tabId,
          {
            type: "SHOW_RICH_TOAST",
            payload: {
              item: item,
              alertType: alertType,
              diff: diff,
              autoClose: CONFIG.toast.autoClose,
              duration: CONFIG.toast.duration,
            },
          },
          () => {
            let ignore = chrome.runtime.lastError;
          },
        );
      }
    });
  }
}

function renderSidebar(dataArray) {
  const counts = { scheduled: 0, progress: 0, finished: 0 };
  let dataCounts = { late: 0, critical: 0, progress: 0, finished: 0, out: 0 };
  let htmlData = {
    late: "",
    critical: "",
    progress: "",
    finished: "",
    out: "",
  };

  dataArray.sort((a, b) => {
    const minA = calculateMinutes(a.baseTime);
    const minB = calculateMinutes(b.baseTime);
    if (minA === null) return 1;
    if (minB === null) return -1;
    return minA - minB;
  });

  const currentUnitsOnYard = new Set();

  dataArray.forEach((item) => {
    const detectedLane = extractLane(item.lane || item.ref) || item.lane || "";

    // Filtrowanie kart: w trybie SINGLE dopuszczamy tylko relację podstawową
    if (routeDisplayMode === "SINGLE" && detectedLane && detectedLane !== PRIMARY_ROUTE) {
      return;
    }

    const trailerId = (item.trailer || item.ref || "").trim();
    const locId = (item.loc || "").trim();
    const unitKey = `${trailerId}_${locId}`;

    if (trailerId && trailerId !== "---") {
      currentUnitsOnYard.add(unitKey);
    }

    const calcDiff = calculateMinutes(item.baseTime);
    const diff = calcDiff !== null ? calcDiff : 999;
    const targetTimeStr = getAddedTimeStr(item.baseTime);
    const displayBaseTime = item.baseTime || "--:--";
    const statusUpper = (item.status || "").toUpperCase();

    if (statusUpper.includes("SCHEDULED")) counts.scheduled++;
    else if (statusUpper.includes("PROGRESS")) counts.progress++;
    else if (statusUpper.includes("FINISHED")) counts.finished++;

    const directionRow = detectDirection(
      item.lane || "",
      item.loc || "",
      item.ref || "",
      item.status || "",
      item.trailer || "",
      item.seal || "",
      item.account || ""
    );

    const cardBody = `<div class="card-body"><div class="trailer-huge"><span>TRAILER:</span>${item.trailer || "---"}</div><div class="data-row"><span>STATUS:</span> <b>${statusUpper || "BRAK"}</b></div>${directionRow}<div class="data-row"><span>LANE:</span> <b>${(item.lane || "---").replace(/&gt;/g, ">")}</b></div>${vridClickRow(item.ref, item.hasDriver)}<div class="data-row"><span>CARR:</span> <b title="${item.carrier || ""}">${item.carrier || "---"}</b></div><div class="data-row"><span>LOC:</span> <b>${item.loc || "---"}</b></div></div>`;

    if (calcDiff === null || (diff > -120 && diff < 300)) {
      if (statusUpper === "OUT" || statusUpper.includes("COMPLETE")) {
        dataCounts.out++;
        htmlData.out += `<div class="ssp-card" style="border-left-color: ${CONFIG.colors.outCol}; opacity: 0.8;"><div class="card-header"><span style="color:var(--text-muted)">[OUT] ${displayBaseTime} (${targetTimeStr})</span><span class="time-badge" style="color:var(--text-muted)">T: ${calcDiff !== null ? diff + 'm' : '—'}</span></div>${cardBody.replace("TRAILER:</span>", 'TRAILER:</span><span style="text-decoration:line-through;">')}</div>`;
        trailerAlertStages.delete(unitKey);
      } else if (calcDiff !== null && diff < 0) {
        dataCounts.late++;
        htmlData.late += `<div class="ssp-card" style="border-left-color: ${CONFIG.colors.lateAlert};"><div class="card-header" style="color: ${CONFIG.colors.lateAlert}"><span>${displayBaseTime} (${targetTimeStr})</span><span class="time-badge late-blink" style="background:${CONFIG.colors.lateAlert}; color:#fff; padding: 0 4px;">OVERDUE: ${Math.abs(diff)}m</span></div>${cardBody}</div>`;
      } else if (statusUpper.includes("FINISHED")) {
        const lastStage = trailerAlertStages.get(unitKey) || 999;

        if (diff <= CONFIG.timeThresholds.stage5 && diff >= 0) {
          dataCounts.critical++;
          htmlData.critical += `<div class="ssp-card" style="border-left-color: ${CONFIG.colors.urgentAlert};"><div class="card-header" style="color: ${CONFIG.colors.urgentAlert}"><span>${displayBaseTime} (${targetTimeStr})</span><span class="time-badge urgent-blink" style="background:${CONFIG.colors.urgentAlert}; color:#fff; padding: 0 4px;">CRIT: ${diff}m</span></div>${cardBody}</div>`;

          if (lastStage > 5) {
            trailerAlertStages.set(unitKey, 5);
            const msg = `Alarm krytyczny, dla ${item.loc} zostało tylko ${diff} minut.`;
            const fp = `${unitKey}_ST5`;
            if (!spokenFingerprints.has(fp)) {
              spokenFingerprints.add(fp);
              voiceBuffer.enqueue(msg);
              triggerSystemNotification("ALARM 5 MINUT", msg);
              sendRichToast(item, "FIN_CRIT_5", diff);
            }
          }
        } else if (diff <= CONFIG.timeThresholds.stage15 && diff > CONFIG.timeThresholds.stage5) {
          dataCounts.critical++;
          htmlData.critical += `<div class="ssp-card" style="border-left-color: ${CONFIG.colors.urgentAlert};"><div class="card-header" style="color: ${CONFIG.colors.urgentAlert}"><span>${displayBaseTime} (${targetTimeStr})</span><span class="time-badge urgent-blink" style="background:${CONFIG.colors.urgentAlert}; color:#fff; padding: 0 4px;">WAIT: ${diff}m</span></div>${cardBody}</div>`;

          if (lastStage > 15) {
            trailerAlertStages.set(unitKey, 15);
            const msg = `Uwaga, czas dla ${item.loc} to ${diff} minut.`;
            const fp = `${unitKey}_ST15`;
            if (!spokenFingerprints.has(fp)) {
              spokenFingerprints.add(fp);
              voiceBuffer.enqueue(msg);
              triggerSystemNotification("OSTRZEŻENIE 15 MINUT", msg);
              sendRichToast(item, "FIN_CRIT_15", diff);
            }
          }
        } else if (diff <= CONFIG.timeThresholds.stage30 && diff > CONFIG.timeThresholds.stage15) {
          dataCounts.finished++;
          htmlData.finished += `<div class="ssp-card" style="border-left-color: ${CONFIG.colors.fleAlert};"><div class="card-header" style="color: ${CONFIG.colors.fleAlert}"><span>${displayBaseTime} (${targetTimeStr})</span><span class="time-badge" style="background:${CONFIG.colors.fleAlert}; color:#fff; padding: 0 4px;">WAIT: ${diff}m</span></div>${cardBody}</div>`;

          if (lastStage > 30) {
            trailerAlertStages.set(unitKey, 30);
            const msg = `Zbliża się czas wyjazdu dla ${item.loc}.`;
            const fp = `${unitKey}_ST30`;
            if (!spokenFingerprints.has(fp)) {
              spokenFingerprints.add(fp);
              voiceBuffer.enqueue(msg);
              triggerSystemNotification("INFO 30 MINUT", msg);
              sendRichToast(item, "FIN_WARN_30", diff);
            }
          }
        } else {
          dataCounts.finished++;
          htmlData.finished += `<div class="ssp-card" style="border-left-color: ${CONFIG.colors.finished};"><div class="card-header" style="color: ${CONFIG.colors.finished}"><span>${displayBaseTime} (${targetTimeStr})</span><span class="time-badge" style="color:${CONFIG.colors.finished}">WAIT: ${calcDiff !== null ? diff + 'm' : '—'}</span></div>${cardBody}</div>`;
        }
      } else {
        const isUrgent = calcDiff !== null && diff <= CONFIG.timeThresholds.urgent;
        const isWarning = calcDiff !== null && diff <= CONFIG.timeThresholds.warning && !isUrgent;
        let cColor = CONFIG.colors.progress;
        let badgeStyle = "background:transparent; color:var(--text-muted); padding: 0 4px;";
        let badgeClass = "";

        if (isUrgent) {
          cColor = CONFIG.colors.urgentAlert;
          badgeStyle = `background:${cColor}; color:#fff; padding: 0 4px;`;
          badgeClass = "urgent-blink";
        } else if (isWarning) {
          cColor = CONFIG.colors.fleAlert;
          badgeStyle = `background:${cColor}; color:#fff; padding: 0 4px;`;
        }

        const activeCard = `<div class="ssp-card" style="border-left-color: ${cColor};"><div class="card-header" style="color: ${cColor}"><span>${displayBaseTime} (${targetTimeStr})</span><span class="time-badge ${badgeClass}" style="${badgeStyle}">IN: ${calcDiff !== null ? diff + 'm' : '—'}</span></div>${cardBody}</div>`;

        if (isUrgent) {
          dataCounts.critical++;
          htmlData.critical += activeCard;

          const progKey = `${unitKey}_prog`;
          if (!trailerAlertStages.has(progKey)) {
            trailerAlertStages.set(progKey, 10);
            const msg = `Brak kierowcy dla ${item.loc}.`;
            voiceBuffer.enqueue(msg);
            sendRichToast(item, "URGENT", diff);
          }
        } else {
          dataCounts.progress++;
          htmlData.progress += activeCard;
        }
      }
    }
  });

  for (const storedUnitKey of trailerAlertStages.keys()) {
    const rawUnit = storedUnitKey.replace("_prog", "");
    if (!currentUnitsOnYard.has(rawUnit)) {
      trailerAlertStages.delete(storedUnitKey);
      spokenFingerprints.delete(`${rawUnit}_ST30`);
      spokenFingerprints.delete(`${rawUnit}_ST15`);
      spokenFingerprints.delete(`${rawUnit}_ST5`);
    }
  }

  document.getElementById("st-sch").innerText = counts.scheduled;
  document.getElementById("st-pro").innerText = counts.progress;
  document.getElementById("st-fin").innerText = counts.finished;
  document.getElementById("tab-cnt-critical").innerText = `(${dataCounts.critical})`;
  document.getElementById("tab-cnt-late").innerText = `(${dataCounts.late})`;
  document.getElementById("tab-cnt-progress").innerText = `(${dataCounts.progress})`;
  document.getElementById("tab-cnt-finished").innerText = `(${dataCounts.finished})`;
  document.getElementById("tab-cnt-out").innerText = `(${dataCounts.out})`;

  const emptyMsg = `<div style="text-align:center; padding:20px; color:var(--text-muted); font-weight:bold; font-size: 11px;">[ BRAK DANYCH DLA TRASY ]</div>`;
  document.getElementById("pane-critical").innerHTML = htmlData.critical || emptyMsg;
  document.getElementById("pane-late").innerHTML = htmlData.late || emptyMsg;
  document.getElementById("pane-progress").innerHTML = htmlData.progress || emptyMsg;
  document.getElementById("pane-finished").innerHTML = htmlData.finished || emptyMsg;
  document.getElementById("pane-out").innerHTML = htmlData.out || emptyMsg;
}

function updateRouteModeButton() {
  const btn = document.getElementById("btn-toggle-route-mode");
  if (btn) {
    btn.innerText = routeDisplayMode === "SINGLE" ? "1 KIERUNEK" : "WSZYSTKIE";
    btn.title = routeDisplayMode === "SINGLE" ? "Pokazuje tylko WRO5->KTW3" : "Pokazuje wszystkie wykryte trasy";
    btn.style.color = routeDisplayMode === "SINGLE" ? "var(--highlight-color)" : "var(--col-finished)";
  }
}

function sendModeToTabs(mode) {
  if (typeof chrome !== "undefined" && chrome.tabs) {
    chrome.tabs.query({}, (tabs) => {
      tabs.forEach((t) => {
        if (t.id) {
          chrome.tabs.sendMessage(t.id, { type: "SET_ROUTE_MODE", payload: mode }, () => {
            let ignore = chrome.runtime.lastError;
          });
        }
      });
    });
  }
}

document.addEventListener("DOMContentLoaded", () => {
  loadSettingsFromStorage();

  const btnRouteToggle = document.getElementById("btn-toggle-route-mode");
  if (btnRouteToggle) {
    btnRouteToggle.onclick = () => {
      routeDisplayMode = routeDisplayMode === "SINGLE" ? "ALL" : "SINGLE";
      updateRouteModeButton();
      saveSettingsToStorage();
      sendModeToTabs(routeDisplayMode);
      renderSidebar(latestSspData);
      renderYmsRoutes();
    };
  }

  const tabBtns = document.querySelectorAll(".ssp-tab-btn");
  const tabPanes = document.querySelectorAll(".ssp-tab-content");
  tabBtns.forEach((btn) => {
    btn.addEventListener("click", () => {
      tabBtns.forEach((b) => b.classList.remove("active"));
      tabPanes.forEach((p) => p.classList.remove("active"));
      btn.classList.add("active");
      const targetPane = document.getElementById(`pane-${btn.dataset.tab}`);
      if (targetPane) targetPane.classList.add("active");
    });
  });

  let isDark = true;
  document.documentElement.setAttribute("data-theme", "dark");
  const themeBtn = document.getElementById("toggle-theme");
  if (themeBtn) {
    themeBtn.onclick = () => {
      isDark = !isDark;
      document.documentElement.setAttribute("data-theme", isDark ? "dark" : "light");
    };
  }

  const btnCancel = document.getElementById("btn-cancel");
  const btnPause = document.getElementById("btn-pause");
  let pollingPaused = false;

  function sendToTab(type, payload, callback) {
    if (typeof chrome !== "undefined" && chrome.tabs) {
      chrome.tabs.query({ active: true, currentWindow: true }, (tabs) => {
        const tabId = tabs[0]?.id;
        if (!tabId) return callback?.();
        try {
          chrome.tabs.sendMessage(tabId, { type, payload }, () => {
            let ignoreError = chrome.runtime.lastError;
            callback?.();
          });
        } catch (e) {
          callback?.();
        }
      });
    }
  }

  if (btnCancel) btnCancel.onclick = () => sendToTab("SSP_REFRESH_NOW");
  if (btnPause) {
    btnPause.onclick = () => {
      pollingPaused = !pollingPaused;
      sspStatusState.paused = pollingPaused;
      updateSSPHeaderStatus();
      sendToTab(pollingPaused ? "SSP_PAUSE_POLLING" : "SSP_RESUME_POLLING");
    };
  }
});
"}
